class TestMentionWindowPolicy(unittest.TestCase):
    def test_tournament_wide_mention_screened(self):
        """Mention market with no derivable event window (KXWCMENTION-
        MENWORLDCUP: broadcasts already live daily) must never be quoted."""
        bot = IncentiveMarketMaker(client=None, live=False)
        meta = _meta(ticker="KXWCMENTION-MENWORLDCUP-CAPT",
                     event_ticker="KXWCMENTION-MENWORLDCUP",
                     series="KXWCMENTION", cutoff=None)
        self.assertEqual(bot._screen(meta, datetime.now(timezone.utc)),
                         "no_event_window")

    def test_non_mention_without_cutoff_ok(self):
        bot = IncentiveMarketMaker(client=None, live=False)
        meta = _meta(series="KXBTCVSGOLD", cutoff=None)
        self.assertIsNone(bot._screen(meta, datetime.now(timezone.utc)))

    def test_same_day_game_quotable_until_kickoff(self):
        """A mention market whose game is TODAY must survive the pre-filter and
        get an intraday cutoff from the resolver (game-day morning rent)."""
        _clean_persist()
        now = datetime.now(timezone.utc)
        et_now = now.astimezone(imm.ET)
        seg = et_now.strftime("%y%b%d").upper() + "ARGSUI"
        t = f"KXWCMENTION-{seg}-WALK"
        kickoff = now + timedelta(hours=3)
        client = FakeClient()
        client.programs = [dict(client.programs[0], market_ticker=t)]
        client.markets = {t: dict(client.markets["KXGOOD-99DEC31-A"], ticker=t,
                                  event_ticker=f"KXWCMENTION-{seg}")}
        client.books = {t: {"orderbook_fp": {
            "yes_dollars": [["0.48", "500"], ["0.49", "600"]],
            "no_dollars": [["0.49", "1200"]]}}}
        bot = IncentiveMarketMaker(client=client, live=False)
        bot.resolver = imm.EventStartResolver(http_get_json=lambda url: {
            "events": [{
                "date": kickoff.strftime("%Y-%m-%dT%H:%MZ"),
                "competitions": [{"competitors": [
                    {"team": {"abbreviation": "ARG"}},
                    {"team": {"abbreviation": "SUI"}}]}]}]})
        # subject under test is the CUTOFF wiring; the fixture pool is tiny and
        # would legitimately fall below the $1 total-accrual floor in a 3h window
        old_floor = imm.MIN_EST_TOTAL_DOLLARS
        imm.MIN_EST_TOTAL_DOLLARS = 0.0
        try:
            bot.run_cycle()
            self.assertIn(t, bot.state.selected)
            self.assertTrue(bot.state.sim_orders)
        finally:
            imm.MIN_EST_TOTAL_DOLLARS, imm.PAYOUT_FLOOR_DOLLARS = old_floor, 1.0

    def test_postponed_game_quotable_until_makeup(self):
        """A WNBA game postponed past its ticker date (NYDAL 7/16 -> makeup
        7/20 while programs kept paying) must survive the 24h ticker pre-drop
        and quote until the makeup start."""
        _clean_persist()
        now = datetime.now(timezone.utc)
        et_stale = (now - timedelta(days=3)).astimezone(imm.ET)
        seg = et_stale.strftime("%y%b%d").upper() + "NYDAL"
        t = f"KXWNBAMENTION-{seg}-ROOK"
        makeup = now + timedelta(hours=30)
        client = FakeClient()
        client.programs = [dict(client.programs[0], market_ticker=t)]
        client.markets = {t: dict(client.markets["KXGOOD-99DEC31-A"], ticker=t,
                                  event_ticker=f"KXWNBAMENTION-{seg}")}
        client.books = {t: {"orderbook_fp": {
            "yes_dollars": [["0.48", "500"], ["0.49", "600"]],
            "no_dollars": [["0.49", "1200"]]}}}
        bot = IncentiveMarketMaker(client=client, live=False)
        bot.resolver = imm.EventStartResolver(http_get_json=lambda url: {
            "events": [
                {"date": (now - timedelta(days=3)).strftime("%Y-%m-%dT%H:%MZ"),
                 "status": {"type": {"name": "STATUS_POSTPONED"}},
                 "competitions": [{"competitors": [
                     {"team": {"abbreviation": "DAL"}},
                     {"team": {"abbreviation": "NY"}}]}]},
                {"date": makeup.strftime("%Y-%m-%dT%H:%MZ"),
                 "status": {"type": {"name": "STATUS_SCHEDULED"}},
                 "competitions": [{"competitors": [
                     {"team": {"abbreviation": "DAL"}},
                     {"team": {"abbreviation": "NY"}}]}]}]})
        old_floor = imm.MIN_EST_TOTAL_DOLLARS
        imm.MIN_EST_TOTAL_DOLLARS = 0.0   # cutoff wiring is the subject here
        try:
            bot.run_cycle()
            self.assertIn(t, bot.state.selected)
            self.assertTrue(bot.state.sim_orders)
            cutoff = bot.state.selected[t].cutoff
            self.assertIsNotNone(cutoff)
            self.assertGreater(cutoff, now)   # quoting NOW, not killed by ticker date
        finally:
            imm.MIN_EST_TOTAL_DOLLARS, imm.PAYOUT_FLOOR_DOLLARS = old_floor, 1.0


class TestOverrideBuffer(unittest.TestCase):
    """Earnings call / disclosure-release overrides cut off OVERRIDE_BUFFER_MIN
    before the event (Jack: all orders expire 10 min before the release), vs
    the 30-min game buffer; and orders are expiration-capped at that cutoff."""

    def test_disclosure_release_cutoff_and_order_expiry(self):
        _clean_persist()
        now = datetime.now(timezone.utc)
        release = now + timedelta(hours=3)          # e.g. today's 4pm release
        # (was KXINTC-26JULHEAD until 2026-09-24: company headcount events
        # are blocked now, and the subject here is the cutoff wiring)
        ev = "KXINTC-26JULDCAI"
        t = f"{ev}-82000"
        client = FakeClient()
        client.programs = [dict(client.programs[0], market_ticker=t)]
        client.markets = {t: dict(client.markets["KXGOOD-99DEC31-A"], ticker=t,
                                  event_ticker=ev)}
        client.books = {t: {"orderbook_fp": {
            "yes_dollars": [["0.48", "500"], ["0.49", "600"]],
            "no_dollars": [["0.49", "1200"]]}}}
        imm.EVENT_START_OVERRIDES[ev] = release
        old_floor = imm.MIN_EST_TOTAL_DOLLARS
        imm.MIN_EST_TOTAL_DOLLARS = 0.0
        # KXINTC is company family — this test is about cutoff mechanics, so
        # exempt the fixture from the (env-restorable) gates and from the
        # 2026-08-02 re-entry $2/day rate floor (which outranks curation).
        old_no_new = imm.NO_NEW_SERIES
        imm.NO_NEW_SERIES = frozenset()
        old_freeze = imm.FREEZE_SERIES
        imm.FREEZE_SERIES = frozenset()
        old_ov = imm.SERIES_OVERRIDES.get("KXINTC")
        imm.SERIES_OVERRIDES["KXINTC"] = imm.SeriesOverride()
        try:
            # ... and from the 2026-10-03 company-KPI cut, for the same reason
            with _without_cut("KXINTC"):
                bot = IncentiveMarketMaker(client=client, live=False)
                bot.run_cycle()
            self.assertIn(t, bot.state.selected)
            cutoff = bot.state.selected[t].cutoff
            # cutoff = release - OVERRIDE_BUFFER_MIN (10), NOT the 30-min game buffer
            self.assertAlmostEqual(
                (release - cutoff).total_seconds() / 60.0,
                imm.OVERRIDE_BUFFER_MIN, delta=0.5)
            # every order is expiration-capped at that cutoff (exchange-side)
            for o in bot.state.sim_orders.values():
                self.assertLessEqual(o["expire_at"], cutoff.timestamp() + 1)
        finally:
            imm.MIN_EST_TOTAL_DOLLARS, imm.PAYOUT_FLOOR_DOLLARS = old_floor, 1.0
            imm.NO_NEW_SERIES = old_no_new
            imm.FREEZE_SERIES = old_freeze
            imm.EVENT_START_OVERRIDES.pop(ev, None)
            if old_ov is None:
                imm.SERIES_OVERRIDES.pop("KXINTC", None)
            else:
                imm.SERIES_OVERRIDES["KXINTC"] = old_ov


class TestHaltRestartContinuity(unittest.TestCase):
    """Restarts must not reset the loss clock or clear an active halt."""

    def _bot(self):
        _clean_persist()
        return IncentiveMarketMaker(client=FakeClient(), live=False)

    def test_pnl_carry_and_halt_survive_restart(self):
        bot = self._bot()
        bot.state.pnl_today_last = -700.0
        bot.state.halted_until = time.time() + 3600
        bot._save_persist()
        bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
        self.assertAlmostEqual(bot2.state.pnl_carry, -700.0)
        self.assertGreater(bot2.state.halted_until, time.time())

    def test_carry_discarded_on_new_roll_day(self):
        bot = self._bot()
        bot.state.pnl_today_last = -700.0
        bot.state.halted_until = time.time() + 3600
        bot._save_persist()
        with open(bot.PERSIST_PATH, encoding="utf-8") as f:
            data = json.load(f)
        data["halt_day_key"] = "1999-01-01"      # stale day
        with open(bot.PERSIST_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f)
        bot3 = IncentiveMarketMaker(client=FakeClient(), live=False)
        self.assertEqual(bot3.state.pnl_carry, 0.0)
        self.assertEqual(bot3.state.halted_until, 0.0)

    def test_carry_feeds_the_halt(self):
        bot = self._bot()
        bot.state.pnl_carry = -(imm.DAILY_LOSS_LIMIT + 5)   # carried loss
        bot.state.universe_at = time.time()
        bot.run_cycle()                       # fresh measurement ~0 + carry
        self.assertGreater(bot.state.halted_until, time.time())


def _bal(cash: float, positions: float) -> dict:
    """A /portfolio/balance response: cash in dollars, positions in CENTS."""
    return {"balance_dollars": f"{cash:.4f}", "portfolio_value": int(round(positions * 100))}


class TestBalanceFloor(unittest.TestCase):
    """The account floor measures ACCOUNT VALUE -- cash + Kalshi's valuation of
    the positions -- since 2026-10-03 (Jack: "make the balance guard use
    account value. drop of $2k in a day should halt."). The cash version
    halted at 01:40 ET 10/3 on inventory: cash $8,978 -> $3,882 while the
    marked-to-market loss was ~$700."""

    def _bot(self):
        _clean_persist()
        return IncentiveMarketMaker(client=FakeClient(), live=False)

    def test_the_knob(self):
        self.assertEqual(imm.ACCOUNT_DROP_HALT, 2000.0)
        self.assertFalse(hasattr(imm, "BALANCE_DROP_HALT"))      # the cash knob is gone
        self.assertEqual(imm.account_value_dollars(_bal(4302.0662, 20089.56)), 4302.0662 + 20089.56)
        self.assertEqual(imm.account_value_dollars(
            {"balance_dollars": "100.00", "portfolio_value_dollars": "50.25"}), 150.25)
        self.assertIsNone(imm.account_value_dollars({"balance_dollars": "100.00"}))

    def test_anchor_then_halt_on_a_real_drop(self):
        bot = self._bot()
        now = datetime.now(timezone.utc)
        bot.client.get_balance = lambda: _bal(9000.0, 15000.0)
        self.assertFalse(bot._check_balance_floor(now))       # anchors on value
        self.assertEqual(bot.state.account_value_day_start, 24000.0)
        bot.client.get_balance = lambda: _bal(9000.0, 15000.0 - imm.ACCOUNT_DROP_HALT)
        self.assertTrue(bot._check_balance_floor(now))        # positions lost $2k: halts
        self.assertGreater(bot.state.halted_until, time.time())
        msgs = [m for c, m in bot.alerter.today if c == "balance_floor"]
        self.assertTrue(msgs and "ACCOUNT VALUE dropped $2000" in msgs[0] and "positions" in msgs[0])

    def test_buying_inventory_does_not_halt(self):
        # the 10/3 01:40 ET case: cash -$5,097 into positions, ~-$700 marked
        bot = self._bot()
        now = datetime.now(timezone.utc)
        bot.client.get_balance = lambda: _bal(8978.0, 15000.0)
        bot._check_balance_floor(now)
        bot.client.get_balance = lambda: _bal(3882.0, 15000.0 + 5097.0 - 700.0)
        self.assertFalse(bot._check_balance_floor(now))
        self.assertEqual(bot.state.halted_until, 0.0)
        # ...while cash ALONE through a withdrawal / another bot's loss still trips it
        bot.client.get_balance = lambda: _bal(8978.0 - 2000.0, 15000.0)
        self.assertTrue(bot._check_balance_floor(now))

    def test_small_drop_partial_read_and_read_failure_are_fine(self):
        bot = self._bot()
        now = datetime.now(timezone.utc)
        bot.client.get_balance = lambda: _bal(6000.0, 4000.0)
        bot._check_balance_floor(now)
        bot.client.get_balance = lambda: _bal(5000.0, 3100.0)       # -$1,900
        self.assertFalse(bot._check_balance_floor(now))
        bot.client.get_balance = lambda: {"balance_dollars": "1.00"}  # no positions value
        self.assertFalse(bot._check_balance_floor(now))
        def boom():
            raise RuntimeError("api down")
        bot.client.get_balance = boom
        self.assertFalse(bot._check_balance_floor(now))
        self.assertEqual(bot.state.halted_until, 0.0)

    def test_an_old_cash_anchor_is_not_carried(self):
        # a state file written by the cash version carries balance_day_start;
        # the value floor ignores it and anchors fresh
        bot = self._bot()
        bot._save_persist()
        with open(bot.PERSIST_PATH, encoding="utf-8") as f:
            data = json.load(f)
        data["balance_day_start"] = 3882.0
        data.pop("account_value_day_start", None)
        with open(bot.PERSIST_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f)
        bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
        self.assertEqual(bot2.state.account_value_day_start, 0.0)
        bot2.client.get_balance = lambda: _bal(4302.0, 20089.56)
        self.assertFalse(bot2._check_balance_floor(datetime.now(timezone.utc)))
        self.assertAlmostEqual(bot2.state.account_value_day_start, 24391.56)
        # the 5am-CT roll (the daily summary's counter reset) re-arms the anchor
        bot2.build_daily_summary()
        self.assertEqual(bot2.state.account_value_day_start, 0.0)

    def test_halt_sends_one_clear_email(self):
        # Jack 2026-10-03: "i also need a clear email alert if halts due to
        # balance guard" -- its own subject, the numbers, the way back
        bot = self._bot()
        now = datetime.now(timezone.utc)
        sent = []
        bot.alerter.enabled = True
        bot.alerter.send_message = \
            lambda body, subject="", html=None: sent.append((subject, body)) or True
        bot.state.pnl_today_last = -300.0
        bot.client.get_balance = lambda: _bal(9000.0, 15000.0)
        bot._check_balance_floor(now)
        bot.client.get_balance = lambda: _bal(7000.0, 14500.0)           # -$2,500
        self.assertTrue(bot._check_balance_floor(now))
        self.assertEqual(len(sent), 1)                                    # the dedicated email only
        subject, body = sent[0]
        self.assertTrue(subject.startswith(
            "IMM HALTED: account value down $2,500 today (limit $2,000)"), subject)
        self.assertLessEqual(len(body.split("\n")[0]), imm.SMS_MAX_CHARS)  # stands alone on SMS
        for s in ("IMM HALTED by the account-value guard", "today's anchor:  $24,000.00",
                  "(cash $7,000.00 + positions $14,500.00)", "IMM's own P&L today",
                  "-$300.00", "$2,200.00", "another bot", "--clear-halt",
                  "positions are NOT closed"):
            self.assertIn(s, body)
        # the halt is still on the daily summary's list
        self.assertTrue(any(c == "balance_floor" for c, _m in bot.alerter.today))

    def test_email_attribution_when_the_imm_explains_it(self):
        _s, body = imm.balance_halt_email(2500.0, 24000.0, 21500.0, 4000.0, 10,
                                          time.time() + 3600, -2400.0, True)
        self.assertIn("$100.00", body)
        self.assertNotIn("another bot", body)

    def test_clear_halt_also_reanchors(self):
        bot = self._bot()
        bot.state.halted_until = time.time() + 3600
        bot.state.account_value_day_start = 24000.0
        bot._save_persist()
        self.assertEqual(imm.main(["--clear-halt"]), 0)
        with open(bot.PERSIST_PATH, encoding="utf-8") as f:
            data = json.load(f)
        self.assertEqual((data["halted_until"], data["account_value_day_start"]), (0.0, 0.0))


class TestHaltUntilRoll(unittest.TestCase):
    """Jack 2026-10-01: the daily-loss, balance-floor and open-scan halts last
    until the 5am-CT roll that resets their counters. They used to lift at ET
    midnight, five hours early, wake into the same roll day's breach and halt
    again until the next midnight -- through the whole next day."""

    def _bot(self):
        _clean_persist()
        return IncentiveMarketMaker(client=FakeClient(), live=False)

    @staticmethod
    def _ct(y, mo, d, h, mi=0):
        return imm.CT.localize(datetime(y, mo, d, h, mi)).astimezone(timezone.utc)

    def test_next_roll_is_the_next_5am_ct(self):
        ct = self._ct
        self.assertEqual(imm._next_roll_utc(ct(2026, 10, 1, 14)), ct(2026, 10, 2, 5))
        self.assertEqual(imm._next_roll_utc(ct(2026, 10, 2, 4, 59)), ct(2026, 10, 2, 5))
        self.assertEqual(imm._next_roll_utc(ct(2026, 10, 2, 5)), ct(2026, 10, 3, 5))
        # the halt-day key turns over at that same instant
        r = imm._next_roll_utc(ct(2026, 10, 1, 14))
        self.assertNotEqual(imm._halt_day_key(r - timedelta(seconds=1)),
                            imm._halt_day_key(r))
        # 5am on the wall clock across both DST changes (2am Mar 8 / Nov 1)
        self.assertEqual(imm._next_roll_utc(ct(2026, 3, 7, 12)),
                         datetime(2026, 3, 8, 10, tzinfo=timezone.utc))     # CDT
        self.assertEqual(imm._next_roll_utc(ct(2026, 10, 31, 12)),
                         datetime(2026, 11, 1, 11, tzinfo=timezone.utc))    # CST

    def test_loss_halt_lasts_until_the_roll(self):
        bot = self._bot()
        bot.state.pnl_carry = -(imm.DAILY_LOSS_LIMIT + 5)
        bot.state.universe_at = time.time()
        bot.run_cycle()
        until = datetime.fromtimestamp(bot.state.halted_until, timezone.utc).astimezone(imm.CT)
        self.assertEqual((until.hour, until.minute), (imm.SUMMARY_HOUR_CT, 0))
        self.assertTrue(0 < bot.state.halted_until - time.time() <= 25 * 3600)

    def test_balance_floor_halt_lasts_until_the_roll(self):
        bot = self._bot()
        now = datetime.now(timezone.utc)
        bot.client.get_balance = lambda: _bal(6000.0, 4000.0)
        bot._check_balance_floor(now)
        bot.client.get_balance = lambda: _bal(6000.0 - imm.ACCOUNT_DROP_HALT, 4000.0)
        self.assertTrue(bot._check_balance_floor(now))
        self.assertEqual(bot.state.halted_until, imm._next_roll_utc(now).timestamp())

    def test_halted_bot_wakes_into_a_fresh_day_at_the_roll(self):
        bot = self._bot()
        bot.state.universe_at = time.time()
        bot.run_cycle()                               # anchors the alerter's roll day
        now_ct = datetime.now(timezone.utc).astimezone(imm.CT)
        hour = imm.SUMMARY_HOUR_CT
        imm.SUMMARY_HOUR_CT = now_ct.hour             # a roll falls due this hour
        try:
            # yesterday's breach, its halt just expired, today's roll not run yet
            bot.alerter.last_summary_date = now_ct.date() - timedelta(days=1)
            bot.state.pnl_carry = -(imm.DAILY_LOSS_LIMIT + 5)
            bot.state.halted_until = time.time() - 1
            bot.run_cycle()
            self.assertLess(bot.state.halted_until, time.time())     # quoting again
            self.assertEqual(bot.state.pnl_carry, 0.0)                # fresh counter
            self.assertNotIn("loss_halt", [c for c, _m in bot.alerter.today])
            # within a roll day the same breach still halts
            bot.state.pnl_carry = -(imm.DAILY_LOSS_LIMIT + 5)
            bot.run_cycle()
            self.assertGreater(bot.state.halted_until, time.time())
        finally:
            imm.SUMMARY_HOUR_CT = hour


