class TestSeriesAutoEnroll(unittest.TestCase):
    """Daily series classifier + the bot's hot-reloaded extra-allow file."""

    def _classify(self, series, sample):
        import imm_earnings_overrides as ieo
        return ieo.classify_series(series, sample)

    def test_classifier(self):
        self.assertEqual(self._classify("KXTVMENTION", "KXTVMENTION-26AUG01-FOO")[0],
                         "enroll")
        self.assertEqual(self._classify("KXLTCMAXY", "KXLTCMAXY-LTC-26DEC31")[0],
                         "enroll")
        # company shapes: REVIEW since the 7/28 no-new company rule (they
        # were "enroll" until then — the classifier is the front door the
        # NO_NEW_SERIES gate can't see)
        self.assertEqual(self._classify("KXTSLA", "KXTSLA-26AUGDELIV-450000")[0],
                         "review")
        # fleet monthly / blocklist / ambiguous stay out
        self.assertEqual(self._classify("KXLTCMAXMON", "KXLTCMAXMON-LTC-26JUL31")[0],
                         "skip")
        self.assertEqual(self._classify("KXHURCAT", "KXHURCAT-26FAUSTO-T1")[0],
                         "review")
        self.assertEqual(self._classify("KXJOINCLUB",
                                        "KXJOINCLUB-26OCT02JALVAREZ-RMA")[0],
                         "review")   # day+name tail = person/event, not a metric
        self.assertEqual(self._classify("KXCEARAGOV", "KXCEARAGOV-26OCT04-EFRE")[0],
                         "review")
        self.assertEqual(self._classify("KXTEMPMIAH", "KXTEMPMIAH-26JUL2312-T88.99")[0],
                         "review")
        # GPU rental family is blocklisted -> classifier skips (never enrolls)
        self.assertEqual(self._classify("KXH100MS", "KXH100MS-26JUL-2.750")[0],
                         "skip")
        self.assertEqual(self._classify("KXA100MAX", "KXA100MAX-26DEC31-1.990")[0],
                         "skip")
        # dated-observation FT/APP families enroll by family (2026-09-01,
        # after 12 new *APP series appeared overnight)
        self.assertEqual(self._classify("KXGROKAPP", "KXGROKAPP-26OCT08-T500")[0],
                         "enroll")
        self.assertEqual(self._classify("KXWINGSFT",
                                        "KXWINGSFT-26OCT08-T104.5")[0],
                         "enroll")
        # ...but the suffix alone is not membership: person-tail events stay out
        self.assertEqual(self._classify("KXNFLDRAFT",
                                        "KXNFLDRAFT-26APR30-JSMITH")[0],
                         "review")

    def test_state_gas_family_is_pattern_blocked(self):
        # Jack 2026-09-14: "block the state daily family (including any future
        # ones). keep monthlies." The states share the KXAAAGASD prefix with the
        # NATIONAL daily, so this is a SERIES_BLOCK_PATTERNS full-match, not a
        # blocklist prefix. Blocked in BOTH tiers: de-allowlisting alone would
        # make scan_universe_reason return None = scan candidate, and these
        # books clear every scan gate (median vol24h 0, median ROI 0.53/day).
        # scan_universe_reason short-circuits on "allowlist_off" before it
        # reaches _blocked, and this class runs with the allowlist off, so
        # pin the real policy for the scan-tier half of the assertion.
        # 2026-09-27 (Jack: "i received permission to use
        # fuelinsights.gasbuddy.com. use that"): the two-letter STATES are
        # live again behind the GasBuddy gate (TestGasBuddyFairGate), and this
        # 9/14 pattern is what IMM_GB_FAIR_ENABLE=0 restores. A longer suffix
        # (not a state shape) stays blocked either way.
        off = [imm.re.compile(p) for p in imm._series_block_default(False).split(",")]
        for st in ("OH", "CA", "TX", "NC", "ZZ"):      # ZZ = never-listed state
            self.assertTrue(any(p.fullmatch(f"KXAAAGASD{st}") for p in off), st)
        prev_only = imm.ALLOWLIST_ONLY
        try:
            imm.ALLOWLIST_ONLY = True
            for st in ("OH", "CA", "TX", "NC", "ZZ"):
                t = f"KXAAAGASD{st}-26SEP02-3.1500"
                # 2026-10-01 (the gas trial): blocked again by default,
                # GasBuddy logging on; IMM_GB_STATE_QUOTE=1 re-gates them
                self.assertEqual(IncentiveMarketMaker._blocked(t),
                                 not imm.GB_STATE_QUOTE, t)
                self.assertEqual(IncentiveMarketMaker._allowed(t),
                                 imm.GB_STATE_QUOTE, t)
            t = "KXAAAGASDNYC-26SEP02-3.1500"          # not a state shape
            self.assertTrue(IncentiveMarketMaker._blocked(t), t)
            self.assertFalse(IncentiveMarketMaker._allowed(t), t)
            self.assertEqual(imm.scan_universe_reason(t), "blocked", t)
        finally:
            imm.ALLOWLIST_ONLY = prev_only
        # the national daily and the monthly are deliberately KEPT
        for keep in ("KXAAAGASD-26SEP02-3.1500", "KXAAAGASM-26SEP30-4.20"):
            self.assertFalse(IncentiveMarketMaker._blocked(keep), keep)
            self.assertTrue(IncentiveMarketMaker._allowed(keep), keep)
        # the monthly max / min pair is not pattern-blocked either: it was
        # cut BY NAME on 2026-10-03 (test_imm_scan_graduates)
        for s in ("KXAAAGASMINM", "KXAAAGASMAXM"):
            self.assertFalse(imm.series_pattern_blocked(s), s)
            self.assertTrue(IncentiveMarketMaker._blocked(f"{s}-26SEP30-4.20"), s)
        # full-match, not prefix-match: the pattern must not reach the national
        self.assertFalse(imm.series_pattern_blocked("KXAAAGASD"))
        self.assertTrue(imm.series_pattern_blocked("KXAAAGASDNYC"))
        # the family-override clone machinery is unchanged and still resolves
        # the national parent for every state (the guards a live state runs
        # under behind the GasBuddy gate).
        fake = "KXAAAGASDZZ"
        self.assertNotIn(fake, imm.SERIES_OVERRIDES)
        try:
            imm.ensure_family_override(fake)
            self.assertTrue(imm.series_safe_join(fake))
            # every guard but the rate floor (2026-09-27: "drop the $2/day
            # floor" for the states while the GasBuddy gate is on)
            self.assertEqual(imm.series_min_est_rate(fake),
                             imm.GB_STATE_MIN_RATE if imm.GB_FAIR_ENABLE
                             else imm.series_min_est_rate("KXAAAGASD"))
            self.assertEqual(imm.SERIES_OVERRIDES[fake].blackout_et,
                             imm.SERIES_OVERRIDES["KXAAAGASD"].blackout_et)
        finally:
            imm.SERIES_OVERRIDES.pop(fake, None)

    def test_hourly_temp_family_is_pattern_blocked(self):
        # Jack 2026-09-17: "blocklist hourly temp markets like KXTEMPMIAH".
        # KXTEMPMIAH is the example, the hourly FAMILY is the target, so this
        # is a SERIES_BLOCK_PATTERNS full-match on the same ^KXTEMP<CITY>H
        # shape _HOURLY_TEMP_RE and restart_imm.ps1 already key on. Blocked in
        # BOTH tiers for the gas-daily reason: de-allowlisting alone would
        # make scan_universe_reason return None = scan candidate.
        prev_only = imm.ALLOWLIST_ONLY
        try:
            imm.ALLOWLIST_ONLY = True
            # the six live hourly books, plus a city that has not listed yet
            for city in ("MIA", "NYC", "AUS", "CHI", "DC", "LAX", "ZZZ"):
                t = f"KXTEMP{city}H-26SEP1714-T79.99"
                self.assertTrue(IncentiveMarketMaker._blocked(t), t)
                self.assertFalse(IncentiveMarketMaker._allowed(t), t)
                self.assertEqual(imm.scan_universe_reason(t), "blocked", t)
        finally:
            imm.ALLOWLIST_ONLY = prev_only
        # full-match, not prefix-match: KXTEMPHELP is the near miss in the live
        # feed and stays quotable through the KXTEMP allow prefix
        self.assertFalse(imm.series_pattern_blocked("KXTEMPHELP"))
        self.assertTrue(IncentiveMarketMaker._allowed("KXTEMPHELP-26SEP17-X"))
        # the gas-daily entry is untouched by the second pattern (states are
        # pattern-blocked unless the gated state quoting is on -- 2026-09-27,
        # off again for the 2026-10-01 gas trial)
        self.assertEqual(imm.series_pattern_blocked("KXAAAGASDCA"),
                         not imm.GB_STATE_QUOTE)
        self.assertTrue(imm.series_pattern_blocked("KXAAAGASDNYC"))
        self.assertFalse(imm.series_pattern_blocked("KXAAAGASD"))
        # ...and so is every other weather family the bot quotes
        for keep in ("KXHIGHNY", "KXLOWTNY", "KXAVGTNYC", "KXAQICITYNYC",
                     "KXRAINNYCM"):
            self.assertFalse(imm.series_pattern_blocked(keep), keep)
        # the auto-enroll loaders share series_pattern_blocked, so the 6:45am
        # classifier can never write an hourly temp series back in as allowed
        self.assertTrue(imm.series_pattern_blocked("KXTEMPMIAH"))

    def test_hourly_temp_block_winds_down_like_any_other(self):
        # standard blocklist semantics: a named event can still be exempted to
        # quote to completion, and open positions are never force-flattened
        ev = "KXTEMPMIAH-26SEP1714"
        self.assertTrue(IncentiveMarketMaker._blocked(f"{ev}-T79.99"))
        prev = imm.BLOCKLIST_WIND_DOWN_EVENTS
        try:
            imm.BLOCKLIST_WIND_DOWN_EVENTS = frozenset({ev})
            self.assertFalse(IncentiveMarketMaker._blocked(f"{ev}-T79.99"))
            # the next hour's event is untouched by that exemption
            self.assertTrue(
                IncentiveMarketMaker._blocked("KXTEMPMIAH-26SEP1715-T79.99"))
        finally:
            imm.BLOCKLIST_WIND_DOWN_EVENTS = prev

    def test_pattern_block_is_configurable_and_winds_down(self):
        # empty env disables the mechanism entirely
        self.assertFalse(imm.series_pattern_blocked("KXANYTHING")
                         if not imm.SERIES_BLOCK_PATTERNS else False)
        # a pattern-blocked event can still be exempted to quote to completion,
        # exactly like a prefix-blocked one (BLOCKLIST_WIND_DOWN_EVENTS)
        # (a longer-than-state gas suffix: pattern-blocked whatever the
        # GasBuddy gate switch says, 2026-09-27)
        ev = "KXAAAGASDNYC-26SEP15"
        self.assertTrue(IncentiveMarketMaker._blocked(f"{ev}-4.1450"))
        prev = imm.BLOCKLIST_WIND_DOWN_EVENTS
        try:
            imm.BLOCKLIST_WIND_DOWN_EVENTS = frozenset({ev})
            self.assertFalse(IncentiveMarketMaker._blocked(f"{ev}-4.1450"))
            # a sibling event is untouched by that exemption
            self.assertTrue(IncentiveMarketMaker._blocked("KXAAAGASDLAX-26SEP15-4.1450"))
        finally:
            imm.BLOCKLIST_WIND_DOWN_EVENTS = prev

    def test_auto_enroll_loaders_refuse_a_pattern_blocked_series(self):
        # the 6:45am classifier writes extra_allow_series.json; a pattern-blocked
        # family must never be readmitted through it (the whole point of
        # "including any future ones")
        self.assertTrue(imm.series_pattern_blocked("KXAAAGASDNYC"))
        self.assertEqual(imm.series_pattern_blocked("KXAAAGASDWY"),
                         not imm.GB_STATE_QUOTE)   # gated 9/27, blocked 10/01
        self.assertFalse(imm.series_pattern_blocked("KXAAAGASD"))
        self.assertFalse(imm.series_pattern_blocked("KXDIESELD"))

    def test_cpi_family_is_pattern_blocked(self):
        # Jack 2026-09-24: "blocklist CPI markets". Every series whose NAME
        # carries CPI, in BOTH tiers (KXCPI / KXCPIYOY / KXCPICOREYOY were
        # quoting that morning as open-scan members), plus the two CPI prints
        # whose ticker lacks the letters. Audited against the full 14,379-
        # series catalog: all 90 tickers containing "CPI" are CPI/inflation
        # markets -- the substring has no near miss.
        prev_only = imm.ALLOWLIST_ONLY
        try:
            imm.ALLOWLIST_ONLY = True
            # (core 26OCT: 26NOV/26DEC are the 2026-09-28 pilot's, below;
            # KXCPICOREYOY joined the pilot as a family on 2026-10-01)
            for t in ("KXCPI-26DEC-T0.2", "KXCPICORE-26OCT-T0.2",
                      "KXCPIYOY-26NOV-T3.5",
                      "KXCPICOMBO-26OCT-X", "KXECONSTATCPI-26OCT-T0.3",
                      "KXECONSTATCORECPIYOY-26OCT-T3", "KXUSGASCPI-26OCT-T1",
                      "KXCHINACPI-26OCT-T1", "KXCPINDEX-26OCT-T330",
                      "KXCOREUND-26DEC31-T2.5", "KXUSEDCAR-26OCT-T1",
                      "KXNEWCPIFAMILY-26OCT-T1"):    # a series not listed yet
                self.assertTrue(IncentiveMarketMaker._blocked(t), t)
                self.assertFalse(IncentiveMarketMaker._allowed(t), t)
                self.assertEqual(imm.scan_universe_reason(t), "blocked", t)
        finally:
            imm.ALLOWLIST_ONLY = prev_only
        # the other inflation / macro prints are untouched
        for keep in ("KXPCE", "KXPPI", "KXGDP", "KXJOLTS", "KXUST10Y", "KXFED",
                     "KXUSGBEEF", "KXTRUFEGGS"):
            self.assertFalse(imm.series_pattern_blocked(keep), keep)
        # the earlier two entries still hold (the gas one in its 2026-09-27
        # form: states only while the GasBuddy gate is off)
        self.assertTrue(imm.series_pattern_blocked("KXAAAGASDNYC"))
        self.assertTrue(imm.series_pattern_blocked("KXTEMPMIAH"))

    def test_cpi_pilot_quotes_two_core_events_in_the_normal_book(self):
        # Jack 2026-09-28: "try the least bad version. keep size same as
        # normal IMM" -- KXCPICORE-26NOV/-26DEC only, normal size, weekday
        # 08:25-11:05 ET blackout, out 7 days before close; every other CPI
        # market stays blocked. No end date by default (Jack 2026-09-28 pm:
        # "keep it default running, dont block ... ill block if needed");
        # IMM_CPI_PILOT_UNTIL can still set one.
        self.assertEqual(imm.CPI_PILOT_EVENTS,
                         ("KXCPICORE-26DEC", "KXCPICORE-26NOV"))
        self.assertIsNone(imm.CPI_PILOT_UNTIL)
        prev_only, prev_until = imm.ALLOWLIST_ONLY, imm.CPI_PILOT_UNTIL
        try:
            imm.ALLOWLIST_ONLY = True
            for until in (None, datetime.now(timezone.utc) + timedelta(days=1)):
                imm.CPI_PILOT_UNTIL = until
                for t in ("KXCPICORE-26NOV-T0.3", "KXCPICORE-26DEC-T0.2"):
                    self.assertFalse(IncentiveMarketMaker._blocked(t), (t, until))
                    self.assertTrue(IncentiveMarketMaker._allowed(t), (t, until))
            # far in the future with no end date: still quoted
            imm.CPI_PILOT_UNTIL = None
            self.assertTrue(imm.cpi_pilot_active(
                "KXCPICORE-26DEC-T0.2", datetime(2026, 12, 31, tzinfo=timezone.utc)))
            # the rest of CPI stays blocked (the YoY core family is its own
            # test below)
            for t in ("KXCPICORE-26OCT-T0.3", "KXCPICORE-26SEP-T0.3",
                      "KXCPI-26NOV-T0.3", "KXCPI-26DEC-T0.2",
                      "KXCPIYOY-26DEC-T3.5"):
                self.assertTrue(IncentiveMarketMaker._blocked(t), t)
                self.assertFalse(IncentiveMarketMaker._allowed(t), t)
            # the family probe never opens the series, so no auto-enroll
            # path can write KXCPICORE into an allow file
            self.assertTrue(IncentiveMarketMaker._blocked("KXCPICORE-X"))
            self.assertTrue(imm.series_pattern_blocked("KXCPICORE"))
            # past the window the block closes over them again
            imm.CPI_PILOT_UNTIL = datetime.now(timezone.utc) - timedelta(seconds=1)
            for t in ("KXCPICORE-26NOV-T0.3", "KXCPICORE-26DEC-T0.2"):
                self.assertTrue(IncentiveMarketMaker._blocked(t), t)
                self.assertFalse(IncentiveMarketMaker._allowed(t), t)
        finally:
            imm.ALLOWLIST_ONLY, imm.CPI_PILOT_UNTIL = prev_only, prev_until
        # normal size: no family multiplier, no hand-tuned ladder or cap
        ov = imm.series_override("KXCPICORE")
        self.assertIsNone(ov.size_mult)
        self.assertIsNone(ov.levels)
        self.assertIsNone(ov.max_position)

        def at(y, mo, d, hh, mm):
            return imm.ET.localize(datetime(y, mo, d, hh, mm)).astimezone(timezone.utc)
        # weekday-only 08:25-11:05 ET blackout (Tue 9/29; Sat 10/3, Sun 10/4)
        self.assertFalse(imm.series_in_blackout("KXCPICORE", at(2026, 9, 29, 8, 24)))
        self.assertTrue(imm.series_in_blackout("KXCPICORE", at(2026, 9, 29, 8, 25)))
        self.assertTrue(imm.series_in_blackout("KXCPICORE", at(2026, 9, 29, 10, 0)))
        self.assertTrue(imm.series_in_blackout("KXCPICORE", at(2026, 9, 29, 11, 4)))
        self.assertFalse(imm.series_in_blackout("KXCPICORE", at(2026, 9, 29, 11, 5)))
        self.assertFalse(imm.series_in_blackout("KXCPICORE", at(2026, 10, 3, 9, 0)))
        self.assertFalse(imm.series_in_blackout("KXCPICORE", at(2026, 10, 4, 9, 0)))
        # weekday-only is opt-in: the AAA print blackout still runs Saturdays
        self.assertTrue(imm.series_in_blackout("KXAAAGASW", at(2026, 10, 3, 3, 20)))
        # out 7 days before close, i.e. a week before the event's own release
        close = datetime(2026, 12, 10, 13, 30, tzinfo=timezone.utc)
        cut = imm.apply_series_cutoff_adjustments(
            "KXCPICORE", "KXCPICORE-26NOV", None, close_time=close)
        self.assertEqual(cut, close - timedelta(days=7))

    def test_cpi_pilot_takes_the_whole_yoy_core_family(self):
        # Jack 2026-10-01: "yes add this family" (KXCPICOREYOY-26DEC's
        # program opened that day): every KXCPICOREYOY event, present and
        # future, quotes in the pilot under its guards; the series probe and
        # the other CPI families stay blocked.
        self.assertEqual(imm.CPI_PILOT_FAMILIES, ("KXCPICOREYOY",))
        self.assertIn("KXCPICOREYOY", imm.CPI_PILOT_SERIES)
        self.assertIn("KXCPICORE", imm.CPI_PILOT_SERIES)
        prev_only, prev_until = imm.ALLOWLIST_ONLY, imm.CPI_PILOT_UNTIL
        try:
            imm.ALLOWLIST_ONLY = True
            imm.CPI_PILOT_UNTIL = None
            for t in ("KXCPICOREYOY-26DEC-T3.0", "KXCPICOREYOY-26NOV-T2.5",
                      "KXCPICOREYOY-27MAR-T2.8", "KXCPICOREYOY-26DEC"):
                self.assertTrue(imm.cpi_pilot_active(t), t)
                self.assertFalse(IncentiveMarketMaker._blocked(t), t)
                self.assertTrue(IncentiveMarketMaker._allowed(t), t)
            # the normal book owns it, so the open scan never takes it
            self.assertEqual(imm.scan_universe_reason("KXCPICOREYOY-26DEC-T3.0"),
                             "allowed")
            # the probe, a bare series and look-alike series stay blocked
            for t in ("KXCPICOREYOY-X", "KXCPICOREYOY", "KXCPICOREYOYX-26DEC-T3.0",
                      "KXCPIYOY-26DEC-T3.5"):
                self.assertFalse(imm.cpi_pilot_active(t), t)
                self.assertTrue(IncentiveMarketMaker._blocked(t), t)
            self.assertEqual(imm.scan_universe_reason("KXCPIYOY-26DEC-T3.5"), "blocked")
            # an end date closes the family too
            imm.CPI_PILOT_UNTIL = datetime.now(timezone.utc) - timedelta(seconds=1)
            self.assertTrue(IncentiveMarketMaker._blocked("KXCPICOREYOY-26DEC-T3.0"))
        finally:
            imm.ALLOWLIST_ONLY, imm.CPI_PILOT_UNTIL = prev_only, prev_until
        # the same guards: weekday 08:25-11:05 ET blackout, out 7 days
        # before close, normal size
        def at(y, mo, d, hh, mm):
            return imm.ET.localize(datetime(y, mo, d, hh, mm)).astimezone(timezone.utc)
        self.assertTrue(imm.series_in_blackout("KXCPICOREYOY", at(2026, 10, 2, 9, 0)))
        self.assertFalse(imm.series_in_blackout("KXCPICOREYOY", at(2026, 10, 2, 11, 5)))
        self.assertFalse(imm.series_in_blackout("KXCPICOREYOY", at(2026, 10, 3, 9, 0)))
        close = datetime(2027, 1, 13, 13, 30, tzinfo=timezone.utc)
        self.assertEqual(imm.apply_series_cutoff_adjustments(
            "KXCPICOREYOY", "KXCPICOREYOY-26DEC", None, close_time=close),
            close - timedelta(days=7))
        ov = imm.series_override("KXCPICOREYOY")
        self.assertIsNone(ov.size_mult)
        self.assertIsNone(ov.levels)
        self.assertIsNone(ov.max_position)

    def test_company_headcount_events_are_blocked(self):
        # Jack 2026-09-24: "blocklist ... company headcount markets". The
        # Fiscal.ai KPI class names the metric in the EVENT segment
        # (KXAMZN-26OCTEMP = Amazon headcount in Q3, KXGOOGA-28JANHEAD =
        # Google headcount in 2026; 21 HEAD + 1 EMP events in the catalog),
        # so the block is an EVENT_BLOCK_PATTERNS full-match on the event
        # ticker and the company SERIES keeps its other KPIs. Meta's own
        # KXMETAHEADCOUNT series (26Q4 / 26JUL events, no suffix) is a
        # SERIES_BLOCK_PATTERNS entry. (The 2026-10-03 company-KPI cut
        # freezes these companies' whole series by name; lifted here, the
        # subject is the event-pattern block.)
        self.enterContext(_without_cut())
        prev_only = imm.ALLOWLIST_ONLY
        try:
            imm.ALLOWLIST_ONLY = True
            for t in ("KXAMZN-26OCTEMP-1600000.0", "KXAMZNA-28JANHEAD-1575000",
                      "KXGOOGA-28JANHEAD-205000", "KXINTC-26OCTHEAD-83500.0",
                      "KXSBUXA-26NOVHEAD-368000", "KXMETAHEADCOUNT-26Q4-70000",
                      "KXMETAHEADCOUNT-26JUL-70000", "KXNEWCO-27Q1HEAD-100",
                      "KXNEWCO-27JANEMPLOYEES-100"):
                self.assertTrue(IncentiveMarketMaker._blocked(t), t)
                self.assertFalse(IncentiveMarketMaker._allowed(t), t)
                self.assertEqual(imm.scan_universe_reason(t), "blocked", t)
            # the event ticker itself is blocked; the family probe is not,
            # so the company SERIES stays in the normal book
            self.assertTrue(IncentiveMarketMaker._blocked("KXAMZN-26OCTEMP"))
            self.assertFalse(IncentiveMarketMaker._blocked("KXAMZN-X"))
            self.assertTrue(IncentiveMarketMaker._allowed("KXAMZN-X"))
            # sibling KPIs of the same companies are untouched (the catalog's
            # near misses: DAP / CLICKS / IMPR / PROD / DEL / CARDS / MAU /
            # RESTS / STORES / COMPTXN / F35 / PREMSUBS), and so is anything
            # whose KPI merely CONTAINS the letters
            for keep in ("KXMETA-26OCTDAP-3.5", "KXGOOG-26OCTCLICKS-T5",
                         "KXAMZN-26OCTREV-T170", "KXSBUXA-28JANSTORES-42000",
                         "KXTSLAA-28JANDEL-1800000", "KXBA-26OCTDELIV-T45",
                         "KXAMZN-26OCTTEMP-1", "KXAMZN-26OCTHEADLINE-1",
                         "KXTEMPHELP-26SEP17-X"):
                self.assertFalse(IncentiveMarketMaker._blocked(keep), keep)
        finally:
            imm.ALLOWLIST_ONLY = prev_only
        # standard semantics: a named event can still be exempted to quote
        # to completion, its siblings stay frozen
        ev = "KXAMZN-26OCTEMP"
        prev = imm.BLOCKLIST_WIND_DOWN_EVENTS
        try:
            imm.BLOCKLIST_WIND_DOWN_EVENTS = frozenset({ev})
            self.assertFalse(IncentiveMarketMaker._blocked(f"{ev}-1600000.0"))
            self.assertTrue(
                IncentiveMarketMaker._blocked("KXAMZNA-28JANHEAD-1575000"))
        finally:
            imm.BLOCKLIST_WIND_DOWN_EVENTS = prev
        # full-match on the event ticker; env-configurable like the others
        self.assertTrue(imm.event_pattern_blocked("KXAMZN-26OCTEMP"))
        self.assertFalse(imm.event_pattern_blocked("KXAMZN-26OCTEMPX"))
        self.assertEqual(imm.event_ticker_of("KXAMZN-26OCTEMP-1600000.0"),
                         "KXAMZN-26OCTEMP")
        self.assertEqual(imm.event_ticker_of("KXAMZN-26OCTEMP"), "KXAMZN-26OCTEMP")
        self.assertEqual(imm.event_ticker_of("KXAMZN-X"), "KXAMZN-X")
        with mock.patch.object(imm, "EVENT_BLOCK_PATTERNS", ()):
            self.assertFalse(imm.event_pattern_blocked("KXAMZN-26OCTEMP"))

    def test_event_top_n_gas_cap(self):
        # Jack 2026-09-02: gas events quote only the 3 highest-ROI markets
        # (all strikes settle on the same AAA print — correlated inventory).
        def m(t, est, expo=10.0, coll=0.0):
            return imm.MarketMeta(
                ticker=t, event_ticker=t.rsplit("-", 1)[0],
                series=t.split("-")[0], dollars_per_day=20.0,
                program_end=None, target_size=1000, discount_factor=0.5,
                cutoff=None, close_time=None, est_dollars_per_day=est,
                est_exposure_dollars=expo, est_collateral_dollars=coll)
        gas = [m("KXAAAGASDIL-26SEP03-4.20", 2.0),
               m("KXAAAGASDIL-26SEP03-4.21", 3.0),
               m("KXAAAGASDIL-26SEP03-4.22", 1.0),
               m("KXAAAGASDIL-26SEP03-4.23", 4.0),
               m("KXAAAGASDIL-26SEP03-4.24", 0.5)]
        rain = [m("KXRAINNYC-26SEP03-X", 0.01) for _ in range(5)]
        cut = imm.event_top_n_cut(gas + rain, incumbent=set())
        # keep ROI 0.4/0.3/0.2 -> cut the 1.0 and 0.5 est markets; rain
        # (uncapped series) untouched however weak.
        self.assertEqual(cut, {"KXAAAGASDIL-26SEP03-4.22",
                               "KXAAAGASDIL-26SEP03-4.24"})
        # national daily + weekly + states all resolve to N=3 via the
        # KXAAAGAS prefix, diesel D/W via KXDIESEL (2026-09-02 "do the
        # same with diesel"); other families are uncapped.
        for s in ("KXAAAGASD", "KXAAAGASDOH", "KXAAAGASW", "KXAAAGASM",
                  "KXDIESELD", "KXDIESELW"):
            self.assertEqual(imm.event_top_n_for(s), 3, s)
        for s in ("KXRAINNYC", "KXBKFT", "KXCLAUDEAPP", "KXUSGASCPI"):
            self.assertEqual(imm.event_top_n_for(s), 0, s)
        # KXTRUEV unblocked 2026-09-07 ("unblock KXTRUEV but only quote the
        # top 3 ROI markets") and SUNSET 2026-09-11: the cap is kept for the
        # wind-down event (and any later un-block); past and future events
        # are frozen by the blocklist entry; the prefix is exact-family so
        # the unrelated KXTRUFAIDP stays uncapped/blocked.
        self.assertEqual(imm.event_top_n_for("KXTRUEV"), 3)
        self.assertFalse(IncentiveMarketMaker._allowed(
            "KXTRUEV-26SEP07-T1243.42"))
        self.assertTrue(IncentiveMarketMaker._allowed(
            "KXTRUEV-26SEP11-T1213.73"))
        self.assertEqual(imm.event_top_n_for("KXTRUFAIDP"), 0)
        self.assertTrue(any(p == "KXTRUEV"
                            for p in imm.SERIES_BLOCKLIST_PREFIXES))
        # incumbency (1.15x) holds a member's slot on a near-tie: fresh 2.05
        # vs member 2.0 -> member ROI 0.2*1.15=0.23 beats 0.205.
        tie = [m("KXAAAGASDTX-26SEP03-3.60", 2.0),
               m("KXAAAGASDTX-26SEP03-3.61", 2.05),
               m("KXAAAGASDTX-26SEP03-3.62", 5.0),
               m("KXAAAGASDTX-26SEP03-3.63", 5.0)]
        cut = imm.event_top_n_cut(tie, incumbent={"KXAAAGASDTX-26SEP03-3.60"})
        self.assertEqual(cut, {"KXAAAGASDTX-26SEP03-3.61"})
        # exposure fallback: no exposure -> plain collateral ranks it; no
        # denominator at all -> ROI 0 (cut first).
        fb = [m("KXAAAGASDCA-26SEP03-5.60", 4.0, expo=0.0, coll=8.0),
              m("KXAAAGASDCA-26SEP03-5.61", 4.0),
              m("KXAAAGASDCA-26SEP03-5.62", 4.0, expo=0.0, coll=0.0),
              m("KXAAAGASDCA-26SEP03-5.63", 1.0)]
        cut = imm.event_top_n_cut(fb, incumbent=set())
        self.assertEqual(cut, {"KXAAAGASDCA-26SEP03-5.62"})
        # a group at/below N is never touched
        self.assertEqual(imm.event_top_n_cut(gas[:3], set()), set())
        # env spec sanity
        # exact-match form (2026-09-25, KXART): longest-first sort keeps
        # it beside the prefix/suffix forms; a bare '=' is rejected
        self.assertEqual(imm._parse_event_top_n("=KXART:3,*CC:3"),
                         (("=KXART", 3), ("*CC", 3)))
        with self.assertRaises(ValueError):
            imm._parse_event_top_n("=:3")
        self.assertEqual(imm._parse_event_top_n("KXAAAGAS:3,KXDIESEL:2"),
                         (("KXAAAGAS", 3), ("KXDIESEL", 2)))
        with self.assertRaises(ValueError):
            imm._parse_event_top_n("KXAAAGAS")
        # *CC:3 (Jack 2026-09-10 "just quote max 3 markets per event, based
        # on ROI, for CC family"): a leading '*' is a series-name SUFFIX.
        # Longest pattern still wins; a bare '*' or empty pattern is a
        # config error, not a match-everything.
        self.assertEqual(imm._parse_event_top_n("*CC:3,KXAAAGAS:3"),
                         (("KXAAAGAS", 3), ("*CC", 3)))
        with self.assertRaises(ValueError):
            imm._parse_event_top_n("*:3")
        # the Carbon Arc suffix caps were LIFTED 2026-10-01 (Jack: "remove
        # the 3 max cap on carbon arc, ramp AI index"): every strike of a
        # *CC / *ADS / *POS event may quote by default
        self.assertEqual(imm.CA_FAMILY_EVENT_TOP_N, 0)
        self.assertEqual(imm._CA_FAMILY_EVENT_TOP_N_SPEC, "")
        self.assertIn("CA_FAMILY_EVENT_TOP_N", imm._CONFIG_CODE_KNOBS)
        for s in ("KXURBNCC", "KXAMZNCC", "KXCOSTCC", "KXDGCC",
                  "KXNEVERSEENCC", "KXCASINOADS", "KXDRPEPPERPOS"):
            self.assertEqual(imm.event_top_n_for(s), 0, s)
        cc = [m(f"KXURBNCC-26OCT07-T{90 + 3 * i}", float(9 - i))
              for i in range(9)]
        self.assertEqual(imm.event_top_n_cut(cc, incumbent=set()), set())
        # ...and IMM_CA_FAMILY_EVENT_TOP_N=3 restores the suffix rule: a
        # series ENDING in CC is capped, one merely CONTAINING it is not,
        # and the cut works on a CC event: 9 strikes -> 3 by ROI
        with mock.patch.object(imm, "EVENT_TOP_N",
                               imm._parse_event_top_n("*CC:3,*ADS:3,*POS:3")):
            for s in ("KXURBNCC", "KXAMZNCC", "KXCASINOADS", "KXDRPEPPERPOS"):
                self.assertEqual(imm.event_top_n_for(s), 3, s)
            for s in ("KXCCL", "KXCCMONTHLY", "KXSBUX"):
                self.assertEqual(imm.event_top_n_for(s), 0, s)
            cut = imm.event_top_n_cut(cc, incumbent=set())
            self.assertEqual(len(cut), 6)
            self.assertEqual({t for t in {x.ticker for x in cc} - cut},
                             {"KXURBNCC-26OCT07-T90", "KXURBNCC-26OCT07-T93",
                              "KXURBNCC-26OCT07-T96"})

    def test_event_top_n_members_hold_their_slots(self):
        # Jack 2026-09-06 "the quoted markets are moving around, it should
        # be constant". The estimator scores a QUOTING market on its real
        # resting orders and an idle one on a hypothetical full ladder, so
        # idle siblings read ~2.5x higher and the old re-rank swapped a slot
        # nearly every refresh. Members now hold their slots.
        def m(t, est, expo=10.0, coll=0.0):
            return imm.MarketMeta(
                ticker=t, event_ticker=t.rsplit("-", 1)[0],
                series=t.split("-")[0], dollars_per_day=20.0,
                program_end=None, target_size=1000, discount_factor=0.5,
                cutoff=None, close_time=None, est_dollars_per_day=est,
                est_exposure_dollars=expo, est_collateral_dollars=coll)
        # the live pattern: 3 quoting members read low, idle siblings read
        # 2.5x higher. Even 10x cannot displace a member now.
        mem = {"KXAAAGASDNY-26SEP07-4.3150", "KXAAAGASDNY-26SEP07-4.3200",
               "KXAAAGASDNY-26SEP07-4.3300"}
        grp = [m("KXAAAGASDNY-26SEP07-4.3150", 2.9),
               m("KXAAAGASDNY-26SEP07-4.3200", 2.3),
               m("KXAAAGASDNY-26SEP07-4.3300", 1.5),
               m("KXAAAGASDNY-26SEP07-4.3100", 15.0),
               m("KXAAAGASDNY-26SEP07-4.3050", 30.0)]
        self.assertEqual(
            imm.event_top_n_cut(grp, incumbent=mem, members=mem),
            {"KXAAAGASDNY-26SEP07-4.3100", "KXAAAGASDNY-26SEP07-4.3050"})
        # without the member set that is exactly the churn we fixed: both
        # weak members get swapped out for the idle pair.
        self.assertEqual(
            imm.event_top_n_cut(grp, incumbent=mem),
            {"KXAAAGASDNY-26SEP07-4.3300", "KXAAAGASDNY-26SEP07-4.3200"})
        # a free slot still admits the best challenger...
        self.assertEqual(
            imm.event_top_n_cut(grp, incumbent=mem,
                                members=mem - {"KXAAAGASDNY-26SEP07-4.3300"}),
            {"KXAAAGASDNY-26SEP07-4.3300", "KXAAAGASDNY-26SEP07-4.3100"})
        # ...and the cap stays a HARD bound: members alone past N (an N
        # lowered by config, a restart restoring a wider set) are trimmed
        # worst-ROI-first rather than riding over the cap.
        wide = mem | {"KXAAAGASDNY-26SEP07-4.3100",
                      "KXAAAGASDNY-26SEP07-4.3050"}
        self.assertEqual(
            imm.event_top_n_cut(grp, incumbent=wide, members=wide),
            {"KXAAAGASDNY-26SEP07-4.3300", "KXAAAGASDNY-26SEP07-4.3200"})
        # immune (finecon/scan) outranks member tenure: it consumes the
        # event's N first, and a member past what is left is trimmed.
        self.assertEqual(
            imm.event_top_n_cut(grp, incumbent=mem, members=mem,
                                immune={"KXAAAGASDNY-26SEP07-4.3050"}),
            {"KXAAAGASDNY-26SEP07-4.3300", "KXAAAGASDNY-26SEP07-4.3100"})

    def test_event_top_n_two_sided_beats_roi(self):
        # Jack 2026-09-07, KXTRUEV-26SEP07-T1263.42 taking a slot over
        # T1253.42: "only supports 1 side quoting, and is more likely to
        # fall out of the quoting range and stop earning". Live numbers from
        # that admission — the one-sided market won on the DENOMINATOR.
        def m(t, est, expo, sides=2):
            return imm.MarketMeta(
                ticker=t, event_ticker=t.rsplit("-", 1)[0],
                series=t.split("-")[0], dollars_per_day=106.89,
                program_end=None, target_size=1000, discount_factor=0.5,
                cutoff=None, close_time=None, est_dollars_per_day=est,
                est_exposure_dollars=expo, est_collateral_dollars=0.0,
                quotable_sides=sides)
        ev = "KXTRUEV-26SEP07"
        grp = [m(f"{ev}-T1243.42", 3.6649, 12.20),          # ROI 0.300
               m(f"{ev}-T1253.42", 2.5171, 25.10),          # ROI 0.100
               m(f"{ev}-T1233.42", 2.3465, 10.80),          # ROI 0.217
               m(f"{ev}-T1263.42", 2.4929, 19.00, sides=1)]  # ROI 0.131, 1-sided
        # ROI alone put T1263 third and cut T1253; two-sidedness reverses it.
        self.assertEqual(imm.event_top_n_cut(grp, incumbent=set()),
                         {f"{ev}-T1263.42"})
        # a one-sided MEMBER forfeits tenure — this is what lets the fix move
        # a slot that has already gone one-sided
        self.assertEqual(
            imm.event_top_n_cut(grp, incumbent={f"{ev}-T1263.42"},
                                members={f"{ev}-T1263.42"}),
            {f"{ev}-T1263.42"})
        # ...while a two-sided member keeps it against a better challenger
        self.assertNotIn(f"{ev}-T1253.42",
                         imm.event_top_n_cut(grp, incumbent={f"{ev}-T1253.42"},
                                             members={f"{ev}-T1253.42"}))
        # not an outright exclusion: with only two two-sided candidates the
        # one-sided market still takes the spare slot rather than idling it
        thin = [grp[0], grp[1], grp[3]]
        self.assertEqual(imm.event_top_n_cut(thin, incumbent=set()), set())
        # immune (finecon/scan quote-to-completion) is never broken by this
        self.assertNotIn(f"{ev}-T1263.42",
                         imm.event_top_n_cut(grp, incumbent=set(),
                                             immune={f"{ev}-T1263.42"}))
        # knob off -> the old pure-ROI order, which cut T1253
        imm.EVENT_TOP_N_TWO_SIDED = False
        try:
            self.assertEqual(imm.event_top_n_cut(grp, incumbent=set()),
                             {f"{ev}-T1253.42"})
        finally:
            imm.EVENT_TOP_N_TWO_SIDED = True
        # metas built outside the estimator fail OPEN (default 2)
        self.assertEqual(imm.MarketMeta(
            ticker="x", event_ticker="x", series="x", dollars_per_day=0.0,
            program_end=None, target_size=0, discount_factor=0.5,
            cutoff=None, close_time=None).quotable_sides, 2)

    def test_event_top_n_lifetime_slots(self):
        # Jack 2026-09-07: "3 max quoted markets on an event, not 3 at a
        # given time. so if 2 drop then none replace them."
        def m(t, est, expo, sides=2):
            return imm.MarketMeta(
                ticker=t, event_ticker=t.rsplit("-", 1)[0],
                series=t.split("-")[0], dollars_per_day=100.0,
                program_end=None, target_size=1000, discount_factor=0.5,
                cutoff=None, close_time=None, est_dollars_per_day=est,
                est_exposure_dollars=expo, est_collateral_dollars=0.0,
                quotable_sides=sides)
        ev = "KXDIESELW-26SEP14"
        grp = [m(f"{ev}-T5.92", 2.0, 10.0),
               m(f"{ev}-T5.94", 0.6, 16.6, sides=1),
               m(f"{ev}-T5.96", 0.6, 19.8, sides=0),
               m(f"{ev}-T5.84", 1.9, 9.0),
               m(f"{ev}-T5.86", 3.8, 12.6)]
        # THE REGRESSION: the concurrent cap handed T5.94/T5.96's slots to
        # T5.84/T5.86, so the event ended the day holding inventory in five
        # strikes. With the ledger spent on the first three, the two
        # newcomers are refused however good they look...
        # the ledger is ORDERED by when each market took its slot
        spent = {ev: [f"{ev}-T5.92", f"{ev}-T5.94", f"{ev}-T5.96"]}
        self.assertEqual(
            imm.event_top_n_cut(grp, incumbent=set(), slots_used=spent),
            {f"{ev}-T5.84", f"{ev}-T5.86"})
        # ...and a spent market keeps its slot even one-sided, because with
        # the ledger full there is no two-sided market that could take it —
        # yielding would idle the slot, not reallocate it.
        self.assertNotIn(f"{ev}-T5.94",
                         imm.event_top_n_cut(grp, incumbent=set(),
                                             slots_used=spent))
        # a partly-spent ledger opens only the remainder, best first
        self.assertEqual(
            imm.event_top_n_cut(grp, incumbent=set(),
                                slots_used={ev: [f"{ev}-T5.92"]}),
            {f"{ev}-T5.94", f"{ev}-T5.96"})     # T5.86, T5.84 take the two
        # dropping out refunds NOTHING: T5.94/T5.96 gone from the candidate
        # list entirely, and the newcomers are still refused
        self.assertEqual(
            imm.event_top_n_cut([grp[0], grp[3], grp[4]], incumbent=set(),
                                slots_used=spent),
            {f"{ev}-T5.84", f"{ev}-T5.86"})
        # the lifetime budget also binds when the event has <= N candidates
        # (the old early-continue would have waved this through)
        self.assertEqual(
            imm.event_top_n_cut([grp[3]], incumbent=set(), slots_used=spent),
            {f"{ev}-T5.84"})

        # KXAAAGASDGA-26SEP08: wide books, EVERY candidate one-sided, so
        # nothing earned two-sided tenure and the ROI rank alternated the
        # third slot ~every refresh (3.8800 est 2.07 idle / 0.48 quoting).
        # With the ledger full nothing is ranked, so nothing can flip.
        ga = "KXAAAGASDGA-26SEP08"
        pair = [m(f"{ga}-3.8800", 2.0672, 3.40, sides=1),
                m(f"{ga}-3.8850", 0.3328, 1.40, sides=1),
                m(f"{ga}-3.8550", 1.0, 5.0, sides=1)]
        ga_spent = {ga: [f"{ga}-3.8800", f"{ga}-3.8850", f"{ga}-3.8550"]}
        first = imm.event_top_n_cut(pair, incumbent=set(), slots_used=ga_spent)
        # swap the est values the way the estimator does between refreshes
        pair[0].est_dollars_per_day, pair[1].est_dollars_per_day = 0.4833, 1.9865
        second = imm.event_top_n_cut(pair, incumbent=set(), slots_used=ga_spent)
        self.assertEqual(first, set())
        self.assertEqual(first, second)      # no churn across the swing

        # a ledger somehow OVER N (a lowered N, a seeded ledger) stays a
        # hard bound, and trims by slot ORDER so it cannot churn: the
        # earliest three keep their slots on every refresh.
        over = {ev: [f"{ev}-T5.92", f"{ev}-T5.94", f"{ev}-T5.96",
                     f"{ev}-T5.84", f"{ev}-T5.86"]}
        trimmed = imm.event_top_n_cut(grp, incumbent=set(), slots_used=over)
        self.assertEqual(trimmed, {f"{ev}-T5.84", f"{ev}-T5.86"})
        for meta in grp:                      # est swings must not move it
            meta.est_dollars_per_day *= 7.0
        self.assertEqual(
            imm.event_top_n_cut(grp, incumbent=set(), slots_used=over), trimmed)
        for meta in grp:
            meta.est_dollars_per_day /= 7.0

        # knob off -> the concurrent cap, which is what churned
        imm.EVENT_TOP_N_LIFETIME = False
        try:
            self.assertEqual(
                imm.event_top_n_cut(grp, incumbent=set(), slots_used=spent),
                {f"{ev}-T5.94", f"{ev}-T5.96"})   # replaced by the newcomers
        finally:
            imm.EVENT_TOP_N_LIFETIME = True

    def test_finecon_sweep_enrollment_and_guards(self):
        # Jack 2026-09-02: Finance/Economics sweep — the risk-screened
        # survivors are allowed, guarded (safe-join, no rate bar), and the
        # AAA touch-extreme monthlies join the print blackout + KXAAAGAS:3.
        # _allowed is tested with the REAL policy: the suite's setUpModule
        # turns ALLOWLIST_ONLY off for fixture series, and sibling classifier
        # tests leave EXTRA_ALLOW_SERIES scratch behind — both restored.
        # The 2026-10-03 cut (the KPI set, the two food trackers, the AAA
        # max/min pair) blocks members by name; lifted here, the subject is
        # finecon membership and its guards.
        self.enterContext(_without_cut())
        saved_extra = set(imm.EXTRA_ALLOW_SERIES)
        imm.EXTRA_ALLOW_SERIES.clear()
        imm.ALLOWLIST_ONLY = True
        try:
            for s in ("KXSPRLVL", "KXCBDECISIONNZ", "KXCBDISRAEL",
                      "KXVENEZCRUDE", "KXAAAGASMINM", "KXAAAGASMAXM",
                      "KXBRAZILGDP", "KXJOLTSOPEN", "KXDATACENTCON",
                      "KXWENBACONATOR", "KXTBCRUNCHWRAP",
                      # 2026-09-04 additions: company-KPI set + the two
                      # state statistics Jack asked after by name
                      "KXDKS", "KXZM", "KXURBN", "KXLOW", "KXDG", "KXAFRM",
                      "KXBBY", "KXWSM", "KXOKTA", "KXTXOIL", "KXVAPORTTEU"):
                self.assertIn(s, imm.FINECON_SERIES, s)
                self.assertTrue(
                    IncentiveMarketMaker._allowed(f"{s}-26OCT13-T1"), s)
                self.assertTrue(imm.series_safe_join(s), s)
                self.assertEqual(imm.series_min_est_rate(s), 0.0, s)
            # 2026-09-05's Carbon Arc dated-observation members LEFT the
            # group: KXAMZNCC on 2026-09-10 (*CC), the 11 ad-spend series
            # and KXDRPEPPERPOS on 2026-09-22 (*ADS / *POS) -- all three
            # families are name-pattern members of the NORMAL book now
            # (test_cc_family_suffix_allows_into_normal_book)
            for s in ("KXFOOTWEARADS", "KXELECTRONICSADS", "KXCASINOADS",
                      "KXDRPEPPERPOS", "KXAMZNCC"):
                self.assertNotIn(s, imm.FINECON_SERIES, s)
                self.assertTrue(imm.series_family_suffix(s), s)
            # the KPI members' release guard: the overrides task must treat
            # them as company-disclosure series with a Nasdaq symbol to
            # resolve the report time (their tickers carry no day, so the
            # midnight-ET rule can never protect a report-week period).
            import imm_earnings_overrides as ieo
            for s in imm._FINECON_KPI_SERIES.split(","):
                self.assertIn(s, ieo.COMPANY_DISCLOSURE_SERIES, s)
                self.assertIn(s, ieo.COMPANY_TICKERS, s)
            for s in ("KXAAAGASMINM", "KXAAAGASMAXM"):
                self.assertEqual(imm.SERIES_OVERRIDES[s].blackout_et,
                                 imm.SERIES_OVERRIDES["KXAAAGASM"].blackout_et,
                                 s)
                self.assertEqual(imm.event_top_n_for(s), 3, s)
            # the risk-rejected classes stay out (realtime feeds,
            # quote-through releases) — a sample, not the full list
            for s in ("KXEURUSDAW", "KXCAC40", "KXUE", "KXISMPMI",
                      "KXSNOWCRABCATCH", "KXSOCKEYERUN", "KXUSOPENPRICE",
                      "KXTECHLAYOFF"):
                self.assertNotIn(s, imm.FINECON_SERIES, s)
                self.assertFalse(
                    IncentiveMarketMaker._allowed(f"{s}-26OCT13-T1"), s)
        finally:
            imm.ALLOWLIST_ONLY = False
            imm.EXTRA_ALLOW_SERIES.update(saved_extra)

    def test_finecon_group_cut_top10_max3_per_event(self):
        # Jack 2026-09-02: "quote the top 10 markets based on ROI (with no
        # more than 3 on a single event)" across the finecon group.
        def m(t, est, expo=10.0):
            return imm.MarketMeta(
                ticker=t, event_ticker=t.rsplit("-", 1)[0],
                series=t.split("-")[0], dollars_per_day=20.0,
                program_end=None, target_size=1000, discount_factor=0.5,
                cutoff=None, close_time=None, est_dollars_per_day=est,
                est_exposure_dollars=expo, est_collateral_dollars=0.0)
        # 5 SPR strikes with the top ROIs: only 3 may survive; the slack
        # goes to lower-ROI markets of OTHER events.
        spr = [m(f"KXSPRLVL-26SEP09-T28{i}", 9.0 - i) for i in range(5)]
        nz = [m("KXCBDECISIONNZ-26OCT27-HOLD", 3.0),
              m("KXCBDECISIONNZ-26OCT27-H25", 2.9)]
        vz = [m(f"KXVENEZCRUDE-26OCT13-T1{i}00000", 2.0 - i * 0.1)
              for i in range(3)]
        gas = [m(f"KXAAAGASMINM-26SEP30-3.{60 + i}", 1.0 - i * 0.1)
               for i in range(4)]
        wen = [m("KXWENBACONATOR-26OCT02-T8.5", 0.05)]
        rain = [m("KXRAINNYC-26SEP03-X", 50.0)]     # not in the group
        # default cap is 15 since 2026-09-04 (Jack "increase from 10 to
        # 15"); the walk-semantics assertions below pin 10 so the slot
        # competition they encode stays exercised.
        self.assertEqual(imm.FINECON_TOP_N, 25)   # 15->20->25, Jack 2026-09-09
        self.assertEqual(imm.FINECON_DAILY_OPENINGS, 10)  # 5 -> 10, same day
        try:
            imm.FINECON_TOP_N, _n10 = 10, imm.FINECON_TOP_N
            cut = imm.finecon_group_cut(spr + nz + vz + gas + wen + rain,
                                        incumbent=set())
        finally:
            imm.FINECON_TOP_N = _n10
        kept = {x.ticker for x in spr + nz + vz + gas + wen} - cut
        self.assertEqual(len(kept), 10)
        self.assertEqual(sum(1 for t in kept if t.startswith("KXSPRLVL")), 3)
        self.assertEqual(sum(1 for t in kept if t.startswith("KXCBDEC")), 2)
        self.assertEqual(sum(1 for t in kept if t.startswith("KXVENEZ")), 3)
        # 10th slot: two gas strikes beat the $0.05 Baconator
        self.assertEqual(sum(1 for t in kept if t.startswith("KXAAAGAS")), 2)
        self.assertIn("KXWENBACONATOR-26OCT02-T8.5", cut)
        # ungrouped series are never touched, however strong or weak
        self.assertNotIn("KXRAINNYC-26SEP03-X", cut)
        # QUOTE-TO-COMPLETION (Jack 2026-09-03 "once start quoting, should
        # quote to completion. dont unquote them"): a member is NEVER cut,
        # however badly outranked — it consumes slots and only newcomers
        # compete for the remainder.
        edge = [m(f"KXSPRLVL-26SEP09-T28{i}", 5.0) for i in range(3)] \
            + [m("KXVENEZCRUDE-26OCT13-A", 0.01),
               m("KXBRAZILGDP-26DEC02-B", 4.0)]
        try:
            imm.FINECON_TOP_N, _n = 4, imm.FINECON_TOP_N
            # worst-ROI market is a member -> kept; the strong Brazil
            # newcomer loses: only one free slot and SPR ROIs beat it.
            cut = imm.finecon_group_cut(
                edge, incumbent=set(), members={"KXVENEZCRUDE-26OCT13-A"})
            self.assertEqual(cut, {"KXBRAZILGDP-26DEC02-B"})
            # members consume an EVENT's slots too: 3 SPR members block a
            # 4th SPR strike however strong; the open global slot goes to
            # the best other-event newcomer instead.
            spr_members = {f"KXSPRLVL-26SEP09-T28{i}" for i in range(3)}
            edge2 = [m(f"KXSPRLVL-26SEP09-T28{i}", 0.01) for i in range(3)] \
                + [m("KXSPRLVL-26SEP09-T289", 9.0),
                   m("KXBRAZILGDP-26DEC02-B", 0.5)]
            cut = imm.finecon_group_cut(edge2, set(), members=spr_members)
            self.assertEqual(cut, {"KXSPRLVL-26SEP09-T289"})
            # members beyond a lowered cap ALL stay; nothing new enters.
            imm.FINECON_TOP_N = 2
            cut = imm.finecon_group_cut(edge2, set(), members=spr_members)
            self.assertEqual(cut, {"KXSPRLVL-26SEP09-T289",
                                   "KXBRAZILGDP-26DEC02-B"})
            # knob off -> no cut at all
            imm.FINECON_TOP_N = 0
            self.assertEqual(imm.finecon_group_cut(edge, set()), set())
        finally:
            imm.FINECON_TOP_N = _n
        # the same immunity reaches the KXAAAGAS:3 per-event cut, which
        # catches KXAAAGASMINM/MAXM: an immune member is kept at any ROI
        # and shrinks the slots the rest compete for.
        minm = [m(f"KXAAAGASMINM-26SEP30-3.{60 + i}", 5.0 - i)
                for i in range(5)]                      # 3.64 = worst ROI
        cut = imm.event_top_n_cut(minm, incumbent=set(),
                                  immune={"KXAAAGASMINM-26SEP30-3.64"})
        self.assertEqual(cut, {"KXAAAGASMINM-26SEP30-3.62",
                               "KXAAAGASMINM-26SEP30-3.63"})

    def test_finecon_daily_openings(self):
        # Jack 2026-09-05: "add 5 openings each day to the 15 quoted...
        # so that new events have a chance to be quoted if high ROI even
        # if the main 15 slots are full."
        def m(t, est, expo=10.0):
            return imm.MarketMeta(
                ticker=t, event_ticker=t.rsplit("-", 1)[0],
                series=t.split("-")[0], dollars_per_day=20.0,
                program_end=None, target_size=1000, discount_factor=0.5,
                cutoff=None, close_time=None, est_dollars_per_day=est,
                est_exposure_dollars=expo, est_collateral_dollars=0.0)
        # a full house: FINECON_TOP_N members, 3 per event (cap-legal).
        # Built from the constant so the 2026-09-09 raise to 20 does not
        # leave the group half-empty and let newcomers in for free.
        _n = imm.FINECON_TOP_N
        members = [m(f"KXSPRLVL-26SEP{9 + (i // 3):02d}-T{i % 3}", 1.0)
                   for i in range(_n)]
        mem_ids = {x.ticker for x in members}
        new = [m("KXVENEZCRUDE-26OCT07-T100", 9.0),
               m("KXVENEZCRUDE-26OCT07-T102", 8.0),
               m("KXJOLTSOPEN-26OCT03-T95", 7.0),
               m("KXBRAZILGDP-26DEC02-T2.2", 6.0)]
        # no openings: cap full -> every newcomer cut (yesterday's rule)
        cut = imm.finecon_group_cut(members + new, set(), members=mem_ids)
        self.assertEqual(cut, {x.ticker for x in new})
        # 2 openings: the two best go through the full cap; the rest wait
        cut = imm.finecon_group_cut(members + new, set(), members=mem_ids,
                                    extra_openings=2)
        self.assertEqual(cut, {"KXJOLTSOPEN-26OCT03-T95",
                               "KXBRAZILGDP-26DEC02-T2.2"})
        # openings never override the 3-per-event bound: a 3rd VENEZCRUDE
        # strike is skipped, the opening flows to the next event instead
        new3 = new + [m("KXVENEZCRUDE-26OCT07-T104", 8.5)]
        cut = imm.finecon_group_cut(members + new3, set(), members=mem_ids,
                                    extra_openings=3)
        kept = {x.ticker for x in new3} - cut
        self.assertEqual(kept, {"KXVENEZCRUDE-26OCT07-T100",
                                "KXVENEZCRUDE-26OCT07-T102",
                                "KXVENEZCRUDE-26OCT07-T104"})
        # 3 VENEZCRUDE strikes IS the per-event cap — legal. A 4th VENEZCRUDE
        # (the event's weakest, T102 at 8.0 vs T106's 8.2) is refused
        # even with openings to spare; the opening flows on to JOLTS.
        new4 = new3 + [m("KXVENEZCRUDE-26OCT07-T106", 8.2)]
        cut = imm.finecon_group_cut(members + new4, set(), members=mem_ids,
                                    extra_openings=5)
        self.assertIn("KXVENEZCRUDE-26OCT07-T102", cut)
        self.assertNotIn("KXVENEZCRUDE-26OCT07-T106", cut)
        self.assertNotIn("KXJOLTSOPEN-26OCT03-T95", cut)
        # the openings-burn accounting: only over-cap admissions count.
        # Relative to FINECON_TOP_N so a cap change (15 -> 20 on
        # 2026-09-09) cannot silently turn these into no-ops.
        _n = imm.FINECON_TOP_N
        self.assertEqual(imm.finecon_openings_used(_n + 2, _n), 2)
        self.assertEqual(imm.finecon_openings_used(_n, _n), 0)
        # members already OVER the cap: growth is charged past THEM, not the cap
        self.assertEqual(imm.finecon_openings_used(_n + 5, _n + 2), 3)
        # under cap and under membership: in-cap fills are free
        self.assertEqual(imm.finecon_openings_used(_n - 1, _n - 3), 0)

    def test_finecon_group_is_bounded_and_refills(self):
        """Jack 2026-09-09: "yes add it" — the finecon walk had no ceiling.
        admit_cap was max(members, FINECON_TOP_N) + openings, so each ET day's
        openings stacked on the previous high-water mark and only attrition
        pulled it back. Measured that day 15:28Z: 30 members against a nominal
        25 with all 10 openings spent = a 40-market cap the next morning, 80
        inside a week at zero attrition. Same bound + refill the open scan got
        on 2026-09-05/09."""
        self.assertTrue(imm.FINECON_REFILL_ON_DEPARTURE)
        self.assertEqual(imm.finecon_ceiling(),
                         imm.FINECON_TOP_N + imm.FINECON_DAILY_OPENINGS)

        def m(t, est):
            return imm.MarketMeta(
                ticker=t, event_ticker=t.rsplit("-", 1)[0],
                series=t.split("-")[0], dollars_per_day=20.0, program_end=None,
                target_size=1000, discount_factor=0.5, cutoff=None,
                close_time=None, est_dollars_per_day=est,
                est_exposure_dollars=10.0, est_collateral_dollars=0.0)

        cap, opens = imm.FINECON_TOP_N, imm.FINECON_DAILY_OPENINGS
        ceiling = imm.finecon_ceiling()
        # newcomers are SPR strikes on distinct events so FINECON_EVENT_TOP_N
        # can never be what bounds the result here.
        newcomers = [m(f"KXSPRLVL-26DEC{1 + i:02d}-T1", 0.5) for i in range(20)]

        # BOUNDED: the live 2026-09-09 shape — over the cap, a full day of
        # openings left. Uncapped this admitted 30 + 10 = 40.
        over = [m(f"KXSPRLVL-26SEP{9 + (i // 3):02d}-T{i % 3}", 1.0)
                for i in range(cap + 5)]
        mem_over = {x.ticker for x in over}
        cut = imm.finecon_group_cut(over + newcomers, set(), members=mem_over,
                                    extra_openings=opens, refill_to=len(over))
        self.assertEqual(len(over) + len(newcomers) - len(cut), ceiling,
                         "the group grew past its ceiling")

        # members are NEVER evicted by the ceiling — they quote to completion.
        # A group already above it simply admits nobody until attrition.
        big = [m(f"KXSPRLVL-26OCT{1 + (i // 3):02d}-T{i % 3}", 1.0)
               for i in range(ceiling + 15)]
        mem_big = {x.ticker for x in big}
        cut_big = imm.finecon_group_cut(big + newcomers, set(),
                                        members=mem_big, extra_openings=opens,
                                        refill_to=len(big))
        self.assertEqual(cut_big, {x.ticker for x in newcomers},
                         "the ceiling evicted quote-to-completion members")

        # REFILL: at the ceiling with the day's openings spent, a departure's
        # seat is closed in the same pass and bills no opening.
        surv = [m(f"KXSPRLVL-26NOV{1 + (i // 3):02d}-T{i % 3}", 1.0)
                for i in range(ceiling - 1)]
        mem = {x.ticker for x in surv}
        cut2 = imm.finecon_group_cut(surv + newcomers, set(), members=mem,
                                     extra_openings=0, refill_to=ceiling)
        kept = len(surv) + len(newcomers) - len(cut2)
        self.assertEqual(kept, ceiling, "the freed seat was not refilled")
        self.assertEqual(
            imm.finecon_openings_used(kept, max(len(mem), ceiling)), 0,
            "a refill must not be billed as an expansion")

        # and the knob restores the old bleed-down
        with mock.patch.object(imm, "FINECON_REFILL_ON_DEPARTURE", False):
            cut3 = imm.finecon_group_cut(surv + newcomers, set(), members=mem,
                                         extra_openings=0, refill_to=ceiling)
            self.assertEqual(
                len(surv) + len(newcomers) - len(cut3), ceiling - 1)

        # IMM_FINECON_DAILY_OPENINGS=0 gives a hard FINECON_TOP_N
        with mock.patch.object(imm, "FINECON_DAILY_OPENINGS", 0):
            self.assertEqual(imm.finecon_ceiling(), cap)

    def test_finecon_extra_series_hot_reload(self):
        # Jack 2026-09-05 "yes self-extend carbon arc": the overrides task
        # appends to FINECON_EXTRA_FILE; the bot merges, guards and allows
        # on the next refresh. Blocklist still wins; base stays code-owned.
        # KXHIGH rather than the old KXTRUEV stand-in, which stopped being
        # blocklisted on 2026-09-07: KXHIGH is owned by high_temp_trading.py
        # and is a permanent code-level block, so it cannot rot the same way.
        fake, blocked = "KXFAKECARB", "KXHIGH"
        base_n = len(imm._FINECON_BASE)
        saved_state = dict(imm._finecon_extra_state)

        def _write(series):
            with open(imm.FINECON_EXTRA_FILE, "w", encoding="utf-8") as f:
                json.dump({"series": series}, f)
            os.utime(imm.FINECON_EXTRA_FILE,
                     (time.time(), time.time() + len(series)))
        try:
            _write([fake, blocked])
            imm.load_finecon_extra_series()
            self.assertIn(fake, imm.FINECON_SERIES)
            self.assertNotIn(blocked, imm.FINECON_SERIES)
            self.assertTrue(imm.series_safe_join(fake))
            self.assertEqual(imm.series_min_est_rate(fake), 0.0)
            imm.ALLOWLIST_ONLY = True
            try:
                self.assertTrue(IncentiveMarketMaker._allowed(
                    f"{fake}-26OCT13-T1"))
            finally:
                imm.ALLOWLIST_ONLY = False
            # removal drops the extra but never the base
            _write([])
            imm.load_finecon_extra_series()
            self.assertNotIn(fake, imm.FINECON_SERIES)
            self.assertEqual(len(imm.FINECON_SERIES), base_n)
        finally:
            imm.SERIES_OVERRIDES.pop(fake, None)
            imm.FINECON_SERIES.clear()
            imm.FINECON_SERIES.update(imm._FINECON_BASE)
            imm._finecon_extra_state.update(saved_state)
            try:
                os.remove(imm.FINECON_EXTRA_FILE)
            except OSError:
                pass

    def test_carbon_arc_detector(self):
        import imm_earnings_overrides as ieo

        class _Stub:
            def __init__(self, name):
                self._name = name

            def get(self, _path):
                return {"series": {"settlement_sources": [
                    {"name": self._name}]}}
        self.assertTrue(ieo.carbon_arc_series(_Stub("Carbon Arc"), "KXX"))
        self.assertTrue(ieo.carbon_arc_series(_Stub("carbon arc"), "KXX"))
        self.assertFalse(ieo.carbon_arc_series(_Stub("AAA"), "KXX"))

    def test_family_override_suffix_requires_membership(self):
        # *FT suffix alone (KXNFLDRAFT is never allowlisted) clones nothing...
        try:
            imm.ensure_family_override("KXNFLDRAFT")
            self.assertNotIn("KXNFLDRAFT", imm.SERIES_OVERRIDES)
            # ...while an extra-allow member inherits the company archetype.
            imm.EXTRA_ALLOW_SERIES.add("KXZZFT")
            imm.ensure_family_override("KXZZFT")
            self.assertTrue(imm.series_safe_join("KXZZFT"))
            self.assertEqual(imm.SERIES_OVERRIDES["KXZZFT"],
                             imm.SERIES_OVERRIDES["KXBKFT"])
            # consumer-observation families carry NO fresh-candidate rate
            # bar (2026-09-01 "start quoting things as if normal") — but
            # keep safe-join; gas keeps the national $2 bar.
            for s in ("KXZZFT", "KXBKFT", "KXCLAUDEAPP"):
                self.assertEqual(imm.series_min_est_rate(s), 0.0, s)
            self.assertEqual(imm.series_min_est_rate("KXAAAGASD"), 2.0)
        finally:
            imm.EXTRA_ALLOW_SERIES.discard("KXZZFT")
            imm.SERIES_OVERRIDES.pop("KXZZFT", None)
            imm.SERIES_OVERRIDES.pop("KXNFLDRAFT", None)

    def _seed_family_verdicts(self, *series, carbon_arc=True):
        for s in series:
            imm.FAMILY_VERDICTS[s] = {"carbon_arc": carbon_arc,
                                      "ts": time.time(), "title": s}

    def test_cc_family_suffix_allows_into_normal_book(self):
        # Jack 2026-09-10: "allowlist the CC Carbon Arc family -- KXURBNCC,
        # KXDGCC, KXCOSTCC, etc. and they should be picked up by the normal
        # IMM ... not the opportunistic". Membership is the *CC name
        # pattern (ALLOW_FAMILY_SUFFIXES), not an exact list and not the
        # finecon group. 2026-09-22: *ADS and *POS join the same rule (Jack
        # "should be auto-quoted as part of IMM right? ... set limit of max
        # 3 per event"), and membership is the suffix AND a Carbon Arc
        # source verdict (the catalog sweep in the ALLOW_FAMILY_SUFFIXES
        # note: KXAMAZONADS, KXINXPOS, FCC ... all end in a family suffix).
        saved_only = imm.ALLOWLIST_ONLY
        saved_verdicts = dict(imm.FAMILY_VERDICTS)
        imm.ALLOWLIST_ONLY = True
        imm.FAMILY_VERDICTS.clear()
        try:
            self.assertEqual(imm.ALLOW_FAMILY_SUFFIXES, ("CC", "ADS", "POS"))
            self.assertTrue(imm.FAMILY_SOURCE_CHECK)
            members = ("KXURBNCC", "KXDGCC", "KXCOSTCC", "KXAMZNCC",
                       "KXSBUXCC", "KXNEVERSEENCC",
                       "KXCASINOADS", "KXAMUSEMENTADS", "KXELECTRONICSADS",
                       "KXC4POS", "KXBUDLIGHTPOS", "KXCOORSLIGHTPOS",
                       "KXDRPEPPERPOS", "KXNEVERSEENPOS")
            # no verdict yet: NOT allowed (fail closed), and the scan tier
            # leaves it to the normal book rather than screening it
            for s in members:
                self.assertTrue(imm.series_family_suffix(s), s)
                self.assertFalse(
                    IncentiveMarketMaker._allowed(f"{s}-26OCT07-T100"), s)
                self.assertEqual(
                    imm.scan_universe_reason(f"{s}-26OCT07-T100"),
                    "family_pending", s)
            self._seed_family_verdicts(*members)
            for s in members:
                self.assertTrue(
                    IncentiveMarketMaker._allowed(f"{s}-26OCT07-T100"), s)
                # allowed => the open scan never touches it
                self.assertEqual(
                    imm.scan_universe_reason(f"{s}-26OCT07-T100"),
                    "allowed", s)
                # ...and it is NOT walked/capped as finecon
                self.assertNotIn(s, imm.FINECON_SERIES, s)
                self.assertNotIn(s, imm._FINECON_BASE, s)
                # ...and since 2026-10-01 no per-event cap (Jack: "remove
                # the 3 max cap on carbon arc"; it carried *SUF:3 before)
                self.assertEqual(imm.event_top_n_for(s), 0, s)
            # a suffix match that is NOT Carbon Arc (the 2026-09-22 catalog
            # sweep: KXAMAZONADS is a PACER-settled lawsuit binary, KXINXPOS
            # a Trading View-settled live index, KXFCC the next commissioner)
            # is refused by the family rule and left to the scan's screens
            self._seed_family_verdicts("KXAMAZONADS", "KXINXPOS", "KXFCC",
                                       carbon_arc=False)
            for t in ("KXAMAZONADS-29-YES", "KXINXPOS-26DEC31H1900-T6845.5",
                      "KXFCC-26DEC31-JOE"):
                self.assertFalse(IncentiveMarketMaker._allowed(t), t)
                # ...and the scan judges it on its own terms: an ordinary
                # candidate, or (KXINX*) its prefix ban on live index families
                self.assertIn(imm.scan_universe_reason(t),
                              (None, "excluded_family"), t)
            # the MENTION suffix tuple is untouched: the families carry no
            # mention semantics (no no_event_window stand-down, no pre-drop
            # waiver)
            self.assertEqual(imm.ALLOW_SERIES_SUFFIXES, ("MENTION",))
            self.assertTrue(imm.mention_cutoff_is_clear(
                "KXURBNCC", None, None, None))
            # a never-seen sibling clones its family's archetype on first
            # sight WITHOUT exact/extra-allow membership (unlike *FT/*APP)
            for fake, parent in (("KXNEVERSEENCC", "KXAMZNCC"),
                                 ("KXNEVERSEENADS", "KXAMUSEMENTADS"),
                                 ("KXNEVERSEENPOS", "KXDRPEPPERPOS")):
                self.assertNotIn(fake, imm.SERIES_OVERRIDES)
                imm.ensure_family_override(fake)
                self.assertIn(fake, imm.SERIES_OVERRIDES)
                self.assertEqual(imm.SERIES_OVERRIDES[fake],
                                 imm.SERIES_OVERRIDES[parent], fake)
                self.assertTrue(imm.series_safe_join(fake))
                self.assertEqual(imm.series_min_est_rate(fake), 0.0)
            # blocklist still wins over the family rule
            self._seed_family_verdicts("KXHIGHCC")
            self.assertFalse(IncentiveMarketMaker._allowed("KXHIGHCC-26OCT07-T1"))
            # kill switch: IMM_FAMILY_SOURCE_CHECK=0 is the bare suffix rule
            with mock.patch.object(imm, "FAMILY_SOURCE_CHECK", False):
                self.assertTrue(IncentiveMarketMaker._allowed(
                    "KXUNREADCC-26OCT07-T1"))
                self.assertEqual(imm.scan_universe_reason(
                    "KXUNREADCC-26OCT07-T1"), "allowed")
        finally:
            imm.ALLOWLIST_ONLY = saved_only
            imm.FAMILY_VERDICTS.clear()
            imm.FAMILY_VERDICTS.update(saved_verdicts)
            for fake in ("KXNEVERSEENCC", "KXNEVERSEENADS", "KXNEVERSEENPOS"):
                imm.SERIES_OVERRIDES.pop(fake, None)

    def test_sports_ladders_and_escalators_are_allowlisted_by_pattern(self):
        # Jack 2026-09-24: "allowlist sports ladders and escalators" -- a
        # league prefix with LADDER / ESCALATOR anywhere after it, every stat
        # and every future league covered; guards clone KXNFLLADDERREC.
        saved_only = imm.ALLOWLIST_ONLY
        imm.ALLOWLIST_ONLY = True
        try:
            for t in ("KXNFLLADDERREC-26SEP24ATLGB-ATLDLONDON5",
                      "KXNFLLADDERRECYDS-26SEP24ATLGB-ATLBROBINSON7",
                      "KXNFLLADDERRSHYDS-26SEP24ATLGB-GBJJACOBS8",
                      "KXNFLESCALATORREC-26SEP24ATLGB-ATLBROBINSON7",
                      "KXNFLFFPTSLADDER-26SEP24ATLGB-GBJLOVE10",
                      "KXNBALADDERPTS-26OCT21BOSNYK-BOSJTATUM25"):
                self.assertTrue(IncentiveMarketMaker._allowed(t), t)
                self.assertEqual(imm.scan_universe_reason(t), "allowed", t)
            for s in ("KXNFLGAME", "KXLADDERCPI", "KXNFLMENTION", "KXNFL"):
                self.assertFalse(imm.series_pattern_allowed(s), s)
            self.assertFalse(IncentiveMarketMaker._allowed("KXNFLGAME-26SEP24ATLGB-ATL"))
            # guards: a never-seen sibling clones the archetype on first sight
            imm.SERIES_OVERRIDES.pop("KXNBALADDERPTS", None)
            imm.ensure_family_override("KXNBALADDERPTS")
            self.assertEqual(imm.SERIES_OVERRIDES["KXNBALADDERPTS"],
                             imm.SERIES_OVERRIDES["KXNFLLADDERREC"])
            self.assertTrue(imm.series_safe_join("KXNBALADDERPTS"))
            self.assertEqual(imm.series_min_est_rate("KXNBALADDERPTS"), 0.0)
            # Jack 2026-09-26: "for ESCALATOR/LADDER only, allow quoting range
            # 1-99c and double contract size (use that for calculating if
            # hits payout floor)" -- band, x2 geometry, and the screen
            self.assertEqual(imm.member_price_band("KXNBALADDERPTS", False), (1, 99))
            self.assertEqual(imm.member_price_band("KXNBALADDERPTS", True), (1, 99))
            # 2026-09-26 pm: x3 ("so should be 90" on a Saturday) and a $1.20
            # fresh-entry bar for the family; the cliff for banked / members.
            # 2026-09-29: x4 ("increase LADDER and ESCALATOR families to 4x
            # multiplier, from the 3x"); 2026-10-02: x5 ("increase
            # LADDER/ESCALATOR to 5x immediately")
            self.assertEqual(imm.applied_mention_mult("KXNBALADDERPTS"), 5.0)
            self.assertEqual(imm.series_min_est_total("KXNBALADDERPTS"), 1.2)
            self.assertEqual(imm.floor_bar_dollars("KXNBALADDERPTS", banked=False), 1.2)
            self.assertEqual(imm.floor_bar_dollars("KXNBALADDERPTS", banked=True),
                             imm.PAYOUT_FLOOR_DOLLARS)
            self.assertEqual(imm.series_min_est_total("KXGOOD"), imm.MIN_EST_TOTAL_DOLLARS)
            noon = utc(2026, 9, 30, 15, 0)              # a weekday, no hour mult
            base = imm.series_levels("KXNBALADDERPTS")
            self.assertEqual(imm.hour_scaled_levels("KXNBALADDERPTS", noon),
                             [(t_, 5 * s_) for t_, s_ in base])
            self.assertEqual(imm.series_max_position("KXNBALADDERPTS"),
                             5 * imm.MAX_POSITION_CONTRACTS)
            self.assertEqual(imm.event_cap_contracts("KXNBALADDERPTS-26OCT21BOSNYK"),
                             5 * imm.MAX_EVENT_CONTRACTS)
            # KXTRUMPAPPROVE copied the ladders' x3 on 9/26 but keeps its own
            self.assertEqual(imm.applied_mention_mult("KXTRUMPAPPROVE"), 3.0)
            bot = IncentiveMarketMaker(client=None, live=False)
            now = datetime.now(timezone.utc)
            lad_meta = _meta(series="KXNBALADDERPTS",
                             ticker="KXNBALADDERPTS-26OCT21BOSNYK-BOSJTATUM25",
                             event_ticker="KXNBALADDERPTS-26OCT21BOSNYK",
                             mid_cents=3.0, spread_cents=1)
            self.assertIsNone(bot._screen(lad_meta, now))
            self.assertEqual(bot._screen(_meta(mid_cents=3.0, spread_cents=1), now),
                             "extreme_mid")
            # ordinary series keep their band and geometry
            self.assertEqual(imm.applied_mention_mult("KXGOOD"), 1.0)
            self.assertEqual(imm.member_price_band("KXGOOD", False),
                             (imm.PRICE_MIN_CENTS, imm.PRICE_MAX_CENTS))
            # the cutoff comes from the live schedule, so the ticker-date
            # pre-drop never applies; leagues without an ESPN path fall back
            self.assertEqual(imm.sports_ladder_league("KXNFLESCALATORRSHYDS"), "NFL")
            self.assertIsNone(imm.sports_ladder_league("KXNFLGAME"))
            self.assertTrue(imm.schedule_resolved_series("KXNFLLADDERREC"))
            self.assertTrue(imm.schedule_resolved_series("KXWNBAMENTION"))
            self.assertFalse(imm.schedule_resolved_series("KXNFLGAME"))
            # blocklist still wins
            with mock.patch.object(imm, "SERIES_BLOCK_PATTERNS",
                                   tuple(imm.SERIES_BLOCK_PATTERNS)
                                   + (imm.re.compile(r"KXNFLESCALATOR[A-Z]+"),)):
                self.assertFalse(IncentiveMarketMaker._allowed(
                    "KXNFLESCALATORREC-26SEP24ATLGB-ATLBROBINSON7"))
        finally:
            imm.ALLOWLIST_ONLY = saved_only
            imm.SERIES_OVERRIDES.pop("KXNBALADDERPTS", None)

    def test_extra_allow_file_reload_and_safety(self):
        old_path = imm.EXTRA_ALLOW_FILE
        tmp = os.path.join(os.path.dirname(imm.EXTRA_ALLOW_FILE),
                           "test_extra_allow.json")
        imm.EXTRA_ALLOW_FILE = tmp
        imm._extra_allow_state["mtime"] = 0.0
        snapshot = set(imm.EXTRA_ALLOW_SERIES)
        try:
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump({"series": ["KXNEWCO", "KXBTCMAXMON", "KXHIGHNY"]}, f)
            imm.load_extra_allow_series()
            self.assertIn("KXNEWCO", imm.EXTRA_ALLOW_SERIES)
            self.assertNotIn("KXBTCMAXMON", imm.EXTRA_ALLOW_SERIES)  # fleet refused
            self.assertNotIn("KXHIGHNY", imm.EXTRA_ALLOW_SERIES)     # blocklisted
            self.assertTrue(IncentiveMarketMaker._allowed("KXNEWCO-26AUGDELIV-5"))
        finally:
            imm.EXTRA_ALLOW_FILE = old_path
            imm._extra_allow_state["mtime"] = 0.0
            imm.EXTRA_ALLOW_SERIES.clear()
            imm.EXTRA_ALLOW_SERIES.update(snapshot)
            try:
                os.remove(tmp)
            except FileNotFoundError:
                pass


class TestEarningsCallTimeParse(unittest.TestCase):
    """parse_call_time against the real IR phrasings that motivated the tool
    (Alphabet / Tesla / Alaska, Jul 2026)."""

    def _parse(self, text):
        import imm_earnings_overrides as ieo
        return ieo.parse_call_time(text)

    def test_alphabet_phrasing(self):
        hit = self._parse(
            "Alphabet Inc. will hold its quarterly conference call to discuss "
            "second quarter 2026 financial results on Wednesday, July 22, at "
            "1:30pm Pacific Time (4:30pm Eastern Time).")
        self.assertIsNotNone(hit)
        dt_et, _ = hit
        self.assertEqual((dt_et.month, dt_et.day, dt_et.hour, dt_et.minute),
                         (7, 22, 16, 30))

    def test_tesla_phrasing_skips_central(self):
        hit = self._parse(
            "Tesla will host a live question and answer webcast at 4:30 p.m. "
            "Central Time / 5:30 p.m. Eastern Time on Wednesday, July 22, 2026 "
            "to discuss the results.")
        self.assertIsNotNone(hit)
        dt_et, _ = hit
        self.assertEqual((dt_et.day, dt_et.hour, dt_et.minute), (22, 17, 30))

    def test_alaska_phrasing(self):
        hit = self._parse(
            "Alaska Air Group will hold its quarterly conference call July 22, "
            "2026 to review second-quarter financial results at 11:30 a.m. EDT "
            "/ 8:30 a.m. PDT.")
        self.assertIsNotNone(hit)
        dt_et, _ = hit
        self.assertEqual((dt_et.day, dt_et.hour, dt_et.minute), (22, 11, 30))

    def test_no_false_positive_without_call_context(self):
        self.assertIsNone(self._parse(
            "The company estimated revenue of $4.30 per share for July 22."))


class TestReleaseTimeParse(unittest.TestCase):
    """parse_release_time — the earnings PRESS-RELEASE resolver for company-
    disclosure cutoffs (after-close -> 4pm ET, before-open -> 7am ET)."""

    def _parse(self, text, year=2026):
        import imm_earnings_overrides as ieo
        return ieo.parse_release_time(text, year)

    def test_intel_after_close(self):
        hit = self._parse(
            "Intel will report second-quarter financial results on Thursday, "
            "July 23, 2026, promptly after close of market. Following the "
            "report, Intel will hold a conference call at 2 p.m. PDT.")
        self.assertIsNotNone(hit)
        dt, label, _ = hit
        self.assertEqual((dt.month, dt.day, dt.hour, dt.minute), (7, 23, 16, 0))
        self.assertIn("close", label)

    def test_before_market_open(self):
        hit = self._parse(
            "Boeing will report second-quarter 2026 financial results before "
            "the market opens on July 29, 2026.")
        self.assertIsNotNone(hit)
        dt, label, _ = hit
        self.assertEqual((dt.month, dt.day, dt.hour), (7, 29, 7))
        self.assertIn("open", label)

    def test_stated_release_time_not_the_call(self):
        # a specific RELEASE time is used; the later call time is NOT picked
        hit = self._parse(
            "The company will release its quarterly results at 6:00 a.m. ET on "
            "August 5, 2026, and host a conference call at 8:30 a.m. ET.")
        self.assertIsNotNone(hit)
        dt, _, _ = hit
        self.assertEqual((dt.month, dt.day, dt.hour, dt.minute), (8, 5, 6, 0))

    def test_no_report_context_returns_none(self):
        self.assertIsNone(self._parse(
            "Shares closed after the market close up 3% on Tuesday."))


class TestEarningsYearAcrossYearBoundary(unittest.TestCase):
    """Year for a year-less 'Month DD' on an IR page. Both parsers defaulted to
    a literal 2026: from ~mid-December 2026 an IR-resolved January call would
    have been stamped a year EARLY, and resolved overrides are write-once, so
    the event stays stood down for its whole life. The release path took the
    year from the occurrence/wall clock, which lands a year LATE across Dec/Jan."""

    CALL = ("The company will hold its quarterly conference call on Thursday, "
            "January 28, at 8:30 a.m. ET to discuss fourth-quarter results.")

    @staticmethod
    def _ieo():
        import imm_earnings_overrides as ieo
        return ieo

    def test_january_call_read_in_january_is_next_year(self):
        hit = self._ieo().parse_call_time(
            self.CALL, ref=datetime(2027, 1, 28, tzinfo=timezone.utc))
        self.assertEqual(hit[0].year, 2027)

    def test_january_call_read_in_december_is_next_year(self):
        # the scenario that broke: a mid-December run resolving a Jan call
        hit = self._ieo().parse_call_time(
            self.CALL, ref=datetime(2026, 12, 20, tzinfo=timezone.utc))
        self.assertEqual((hit[0].year, hit[0].month, hit[0].day), (2027, 1, 28))

    def test_december_release_read_in_january_is_previous_year(self):
        hit = self._ieo().parse_release_time(
            "Acme will report fourth-quarter financial results on December 30 "
            "after the market close.",
            ref=datetime(2027, 1, 5, tzinfo=timezone.utc))
        self.assertEqual((hit[0].year, hit[0].month, hit[0].day), (2026, 12, 30))

    def test_year_printed_on_page_wins(self):
        hit = self._ieo().parse_call_time(
            "Earnings conference call on January 28, 2027 at 8:30 a.m. ET.",
            ref=datetime(2026, 6, 1, tzinfo=timezone.utc))
        self.assertEqual(hit[0].year, 2027)

    def test_explicit_year_argument_still_honoured(self):
        # backward compatible with the positional-year call in TestReleaseTimeParse
        hit = self._ieo().parse_release_time(
            "Acme will report quarterly financial results on March 3 after "
            "the market close.", 2031)
        self.assertEqual(hit[0].year, 2031)

    def test_no_literal_2026_default_remains(self):
        self.assertEqual(
            self._ieo()._year_for(1, 12, ref=datetime(2030, 1, 10)), 2030)
        self.assertEqual(
            self._ieo()._year_for(12, 31, ref=datetime(2030, 1, 2)), 2029)

    def test_feb_29_picks_a_leap_year_or_falls_back(self):
        y = self._ieo()._year_for(2, 29, ref=datetime(2027, 3, 1))
        self.assertEqual(y, 2028)


class TestIrPageLateGuard(unittest.TestCase):
    """An EARLY override only stands the bot down early (safe); a LATE one
    quotes through the call (loses money). DATE_RE takes the first date in the
    window, so an IR page can mis-parse -- and nearest-year resolution made
    some mis-parses LATE. An IR-page date implausibly late versus the event's
    own date is therefore NOT written (fail closed -> UNRESOLVED -> --set)."""

    @staticmethod
    def _ieo():
        import imm_earnings_overrides as ieo
        return ieo

    def test_the_bond_maturity_misparse_is_rejected(self):
        ieo = self._ieo()
        ref = datetime(2026, 12, 3, 5, tzinfo=timezone.utc)
        hit = ieo.parse_call_time(
            "The company's Senior Notes due March 15, 2031 remain outstanding. "
            "It will host a conference call at 8:30 a.m. ET on December 3.",
            ref=ref)
        self.assertEqual(hit[0].year, 2031)            # the parser mis-reads...
        self.assertTrue(ieo.ir_date_too_late(hit[0], ref))   # ...the guard refuses

    def test_on_time_and_early_readings_pass(self):
        ieo = self._ieo()
        ref = datetime(2026, 10, 14, 4, tzinfo=timezone.utc)
        on_time = datetime(2026, 10, 14, 20, 30, tzinfo=timezone.utc)
        self.assertFalse(ieo.ir_date_too_late(on_time, ref))
        self.assertFalse(ieo.ir_date_too_late(on_time + timedelta(days=5), ref))
        # EARLY is the safe direction: never blocked
        self.assertFalse(ieo.ir_date_too_late(on_time - timedelta(days=200), ref))

    def test_feb_29_a_year_out_is_rejected(self):
        ieo = self._ieo()
        ref = datetime(2027, 3, 1, tzinfo=timezone.utc)
        hit = ieo.parse_call_time(
            "Our earnings conference call is February 29 at 8:30 a.m. ET.", ref=ref)
        self.assertEqual(hit[0].year, 2028)
        self.assertTrue(ieo.ir_date_too_late(hit[0], ref))

    def test_uncomparable_fails_closed(self):
        ieo = self._ieo()
        naive = datetime(2026, 10, 14)
        aware = datetime(2026, 10, 14, tzinfo=timezone.utc)
        self.assertTrue(ieo.ir_date_too_late(naive, aware))


class TestNasdaqRelease(unittest.TestCase):
    """Nasdaq-calendar release resolver: after-hours->4pm ET, pre-market->7am,
    scanning forward from now (robust to Kalshi's wrong occurrence)."""

    def test_amc_and_bmo_from_calendar(self):
        import imm_earnings_overrides as ieo
        now = datetime(2026, 7, 23, 12, 0, tzinfo=timezone.utc)
        ieo._nasdaq_cache.clear()
        for i in range(6):
            di = (now + timedelta(days=i)).astimezone(ieo.ET).date().isoformat()
            ieo._nasdaq_cache[di] = {}
        hit_date = (now + timedelta(days=2)).astimezone(ieo.ET).date().isoformat()
        ieo._nasdaq_cache[hit_date] = {"FOO": "time-after-hours",
                                       "BAR": "time-pre-market"}
        try:
            amc = ieo.nasdaq_release_datetime("FOO", now, 5)
            self.assertIsNotNone(amc)
            self.assertEqual(amc[0].astimezone(ieo.ET).hour, 16)   # 4pm ET
            bmo = ieo.nasdaq_release_datetime("BAR", now, 5)
            self.assertEqual(bmo[0].astimezone(ieo.ET).hour, 7)    # 7am ET
            self.assertIsNone(ieo.nasdaq_release_datetime("NOPE", now, 5))
        finally:
            ieo._nasdaq_cache.clear()


class TestUnknownEarningsTimeFailsSafe(unittest.TestCase):
    """KXEARNINGSMENTIONCELH-26AUG06 (2026-08-06).

    Nasdaq's earnings calendar carried NO time flag for Celsius, the resolver's
    else-branch synthesized 16:00 ET, Celsius in fact reported BEFORE the open
    with an 8:00am ET call, and the bot quoted 15 markets from midnight straight
    through that call with the Q2 results already public. Jack stopped it by
    hand at 12:31Z.

    The two ways of being wrong are not symmetric, and this is the test that
    pins the direction: guess before-open when the truth is after-close and the
    bot stands down early, forfeiting a day of reward accrual; guess after-close
    when the truth is before-open and the bot makes markets into a print."""

    def setUp(self):
        import imm_earnings_overrides as ieo
        self.ieo = ieo
        # the real run that wrote the bad value: 2026-08-02 16:45 ET
        self.now = datetime(2026, 8, 2, 20, 45, tzinfo=timezone.utc)
        ieo._nasdaq_cache.clear()
        for i in range(9):                      # calendar known-empty by default
            d = (self.now + timedelta(days=i)).astimezone(ieo.ET).date()
            ieo._nasdaq_cache[d.isoformat()] = {}

    def tearDown(self):
        self.ieo._nasdaq_cache.clear()

    def _on(self, days, **flags):
        d = (self.now + timedelta(days=days)).astimezone(self.ieo.ET).date()
        self.ieo._nasdaq_cache[d.isoformat()] = dict(flags)
        return d

    def test_no_time_supplied_lands_in_the_morning_not_after_the_close(self):
        d = self._on(4, CELH="time-not-supplied")     # the literal CELH row
        hit = self.ieo.nasdaq_release_datetime("CELH", self.now, 7)
        self.assertIsNotNone(hit)
        dt_et, label = hit
        et = dt_et.astimezone(self.ieo.ET)
        self.assertEqual((et.date(), et.hour), (d, 7))
        # and it must be RECORDED as a guess: a fail-safe 07:00 and a measured
        # pre-market 07:00 are byte-identical in the overrides file, so the
        # label is the only channel the digest has for telling them apart.
        self.assertEqual(self.ieo.provenance_of(label), "guess")

    def test_a_missing_time_FIELD_is_the_same_guess(self):
        # nasdaq_earnings_for_date does `row.get("time") or ""`, so an absent
        # field arrives as "" — falsy but NOT None, so it clears the
        # `if flag is None: continue` guard and reaches the same branch.
        self._on(2, FOO="")
        dt_et, label = self.ieo.nasdaq_release_datetime("FOO", self.now, 7)
        self.assertEqual(dt_et.astimezone(self.ieo.ET).hour, 7)
        self.assertEqual(self.ieo.provenance_of(label), "guess")

    def test_the_failsafe_cutoff_bites_before_the_call_it_missed(self):
        # end to end on the real numbers: 07:00 ET minus the bot's override
        # buffer must land before Celsius's 8:00am ET call. The old 16:00 put
        # the cutoff at 15:50 ET — nearly eight hours of quoting into the news.
        self._on(4, CELH="time-not-supplied")
        dt_et = self.ieo.nasdaq_release_datetime("CELH", self.now, 7)[0]
        cutoff = dt_et - timedelta(minutes=imm.OVERRIDE_BUFFER_MIN)
        self.assertLess(cutoff, self.ieo.ET.localize(datetime(2026, 8, 6, 8, 0)))

    def test_measured_flags_are_untouched_and_count_as_measurements(self):
        # the fail-safe must not swallow the 28 genuine after-close readings
        self._on(1, AAA="time-after-hours", BBB="time-pre-market")
        amc = self.ieo.nasdaq_release_datetime("AAA", self.now, 7)
        bmo = self.ieo.nasdaq_release_datetime("BBB", self.now, 7)
        self.assertEqual(amc[0].astimezone(self.ieo.ET).hour, 16)
        self.assertEqual(bmo[0].astimezone(self.ieo.ET).hour, 7)
        self.assertEqual(self.ieo.provenance_of(amc[1]), "read")
        self.assertEqual(self.ieo.provenance_of(bmo[1]), "read")

    def test_absent_from_the_calendar_is_still_None_not_a_guess(self):
        # "not on the calendar" and "on the calendar without a time" are
        # different unknowns and must not collapse into one another: None sends
        # the event to the IR scrape and then to the UNRESOLVED email.
        self.assertIsNone(self.ieo.nasdaq_release_datetime("NOPE", self.now, 7))


class TestProvisionalGuessRecheck(unittest.TestCase):
    """A fail-safe guess must stay OPEN until somebody measures it.

    The `covered` short-circuit made every written value permanent. Nasdaq
    filled CELH in as "time-pre-market" within days of guessing on it — the
    right answer sat in the same endpoint the resolver already calls — and the
    thirteen scheduled runs in between each skipped the event without a line of
    log output. A measurement stays taken; a guess gets re-opened."""

    EV = "KXEARNINGSMENTIONCELH-26AUG06"
    GUESS = "2026-08-06T07:00:00-04:00"

    def setUp(self):
        import imm_earnings_overrides as ieo
        self.ieo = ieo
        self.dir = tempfile.mkdtemp(prefix="imm_meta_")
        self.old_meta = ieo.OVERRIDE_META_FILE
        ieo.OVERRIDE_META_FILE = os.path.join(self.dir, "meta.json")

    def tearDown(self):
        self.ieo.OVERRIDE_META_FILE = self.old_meta

    def _meta(self, **rec):
        with open(self.ieo.OVERRIDE_META_FILE, "w", encoding="utf-8") as f:
            json.dump({self.EV: rec}, f)

    def test_a_standing_guess_is_reopened(self):
        self._meta(iso=self.GUESS, confidence="guess",
                   label="time n/a->7am ET BMO assumed (Nasdaq, fail-safe)")
        self.assertIn(self.EV,
                      self.ieo.provisional_events({self.EV: self.GUESS}))

    def test_a_measurement_is_never_reopened(self):
        self._meta(iso=self.GUESS, confidence="read",
                   label="before open (~7am ET, Nasdaq)")
        self.assertEqual(self.ieo.provisional_events({self.EV: self.GUESS}),
                         set())

    def test_a_hand_set_supersedes_and_can_never_be_overwritten(self):
        # Jack --set CELH to 07:00 at 08:41 on 2026-08-06. record_meta files a
        # --set as a reading, which is what takes it out of the re-check pool.
        self.ieo.record_meta([(self.EV, self.GUESS, "hand-set by operator")],
                             {self.EV: self.GUESS})
        self.assertEqual(self.ieo.load_meta()[self.EV]["confidence"], "read")
        self.assertEqual(self.ieo.provisional_events({self.EV: self.GUESS}),
                         set())

    def test_a_guess_whose_value_moved_is_not_ours_to_move_again(self):
        self._meta(iso=self.GUESS, confidence="guess", label="time n/a")
        live = {self.EV: "2026-08-06T08:30:00-04:00"}     # somebody edited it
        self.assertEqual(self.ieo.provisional_events(live), set())

    def test_the_guess_label_survives_the_round_trip_as_a_guess(self):
        # provenance_batch decodes the phase tuples; if the bracketed label is
        # lost the guess silently records as a measurement and never re-checks.
        rows = self.ieo.provenance_batch(
            [(self.EV, self.GUESS, "nasdaq:CELH",
              "call cutoff = earnings RELEASE [time n/a->7am ET BMO assumed "
              "(Nasdaq, fail-safe)] (safe: call is at/after the release)")],
            [], [], [])
        self.ieo.record_meta(rows, {self.EV: self.GUESS})
        self.assertEqual(self.ieo.load_meta()[self.EV]["confidence"], "guess")
        self.assertIn(self.EV,
                      self.ieo.provisional_events({self.EV: self.GUESS}))

    def test_pruning_drops_events_the_overrides_file_no_longer_has(self):
        self.ieo.record_meta([(self.EV, self.GUESS, "time n/a fail-safe")],
                             {self.EV: self.GUESS})
        self.ieo.record_meta([], {})              # event gone from the file
        self.assertEqual(self.ieo.load_meta(), {})


class TestDigestUnverifiedCallTimes(unittest.TestCase):
    """send_imm_digest's CUTOFF AUDIT compares ET DATES. CELH's override date
    (Aug 6) MATCHED its ticker date (Aug 6) and was wrong by nine HOURS, so the
    audit skipped it at `if delta == 0: continue` and the 7:10am email said
    nothing. These tests pin the hour dimension, and pin that it stays quiet."""

    CELH = "KXEARNINGSMENTIONCELH-26AUG06"
    ABNB = "KXEARNINGSMENTIONABNB-26AUG06"
    BAD = "2026-08-06T16:00:00-04:00"          # what the resolver wrote

    class _Client:
        def __init__(self, events):
            self.events = events

        def get(self, path, params=None):
            if "incentive_programs" not in path:
                return {}
            progs = []
            for ev in self.events:
                for i in range(2):
                    progs.append({
                        "incentive_type": "liquidity", "paid_out": False,
                        "market_ticker": "{}-M{}".format(ev, i),
                        "start_date": "2026-08-05T00:00:00Z",
                        "end_date": "2026-08-07T00:00:00Z",
                        "period_reward": 6000000})
            return {"incentive_programs": progs, "next_cursor": None}

    def setUp(self):
        import send_imm_digest as sd
        self.sd = sd
        self.now = datetime(2026, 8, 6, 11, 0, tzinfo=timezone.utc)
        self.old_meta = sd.OVERRIDE_META_PATH
        self.dir = tempfile.mkdtemp(prefix="imm_digest_")
        sd.OVERRIDE_META_PATH = os.path.join(self.dir, "meta.json")
        self.client = self._Client([self.CELH, self.ABNB])

    def tearDown(self):
        self.sd.OVERRIDE_META_PATH = self.old_meta
        self._overrides({})                       # unload from the live dict
        imm.load_file_event_overrides()

    def _overrides(self, data):
        with open(imm.EVENT_OVERRIDES_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f)
        imm._file_override_state["mtime"] = 0.0

    def _meta(self, data):
        with open(self.sd.OVERRIDE_META_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f)

    def _audit(self, pos=None):
        return self.sd.cutoff_audit(self.client, self.now,
                                    pos or {self.CELH + "-M0": 240})

    def _flat(self, a):
        """The text block as one whitespace-normalized string. The block is
        wrapped to 76 cols, so a phrase assertion on the raw join would break
        purely on where a line happens to end."""
        return " ".join(" ".join(self.sd._unverified_lines(a)).split())

    def test_a_guessed_hour_surfaces_even_though_the_DATE_agrees(self):
        self._overrides({self.CELH: self.BAD, self.ABNB: self.BAD})
        self._meta({
            self.CELH: {"iso": self.BAD, "confidence": "guess",
                        "label": "time n/a->4pm ET (Nasdaq)"},
            self.ABNB: {"iso": self.BAD, "confidence": "read",
                        "label": "after close (4pm ET, Nasdaq)"}})
        a = self._audit()
        self.assertIsNone(a["error"])
        # the DATE audit is blind to this — that is the bug, asserted
        self.assertNotIn(self.CELH, [r["event"] for r in a["rows"]])
        flagged = [r["event"] for r in a["unverified"]]
        self.assertEqual(flagged, [self.CELH])
        self.assertTrue(a["unverified"][0]["unsafe"])
        self.assertEqual(a["unverified"][0]["contracts"], 240)
        self.assertIn("CELH", self.sd.cutoff_banner(a))

    def test_a_measured_after_close_hour_is_never_flagged(self):
        # 28 of the 29 live 16:00 overrides are a real Nasdaq after-close flag.
        # Flagging on hour-shape would ship 29 rows to catch one and the block
        # would be skimmed on the morning it matters.
        self._overrides({self.ABNB: self.BAD})
        self._meta({self.ABNB: {"iso": self.BAD, "confidence": "read",
                                "label": "after close (4pm ET, Nasdaq)"}})
        a = self._audit(pos={})
        self.assertEqual(a["unverified"], [])
        self.assertEqual(self.sd.cutoff_banner(a), "")

    def test_a_hand_set_value_stops_being_flagged_the_same_morning(self):
        # the sidecar records the ISO it describes; once --set moves the value
        # the record no longer applies and the row must go quiet, or a fixed
        # guess stays red forever and trains the reader to skip the block.
        fixed = "2026-08-06T07:00:00-04:00"
        self._overrides({self.CELH: fixed})
        self._meta({self.CELH: {"iso": self.BAD, "confidence": "guess",
                                "label": "time n/a->4pm ET (Nasdaq)"}})
        a = self._audit()
        self.assertEqual(a["unverified"], [])
        self.assertEqual(self.sd.cutoff_banner(a), "")
        self.assertGreaterEqual(a["no_prov"], 1)

    def test_a_failsafe_morning_guess_is_reported_but_never_shouted(self):
        # post-fix world: the guess lands at 07:00, the bot already stands down
        # early, so the row prints for the record and the banner stays silent.
        safe = "2026-08-06T07:00:00-04:00"
        self._overrides({self.CELH: safe})
        self._meta({self.CELH: {
            "iso": safe, "confidence": "guess",
            "label": "time n/a->7am ET BMO assumed (Nasdaq, fail-safe)"}})
        # 05:00 ET — before the 06:50 ET cutoff, i.e. while there is still
        # something to act on. That the SAME row disappears once 06:50 passes
        # is asserted by test_a_passed_cutoff_is_history_and_drops_out.
        a = self.sd.cutoff_audit(
            self.client, datetime(2026, 8, 6, 9, 0, tzinfo=timezone.utc),
            {self.CELH + "-M0": 240})
        self.assertEqual([r["event"] for r in a["unverified"]], [self.CELH])
        self.assertFalse(a["unverified"][0]["unsafe"])
        self.assertEqual(self.sd.cutoff_banner(a), "")
        self.assertTrue(any("UNVERIFIED CALL TIMES" in ln
                            for ln in self.sd._unverified_lines(a)))

    def test_a_passed_cutoff_is_history_and_drops_out(self):
        self._overrides({self.CELH: self.BAD})
        self._meta({self.CELH: {"iso": self.BAD, "confidence": "guess",
                                "label": "time n/a->4pm ET (Nasdaq)"}})
        a = self.sd.cutoff_audit(
            self.client, datetime(2026, 8, 6, 23, 0, tzinfo=timezone.utc), {})
        self.assertEqual(a["unverified"], [])

    def test_missing_provenance_reports_its_own_coverage_not_a_clean_bill(self):
        # an empty section must not look the same as a clean one
        self._overrides({self.CELH: self.BAD})
        self._meta({})
        a = self._audit()
        self.assertEqual(a["unverified"], [])
        line = self._flat(a)
        self.assertIn("0/{}".format(a["checked"]), line)
        self.assertIn("NOT covered by this check", line)

    def test_coverage_is_stated_as_a_fraction_at_every_level(self):
        """The honesty signal must not evaporate at 1/N coverage.

        The old copy gated "NOT yet effective" on no_prov >= checked, so a single
        new resolution flipped the section to "...the rest were measured, not
        guessed" — reassurance while the check could see 2 of 62, with CELH's own
        class ("written before provenance recording") listed among benign causes.
        """
        self._overrides({self.CELH: self.BAD, self.ABNB: self.BAD})
        self._meta({self.ABNB: {"iso": self.BAD, "confidence": "read",
                                "label": "after close (4pm ET, Nasdaq)"}})
        a = self._audit(pos={})
        self.assertEqual(a["unverified"], [])            # nothing to shout about
        line = self._flat(a)
        self.assertIn("1/{}".format(a["checked"]), line)
        # never closes on reassurance while most of the file is invisible
        self.assertNotIn("the rest were measured", line)
        self.assertIn("NOT covered by this check", line)
        # and it must not promise a convergence the writer cannot deliver:
        # imm_earnings_overrides.py's `covered` short-circuit never rewrites an
        # existing entry, so the unrecorded set does not fill in on its own.
        self.assertIn("does not fill in on its own", line)
        self.assertNotIn("fills in as", line)

    def test_the_coverage_line_survives_into_the_rows_branch_and_the_html(self):
        safe = "2026-08-06T07:00:00-04:00"
        self._overrides({self.CELH: safe, self.ABNB: self.BAD})
        self._meta({self.CELH: {
            "iso": safe, "confidence": "guess",
            "label": "time n/a->7am ET BMO assumed (Nasdaq, fail-safe)"}})
        a = self.sd.cutoff_audit(
            self.client, datetime(2026, 8, 6, 9, 0, tzinfo=timezone.utc), {})
        self.assertEqual([r["event"] for r in a["unverified"]], [self.CELH])
        self.assertIn("NOT covered by this check", self._flat(a))
        self.assertIn("NOT covered by this check", self.sd._unverified_html(a))

    def _meaning(self, unsafe: bool):
        return self.sd._unverified_meaning({
            "event": self.CELH, "dpd": 401.0, "unsafe": unsafe,
            "override_et": datetime(2026, 8, 20, 7 if not unsafe else 16, 0),
            "cutoff_et": datetime(2026, 8, 20, 6 if not unsafe else 15, 50)})

    def test_the_safe_side_row_forbids_the_accrual_chasing_edit(self):
        """Post-fix this is the section's ONLY steady-state output.

        Every future guess lands at 07:00, so this row is what Jack reads at
        7:10am on an ordinary morning. The old copy ended "Confirm only if you
        want the $401/day back" — a dangled dollar figure, no prohibition, no
        source named. Acting on it means pushing a safe 07:00 BMO guess out to
        16:00, i.e. re-creating CELH by hand."""
        why, action = self._meaning(unsafe=False)
        blob = (why + " " + action).lower()
        self.assertIn("do not push this override later", blob)
        self.assertIn("celh", blob)                       # names the incident
        self.assertIn("ir page", blob)                    # names a PRIMARY source
        # and disowns the source that already returned nothing here
        self.assertIn("not nasdaq", blob.replace("—", "").replace("  ", " "))
        self.assertNotIn("confirm only if you want", blob)
        self.assertTrue(action.startswith("ACTION: none"))

    def test_the_unsafe_side_row_still_asks_for_the_fail_safe_set(self):
        why, action = self._meaning(unsafe=True)
        self.assertIn("SYNTHESIZED", why)
        self.assertIn("--set", action)
        self.assertIn("07:00 ET", action)

    def test_a_no_action_row_is_not_the_loudest_thing_in_the_html(self):
        """ACTION: none rendered at font-weight:600 is how a no-op becomes a
        to-do. Bold is reserved for the row that actually wants a human."""
        base = {"ticker_date": datetime(2026, 8, 20).date(),
                "days_out": 1, "mkts": 18, "contracts": 0.0, "dpd": 401.0,
                "label": "time n/a->7am ET BMO assumed (Nasdaq, fail-safe)"}
        def row(unsafe):
            r = dict(base, event=self.CELH, unsafe=unsafe)
            r["override_et"] = datetime(2026, 8, 20, 16 if unsafe else 7, 0)
            r["cutoff_et"] = datetime(2026, 8, 20, 15 if unsafe else 6, 50)
            return r
        safe_html = self.sd._unverified_html(
            {"unverified": [row(False)], "checked": 1, "no_prov": 0})
        unsafe_html = self.sd._unverified_html(
            {"unverified": [row(True)], "checked": 1, "no_prov": 0})
        self.assertIn("color:#777;font-weight:400", safe_html)
        self.assertNotIn("color:#333;font-weight:600", safe_html)
        self.assertIn("color:#333;font-weight:600", unsafe_html)


class TestFileEventOverrides(unittest.TestCase):
    """Hot-reloaded call-time overrides file (imm_earnings_overrides.py)."""

    def setUp(self):
        self.old_path = imm.EVENT_OVERRIDES_FILE
        self.tmp = os.path.join(os.path.dirname(imm.EVENT_OVERRIDES_FILE),
                                "test_event_overrides.json")
        imm.EVENT_OVERRIDES_FILE = self.tmp
        imm._file_override_state["mtime"] = 0.0
        imm._file_override_state["keys"] = set()
        self.snapshot = dict(imm.EVENT_START_OVERRIDES)

    def tearDown(self):
        imm.EVENT_OVERRIDES_FILE = self.old_path
        imm._file_override_state["mtime"] = 0.0
        imm._file_override_state["keys"] = set()
        imm.EVENT_START_OVERRIDES.clear()
        imm.EVENT_START_OVERRIDES.update(self.snapshot)
        try:
            os.remove(self.tmp)
        except FileNotFoundError:
            pass

    _mtime_seq = 0

    def _write(self, data):
        with open(self.tmp, "w", encoding="utf-8") as f:
            json.dump(data, f)
        # Windows time.time() ticks ~15.6ms — consecutive writes in one tick
        # got identical mtimes and read as "unchanged". Force distinct mtimes.
        TestFileEventOverrides._mtime_seq += 60
        os.utime(self.tmp, (time.time(), 1_700_000_000 + self._mtime_seq))

    def test_merge_update_and_remove(self):
        self._write({"KXEARNINGSMENTIONFOO-26AUG01": "2026-08-01T16:30:00-04:00"})
        self.assertEqual(imm.load_file_event_overrides(), 1)
        self.assertIn("KXEARNINGSMENTIONFOO-26AUG01", imm.EVENT_START_OVERRIDES)
        # unchanged file -> no work
        self.assertEqual(imm.load_file_event_overrides(), 0)
        # update wins over previous FILE value
        self._write({"KXEARNINGSMENTIONFOO-26AUG01": "2026-08-01T17:00:00-04:00"})
        self.assertEqual(imm.load_file_event_overrides(), 1)
        et = imm.EVENT_START_OVERRIDES["KXEARNINGSMENTIONFOO-26AUG01"].astimezone(imm.ET)
        self.assertEqual(et.hour, 17)
        # removal from file -> forgotten
        self._write({})
        imm.load_file_event_overrides()
        self.assertNotIn("KXEARNINGSMENTIONFOO-26AUG01", imm.EVENT_START_OVERRIDES)

    def test_env_code_entry_wins(self):
        ev = "KXEARNINGSMENTIONBAR-26AUG02"
        code_dt = imm.parse_iso_utc("2026-08-02T10:00:00-04:00")
        imm.EVENT_START_OVERRIDES[ev] = code_dt
        self._write({ev: "2026-08-02T23:00:00-04:00"})
        imm.load_file_event_overrides()
        self.assertEqual(imm.EVENT_START_OVERRIDES[ev], code_dt)   # untouched


class TestTempSeriesTuning(unittest.TestCase):
    """Jack 2026-07-21: KXTEMP = 5/2/2 ladder, net cap 40, quotes only 5..90c.
    2026-08-02: out 10 min before the reading (was 15) + $0.70 min-payout
    floor (sub-hour windows made the $1 global bar unreachable for flanks)."""

    def test_temp_ladder_and_caps(self):
        self.assertEqual(imm.series_levels("KXTEMPDCH"), [(0, 5), (1, 2), (2, 2)])
        self.assertEqual(imm.series_side_max("KXTEMPDCH"), 9)
        self.assertEqual(imm.series_max_position("KXTEMPDCH"), 50)
        self.assertEqual(imm.series_price_min("KXTEMPDCH"), 5)
        self.assertEqual(imm.series_price_max("KXTEMPDCH"), 90)
        ov = imm.series_override("KXTEMPDCH")
        self.assertEqual(ov.cutoff_from_close_min, 10)
        # non-temp series keep the globals
        self.assertEqual(imm.series_price_min("KXGOOD"), imm.PRICE_MIN_CENTS)
        self.assertEqual(imm.series_price_max("KXGOOD"), imm.PRICE_MAX_CENTS)

    def test_member_quotes_to_true_cutoff(self):
        # Jack 2026-08-03: the 5-min fresh-entry buffer must not kill
        # members early — a member 3 min from cutoff still screens clean;
        # a fresh candidate inside the buffer is refused.
        bot = imm.IncentiveMarketMaker(client=None, live=False)
        meta = imm.MarketMeta(
            ticker="KXGOOD-99DEC31-A", event_ticker="KXGOOD-99DEC31",
            series="KXGOOD", dollars_per_day=10.0, program_end=None,
            target_size=1000.0, discount_factor=0.5,
            cutoff=datetime.now(timezone.utc) + timedelta(minutes=3),
            close_time=datetime.now(timezone.utc) + timedelta(hours=2),
            mid_cents=50.0, spread_cents=2, volume=100.0)
        now = datetime.now(timezone.utc)
        self.assertEqual(bot._screen(meta, now, member=False), "cutoff")
        self.assertIsNone(bot._screen(meta, now, member=True))

    def test_temp_min_payout_floor(self):
        # 2026-09-12: temp carries NO bar of its own any more -- it reads the
        # global ($1.50), and a raised global raises temp with it. An explicit
        # per-series value (IMM_TEMP_MIN_EST_TOTAL) may still win downward,
        # but never below PAYOUT_FLOOR_DOLLARS (next test).
        import dataclasses
        self.assertIsNone(imm.SERIES_OVERRIDES["KXTEMPDCH"].min_est_total)
        self.assertEqual(imm.series_min_est_total("KXTEMPDCH"),
                         imm.MIN_EST_TOTAL_DOLLARS)
        old = imm.MIN_EST_TOTAL_DOLLARS
        imm.MIN_EST_TOTAL_DOLLARS = 123.0
        try:
            self.assertEqual(imm.series_min_est_total("KXGOOD"), 123.0)
            self.assertEqual(imm.series_min_est_total("KXTEMPDCH"), 123.0)
            ov = imm.SERIES_OVERRIDES["KXTEMPDCH"]
            imm.SERIES_OVERRIDES["KXTEMPDCH"] = dataclasses.replace(
                ov, min_est_total=1.00)
            try:
                self.assertEqual(imm.series_min_est_total("KXTEMPDCH"), 1.00)
            finally:
                imm.SERIES_OVERRIDES["KXTEMPDCH"] = ov
        finally:
            imm.MIN_EST_TOTAL_DOLLARS = old

    def test_series_override_cannot_sit_below_the_payout_floor(self):
        # A sub-$1 series bar admits markets whose OPTIMISTIC projection still
        # pays zero. Guard the class, not just the KXTEMP instance.
        import dataclasses
        ov = imm.SERIES_OVERRIDES["KXTEMPDCH"]
        try:
            imm.SERIES_OVERRIDES["KXTEMPDCH"] = dataclasses.replace(
                ov, min_est_total=0.10)
            self.assertEqual(imm.series_min_est_total("KXTEMPDCH"),
                             imm.PAYOUT_FLOOR_DOLLARS)
        finally:
            imm.SERIES_OVERRIDES["KXTEMPDCH"] = ov
        for s, o in imm.SERIES_OVERRIDES.items():
            if o.min_est_total is not None:
                self.assertGreaterEqual(
                    imm.series_min_est_total(s), imm.PAYOUT_FLOOR_DOLLARS,
                    f"{s} entry floor sits under the exchange payout minimum")

    def test_temp_band_trims_ladder(self):
        # bid anchor at 6c: levels at 6/5/4 -> the 4c rung is below the 5c
        # floor and must be dropped; ask anchor 89: rungs 89/90/91 -> 91 over.
        bids = imm.build_side_ladder("KXTEMPDCH-26JUL2112-T80.99", "bid",
                                     6, 10, 100)
        self.assertEqual([q.price_cents for q in bids], [6, 5])
        asks = imm.build_side_ladder("KXTEMPDCH-26JUL2112-T80.99", "ask",
                                     89, 80, 100)
        self.assertEqual([q.price_cents for q in asks], [89, 90])
        # non-temp tickers now share the same 5..90 global band (2026-07-26):
        # the 4c rung dies for them too
        bids2 = imm.build_side_ladder("KXGOOD-99DEC31-A", "bid", 6, 10, 100)
        self.assertEqual([q.price_cents for q in bids2], [6, 5])

    def test_rain_series_share_the_weather_band(self):
        # Jack 2026-07-26: rain (daily + monthly city series) uses the same
        # 5..90c band as KXTEMP — caught the bot at 2cx3c on a dead
        # KXRAINHOUM strike under the 1..95 global band.
        for s in ("KXRAIN", "KXRAINHOUM", "KXRAINSTPM"):
            self.assertEqual(imm.series_price_min(s), 5, s)
            self.assertEqual(imm.series_price_max(s), 90, s)
        # band trims the ladder exactly like temp
        bids = imm.build_side_ladder("KXRAINHOUM-26JUL-6", "bid", 6, 10, 100)
        self.assertEqual([q.price_cents for q in bids], [6, 5])
        # the ladder stays global (band override); the daily keeps the
        # ticker-date cutoff, and since 2026-10-01 the monthlies carry the
        # monthly rain gate's 22:00 ET day-before-the-last-day cutoff
        for s in ("KXRAIN", "KXRAINHOUM"):
            self.assertIsNone(imm.series_override(s).levels, s)
        self.assertIsNone(imm.series_override("KXRAIN").cutoff_from_close_min)
        self.assertEqual(imm.series_override("KXRAINHOUM").cutoff_from_close_min,
                         imm.RAIN_MONTHLY_CUTOFF_FROM_CLOSE_MIN)

    def test_out_of_band_top_stands_aside_entirely(self):
        # Jack 2026-07-21: if the TOP of book is outside the band, no quotes
        # at all — not even the in-band side. Member boundary is the sticky
        # band (93 since 2026-08-03, was 98): a 96x98 top stands a member
        # down again — the Austin 96c pickoff class.
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        bot.run_cycle()
        t = "KXGOOD-99DEC31-A"
        self.assertTrue(bot.state.sim_orders)
        bot.client.books[t] = {"orderbook_fp": {
            "yes_dollars": [["0.96", "500"]], "no_dollars": [["0.02", "1200"]]}}
        bot.client.markets[t]["yes_bid_dollars"] = "0.9600"
        bot.client.markets[t]["yes_ask_dollars"] = "0.9800"
        bot.state.universe_at = time.time()      # no refresh: quote loop only
        bot.run_cycle()
        self.assertEqual(bot.state.sim_orders, {})   # beyond 93: stands aside
        self.assertIn(t, bot.state.selected)         # but still selected (sticky)

    def test_band_is_two_sided(self):
        # Live incident 2026-07-21: a BID at 97c filled on a likely-YES temp
        # strike — the band only floored bids and capped asks. Both bounds
        # must apply to both sides.
        bids = imm.build_side_ladder("KXTEMPDCH-26JUL2112-T80.99", "bid",
                                     97, 99, 100)     # rungs 97/96/95: all > 90
        self.assertEqual(bids, [])
        asks = imm.build_side_ladder("KXTEMPDCH-26JUL2112-T80.99", "ask",
                                     3, 1, 100)       # rungs 3/4/5: 3,4 < 5
        self.assertEqual([q.price_cents for q in asks], [5])
        # global band is 5..90 too (Jack 2026-07-26): rungs 97/96/95 all die
        bids2 = imm.build_side_ladder("KXGOOD-99DEC31-A", "bid", 97, 99, 100)
        self.assertEqual(bids2, [])
        bids3 = imm.build_side_ladder("KXGOOD-99DEC31-A", "bid", 91, 99, 100)
        self.assertEqual([q.price_cents for q in bids3], [90, 89])


class TestStickySelection(unittest.TestCase):
    """Jack 2026-07-21: Kalshi pays a market's daily accrual only above ~$1 —
    a quoted market must not be deselected by QUALITY screens mid-life, only
    by its natural end (cutoff/closing/program_over) or a safety stop."""

    T = "KXGOOD-99DEC31-A"

    def _quoting_bot(self):
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        bot.run_cycle()
        assert self.T in bot.state.selected
        return bot

    def test_quality_screen_does_not_drop_quoted_market(self):
        bot = self._quoting_bot()
        # book pins outside the mid band (mid 97 > MID_BAND_HI): a NEW market
        # would be screened extreme_mid, but a quoted one must be retained.
        bot.client.books[self.T] = {"orderbook_fp": {
            "yes_dollars": [["0.96", "500"]], "no_dollars": [["0.02", "1200"]]}}
        bot.client.markets[self.T]["yes_bid_dollars"] = "0.9600"
        bot.client.markets[self.T]["yes_ask_dollars"] = "0.9800"
        bot.state.universe_at = 0.0          # force refresh deterministically
        bot.run_cycle()
        self.assertIn(self.T, bot.state.selected)

    def test_one_sided_book_does_not_drop_quoted_market(self):
        bot = self._quoting_bot()
        bot.client.markets[self.T]["yes_bid_dollars"] = "0.0000"   # bid side gone
        bot.state.universe_at = 0.0
        bot.run_cycle()
        self.assertIn(self.T, bot.state.selected)

    def test_natural_end_still_drops(self):
        bot = self._quoting_bot()
        # close_time now inside MIN_HOURS_TO_CLOSE -> 'closing' is a death
        # reason; sticky must NOT override it.
        soon = (datetime.now(timezone.utc) + timedelta(minutes=20))
        bot.client.markets[self.T]["close_time"] = soon.strftime("%Y-%m-%dT%H:%M:%SZ")
        bot.state.universe_at = 0.0
        bot.run_cycle()
        self.assertNotIn(self.T, bot.state.selected)

    def test_hopeless_member_is_evicted(self):
        # Jack 2026-07-25 (REVERSES the 7/21 unconditional retention for this
        # one case): a member whose accrued + optimistic projection can't
        # reach the $1 min payout stops quoting mid-life — sub-$1 accrual
        # pays nothing, so riding it out is pure fill risk for zero reward.
        bot = self._quoting_bot()
        old_floor = imm.MIN_EST_TOTAL_DOLLARS
        imm.MIN_EST_TOTAL_DOLLARS = imm.PAYOUT_FLOOR_DOLLARS = 1e9        # projection can never reach
        try:
            bot._est_peak.clear()              # no stale peak credit
            # SUSTAINED, not a dip (Jack 2026-08-05): backdate the sub-bar
            # clock past the window, otherwise the dip guard rightly holds it.
            bot.state.hopeless_since[self.T] = (
                time.time() - imm.HOPELESS_SUSTAIN_SECS - 1)
            bot.state.universe_at = 0.0
            bot.run_cycle()
            self.assertNotIn(self.T, bot.state.selected)
        finally:
            imm.MIN_EST_TOTAL_DOLLARS, imm.PAYOUT_FLOOR_DOLLARS = old_floor, 1.0

    def test_finecon_member_survives_hopeless(self):
        # Jack 2026-09-03 ("once start quoting, should quote to completion.
        # dont unquote them"): the SAME sustained-hopeless setup that evicts
        # an ordinary member must not evict a finecon-group member.
        bot = self._quoting_bot()
        old_floor = imm.MIN_EST_TOTAL_DOLLARS
        old_fin = imm.FINECON_SERIES
        imm.MIN_EST_TOTAL_DOLLARS = imm.PAYOUT_FLOOR_DOLLARS = 1e9
        imm.FINECON_SERIES = old_fin | {"KXGOOD"}
        try:
            bot._est_peak.clear()
            bot.state.hopeless_since[self.T] = (
                time.time() - imm.HOPELESS_SUSTAIN_SECS - 1)
            bot.state.universe_at = 0.0
            bot.run_cycle()
            self.assertIn(self.T, bot.state.selected)
        finally:
            imm.MIN_EST_TOTAL_DOLLARS, imm.PAYOUT_FLOOR_DOLLARS = old_floor, 1.0
            imm.FINECON_SERIES = old_fin

    def test_hopeless_member_survives_a_dip(self):
        # The same market, WITHOUT a sustained sub-bar history, must keep
        # quoting — this is the regression that cost KXUST7AM 8 of 15 strikes.
        bot = self._quoting_bot()
        old_floor = imm.MIN_EST_TOTAL_DOLLARS
        imm.MIN_EST_TOTAL_DOLLARS = imm.PAYOUT_FLOOR_DOLLARS = 1e9
        try:
            bot._est_peak.clear()
            bot.state.hopeless_since.clear()   # first cycle under the bar
            bot.state.universe_at = 0.0
            bot.run_cycle()
            self.assertIn(self.T, bot.state.selected)
        finally:
            imm.MIN_EST_TOTAL_DOLLARS, imm.PAYOUT_FLOOR_DOLLARS = old_floor, 1.0

    def test_accrued_credit_retains_member(self):
        # ...but a member that already banked (most of) the $1 keeps quoting:
        # accrued + projection clears the bar even when the remaining window
        # alone can't (the 7/24 TRUMPMENTION rule — protect earned accruals
        # whenever finishing the job is plausible).
        bot = self._quoting_bot()
        old_floor = imm.MIN_EST_TOTAL_DOLLARS
        imm.MIN_EST_TOTAL_DOLLARS = imm.PAYOUT_FLOOR_DOLLARS = 1e9
        try:
            bot.state.accrued_est[self.T] = 2e9
            bot.state.universe_at = 0.0
            bot.run_cycle()
            self.assertIn(self.T, bot.state.selected)
        finally:
            imm.MIN_EST_TOTAL_DOLLARS, imm.PAYOUT_FLOOR_DOLLARS = old_floor, 1.0

    def test_floor_credit_is_this_periods_accrual(self):
        # Jack 2026-09-22 pm, KXRT-STRA-50 / -45: "why is this quoted? it
        # should be hopeless". Kalshi had re-listed the program as a fresh
        # one-day period; the two had accrued $0.09 / $0.06 in it, but the
        # projection credited their LIFETIME accrued_est ($5 / $7, paid out
        # in the period that had just ended), so the hopeless clock never
        # started. The exchange's $1 floor is per program period, so the
        # credit is accrued_est - period_base (this period), not lifetime.
        bot = self._quoting_bot()
        old_floor = imm.MIN_EST_TOTAL_DOLLARS
        imm.MIN_EST_TOTAL_DOLLARS = imm.PAYOUT_FLOOR_DOLLARS = 1e9
        try:
            bot._est_peak.clear()
            bot.state.hopeless_since[self.T] = (
                time.time() - imm.HOPELESS_SUSTAIN_SECS - 1)
            # a market that banked a fortune in EARLIER periods and nothing
            # in this one is hopeless
            bot.state.accrued_est[self.T] = 2e9
            bot.state.period_base[self.T] = 2e9
            self.assertAlmostEqual(bot.period_accrued(self.T), 0.0)
            bot.state.universe_at = 0.0
            bot.run_cycle()
            self.assertNotIn(self.T, bot.state.selected)
        finally:
            imm.MIN_EST_TOTAL_DOLLARS, imm.PAYOUT_FLOOR_DOLLARS = old_floor, 1.0

    def test_floor_credit_keeps_a_member_that_banked_this_period(self):
        # ...while one whose THIS-period accrual clears the bar keeps
        # quoting (the 7/24 rule, now measured per period), and the kill
        # switch restores the lifetime credit.
        bot = self._quoting_bot()
        old_floor = imm.MIN_EST_TOTAL_DOLLARS
        imm.MIN_EST_TOTAL_DOLLARS = imm.PAYOUT_FLOOR_DOLLARS = 1e9
        try:
            bot._est_peak.clear()
            bot.state.hopeless_since[self.T] = (
                time.time() - imm.HOPELESS_SUSTAIN_SECS - 1)
            bot.state.accrued_est[self.T] = 5e9
            bot.state.period_base[self.T] = 2e9
            self.assertAlmostEqual(bot.period_accrued(self.T), 3e9)
            bot.state.universe_at = 0.0
            bot.run_cycle()
            self.assertIn(self.T, bot.state.selected)
            # kill switch: the lifetime credit, the pre-2026-09-22 reading
            bot.state.accrued_est[self.T] = 2e9
            bot.state.period_base[self.T] = 2e9
            bot.state.hopeless_since[self.T] = (
                time.time() - imm.HOPELESS_SUSTAIN_SECS - 1)
            with mock.patch.object(imm, "FLOOR_ACCRUAL_PER_PERIOD", False):
                self.assertAlmostEqual(bot.period_accrued(self.T), 2e9)
                bot.state.universe_at = 0.0
                bot.run_cycle()
                self.assertIn(self.T, bot.state.selected)
        finally:
            imm.MIN_EST_TOTAL_DOLLARS, imm.PAYOUT_FLOOR_DOLLARS = old_floor, 1.0

    def test_hopeless_exit_kill_switch(self):
        # IMM_HOPELESS_EXIT=0 restores the unconditional 7/21 retention.
        bot = self._quoting_bot()
        old_floor, old_flag = imm.MIN_EST_TOTAL_DOLLARS, imm.HOPELESS_EXIT
        imm.MIN_EST_TOTAL_DOLLARS, imm.HOPELESS_EXIT = 1e9, False
        try:
            bot._est_peak.clear()
            bot.state.universe_at = 0.0
            bot.run_cycle()
            self.assertIn(self.T, bot.state.selected)
        finally:
            imm.MIN_EST_TOTAL_DOLLARS, imm.HOPELESS_EXIT = old_floor, old_flag

    def test_rate_floor_beats_curated_override(self):
        # Jack 2026-08-02 TLN audit: an auto-written disclosure override
        # curated KXTLN-26AUGGEN past the $2 bar at ~$0.45/day est. The
        # re-entry RATE floor must gate FRESH candidates even on curated
        # events (members stay sticky; the est_TOTAL bypass rationale does
        # not apply to a per-day rate).
        bot = self._quoting_bot()
        old_ov = imm.SERIES_OVERRIDES.get("KXGOOD")
        imm.SERIES_OVERRIDES["KXGOOD"] = imm.SeriesOverride(min_est_per_day=1e9)
        imm.EVENT_START_OVERRIDES["KXGOOD-99DEC31"] = utc(2099, 1, 1)
        try:
            bot.state.selected.pop(self.T, None)      # make it FRESH
            bot.state.sticky_prev.discard(self.T)
            bot._est_peak.clear()
            bot.state.universe_at = 0.0
            bot.run_cycle()
            self.assertNotIn(self.T, bot.state.selected)   # rate-floored
        finally:
            imm.EVENT_START_OVERRIDES.pop("KXGOOD-99DEC31", None)
            if old_ov is None:
                imm.SERIES_OVERRIDES.pop("KXGOOD", None)
            else:
                imm.SERIES_OVERRIDES["KXGOOD"] = old_ov

    def test_dieselmonak_enrolled_with_the_diesel_guards(self):
        # Jack 2026-09-27: "allowlist KXDIESELMONAK" (AAA Alaska diesel on
        # one date, open across six daily AAA prints -- the KXDIESELW shape)
        s = "KXDIESELMONAK"
        self.assertIn(s, imm.ALLOW_SERIES)
        self.assertFalse(imm.series_pattern_blocked(s))
        self.assertTrue(imm.series_safe_join(s))
        self.assertEqual(imm.series_min_est_rate(s), imm.series_min_est_rate("KXDIESELD"))
        self.assertEqual(imm.series_override(s).blackout_et, ("03:05", "04:00"))
        self.assertTrue(imm.series_in_blackout(s, imm.ET.localize(
            datetime(2026, 9, 28, 3, 20)).astimezone(timezone.utc)))
        # no per-event cap (Jack 2026-09-27: "no 3 market max for this
        # one"); the rest of the diesel family keeps its 3
        self.assertEqual(imm.event_top_n_for(s), 0)
        for other in ("KXDIESELD", "KXDIESELW", "KXDIESELMON", "KXDIESELM"):
            self.assertEqual(imm.event_top_n_for(other), 3, other)
        # the day-dated ticker: out at 00:00 ET on the print day, before the
        # 00:29 ET close and the ~03:20 ET print
        cut = imm.trade_cutoff_utc(
            "KXDIESELMONAK-26SEP30",
            datetime(2026, 9, 30, 6, 0, tzinfo=timezone.utc),
            datetime(2026, 10, 7, 6, 0, tzinfo=timezone.utc))
        self.assertEqual(cut, datetime(2026, 9, 30, 4, 0, tzinfo=timezone.utc))

    def test_aaa_print_blackout_window(self):
        # Jack 2026-08-04: AAA posts gas AND diesel 03:18-03:36 ET (5 days
        # observed at 5s resolution). Weekly/monthly markets stay open across
        # the print and measured -14.4c/contract in hour 3.
        def at(hh, mm):
            return imm.ET.localize(
                datetime(2026, 8, 5, hh, mm)).astimezone(timezone.utc)
        for s in ("KXAAAGASW", "KXAAAGASM", "KXDIESELW"):
            self.assertEqual(imm.series_override(s).blackout_et,
                             ("03:05", "04:00"), s)
            self.assertFalse(imm.series_in_blackout(s, at(2, 50)), s)
            self.assertTrue(imm.series_in_blackout(s, at(3, 18)), s)
            self.assertTrue(imm.series_in_blackout(s, at(3, 36)), s)
            self.assertFalse(imm.series_in_blackout(s, at(4, 5)), s)
        # 2026-10-01, the gas trial (Jack: "adjust all three to trade
        # 1pm-midnight", then "National + diesel only"): the national gas
        # and diesel DAILIES quote 13:00 ET to the close; their no-quote
        # window 00:00-13:00 ET contains the print blackout
        self.assertEqual(imm.GAS_TRIAL_SERIES, ("KXAAAGASD", "KXDIESELD"))
        for s in ("KXAAAGASD", "KXDIESELD"):
            self.assertEqual(imm.series_override(s).blackout_et,
                             ("00:00", "13:00"), s)
            for hh, mm in ((0, 0), (3, 18), (8, 0), (12, 59)):
                self.assertTrue(imm.series_in_blackout(s, at(hh, mm)), (s, hh, mm))
            for hh, mm in ((13, 0), (18, 30), (23, 59)):
                self.assertFalse(imm.series_in_blackout(s, at(hh, mm)), (s, hh, mm))
        # KXDIESELW keeps its $0 rate floor: the blackout must not have
        # clobbered the series override it was merged into
        self.assertEqual(imm.series_min_est_rate("KXDIESELW"), 0.0)
        # non-AAA series unaffected at the same instant
        self.assertFalse(imm.series_in_blackout("KXTEMPDCH", at(3, 20)))

    def test_close_anchored_cutoff_applies_to_both_producers(self):
        # LIVE BUG 2026-08-04: refresh_universe applied the temp close-10 rule
        # but restore_orphan_metas did not, so orphan-restored temp markets
        # quoted to the CLOSE — 7 fills landed as late as 6.7 min to close.
        # The shared tightener must produce close-10 from a raw close-time
        # cutoff, which is exactly what the restore path feeds it.
        close = utc(2026, 8, 4, 4, 0)
        got = imm.apply_series_cutoff_adjustments(
            "KXTEMPAUSH", "KXTEMPAUSH-26AUG0400", close, close_time=close)
        self.assertEqual(got, utc(2026, 8, 4, 3, 50))
        # with no cutoff at all it still anchors off the close
        got = imm.apply_series_cutoff_adjustments(
            "KXTEMPAUSH", "KXTEMPAUSH-26AUG0400", None, close_time=close)
        self.assertEqual(got, utc(2026, 8, 4, 3, 50))
        # never LOOSENS an already-tighter cutoff
        tight = utc(2026, 8, 4, 3, 30)
        got = imm.apply_series_cutoff_adjustments(
            "KXTEMPAUSH", "KXTEMPAUSH-26AUG0400", tight, close_time=close)
        self.assertEqual(got, tight)
        # non-close-anchored series unaffected
        got = imm.apply_series_cutoff_adjustments(
            "KXGOOD", "KXGOOD-99DEC31", close, close_time=close)
        self.assertEqual(got, close)

    def test_truev_print_day_market_survives_its_own_ticker_date(self):
        # Kalshi lists each KXTRUEV daily ON its print day (Jack 2026-08-24:
        # the enrollment shipped dark — the midnight-ET rule's cutoff was
        # already past the moment each market appeared). The close-anchored
        # override governs instead: refresh_universe's cutoff_from_close_min
        # branch skips trade_cutoff_utc entirely, and the shared tightener
        # yields close-60 for both producers.
        close = utc(2026, 8, 25, 21, 0)   # print day Aug 25, 5pm ET close
