class _FillJoinClient(FakeClient):
    """FakeClient with a resting book (get_orders serves `resting`, a cancel
    takes an order off it) and Kalshi's answer for an order that already
    filled out: a cancel or amend of an id in `dead` raises its status."""

    def __init__(self, resting=()):
        super().__init__()
        self.resting = [dict(o) for o in resting]
        self.dead = {}          # order id -> HTTP status

    def get_orders(self, **kw):
        return {"orders": [dict(o) for o in self.resting], "cursor": None}

    def cancel_order(self, order_id):
        if order_id in self.dead:
            raise HttpError("Not Found", self.dead[order_id])
        super().cancel_order(order_id)
        self.resting = [o for o in self.resting if o["order_id"] != order_id]
        return {}

    def amend_order(self, **kw):
        if kw["order_id"] in self.dead:
            raise HttpError("Conflict", self.dead[kw["order_id"]])
        self.amended = getattr(self, "amended", []) + [kw]
        return {"order": {"order_id": kw["order_id"]}}


class TestFillLedgerJoin(unittest.TestCase):
    """2026-10-04. Each fills_*.jsonl row joins the order its fill hit (side,
    price, size, client id, age, pad). The join read state.ledger when the
    fill was booked, but the ledger lets an order go BEFORE the next poll
    books its fill: _merge_ledger drops one the resting read no longer holds
    (it filled out), a cancel or amend answered 404/409 drops it, our own
    cancel after a partial fill drops it, and a restart starts empty -- 231
    of 482 maker fill rows on 10/4 (to ~22:00Z) had no join. An amend
    overwrote the price too (37 joined rows on 10/3-10/4). The row now
    joins _fill_join: every version the ledger gave the order, kept past
    the ledger and handed over at a restart."""

    T = "KXGOOD-99DEC31-A"
    JOIN = ("our_book_side", "our_price_cents", "our_remaining_before",
            "our_left_before", "join_src")

    def setUp(self):
        _clean_persist()
        self.dir = tempfile.mkdtemp(prefix="imm_fill_join_")
        p = mock.patch.object(imm, "STATUS_DIR", self.dir)
        p.start()
        self.addCleanup(p.stop)

    def _bot(self, client=None):
        bot = IncentiveMarketMaker(client=client or _FillJoinClient(), live=True)
        bot.state.universe_at = time.time()          # no universe refresh
        return bot

    def _rows(self):
        out = []
        for p in sorted(glob.glob(os.path.join(self.dir, "fills_*.jsonl"))):
            with open(p, encoding="utf-8") as f:
                out.extend(json.loads(ln) for ln in f if ln.strip())
        return out

    def _by_id(self):
        return {r["fill_id"]: r for r in self._rows()}

    def _join(self, row):
        return tuple(row[k] for k in self.JOIN)

    def _fill(self, fid, oid, count, cents, ts, side="no", action="buy"):
        """One of our maker fills as Kalshi's fills read returns it (an ask
        of ours lifted is a NO buy)."""
        return {"fill_id": fid, "trade_id": fid, "order_id": oid,
                "ticker": self.T, "side": side, "action": action,
                "count_fp": f"{count:.2f}",
                "yes_price_dollars": f"{cents / 100:.4f}",
                "ts": int(ts), "is_taker": False}

    @staticmethod
    def _at(ts):
        """Pin the bot's wall clock (the version stamps) to `ts`."""
        return mock.patch.object(imm.time, "time", return_value=ts)

    # -- a fill that clears its order ---------------------------------------

    def test_a_fill_that_clears_its_order_keeps_the_join(self):
        """The bulk of 10/4 (87 rows, and 40 more on adopted orders): the
        order fills out after one cycle's fills poll, that cycle's resting
        read no longer holds it, _merge_ledger drops it, and the NEXT poll
        books the fill. That poll comes newest first: the 15 that cleared the
        order reads 15 left -- a full-rung fill."""
        bot = self._bot()
        t0 = time.time()
        self.assertTrue(bot.place_order(Quote(self.T, "ask", 41, 20), t0 - 60))
        oid = "real-1"
        coid = bot.state.ledger[oid]["client_order_id"]
        bot._merge_ledger([{"order_id": oid, "ticker": self.T,
                            "status": "resting"}], t0)       # confirmed
        bot.run_cycle()                  # the resting read no longer holds it
        self.assertNotIn(oid, bot.state.ledger)
        bot.client.fills = [self._fill("t2", oid, 15, 41, t0 + 10),
                            self._fill("t1", oid, 5, 41, t0 + 5)]
        bot.client.positions[self.T] = -20.0      # the account holds them too
        bot.run_cycle()
        rows = self._by_id()
        self.assertEqual(self._join(rows["t1"]), ("ask", 41, 20.0, 20.0, "ledger"))
        self.assertEqual(self._join(rows["t2"]), ("ask", 41, 20.0, 15.0, "ledger"))
        r = rows["t2"]
        self.assertEqual((r["client_order_id"], r["is_pad"]), (coid, False))
        self.assertGreaterEqual(r["order_age_secs"], 60.0)
        # the fills are booked exactly as before
        self.assertAlmostEqual(bot.pnl.pos[self.T], -20.0)
        self.assertAlmostEqual(bot.state.fills_today, 20.0)

    def test_a_cancel_or_amend_that_finds_the_order_gone_keeps_the_join(self):
        """The order filled out and our cancel (26 rows on 10/4) or amend got
        404/409, which drops it from the ledger before the poll books the
        fill."""
        for path, status in (("cancel", 404), ("cancel", 409), ("amend", 404),
                             ("amend", 409)):
            with self.subTest(path=path, status=status):
                _clean_persist()
                for p in glob.glob(os.path.join(self.dir, "fills_*.jsonl")):
                    os.remove(p)
                bot = self._bot()
                t0 = time.time()
                bot.place_order(Quote(self.T, "bid", 40, 30), t0)
                oid = "real-1"
                bot.client.dead[oid] = status
                if path == "cancel":
                    self.assertTrue(bot.cancel_order(oid, reason="requote_diff"))
                else:
                    self.assertFalse(bot.amend_order_inplace(
                        dict(bot.state.ledger[oid]), Quote(self.T, "bid", 39, 30), t0))
                self.assertNotIn(oid, bot.state.ledger)
                bot.client.fills = [self._fill("t1", oid, 30, 40, t0 + 5,
                                               side="yes", action="buy")]
                bot.run_cycle()
                (row,) = self._rows()
                self.assertEqual(self._join(row), ("bid", 40, 30.0, 30.0, "ledger"))

    # -- a partial fill ----------------------------------------------------

    def test_partial_fills_keep_the_join_and_say_what_was_left(self):
        """A partial fill while the order rests is joined, and so is the next
        one after our own cancel pulled the rest before the poll (23 rows on
        10/4). our_remaining_before is the size as we set it (60);
        our_left_before nets the order's earlier fills, so neither partial
        reads as taking the rung."""
        bot = self._bot()
        t0 = time.time()
        bot.place_order(Quote(self.T, "ask", 41, 60), t0)
        oid = "real-1"
        bot.client.fills = [self._fill("t1", oid, 20, 41, t0 + 5)]
        # the poll books the partial; then (an unmanaged market here, a
        # requote or TTL renewal live) the cycle cancels what is left
        bot.run_cycle()
        self.assertIn(oid, bot.client.cancelled)
        self.assertNotIn(oid, bot.state.ledger)
        # a second partial landed before that cancel; the next poll books it
        bot.client.fills = [self._fill("t2", oid, 15, 41, t0 + 8)]
        bot.run_cycle()
        rows = self._by_id()
        self.assertEqual(self._join(rows["t1"]), ("ask", 41, 60.0, 60.0, "ledger"))
        self.assertEqual(self._join(rows["t2"]), ("ask", 41, 60.0, 40.0, "ledger"))
        for r in rows.values():
            self.assertLess(r["count"], r["our_left_before"])

    def test_a_fill_booked_after_an_amend_joins_the_price_it_hit(self):
        """10/4 KXTRUMPAPPROVE-26OCT04-E38.1: 79.11 filled at 35, the order was
        amended to 40 x 120 a minute later, and the poll after that logged the
        fill at 40 / 120. The row takes the version in force at the fill."""
        bot = self._bot()
        t0 = time.time()
        with self._at(t0 - 300):
            bot.place_order(Quote(self.T, "ask", 35, 90), t0 - 300)
        oid = "real-1"
        with self._at(t0 - 100):
            self.assertTrue(bot.amend_order_inplace(
                dict(bot.state.ledger[oid]), Quote(self.T, "ask", 40, 120), t0 - 100))
        self.assertEqual(bot.state.ledger[oid]["yes_price"], 40)
        bot.client.fills = [self._fill("t2", oid, 30, 40, t0 - 50),
                            self._fill("t1", oid, 79.11, 35, t0 - 200)]
        bot.run_cycle()
        rows = self._by_id()
        self.assertEqual(self._join(rows["t1"]), ("ask", 35, 90.0, 90.0, "ledger"))
        self.assertEqual(self._join(rows["t2"]), ("ask", 40, 120.0, 120.0, "ledger"))

    def test_the_version_pick_trusts_the_fills_price_inside_the_stamp(self):
        """Kalshi stamps whole seconds: an amend set 1.5s after the stamp may
        be the one the fill hit -- its price says so. A fill older than every
        version takes the first, and knows no size before it."""
        vs = [[100.0, 41, None, 60.0, "ledger"], [201.5, 42, None, 30.0, "ledger"]]
        self.assertEqual(imm._join_pick(vs, 150, 41.0), 0)
        self.assertEqual(imm._join_pick(vs, 200, 42.0), 1)     # amend 1.5s on
        self.assertEqual(imm._join_pick(vs, 200, 41.0), 0)     # fill before it
        self.assertEqual(imm._join_pick(vs, 250, 41.0), 0)     # price over clock
        self.assertEqual(imm._join_pick(vs, 250, 45.0), 1)     # no price: clock
        self.assertEqual(imm._join_pick(vs, 50, 41.0), 0)      # predates both
        sub = [[100.0, 42, 41.5, 20.0, "ledger"]]               # sub-penny ask
        self.assertTrue(imm._join_px_ok(sub[0], 41.5))
        self.assertFalse(imm._join_px_ok(sub[0], 42.0))
        ent = {"v": vs, "f": {}}
        self.assertIsNone(IncentiveMarketMaker._join_left(ent, 0, 50, "x"))

    # -- a fill on an order adopted at a restart handoff ---------------------

    def _old_run_hands_over(self, t0):
        """A run that placed X (ask 41 x 20) and Y (ask 43 x 30) at t0, booked
        a 5-lot on X, and handed both over at a planned restart."""
        old = self._bot()
        with self._at(t0):
            old.place_order(Quote(self.T, "ask", 41, 20), t0)
            old.place_order(Quote(self.T, "ask", 43, 30), t0)
        coid = {o: old.state.ledger[o]["client_order_id"] for o in ("real-1", "real-2")}
        old._book_fill(self._fill("t1", "real-1", 5, 41, t0 + 10), t0 + 15)
        born = datetime.fromtimestamp(t0, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        old.client.resting = [
            {"order_id": o, "ticker": self.T, "status": "resting",
             "client_order_id": coid[o], "book_side": "ask", "yes_price": px,
             "remaining_count": n, "created_time": born}
            for o, px, n in (("real-1", 41, 15), ("real-2", 43, 30))]
        now = datetime.now(timezone.utc)
        old.state.selected[self.T] = MarketMeta(
            ticker=self.T, event_ticker="KXGOOD-99DEC31", series="KXGOOD",
            dollars_per_day=10.0, program_end=now + timedelta(days=3),
            target_size=1000.0, discount_factor=0.5,
            cutoff=now + timedelta(days=2), close_time=now + timedelta(days=4))
        with mock.patch.object(old, "_restart_preflight", return_value=(True, "ok")):
            self.assertTrue(old._prepare_restart_handoff())
        return old, coid

    def test_a_fill_on_an_order_adopted_at_a_restart_handoff_keeps_the_join(self):
        """On 10/4 (22 runs), 93 unjoined rows were on orders an earlier run
        placed: 51 adopted and then dropped like any other, 42 filled in the
        restart gap, which the old run's last poll missed and the new run's
        ledger never held. The old run now hands its join over with the book.
        In the gap Y filled out (never adopted) and X took 5 more; after
        adoption X filled out."""
        t0 = time.time() - 120
        old, coid = self._old_run_hands_over(t0)
        with open(imm.restart_handoff_path(), encoding="utf-8") as f:
            self.assertEqual(sorted(json.load(f)["fill_join"]), ["real-1", "real-2"])
        # the relaunch: Y is gone, X rests with 10 left
        new = self._bot(_FillJoinClient([dict(old.client.resting[0],
                                              remaining_count=10)]))
        for o in ("real-1", "real-2"):        # persisted across restarts live
            new.state.our_order_ids.setdefault(o, t0)
        self.assertEqual(new._adopt_restart_handoff(), 1)
        self.assertEqual(new.state.ledger["real-1"]["remaining_count"], 10.0)
        self.assertNotIn("real-2", new.state.ledger)
        now = time.time()
        new.client.fills = [self._fill("t4", "real-1", 10, 41, now + 30),
                            self._fill("t3", "real-1", 5, 41, t0 + 95),
                            self._fill("t2", "real-2", 30, 43, t0 + 90)]
        new.run_cycle()
        rows = self._by_id()
        # Y, filled out in the gap: the old run's record
        self.assertEqual(self._join(rows["t2"]), ("ask", 43, 30.0, 30.0, "handoff"))
        self.assertEqual(rows["t2"]["client_order_id"], coid["real-2"])
        # X's gap fill: the old run's version, net of the 5 that run booked
        self.assertEqual(self._join(rows["t3"]), ("ask", 41, 20.0, 15.0, "handoff"))
        # X after adoption: the adopted version (10 left), which it cleared
        self.assertEqual(self._join(rows["t4"]), ("ask", 41, 10.0, 10.0, "ledger"))
        self.assertEqual(rows["t4"]["client_order_id"], coid["real-1"])
        self.assertGreater(rows["t4"]["order_age_secs"], 100.0)

    def test_an_adopted_order_without_a_handed_over_join_keeps_what_it_knows(self):
        """The first restart onto this code: the old run's handoff carries no
        join. A gap fill on an adopted order predates the adopted version,
        so it keeps the side, price and client id but no size; a fill after
        adoption has all of it."""
        t0 = time.time() - 120
        with open(imm.restart_handoff_path(), "w", encoding="utf-8") as f:
            json.dump({"ts": time.time() - 30, "run_id": "old", "kept": 1,
                       "order_ids": ["o9"]}, f)
        born = datetime.fromtimestamp(t0, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        bot = self._bot(_FillJoinClient([{
            "order_id": "o9", "ticker": self.T, "status": "resting",
            "client_order_id": "imm-old-o9", "book_side": "bid",
            "yes_price_dollars": "0.3800", "remaining_count": 25,
            "created_time": born}]))
        self.assertEqual(bot._adopt_restart_handoff(), 1)
        now = time.time()
        bot.client.fills = [
            self._fill("a2", "o9", 25, 38, now + 30, side="yes", action="buy"),
            self._fill("a1", "o9", 5, 38, now - 60, side="yes", action="buy")]
        bot.run_cycle()
        rows = self._by_id()
        self.assertEqual(self._join(rows["a1"]), ("bid", 38, None, None, "ledger"))
        self.assertEqual(rows["a1"]["client_order_id"], "imm-old-o9")
        self.assertEqual(self._join(rows["a2"]), ("bid", 38, 25.0, 25.0, "ledger"))

    # -- the fallback, the bounds, and the guarantees ------------------------

    def test_no_record_of_the_order_derives_the_side_from_kalshis(self):
        """A fill on an order no run recorded (a crash restart, a taker
        order): our_book_side from Kalshi's side / action, marked derived."""
        bot = self._bot()
        now = time.time()
        for i, (side, action) in enumerate((("yes", "buy"), ("no", "sell"),
                                            ("yes", "sell"), ("no", "buy"))):
            bot._book_fill(self._fill(f"d{i}", f"x{i}", 5, 50, now,
                                      side=side, action=action), now)
        rows = self._rows()
        self.assertEqual([r["our_book_side"] for r in rows],
                         ["bid", "bid", "ask", "ask"])
        for r in rows:
            self.assertEqual(r["join_src"], "derived")
            for k in ("our_price_cents", "our_remaining_before", "our_left_before",
                      "client_order_id", "order_age_secs", "is_pad"):
                self.assertIsNone(r[k], k)

    def test_an_order_is_kept_a_while_after_it_leaves_the_ledger(self):
        bot = self._bot()
        now = time.time()
        bot.place_order(Quote(self.T, "bid", 40, 10), now)
        bot.place_order(Quote(self.T, "bid", 39, 10), now)
        bot._join_prune(now + 10 * imm.FILL_JOIN_KEEP_SECS)   # in the ledger
        self.assertEqual(sorted(bot._fill_join), ["real-1", "real-2"])
        bot.state.ledger.pop("real-1")
        bot._join_prune(now)                                  # first seen gone
        bot._join_prune(now + imm.FILL_JOIN_KEEP_SECS)
        self.assertIn("real-1", bot._fill_join)
        bot._join_prune(now + imm.FILL_JOIN_KEEP_SECS + 1)
        self.assertEqual(sorted(bot._fill_join), ["real-2"])
        # the ceiling drops gone orders, oldest first
        bot.state.ledger.clear()
        bot._fill_join.clear()
        for i in range(3):
            bot._fill_join[f"g{i}"] = {"t": self.T, "side": "bid", "coid": None,
                                       "placed": None, "v": [], "f": {},
                                       "gone": now + i}
        with mock.patch.object(imm, "FILL_JOIN_MAX_ORDERS", 2):
            bot._join_prune(now + 5)
        self.assertEqual(sorted(bot._fill_join), ["g1", "g2"])

    def test_analytics_off_keeps_no_join(self):
        with mock.patch.object(IncentiveMarketMaker, "ANALYTICS_ON", False):
            bot = self._bot()
            self.assertTrue(bot.place_order(Quote(self.T, "bid", 40, 10), time.time()))
            self.assertEqual(bot._fill_join, {})
            self.assertEqual(bot._join_import({"o": {"v": [[1.0, 40, None, 5.0]]}}), 0)

    def test_a_broken_join_never_stops_an_order_or_a_row(self):
        """The join sits in the order paths: a failure inside it costs one log
        line, never an order, a booked fill or the row (the ledger answers
        as it did before 2026-10-04)."""
        bot = self._bot()
        bot._fill_join = None                # every join call now fails inside
        now = time.time()
        self.assertTrue(bot.place_order(Quote(self.T, "bid", 40, 10), now))
        self.assertIn("real-1", bot.state.ledger)
        bot._join_note_fills([self._fill("t1", "real-1", 10, 40, now, side="yes")])
        bot._book_fill(self._fill("t1", "real-1", 10, 40, now, side="yes",
                                  action="buy"), now)
        (row,) = self._rows()
        self.assertEqual((row["our_book_side"], row["our_price_cents"],
                          row["join_src"]), ("bid", 40, "ledger"))
        self.assertAlmostEqual(bot.pnl.pos[self.T], 10.0)
        self.assertEqual(bot._join_export(), {})
        self.assertIn("fill_join", bot._sink_muted)
        self.assertNotIn("fills", bot._sink_muted)

    def test_a_malformed_handoff_join_is_skipped(self):
        bot = self._bot()
        n = bot._join_import({
            "ok": {"t": self.T, "side": "bid", "coid": "c", "placed": 1.0,
                   "v": [[1.0, 40, None, 5.0]], "f": {"x": [2.0, 1.0, 0]}},
            "bad_v": {"v": [["nan?", "x"]]},
            "empty": {"v": []},
            "bad_f": {"v": [[1.0, 40, None, 5.0]], "f": {"y": [2.0, 1.0, 7]}}})
        self.assertEqual(n, 2)
        self.assertEqual(bot._fill_join["ok"]["v"][0][4], "handoff")
        self.assertEqual(bot._fill_join["bad_f"]["f"], {})


class TestPlaceUncertain(unittest.TestCase):
    def test_uncertain_level_skipped_then_expires(self):
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        now = time.time()
        bot.state.place_uncertain[("T", "bid", 49)] = now
        placed = bot.place_with_caps(
            [Quote("T", "bid", 49, 5), Quote("T", "bid", 48, 10)], [], set(), now)
        self.assertEqual(placed, 1)   # only the 48c level
        # cooldown expired -> level placeable again
        bot.state.place_uncertain[("T", "bid", 49)] = now - 2 * imm.POLL_SECS - 1
        placed = bot.place_with_caps([Quote("T", "bid", 49, 5)], [], set(), now)
        self.assertEqual(placed, 1)
        self.assertNotIn(("T", "bid", 49), bot.state.place_uncertain)


class TestPersistence(unittest.TestCase):
    def test_round_trip(self):
        _clean_persist()
        try:
            bot = IncentiveMarketMaker(client=FakeClient(), live=False)
            bot.state.known_tickers = {"A", "B"}
            bot.state.last_fill_ts = 1234
            bot.state.seen_fill_ids = {"f1": 1234}
            bot.state.our_order_ids = {"o1": time.time()}
            bot.pnl.pos["A"] = 12.0
            bot.pnl.avg["A"] = 37.5
            bot._save_persist()
            bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
            self.assertEqual(bot2.state.known_tickers, {"A", "B"})
            self.assertEqual(bot2.state.last_fill_ts, 1234)
            self.assertEqual(bot2.state.seen_fill_ids, {"f1": 1234})
            self.assertIn("o1", bot2.state.our_order_ids)
            self.assertAlmostEqual(bot2.pnl.pos["A"], 12.0)
            self.assertAlmostEqual(bot2.pnl.avg["A"], 37.5)   # MTM needs entry cost
        finally:
            _clean_persist()

    def test_stale_order_ids_pruned_on_save(self):
        _clean_persist()
        try:
            bot = IncentiveMarketMaker(client=FakeClient(), live=False)
            bot.state.our_order_ids = {"old": time.time() - 8 * 86400,
                                       "new": time.time()}
            bot._save_persist()
            bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
            self.assertEqual(set(bot2.state.our_order_ids), {"new"})
        finally:
            _clean_persist()

    def test_orphan_position_restored_reduce_only(self):
        """Restart with OUR inventory on a no-longer-selected market: meta is
        rebuilt from the market read and only the reducing side is quoted.
        Wind-down ARMED (off by default since 2026-09-07)."""
        _clean_persist()
        self.enterContext(mock.patch.object(imm, "WINDDOWN_DROPPED", True))
        client = FakeClient()
        bot = IncentiveMarketMaker(client=client, live=False)
        t = "KXGOOD-99DEC31-A"
        client.programs = []               # not selectable anymore
        client.positions[t] = 12
        bot.state.known_tickers = {t}      # as restored from disk
        bot.pnl.pos[t] = 12.0              # own book restored from disk too
        bot.run_cycle()
        self.assertIn(t, bot.state.managed_extra)
        orders = list(bot.state.sim_orders.values())
        self.assertTrue(orders)
        self.assertTrue(all(o["book_side"] == "ask" for o in orders))
        self.assertLessEqual(sum(o["remaining_count"] for o in orders), 12)

    def test_orphan_manual_position_not_adopted(self):
        """A MANUAL position on a once-quoted market is the user's business:
        no reduce-only management, no quotes."""
        _clean_persist()
        client = FakeClient()
        bot = IncentiveMarketMaker(client=client, live=False)
        t = "KXGOOD-99DEC31-A"
        client.programs = []
        client.positions[t] = 12           # account holds it...
        bot.state.known_tickers = {t}      # ...on a market we once quoted...
        bot.run_cycle()                    # ...but our own book is empty
        self.assertNotIn(t, bot.state.managed_extra)
        self.assertEqual(bot.state.sim_orders, {})


class TestManualStandoff(unittest.TestCase):
    def _bot(self):
        _clean_persist()
        return IncentiveMarketMaker(client=FakeClient(), live=False)

    def test_manual_position_yields_market(self):
        """User trades a market the bot is quoting -> quotes cancelled,
        market deselected, standoff recorded."""
        bot = self._bot()
        bot.run_cycle()
        t = "KXGOOD-99DEC31-A"
        self.assertTrue(bot.state.sim_orders)
        bot.client.positions[t] = 50       # manual: our own book is still 0
        bot.run_cycle()
        self.assertEqual(bot.state.sim_orders, {})
        self.assertNotIn(t, bot.state.selected)
        self.assertIn(t, bot.state.manual_standoff)

    def test_standoff_blocks_reselection(self):
        bot = self._bot()
        bot.run_cycle()
        t = "KXGOOD-99DEC31-A"
        bot.client.positions[t] = 50
        bot.run_cycle()                    # yields
        bot.state.universe_at = 0.0        # force refresh
        bot.run_cycle()
        self.assertNotIn(t, bot.state.selected)
        self.assertEqual(bot.state.sim_orders, {})

    def test_release_when_manual_position_gone(self):
        bot = self._bot()
        bot.run_cycle()
        t = "KXGOOD-99DEC31-A"
        bot.client.positions[t] = 50
        bot.run_cycle()                    # yields
        bot.client.positions.pop(t)        # user closed the position
        bot.state.universe_at = 0.0
        bot.run_cycle()                    # refresh skips (standoff entry)...
        bot.state.universe_at = 0.0
        bot.run_cycle()                    # ...loop cleared it; next refresh reselects
        self.assertIn(t, bot.state.selected)
        self.assertTrue(bot.state.sim_orders)

    def test_own_inventory_does_not_yield(self):
        """Positions the bot earned itself are managed, not yielded."""
        bot = self._bot()
        t = "KXGOOD-99DEC31-A"
        bot.client.positions[t] = 20
        bot.pnl.pos[t] = 20
        bot.run_cycle()
        self.assertIn(t, bot.state.selected)
        self.assertNotIn(t, bot.state.manual_standoff)
        self.assertTrue(bot.state.sim_orders)

    def test_foreign_resting_order_yields_live(self):
        """A non-imm resting order on a managed market (user's manual quote)
        triggers the standoff in live mode."""
        _clean_persist()
        client = FakeClient()
        t = "KXGOOD-99DEC31-A"
        client.get_orders = lambda **kw: {"orders": [
            {"order_id": "jack1", "ticker": t, "status": "resting",
             "client_order_id": "", "book_side": "bid", "yes_price": 40,
             "remaining_count": 100}], "cursor": None}
        bot = IncentiveMarketMaker(client=client, live=True)
        bot.run_cycle()
        self.assertIn(t, bot.state.manual_standoff)
        self.assertNotIn(t, bot.state.selected)
        self.assertEqual(getattr(client, "created", []), [])


class TestHourSizeMult(unittest.TestCase):
    """Quiet-hours ladder multiplier (IMM_HOUR_SIZE_MULT): parsing, ET window
    membership, series exclusion, rounding. July dates => EDT (UTC-4)."""

    def setUp(self):
        self._mults = imm.HOUR_SIZE_MULTS
        self._excl = imm.HOUR_MULT_EXCLUDE

    def tearDown(self):
        imm.HOUR_SIZE_MULTS = self._mults
        imm.HOUR_MULT_EXCLUDE = self._excl

    def test_parse_range_inclusive_both_ends(self):
        self.assertEqual(imm._parse_hour_mults("3-7:2.0"),
                         {3: 2.0, 4: 2.0, 5: 2.0, 6: 2.0, 7: 2.0})

    def test_parse_wrap_and_single_hour(self):
        self.assertEqual(imm._parse_hour_mults("22-1:0.5,13:1.5"),
                         {22: 0.5, 23: 0.5, 0: 0.5, 1: 0.5, 13: 1.5})

    def test_parse_rejects_garbage(self):
        for bad in ("3-25:2.0", "x-7:2", "3-7:0", "3-7:-1", "3-7"):
            with self.assertRaises(ValueError):
                imm._parse_hour_mults(bad)

    def test_empty_spec_is_off(self):
        self.assertEqual(imm._parse_hour_mults(""), {})
        imm.HOUR_SIZE_MULTS = {}
        base = imm.series_levels("KXFOO")
        self.assertIs(imm.hour_scaled_levels("KXFOO", utc(2026, 7, 25, 7, 30)),
                      base)

    def test_window_membership_et(self):
        imm.HOUR_SIZE_MULTS = imm._parse_hour_mults("3-7:2.0")
        imm.HOUR_MULT_EXCLUDE = ("KXTEMP",)
        base = imm.series_levels("KXFOO")
        doubled = [(t, s * 2) for t, s in base]
        # 07:30Z = 3:30am EDT -> in; 11:59Z = 7:59am EDT -> still in
        # (hour 7 inclusive); 12:00Z = 8:00am EDT -> out.
        self.assertEqual(
            imm.hour_scaled_levels("KXFOO", utc(2026, 7, 25, 7, 30)), doubled)
        self.assertEqual(
            imm.hour_scaled_levels("KXFOO", utc(2026, 7, 25, 11, 59)), doubled)
        self.assertEqual(
            imm.hour_scaled_levels("KXFOO", utc(2026, 7, 25, 12, 0)), base)
        # 06:59Z = 2:59am EDT -> out (window starts at 3).
        self.assertEqual(
            imm.hour_scaled_levels("KXFOO", utc(2026, 7, 25, 6, 59)), base)

    def test_excluded_prefix_never_scales(self):
        imm.HOUR_SIZE_MULTS = imm._parse_hour_mults("3-7:2.0")
        imm.HOUR_MULT_EXCLUDE = ("KXTEMP",)
        inside = utc(2026, 7, 25, 7, 30)
        self.assertEqual(imm.hour_scaled_levels("KXTEMPAUSH", inside),
                         imm.series_levels("KXTEMPAUSH"))
        self.assertEqual(imm.hour_size_mult("KXTEMPNYCH", inside), 1.0)

    def test_mention_family_multiplier(self):
        # Mechanism test with a PATCHED mult — the default is 1.0 since
        # 2026-07-30 (Jack removed the 7/28 x1.5; family runs the global 10s).
        self.assertEqual(imm.MENTION_SIZE_MULT, 1.0)
        self._old_mult = imm.MENTION_SIZE_MULT
        imm.MENTION_SIZE_MULT = 1.5
        self.addCleanup(lambda: setattr(imm, "MENTION_SIZE_MULT", self._old_mult))
        # Neutralise the earnings-only knob (default 1.5 since 2026-09-17) so
        # this test still measures the FAMILY multiplier by itself; the two
        # knobs' composition is pinned in test_earnings_family_multiplier.
        self._old_earn = imm.EARNINGS_SIZE_MULT
        imm.EARNINGS_SIZE_MULT = 1.0
        self.addCleanup(lambda: setattr(imm, "EARNINGS_SIZE_MULT", self._old_earn))
        imm.HOUR_SIZE_MULTS = {}
        outside = utc(2026, 7, 28, 13, 0)      # 9am ET, no hour mult
        base = imm.series_levels("KXWCMENTION")
        self.assertEqual(imm.hour_scaled_levels("KXWCMENTION", outside),
                         [(t, int(s * 1.5 + 0.5)) for t, s in base])
        self.assertEqual(imm.hour_scaled_levels("KXEARNINGSMENTIONF", outside),
                         [(t, int(s * 1.5 + 0.5)) for t, s in base])
        # non-mention untouched
        self.assertIs(imm.hour_scaled_levels("KXGOOD", outside),
                      imm.series_levels("KXGOOD"))
        # composes with the quiet-hours window: x1.5 x2
        imm.HOUR_SIZE_MULTS = {3: 2.0}
        inside = utc(2026, 7, 28, 7, 30)       # 3:30am ET
        self.assertEqual(imm.hour_scaled_levels("KXWCMENTION", inside),
                         [(t, int(s * 3.0 + 0.5)) for t, s in base])

    def test_mention_caps_scale_commensurately(self):
        self.assertEqual(imm.MENTION_SIZE_MULT, 1.0)   # default off since 7/30
        self._old_mult = imm.MENTION_SIZE_MULT
        imm.MENTION_SIZE_MULT = 1.5
        self.addCleanup(lambda: setattr(imm, "MENTION_SIZE_MULT", self._old_mult))
        self.assertAlmostEqual(imm.series_max_position("KXWCMENTION"),
                               imm.MAX_POSITION_CONTRACTS * 1.5)
        # main TRUMPMENTION: hand-tuned 0:10 RETIRED 2026-08-03 (Jack "same
        # rules as other markets") -> global ladder, family mult applies
        self.assertEqual(imm.series_levels("KXTRUMPMENTION"), imm.LEVELS)
        self.assertEqual(imm.applied_mention_mult("KXTRUMPMENTION"), 1.5)
        self.assertAlmostEqual(imm.series_max_position("KXGOOD"),
                               imm.MAX_POSITION_CONTRACTS)
        # temp override cap unaffected (not mention)
        self.assertEqual(imm.series_max_position("KXTEMPDCH"), 50)
        # hand-tuned override series exempt even though it IS mention:
        # Love Island keeps its literal 7/12 spec (5/5/5, net 50)
        self.assertEqual(imm.series_max_position("KXLOVEISLMENTION"), 50)
        self.assertEqual(imm.applied_mention_mult("KXLOVEISLMENTION"), 1.0)
        self.assertAlmostEqual(
            imm.event_cap_contracts("KXWCMENTION-26JUL24ARGSUI"),
            imm.MAX_EVENT_CONTRACTS * 1.5)
        self.assertAlmostEqual(imm.event_cap_contracts("KXGOOD-99DEC31"),
                               imm.MAX_EVENT_CONTRACTS)
        # skew thresholds scale via the explicit params
        room = imm.skewed_side_room(100, 40, accumulating=True,
                                    side_max=100, soft=45, hard=90)
        self.assertGreater(room, 0)            # 40 < scaled soft 45: no clamp
        room2 = imm.skewed_side_room(100, 40, accumulating=True, side_max=100)
        self.assertLess(room2, 100)            # default soft 30: halved

    def test_earnings_family_multiplier(self):
        # Jack 2026-09-17: "increase quote size on EARNINGSMENTIONS by 1.5x".
        # A knob of its own, NOT the family one: only KXEARNINGSMENTION<TKR>
        # moves, and every commensurate cap moves with it.
        self.assertEqual(imm.EARNINGS_SIZE_MULT, 1.5)   # live default
        self.assertEqual(imm.MENTION_SIZE_MULT, 1.0)    # family still off
        imm.HOUR_SIZE_MULTS = {}
        outside = utc(2026, 7, 28, 13, 0)      # 9am ET, no hour/Saturday mult
        base = imm.series_levels("KXEARNINGSMENTIONUAL")

        # the earnings books scale...
        for s_ in ("KXEARNINGSMENTIONUAL", "KXEARNINGSMENTIONTSLA",
                   "KXEARNINGSMENTIONF", "KXEARNINGSMENTION"):
            self.assertEqual(imm.applied_mention_mult(s_), 1.5, s_)
            self.assertEqual(imm.hour_scaled_levels(s_, outside),
                             [(t, int(sz * 1.5 + 0.5)) for t, sz in base], s_)
        # ...and the rest of the mention family does NOT
        for s_ in ("KXTRUMPMENTION", "KXNBAMENTION", "KXWCMENTION",
                   "KXMAMDANIMENTION"):
            self.assertEqual(imm.applied_mention_mult(s_), 1.0, s_)
            self.assertEqual(imm.hour_scaled_levels(s_, outside),
                             imm.series_levels(s_), s_)
        # non-mention untouched
        self.assertIs(imm.hour_scaled_levels("KXGOOD", outside),
                      imm.series_levels("KXGOOD"))

        # caps move commensurately with the ladder
        self.assertAlmostEqual(imm.series_max_position("KXEARNINGSMENTIONUAL"),
                               imm.MAX_POSITION_CONTRACTS * 1.5)
        self.assertAlmostEqual(imm.series_max_position("KXTRUMPMENTION"),
                               imm.MAX_POSITION_CONTRACTS)
        self.assertAlmostEqual(
            imm.event_cap_contracts("KXEARNINGSMENTIONUAL-26OCT16"),
            imm.MAX_EVENT_CONTRACTS * 1.5)
        self.assertAlmostEqual(
            imm.event_cap_contracts("KXTRUMPMENTION-26OCT16"),
            imm.MAX_EVENT_CONTRACTS)

        # composes with the family knob rather than replacing it
        self._old_mult = imm.MENTION_SIZE_MULT
        imm.MENTION_SIZE_MULT = 1.5
        self.addCleanup(lambda: setattr(imm, "MENTION_SIZE_MULT", self._old_mult))
        self.assertAlmostEqual(imm.applied_mention_mult("KXEARNINGSMENTIONUAL"),
                               2.25)
        self.assertAlmostEqual(imm.applied_mention_mult("KXWCMENTION"), 1.5)
        # ...and with the quiet-hours window on top of both
        imm.HOUR_SIZE_MULTS = {3: 2.0}
        inside = utc(2026, 7, 28, 7, 30)       # 3:30am ET
        self.assertEqual(imm.hour_scaled_levels("KXEARNINGSMENTIONUAL", inside),
                         [(t, int(sz * 4.5 + 0.5)) for t, sz in base])

    def test_earnings_multiplier_is_revertible(self):
        # 1.0 puts the family straight back on the global ladder, no other
        # edit required (the knob is env-tunable: IMM_EARNINGS_SIZE_MULT).
        self._old_earn = imm.EARNINGS_SIZE_MULT
        imm.EARNINGS_SIZE_MULT = 1.0
        self.addCleanup(lambda: setattr(imm, "EARNINGS_SIZE_MULT", self._old_earn))
        imm.HOUR_SIZE_MULTS = {}
        outside = utc(2026, 7, 28, 13, 0)
        self.assertEqual(imm.applied_mention_mult("KXEARNINGSMENTIONUAL"), 1.0)
        self.assertEqual(imm.hour_scaled_levels("KXEARNINGSMENTIONUAL", outside),
                         imm.series_levels("KXEARNINGSMENTIONUAL"))
        self.assertAlmostEqual(imm.series_max_position("KXEARNINGSMENTIONUAL"),
                               imm.MAX_POSITION_CONTRACTS)

    def test_rounding_half_up_floor_one(self):
        imm.HOUR_SIZE_MULTS = {3: 0.5}
        imm.HOUR_MULT_EXCLUDE = ()
        inside = utc(2026, 7, 25, 7, 30)          # 3:30am EDT
        base = imm.series_levels("KXFOO")
        got = imm.hour_scaled_levels("KXFOO", inside)
        self.assertEqual(got, [(t, max(1, int(s * 0.5 + 0.5)))
                               for t, s in base])
        self.assertTrue(all(s >= 1 for _t, s in got))


class TestScheduledKnobs(unittest.TestCase):
    """Jack 2026-10-02: "make both changes for monday". IMM_HOUR_SIZE_MULT_NEXT
    and IMM_EARNINGS_SIZE_MULT_NEXT take over from 00:00 ET on their _FROM day
    (the launcher: 0-9 ET x2 -> 0-8 ET x3, earnings x1.5 -> x2 from
    2026-10-05), read off the clock, no restart. 2026-10-05 is a Monday;
    October => EDT (UTC-4)."""
    FROM = datetime(2026, 10, 5).date()

    def setUp(self):
        self._saved = {k: getattr(imm, k) for k in (
            "HOUR_SIZE_MULTS", "HOUR_SIZE_MULTS_NEXT", "HOUR_SIZE_MULT_FROM",
            "SAT_SIZE_MULT", "EARNINGS_SIZE_MULT", "EARNINGS_SIZE_MULT_NEXT",
            "EARNINGS_SIZE_MULT_FROM", "EARNINGS_SIZE_MULT_FROM_TS", "MENTION_SIZE_MULT")}
        imm.HOUR_SIZE_MULTS = imm._parse_hour_mults("0-9:2.0")
        imm.HOUR_SIZE_MULTS_NEXT = imm._parse_hour_mults("0-8:3.0")
        imm.HOUR_SIZE_MULT_FROM = self.FROM
        imm.SAT_SIZE_MULT = 1.0
        imm.MENTION_SIZE_MULT = 1.0
        imm.EARNINGS_SIZE_MULT = 1.5
        imm.EARNINGS_SIZE_MULT_NEXT = 2.0
        imm.EARNINGS_SIZE_MULT_FROM = self.FROM
        imm.EARNINGS_SIZE_MULT_FROM_TS = imm._et_day_start_ts(self.FROM)

    def tearDown(self):
        for k, v in self._saved.items():
            setattr(imm, k, v)

    @staticmethod
    def et(y, mo, d, h, mi=0):
        return imm.ET.localize(datetime(y, mo, d, h, mi)).astimezone(timezone.utc)

    def test_env_day_parsing(self):
        with mock.patch.dict(os.environ, {"IMM_X_FROM": "2026-10-05"}):
            self.assertEqual(imm._env_et_day("IMM_X_FROM"), self.FROM)
        with mock.patch.dict(os.environ, {"IMM_X_FROM": " "}):
            self.assertIsNone(imm._env_et_day("IMM_X_FROM"))
        for bad in ("10/05/2026", "2026-13-01", "monday"):
            with mock.patch.dict(os.environ, {"IMM_X_FROM": bad}):
                with self.assertRaises(ValueError):
                    imm._env_et_day("IMM_X_FROM")
        # 00:00 ET Monday = 04:00Z (EDT); None stays None
        self.assertEqual(imm._et_day_start_ts(self.FROM), utc(2026, 10, 5, 4, 0).timestamp())
        self.assertIsNone(imm._et_day_start_ts(None))

    def test_window_switches_at_et_midnight(self):
        s = "KXGOOD"
        # before: 0-9 ET x2 (Friday 9:30am is IN the old window)
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 2, 9, 30)), 2.0)
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 4, 3)), 2.0)    # Sunday 3am
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 4, 23, 59)), 1.0)
        # from 00:00 ET Monday: 0-8 ET x3, hour 9 back to x1
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 5, 0)), 3.0)
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 5, 8, 59)), 3.0)
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 5, 9, 30)), 1.0)
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 9, 4)), 3.0)    # and after
        self.assertEqual(imm.global_hour_mults(datetime(2026, 10, 4).date()), imm.HOUR_SIZE_MULTS)
        self.assertEqual(imm.global_hour_mults(self.FROM), imm.HOUR_SIZE_MULTS_NEXT)
        # the ladder scales with it
        base = imm.series_levels(s)
        self.assertEqual(imm.hour_scaled_levels(s, self.et(2026, 10, 5, 3)),
                         [(t, 3 * sz) for t, sz in base])

    def test_exclusions_and_saturday_still_compose(self):
        mon_3am = self.et(2026, 10, 5, 3)
        self.assertEqual(imm.hour_size_mult("KXAAAGASD", mon_3am), 1.0)     # daily family
        self.assertEqual(imm.hour_size_mult("KXTEMPNYCH", mon_3am), 1.0)    # prefix-excluded
        imm.SAT_SIZE_MULT = 2.0
        self.assertEqual(imm.hour_size_mult("KXGOOD", self.et(2026, 10, 10, 4)), 6.0)   # Sat 4am
        self.assertEqual(imm.hour_size_mult("KXGOOD", self.et(2026, 10, 10, 9)), 2.0)   # Sat 9am
        self.assertEqual(imm.hour_size_mult("KXGOOD", self.et(2026, 10, 3, 9)), 4.0)    # this Sat 9am

    def test_half_set_pair_is_ignored(self):
        imm.HOUR_SIZE_MULTS_NEXT = {}                   # FROM without NEXT
        self.assertEqual(imm.hour_size_mult("KXGOOD", self.et(2026, 10, 5, 3)), 2.0)
        imm.HOUR_SIZE_MULTS_NEXT = imm._parse_hour_mults("0-8:3.0")
        imm.HOUR_SIZE_MULT_FROM = None                  # NEXT without FROM
        self.assertEqual(imm.hour_size_mult("KXGOOD", self.et(2026, 10, 5, 3)), 2.0)
        imm.EARNINGS_SIZE_MULT_FROM_TS = None
        self.assertEqual(imm.earnings_size_mult(self.et(2026, 10, 6, 12)), 1.5)
        imm.EARNINGS_SIZE_MULT_FROM_TS = imm._et_day_start_ts(self.FROM)
        imm.EARNINGS_SIZE_MULT_NEXT = 0.0
        self.assertEqual(imm.earnings_size_mult(self.et(2026, 10, 6, 12)), 1.5)

    def test_floor_projection_walks_across_the_switch(self):
        # Sunday 20:00 ET for one day: Sun 20-24 x1 (4h), Mon 0-8 x3 (9h),
        # Mon 9-19 x1 (11h) -- the old window's hour 9 never appears
        prof = dict(imm.size_mult_profile("KXGOOD", self.et(2026, 10, 4, 20), 1.0))
        self.assertAlmostEqual(prof[3.0], 9 / 24, places=9)
        self.assertAlmostEqual(prof[1.0], 15 / 24, places=9)
        self.assertNotIn(2.0, prof)

    def test_earnings_switches_at_et_midnight(self):
        f = imm.earnings_size_mult
        self.assertEqual(f(self.et(2026, 10, 4, 23, 59)), 1.5)
        self.assertEqual(f(self.et(2026, 10, 5, 0)), 2.0)
        self.assertEqual(f(self.et(2026, 11, 1, 12)), 2.0)
        # the wall-clock path (every geometry consumer) moves the rung, both
        # caps and leaves the rest of the mention family alone
        noon = self.et(2026, 10, 5, 12)
        base = imm.series_levels("KXEARNINGSMENTIONUAL")
        with mock.patch.object(imm.time, "time", return_value=self.et(2026, 10, 4, 12).timestamp()):
            self.assertEqual(imm.applied_mention_mult("KXEARNINGSMENTIONUAL"), 1.5)
        with mock.patch.object(imm.time, "time", return_value=noon.timestamp()):
            self.assertEqual(imm.applied_mention_mult("KXEARNINGSMENTIONUAL"), 2.0)
            self.assertEqual(imm.hour_scaled_levels("KXEARNINGSMENTIONUAL", noon),
                             [(t, 2 * sz) for t, sz in base])
            self.assertAlmostEqual(imm.series_max_position("KXEARNINGSMENTIONUAL"),
                                   2 * imm.MAX_POSITION_CONTRACTS)
            self.assertAlmostEqual(imm.event_cap_contracts("KXEARNINGSMENTIONUAL-26OCT16"),
                                   2 * imm.MAX_EVENT_CONTRACTS)
            self.assertEqual(imm.applied_mention_mult("KXTRUMPMENTION"), 1.0)
            self.assertEqual(imm.applied_mention_mult("KXGOOD"), 1.0)
            # and the quiet hours compose on top: Mon 3am = x2 earnings x3 hour
            self.assertEqual(imm.hour_scaled_levels("KXEARNINGSMENTIONUAL", self.et(2026, 10, 5, 3)),
                             [(t, 6 * sz) for t, sz in base])


class TestEveningWindow(unittest.TestCase):
    """Jack 2026-10-02 ("1 and 2 for monday"): ET 18-21 x1.5 on the long-dated
    book from 00:00 ET 2026-10-05 -- never on a quiet hour, never on the
    sports ladders / escalators (pre-kickoff), never on daily families.
    October => EDT (UTC-4)."""

    def setUp(self):
        self._saved = {k: getattr(imm, k) for k in (
            "EVENING_SIZE_MULTS", "EVENING_SIZE_MULT_FROM", "HOUR_SIZE_MULTS",
            "HOUR_SIZE_MULTS_NEXT", "HOUR_SIZE_MULT_FROM", "SAT_SIZE_MULT", "HOUR_MULT_EXCLUDE")}
        imm.EVENING_SIZE_MULTS = imm._parse_hour_mults("18-21:1.5")
        imm.EVENING_SIZE_MULT_FROM = datetime(2026, 10, 5).date()
        imm.HOUR_SIZE_MULTS = imm._parse_hour_mults("0-9:2.0")
        imm.HOUR_SIZE_MULTS_NEXT = imm._parse_hour_mults("0-8:3.0")
        imm.HOUR_SIZE_MULT_FROM = datetime(2026, 10, 5).date()
        imm.SAT_SIZE_MULT = 1.0
        imm.HOUR_MULT_EXCLUDE = ("KXTEMP",)

    def tearDown(self):
        for k, v in self._saved.items():
            setattr(imm, k, v)

    @staticmethod
    def et(y, mo, d, h, mi=0):
        return imm.ET.localize(datetime(y, mo, d, h, mi)).astimezone(timezone.utc)

    def test_code_default(self):
        self.assertEqual(_EVENING_CODE_DEFAULT,
                         ({18: 1.5, 19: 1.5, 20: 1.5, 21: 1.5}, datetime(2026, 10, 5).date()))

    def test_window_from_monday(self):
        s = "KXGOOD"
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 2, 19)), 1.0)      # Friday: not yet
        self.assertEqual(imm.evening_hour_mults(datetime(2026, 10, 4).date()), {})
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 5, 17, 59)), 1.0)
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 5, 18)), 1.5)
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 5, 21, 59)), 1.5)
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 5, 22)), 1.0)
        self.assertEqual(imm.hour_size_mult(s, self.et(2026, 10, 6, 3)), 3.0)       # quiet hours untouched
        base = imm.series_levels(s)
        self.assertEqual(imm.hour_scaled_levels(s, self.et(2026, 10, 5, 19)),
                         [(t, int(sz * 1.5 + 0.5)) for t, sz in base])

    def test_exclusions(self):
        mon_7pm = self.et(2026, 10, 5, 19)
        for s in ("KXNFLLADDERREC", "KXNFLESCALATORRECYDS", "KXNBALADDERPTS"):
            self.assertEqual(imm._hour_window_mult(s, mon_7pm), 1.0, s)              # pre-kickoff
        self.assertEqual(imm.hour_size_mult("KXTEMPNYCH", mon_7pm), 1.0)              # daily / excluded
        self.assertEqual(imm.hour_size_mult("KXRAIN", mon_7pm), 0.5)                  # its own 19-1 halving
        with mock.patch.object(imm, "SCAN_HOUR_MULT", False), \
                mock.patch.object(imm, "SCAN_GUARDED_SERIES", {"KXSCANNED"}):
            self.assertEqual(imm.hour_size_mult("KXSCANNED", mon_7pm), 1.0)           # open-scan member
        # a quiet hour is never also an evening hour
        imm.HOUR_SIZE_MULTS_NEXT = imm._parse_hour_mults("0-8:3.0,19:2.0")
        self.assertEqual(imm.hour_size_mult("KXGOOD", mon_7pm), 2.0)
        self.assertEqual(imm.hour_size_mult("KXGOOD", self.et(2026, 10, 5, 20)), 1.5)
        # "" switches it off
        imm.EVENING_SIZE_MULTS = {}
        self.assertEqual(imm.hour_size_mult("KXGOOD", self.et(2026, 10, 5, 20)), 1.0)

    def test_saturday_and_floor_projection_compose(self):
        imm.SAT_SIZE_MULT = 2.0
        self.assertEqual(imm.hour_size_mult("KXGOOD", self.et(2026, 10, 10, 19)), 3.0)
        imm.SAT_SIZE_MULT = 1.0
        # a Tuesday: 0-8 x3 (9h), 18-21 x1.5 (4h), the rest x1 (11h)
        prof = dict(imm.size_mult_profile("KXGOOD", self.et(2026, 10, 6, 0), 1.0))
        self.assertAlmostEqual(prof[3.0], 9 / 24, places=9)
        self.assertAlmostEqual(prof[1.5], 4 / 24, places=9)
        self.assertAlmostEqual(prof[1.0], 11 / 24, places=9)


class TestYieldSizeMode(unittest.TestCase):
    """Jack 2026-10-02 ("1 and 2 for monday"): from 00:00 ET 2026-10-05 a
    long-dated market with no family multiplier whose modelled reward per
    resting contract is >= $0.011/day rests x1.5, held down to 0.85 of the
    bar, composed with the near-cliff size mode at every reader of the shape."""

    T = "KXGOOD-99DEC31-A"

    def setUp(self):
        self._saved = {k: getattr(imm, k) for k in (
            "YIELD_SIZE_MULT", "YIELD_SIZE_MULT_FROM", "YIELD_SIZE_MULT_FROM_TS",
            "YIELD_SIZE_MIN", "YIELD_SIZE_EXIT_FRAC")}
        imm.YIELD_SIZE_MULT = 1.5
        imm.YIELD_SIZE_MULT_FROM = imm.YIELD_SIZE_MULT_FROM_TS = None    # in force
        imm.YIELD_SIZE_MIN, imm.YIELD_SIZE_EXIT_FRAC = 0.011, 0.85

    def tearDown(self):
        for k, v in self._saved.items():
            setattr(imm, k, v)

    def test_code_default(self):
        self.assertEqual(_YIELD_CODE_DEFAULT, (1.5, datetime(2026, 10, 5).date(), 0.011, 0.85))
        self.assertEqual(imm._et_day_start_ts(_YIELD_CODE_DEFAULT[1]),
                         utc(2026, 10, 5, 4, 0).timestamp())

    def test_activation(self):
        imm.YIELD_SIZE_MULT_FROM_TS = utc(2026, 10, 5, 4, 0).timestamp()
        self.assertFalse(imm.yield_size_active(utc(2026, 10, 5, 3, 59).timestamp()))
        self.assertTrue(imm.yield_size_active(utc(2026, 10, 5, 4, 0).timestamp()))
        imm.YIELD_SIZE_MULT = 1.0
        self.assertFalse(imm.yield_size_active(utc(2026, 10, 6).timestamp()))

    def test_eligibility(self):
        e = imm.yield_size_eligible
        for s in ("KXGOOD", "KXTRUMPMENTION", "KXWCMENTION", "KXAMZNCC"):
            self.assertTrue(e(s), s)
        self.assertFalse(e("KXSUEZWEEKLY"))      # an open-scan graduate (2026-10-03)
        for s in ("KXRT", "KXAAAGASD", "KXAAAGASW", "KXDIESELW", "KXUSGASCPI",       # RT, gas
                  "KXCPICOREYOY", "KXCBDECISIONNZ", "KXFEDDECISION", "KXUST10AD",     # econ / rates
                  "KX7YRDIRLM", "KXCTMFPERMITS", "KXJOBLESSCLAIMS", "KXGDP",
                  "KXNFLGAME", "KXVENUEPERFORM", "KXOSCARPIC", "KXGRAMMYAOTY",        # sports / awards
                  "KXEARNINGSMENTIONAAPL", "KXNFLLADDERREC", "KXCFBLADDERREC",        # family mults
                  "KXTRUMPAPPROVE", "KXTEMPNYCH", "KXRAIN",                           # family / daily
                  imm.ELECTION_ARCHETYPE, "KXSPRLVL"):                                # election, finecon
            self.assertFalse(e(s), s)
        with mock.patch.object(imm, "SCAN_GUARDED_SERIES", {"KXGOOD"}):
            self.assertFalse(e("KXGOOD"))                                           # unreviewed
        with mock.patch.dict(imm.SERIES_OVERRIDES, {"KXGOOD": imm.SeriesOverride(levels=[(0, 5)])}):
            self.assertFalse(e("KXGOOD"))                                           # hand-tuned ladder

    def test_verdict_and_hysteresis(self):
        bot = IncentiveMarketMaker(client=None, live=False)
        m = _meta(series="KXGOOD", ticker=self.T, event_ticker="KXGOOD-99DEC31")
        now = time.time()
        m.yield_per_contract = 0.0105                       # under the bar: not armed
        bot._yield_size_verdict(m, now)
        self.assertNotIn(self.T, bot._yield_boost)
        self.assertEqual((m.ys_size_mult, bot._yield_size_mult(self.T)), (1.0, 1.0))
        m.yield_per_contract = 0.011                        # at the bar: armed
        bot._yield_size_verdict(m, now)
        self.assertEqual((m.ys_size_mult, bot._yield_size_mult(self.T)), (1.5, 1.5))
        m.yield_per_contract = 0.0094                       # >= 0.85 x bar (0.00935): held
        bot._yield_size_verdict(m, now)
        self.assertIn(self.T, bot._yield_boost)
        m.yield_per_contract = 0.0093                       # under it: dropped
        bot._yield_size_verdict(m, now)
        self.assertNotIn(self.T, bot._yield_boost)
        # an ineligible series is never armed, whatever it yields
        r = _meta(series="KXRT", ticker="KXRT-ONE-90", event_ticker="KXRT-ONE")
        r.yield_per_contract = 0.5
        bot._yield_size_verdict(r, now)
        self.assertNotIn(r.ticker, bot._yield_boost)
        # before the start: the verdict drops it and the reader returns 1.0
        bot._yield_boost[self.T] = now
        imm.YIELD_SIZE_MULT_FROM_TS = now + 3600
        self.assertEqual(bot._yield_size_mult(self.T), 1.0)
        m.yield_per_contract = 0.05
        bot._yield_size_verdict(m, now)
        self.assertNotIn(self.T, bot._yield_boost)

    def test_composes_with_near_cliff_and_prunes(self):
        bot = IncentiveMarketMaker(client=None, live=False)
        now = time.time()
        bot._yield_boost[self.T] = now
        self.assertEqual(bot._market_size_mult(self.T), 1.5)
        bot._near_cliff_boost[self.T] = now
        self.assertAlmostEqual(bot._market_size_mult(self.T), imm.NEAR_CLIFF_SIZE_MULT * 1.5)
        bot.state.selected = {}
        bot._prune_yield_boost()                            # left the selection
        self.assertNotIn(self.T, bot._yield_boost)

    def test_quote_loop_and_collateral_rest_the_boosted_ladder(self):
        def plain_sizes(b):
            return {int(o["remaining_count"]) for o in b.state.sim_orders.values()
                    if o["ticker"] == self.T and 1 < o["yes_price"] < 99}
        _clean_persist()
        imm.YIELD_SIZE_MULT = 1.0                           # control: mode off
        ctl = IncentiveMarketMaker(client=FakeClient(), live=False)
        ctl.run_cycle()
        self.assertIn(self.T, ctl.state.selected)
        plain = plain_sizes(ctl)
        self.assertTrue(plain)
        y = ctl.state.selected[self.T].yield_per_contract
        self.assertGreater(y, 0.0)
        # on: the bar just under this market's yield -> armed in the refresh's
        # estimate, and the quote loop rests x1.5 on the same cycle
        imm.YIELD_SIZE_MULT = 1.5
        imm.YIELD_SIZE_MIN = y * 0.99
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        bot.run_cycle()
        self.assertIn(self.T, bot._yield_boost)
        self.assertEqual(bot.state.selected[self.T].ys_size_mult, 1.5)
        self.assertEqual(plain_sizes(bot), {int(c * 1.5 + 0.5) for c in plain})
        # the bar well over the (diluted) yield: dropped on the next refresh,
        # the ladder back to plain size
        imm.YIELD_SIZE_MIN = y * 10.0
        bot.state.universe_at = 0.0
        bot.run_cycle()
        self.assertNotIn(self.T, bot._yield_boost)
        self.assertEqual(plain_sizes(bot), plain)


class TestSaturdaySizeMult(unittest.TestCase):
    """Saturday ladder multiplier (IMM_SAT_SIZE_MULT, Jack 2026-09-12): ET
    calendar-day membership, long-dated-only via prefix exclusion, ladder
    rounding, and composition with the hour windows. Code default OFF.
    2026-09-12 is a Saturday; September => EDT (UTC-4)."""

    def setUp(self):
        self._sat = imm.SAT_SIZE_MULT
        self._excl = imm.SAT_MULT_EXCLUDE
        self._mults = imm.HOUR_SIZE_MULTS
        self._series_mults = imm.SERIES_HOUR_MULTS
        imm.SAT_SIZE_MULT = 1.5
        imm.HOUR_SIZE_MULTS = {}

    def tearDown(self):
        imm.SAT_SIZE_MULT = self._sat
        imm.SAT_MULT_EXCLUDE = self._excl
        imm.HOUR_SIZE_MULTS = self._mults
        imm.SERIES_HOUR_MULTS = self._series_mults

    def test_code_default_is_off(self):
        self.assertEqual(self._sat, 1.0)
        imm.SAT_SIZE_MULT = 1.0
        self.assertEqual(imm.hour_size_mult("KXTRUMPMENTION",
                                            utc(2026, 9, 12, 16, 0)), 1.0)
        imm.SAT_SIZE_MULT = 0.0                     # invalid knob == off
        self.assertEqual(imm.hour_size_mult("KXTRUMPMENTION",
                                            utc(2026, 9, 12, 16, 0)), 1.0)

    def test_saturday_is_the_et_calendar_day(self):
        s = "KXTRUMPMENTION"
        # 03:59Z Sat = Fri 23:59 EDT -> off; 04:00Z = Sat 00:00 EDT -> on;
        # 03:59Z Sun = Sat 23:59 EDT -> still on; 04:00Z Sun = Sun 00:00 -> off.
        self.assertEqual(imm.hour_size_mult(s, utc(2026, 9, 12, 3, 59)), 1.0)
        self.assertEqual(imm.hour_size_mult(s, utc(2026, 9, 12, 4, 0)), 1.5)
        self.assertEqual(imm.hour_size_mult(s, utc(2026, 9, 12, 16, 0)), 1.5)
        self.assertEqual(imm.hour_size_mult(s, utc(2026, 9, 13, 3, 59)), 1.5)
        self.assertEqual(imm.hour_size_mult(s, utc(2026, 9, 13, 4, 0)), 1.0)
        # a weekday is untouched
        self.assertEqual(imm.hour_size_mult(s, utc(2026, 9, 9, 16, 0)), 1.0)

    def test_dailies_and_temp_excluded_by_prefix(self):
        sat = utc(2026, 9, 12, 16, 0)
        for s in ("KXAAAGASD", "KXAAAGASDTX", "KXAAAGASW", "KXAAAGASM",
                  "KXDIESELD", "KXDIESELW", "KXRAIN", "KXRAINWKND",
                  "KXRAINNYCM", "KXTEMPMIAH"):
            self.assertEqual(imm.hour_size_mult(s, sat), 1.0, s)
        for s in ("KXTRUMPMENTION", "KXEARNINGSMENTIONHIMS", "KXUST2AD",
                  "KXDKNGAPP", "KXAMZNCC", "KXAQICITYNYC", "KXFOO"):
            self.assertEqual(imm.hour_size_mult(s, sat), 1.5, s)
        # extra prefixes on top of the daily floor are env-tunable
        imm.SAT_MULT_EXCLUDE = ("KXTRUMP",)
        self.assertEqual(imm.hour_size_mult("KXTRUMPMENTION", sat), 1.0)
        self.assertEqual(imm.hour_size_mult("KXFOO", sat), 1.5)
        self.assertEqual(imm.hour_size_mult("KXAAAGASD", sat), 1.0)   # floor stays

    def test_ladder_scales_half_up_and_excluded_series_keep_shape(self):
        sat = utc(2026, 9, 12, 16, 0)
        base = imm.series_levels("KXTRUMPMENTION")
        self.assertEqual(imm.hour_scaled_levels("KXTRUMPMENTION", sat),
                         [(t, max(1, int(s * 1.5 + 0.5))) for t, s in base])
        self.assertEqual(imm.hour_scaled_levels("KXAAAGASD", sat),
                         imm.series_levels("KXAAAGASD"))
        self.assertIs(imm.hour_scaled_levels("KXFOO", utc(2026, 9, 11, 16, 0)),
                      imm.series_levels("KXFOO"))

    def test_composes_with_quiet_hours_and_per_series_windows(self):
        imm.HOUR_SIZE_MULTS = imm._parse_hour_mults("3-7:2.0")
        imm.SERIES_HOUR_MULTS = imm._parse_series_hour_mults(
            "KXDIESELD:16-1:0.5,KXFOOBAR:17-1:0.5")
        sat_4am = utc(2026, 9, 12, 8, 0)          # 4:00am EDT Saturday
        self.assertEqual(imm.hour_size_mult("KXTRUMPMENTION", sat_4am), 3.0)
        # daily families take neither multiplier (2026-09-12 pm)
        self.assertEqual(imm.hour_size_mult("KXAAAGASD", sat_4am), 1.0)
        self.assertEqual(imm.hour_size_mult("KXTEMPMIAH", sat_4am), 1.0)
        self.assertEqual(imm.hour_size_mult("KXTRUMPMENTION",
                                            utc(2026, 9, 11, 8, 0)), 2.0)
        sat_6pm = utc(2026, 9, 12, 22, 0)         # 6:00pm EDT Saturday
        self.assertAlmostEqual(imm.hour_size_mult("KXFOOBAR", sat_6pm), 0.75)
        self.assertEqual(imm.hour_size_mult("KXDIESELD", sat_6pm), 0.5)
        # the total-multiplier cap still bounds hour x ref mult on Saturday
        self.assertLessEqual(
            3.0 * imm.capped_ref_mult(50, 40, "bid", hour_mult=3.0),
            max(3.0, imm.TOTAL_SIZE_MULT_CAP))


class TestSaturdayGatedStepUp(unittest.TestCase):
    """Gated Saturday step-up (Jack 2026-09-26: "2x next saturday if today +
    prior saturdays show no sign of edge degradation"): the tracker's verdict
    file arms it; anything but a readable PASS naming a bigger multiplier
    leaves Saturday at SAT_SIZE_MULT. 2026-10-03 and 2026-09-26 are
    Saturdays; October => EDT (UTC-4)."""

    SAT = "KXTRUMPMENTION"

    def setUp(self):
        self._saved = (imm.SAT_SIZE_MULT, imm.SAT_SIZE_MULT_GATED, imm.SAT_MULT_EXCLUDE,
                       imm.HOUR_SIZE_MULTS, imm.STATUS_DIR, imm.SAT_GATE_FILE, dict(imm.SAT_GATE_STATE))
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        imm.STATUS_DIR = tmp.name
        imm.SAT_GATE_FILE = "sat_mult_gate.json"
        imm.SAT_SIZE_MULT = 1.5
        imm.SAT_SIZE_MULT_GATED = 2.0
        imm.SAT_MULT_EXCLUDE = ("KXAAAGAS", "KXDIESEL")
        imm.HOUR_SIZE_MULTS = {}
        imm.SAT_GATE_STATE.update(mtime=0.0, verdict="", mult=0.0, effective_from=None)
        self._tick = 0

    def tearDown(self):
        (imm.SAT_SIZE_MULT, imm.SAT_SIZE_MULT_GATED, imm.SAT_MULT_EXCLUDE,
         imm.HOUR_SIZE_MULTS, imm.STATUS_DIR, imm.SAT_GATE_FILE, state) = self._saved
        imm.SAT_GATE_STATE.clear()
        imm.SAT_GATE_STATE.update(state)

    def _write(self, raw=None, **kw):
        """Write a verdict (dict fields, or raw text) and load it; each write
        gets a distinct mtime so the mtime gate always sees it."""
        payload = {"verdict": "PASS", "mult": 2.0, "effective_from": "2026-10-03"}
        payload.update(kw)
        path = imm.sat_gate_path()
        with open(path, "w", encoding="utf-8") as f:
            f.write(raw if raw is not None else json.dumps(payload))
        self._tick += 1
        os.utime(path, (1_800_000_000 + self._tick, 1_800_000_000 + self._tick))
        return imm.load_sat_gate()

    def test_code_default_is_two(self):
        self.assertEqual(self._saved[1], 2.0)

    def test_no_verdict_file_keeps_saturday_at_base(self):
        self.assertFalse(imm.load_sat_gate())
        self.assertEqual(imm.hour_size_mult(self.SAT, utc(2026, 10, 3, 16, 0)), 1.5)
        self.assertIn("awaiting", imm.sat_gate_summary())

    def test_pass_applies_from_the_effective_saturday_on(self):
        self.assertTrue(self._write())
        self.assertEqual(imm.hour_size_mult(self.SAT, utc(2026, 9, 26, 16, 0)), 1.5)   # before: base
        self.assertEqual(imm.hour_size_mult(self.SAT, utc(2026, 10, 2, 16, 0)), 1.0)   # Friday
        # ET calendar-day edges: 03:59Z Sat = Fri 23:59 EDT; 04:00Z = Sat 00:00 EDT
        self.assertEqual(imm.hour_size_mult(self.SAT, utc(2026, 10, 3, 3, 59)), 1.0)
        self.assertEqual(imm.hour_size_mult(self.SAT, utc(2026, 10, 3, 4, 0)), 2.0)
        self.assertEqual(imm.hour_size_mult(self.SAT, utc(2026, 10, 4, 3, 59)), 2.0)
        self.assertEqual(imm.hour_size_mult(self.SAT, utc(2026, 10, 4, 4, 0)), 1.0)    # Sunday
        self.assertEqual(imm.hour_size_mult(self.SAT, utc(2026, 10, 10, 16, 0)), 2.0)  # stays on
        self.assertIn("PASS: x2 on Saturdays from 2026-10-03", imm.sat_gate_summary())

    def test_exclusions_and_composition_are_unchanged(self):
        self._write()
        sat = utc(2026, 10, 3, 16, 0)
        for s in ("KXAAAGASD", "KXAAAGASW", "KXDIESELW", "KXRAINNYCM", "KXTEMPMIAH"):
            self.assertEqual(imm.hour_size_mult(s, sat), 1.0, s)
        imm.HOUR_SIZE_MULTS = imm._parse_hour_mults("0-9:2.0")
        self.assertEqual(imm.hour_size_mult(self.SAT, utc(2026, 10, 3, 8, 0)), 4.0)   # 4am EDT
        self.assertEqual(imm.hour_size_mult(self.SAT, utc(2026, 10, 3, 16, 0)), 2.0)  # noon EDT
        self.assertEqual(imm.hour_scaled_levels(self.SAT, sat),
                         [(t, max(1, int(s * 2.0 + 0.5))) for t, s in imm.series_levels(self.SAT)])

    def test_anything_but_a_readable_pass_fails_closed(self):
        sat = utc(2026, 10, 3, 16, 0)
        for kw in ({"verdict": "FAIL"}, {"verdict": "OFF"}, {"verdict": ""}, {"mult": 0},
                   {"mult": 1.25}, {"mult": "two"}, {"effective_from": None},
                   {"effective_from": "next saturday"}):
            self._write(**kw)
            self.assertEqual(imm.hour_size_mult(self.SAT, sat), 1.5, kw)
        for raw in ("{not json", "[1, 2]", ""):
            self._write(raw=raw)
            self.assertEqual(imm.hour_size_mult(self.SAT, sat), 1.5, raw)
        self._write(verdict="pass")                       # case-insensitive
        self.assertEqual(imm.hour_size_mult(self.SAT, sat), 2.0)

    def test_deleting_the_file_clears_the_verdict(self):
        self._write()
        os.remove(imm.sat_gate_path())
        self.assertTrue(imm.load_sat_gate())
        self.assertEqual(imm.hour_size_mult(self.SAT, utc(2026, 10, 3, 16, 0)), 1.5)

    def test_the_step_is_the_smaller_of_file_and_env(self):
        sat = utc(2026, 10, 3, 16, 0)
        self._write(mult=3.0)
        self.assertEqual(imm.hour_size_mult(self.SAT, sat), 2.0)     # env caps an approval
        imm.SAT_SIZE_MULT_GATED = 1.75
        self._write(mult=2.0)
        self.assertEqual(imm.hour_size_mult(self.SAT, sat), 1.75)    # a lowered env wins

    def test_kill_switches(self):
        sat = utc(2026, 10, 3, 16, 0)
        self._write()
        imm.SAT_SIZE_MULT_GATED = 0.0                  # restart-level kill
        self.assertEqual(imm.hour_size_mult(self.SAT, sat), 1.5)
        self.assertIn("off", imm.sat_gate_summary())
        imm.SAT_SIZE_MULT_GATED = 2.0
        imm.SAT_SIZE_MULT = 1.0                        # Saturday knob off -> everything off
        self.assertEqual(imm.hour_size_mult(self.SAT, sat), 1.0)

    def test_unchanged_file_is_not_reread(self):
        self.assertTrue(self._write())
        with mock.patch("builtins.open", side_effect=AssertionError("re-read")):
            self.assertFalse(imm.load_sat_gate())

    def test_floor_projection_sees_the_step(self):
        # the payout-floor projection samples hour_size_mult, so a window over
        # an armed Saturday projects the x2 ladder there, and x1.5 before it
        self._write()
        prof = dict(imm.size_mult_profile(self.SAT, utc(2026, 10, 3, 4, 0), 1.0))
        self.assertEqual(set(prof), {2.0})
        prof = dict(imm.size_mult_profile(self.SAT, utc(2026, 9, 26, 4, 0), 1.0))
        self.assertEqual(set(prof), {1.5})

    def test_summary_is_ascii(self):
        for kw in ({}, {"verdict": "FAIL"}, {"mult": 1.25}):
            self._write(**kw)
            imm.sat_gate_summary().encode("ascii")


class TestDailySeries(unittest.TestCase):
    """Structural daily-family class (Jack 2026-09-12): prefix floor +
    live-feed classification (dated tickers, >=2 live event dates, p75
    program window <= DAILY_MAX_HOURS) with hysteresis and a persisted file.
    Daily families take neither the global hour window nor the Saturday
    multiplier but keep their own per-series windows."""

    def setUp(self):
        self._dyn = dict(imm.DAILY_SERIES_DYNAMIC)
        self._status = imm.STATUS_DIR
        self._mults = imm.HOUR_SIZE_MULTS
        self._series_mults = imm.SERIES_HOUR_MULTS
        self._sat = imm.SAT_SIZE_MULT
        self._excl = imm.SAT_MULT_EXCLUDE
        self._exempt = imm.DAILY_EXEMPT_PREFIXES
        self._tmp = tempfile.mkdtemp()
        imm.STATUS_DIR = self._tmp
        imm.DAILY_SERIES_DYNAMIC.clear()
        imm.HOUR_SIZE_MULTS = {}
        imm.SAT_SIZE_MULT = 1.0
        imm.SAT_MULT_EXCLUDE = ()

    def tearDown(self):
        imm.DAILY_SERIES_DYNAMIC.clear()
        imm.DAILY_SERIES_DYNAMIC.update(self._dyn)
        imm.STATUS_DIR = self._status
        imm.HOUR_SIZE_MULTS = self._mults
        imm.SERIES_HOUR_MULTS = self._series_mults
        imm.SAT_SIZE_MULT = self._sat
        imm.SAT_MULT_EXCLUDE = self._excl
        imm.DAILY_EXEMPT_PREFIXES = self._exempt

    @staticmethod
    def _feed(spec):
        """[(ticker, start_utc, hours)] -> the fetch_programs() shape."""
        return {t: {"start": st, "end": st + timedelta(hours=h),
                    "dollars_per_day": 1.0, "target": 1000.0, "df": 0.5}
                for t, st, h in spec}

    def test_prefix_floor_and_exempt(self):
        for s in ("KXAAAGASD", "KXAAAGASDTX", "KXDIESELD",
                  "KXRAIN", "KXRAINWKND", "KXTEMPMIAH"):
            self.assertTrue(imm.is_daily_series(s), s)
        # the floor is the TRUE dailies: gas/diesel weeklies, monthlies and
        # annuals are long-dated by structure (they keep the hour window;
        # the Saturday mult skips them via SAT_MULT_EXCLUDE instead)
        for s in ("KXAAAGASW", "KXAAAGASMAXM", "KXDIESELW", "KXDIESELMAXY",
                  "KXTRUMPMENTION", "KXEARNINGSMENTIONHD", "KXAMZNCC", "KXFOO"):
            self.assertFalse(imm.is_daily_series(s), s)
        self.assertEqual(self._excl, ("KXAAAGAS", "KXDIESEL"))   # module default
        imm.DAILY_EXEMPT_PREFIXES = ("KXRAINWKND",)
        self.assertFalse(imm.is_daily_series("KXRAINWKND"))
        self.assertTrue(imm.is_daily_series("KXRAIN"))

    def test_classification_from_feed(self):
        t0 = utc(2026, 9, 12, 12, 0)
        feed = self._feed([
            # gas-like new daily: two dated events live, 16h programs -> daily
            ("KXNEWGASD-26SEP12-4.00", t0 - timedelta(hours=8), 16),
            ("KXNEWGASD-26SEP12-4.10", t0 - timedelta(hours=8), 16),
            ("KXNEWGASD-26SEP13-4.00", t0, 16),
            # treasury-like: listed the day before the print, two dates,
            # 23.5h programs, event horizon ~36h -> daily
            ("KXNEWUST-26SEP12-T4.1", t0 - timedelta(hours=20), 23.5),
            ("KXNEWUST-26SEP13-T4.1", t0 + timedelta(hours=4), 23.5),
            # earnings-like: ONE dated event, 14h -> not daily (dates test)
            ("KXNEWEARN-26SEP15-WORD", t0, 14),
            ("KXNEWEARN-26SEP15-OTHER", t0, 14),
            # mention-like: many dates, same-day AND 22-day programs -> p75
            # long -> not daily
            ("KXNEWMENTION-26SEP12-A", t0, 4),
            ("KXNEWMENTION-26SEP13-B", t0, 6),
            ("KXNEWMENTION-26SEP14-C", t0, 500),
            ("KXNEWMENTION-26SEP15-D", t0, 520),
            # month-named KPI: undated -> not daily
            ("KXNEWKPI-26SEPALBD-T10", t0, 20),
            ("KXNEWKPI-26OCTALBD-T10", t0, 20),
            # weekly market funded in 24h program chunks (the Suez / Bab-el-
            # Mandeb shape): two dated events, short programs, but the event
            # day is a week out -> horizon test keeps it long-dated
            ("KXNEWSHIPWEEKLY-26SEP19-T100", t0, 24),
            ("KXNEWSHIPWEEKLY-26SEP26-T100", t0, 24),
            # floor prefix: daily by prefix, never bookkept dynamically
            ("KXAAAGASDZZ-26SEP12-4.00", t0, 16),
            ("KXAAAGASDZZ-26SEP13-4.00", t0, 16),
        ])
        stats = imm.classify_daily_series(feed)
        self.assertEqual(stats["KXNEWGASD"]["dates"], 2)
        self.assertEqual(stats["KXNEWGASD"]["p75_h"], 16.0)
        self.assertEqual(stats["KXNEWEARN"]["dates"], 1)
        self.assertGreater(stats["KXNEWMENTION"]["p75_h"], imm.DAILY_MAX_HOURS)
        self.assertEqual(stats["KXNEWKPI"]["dates"], 0)
        self.assertIsNone(stats["KXNEWKPI"]["horizon_h"])
        self.assertGreater(stats["KXNEWSHIPWEEKLY"]["horizon_h"], imm.DAILY_MAX_HORIZON_HOURS)
        self.assertLessEqual(stats["KXNEWGASD"]["horizon_h"], imm.DAILY_MAX_HORIZON_HOURS)
        added, dropped = imm.refresh_daily_series(feed, t0)
        self.assertEqual(sorted(added), ["KXNEWGASD", "KXNEWUST"])
        self.assertEqual(dropped, [])
        for s in ("KXNEWGASD", "KXNEWUST", "KXAAAGASDZZ"):
            self.assertTrue(imm.is_daily_series(s), s)
        for s in ("KXNEWEARN", "KXNEWMENTION", "KXNEWKPI", "KXNEWSHIPWEEKLY"):
            self.assertFalse(imm.is_daily_series(s), s)
        self.assertNotIn("KXAAAGASDZZ", imm.DAILY_SERIES_DYNAMIC)

    def test_hysteresis_and_persistence(self):
        t0 = utc(2026, 9, 12, 12, 0)
        feed = self._feed([("KXNEWGASD-26SEP12-4.00", t0, 16),
                           ("KXNEWGASD-26SEP13-4.00", t0, 16)])
        imm.refresh_daily_series(feed, t0)
        self.assertTrue(imm.is_daily_series("KXNEWGASD"))
        # a momentary single-date feed keeps it daily
        imm.refresh_daily_series(
            self._feed([("KXNEWGASD-26SEP13-4.00", t0, 16)]),
            t0 + timedelta(hours=1))
        self.assertTrue(imm.is_daily_series("KXNEWGASD"))
        # between MAX and DROP: still daily
        imm.refresh_daily_series(
            self._feed([("KXNEWGASD-26SEP13-4.00", t0, 60),
                        ("KXNEWGASD-26SEP14-4.00", t0, 60)]),
            t0 + timedelta(hours=2))
        self.assertTrue(imm.is_daily_series("KXNEWGASD"))
        # persisted + reloaded
        imm.DAILY_SERIES_DYNAMIC.clear()
        self.assertEqual(imm.load_daily_series_file(), 1)
        self.assertTrue(imm.is_daily_series("KXNEWGASD"))
        # beyond DROP: dropped
        added, dropped = imm.refresh_daily_series(
            self._feed([("KXNEWGASD-26SEP13-4.00", t0, 80),
                        ("KXNEWGASD-26SEP14-4.00", t0, 80)]),
            t0 + timedelta(hours=3))
        self.assertEqual(dropped, ["KXNEWGASD"])
        self.assertFalse(imm.is_daily_series("KXNEWGASD"))
        # out of the feed for 14 days: forgotten
        imm.refresh_daily_series(feed, t0)
        imm.refresh_daily_series({}, t0 + timedelta(days=15))
        self.assertFalse(imm.is_daily_series("KXNEWGASD"))
        # the horizon is NOT hysteretic: a member whose event day moves out
        # of bounds (a weekly funded in daily chunks) is dropped at once
        imm.refresh_daily_series(feed, t0)
        added, dropped = imm.refresh_daily_series(
            self._feed([("KXNEWGASD-26SEP19-4.00", t0, 16),
                        ("KXNEWGASD-26SEP26-4.00", t0, 16)]),
            t0 + timedelta(hours=4))
        self.assertEqual(dropped, ["KXNEWGASD"])
        # ...and a stale file cannot seed such a member on load
        imm.DAILY_SERIES_DYNAMIC.clear()
        with open(imm.daily_series_path(), "w", encoding="utf-8") as f:
            json.dump({"series": {"KXSTALEWEEKLY": {"p75_h": 24.0, "horizon_h": 203.5,
                                                    "dates": 2, "n": 10},
                                  "KXGOODDAILY": {"p75_h": 16.0, "horizon_h": 40.0,
                                                  "dates": 2, "n": 4}}}, f)
        self.assertEqual(imm.load_daily_series_file(), 1)
        self.assertTrue(imm.is_daily_series("KXGOODDAILY"))
        self.assertFalse(imm.is_daily_series("KXSTALEWEEKLY"))
        # absent file: untouched
        os.remove(imm.daily_series_path())
        self.assertEqual(imm.load_daily_series_file(), 0)

    def test_daily_families_take_no_global_window_but_keep_their_own(self):
        imm.HOUR_SIZE_MULTS = imm._parse_hour_mults("0-9:2.0")
        imm.SERIES_HOUR_MULTS = imm._parse_series_hour_mults(
            "KXNEWGASD:16-1:0.5,KXAAAGASD:16-1:0.5")
        t0 = utc(2026, 9, 9, 12, 0)                  # a Wednesday
        imm.refresh_daily_series(
            self._feed([("KXNEWGASD-26SEP09-4.00", t0, 16),
                        ("KXNEWGASD-26SEP10-4.00", t0, 16)]), t0)
        at_4am = utc(2026, 9, 9, 8, 0)               # 4:00am EDT
        at_9am = utc(2026, 9, 9, 13, 0)              # 9:00am EDT: hour 9 inclusive
        at_10am = utc(2026, 9, 9, 14, 0)             # 10:00am EDT: window closed
        at_8pm = utc(2026, 9, 10, 0, 0)              # 8:00pm EDT Sep 9
        self.assertEqual(imm.hour_size_mult("KXFOO", at_4am), 2.0)
        self.assertEqual(imm.hour_size_mult("KXFOO", at_9am), 2.0)
        self.assertEqual(imm.hour_size_mult("KXFOO", at_10am), 1.0)
        for daily in ("KXNEWGASD", "KXAAAGASD", "KXRAIN", "KXTEMPMIAH"):
            self.assertEqual(imm.hour_size_mult(daily, at_4am), 1.0, daily)
            self.assertEqual(imm.hour_size_mult(daily, at_9am), 1.0, daily)
        # a daily's own per-series window still wins
        self.assertEqual(imm.hour_size_mult("KXNEWGASD", at_8pm), 0.5)
        self.assertEqual(imm.hour_size_mult("KXAAAGASD", at_8pm), 0.5)

    def test_saturday_mult_skips_daily_families(self):
        imm.SAT_SIZE_MULT = 1.5
        t0 = utc(2026, 9, 12, 12, 0)                 # Saturday
        imm.refresh_daily_series(
            self._feed([("KXNEWUST-26SEP12-T4.1", t0 - timedelta(hours=20), 23.5),
                        ("KXNEWUST-26SEP13-T4.1", t0 + timedelta(hours=4), 23.5)]), t0)
        self.assertTrue(imm.is_daily_series("KXNEWUST"))
        sat_noon = utc(2026, 9, 12, 16, 0)
        self.assertEqual(imm.hour_size_mult("KXTRUMPMENTION", sat_noon), 1.5)
        self.assertEqual(imm.hour_size_mult("KXNEWUST", sat_noon), 1.0)
        self.assertEqual(imm.hour_size_mult("KXAAAGASD", sat_noon), 1.0)
        imm.SAT_MULT_EXCLUDE = ("KXTRUMP",)
        self.assertEqual(imm.hour_size_mult("KXTRUMPMENTION", sat_noon), 1.0)
        self.assertEqual(imm.hour_size_mult("KXFOO", sat_noon), 1.5)


# ----------------------------------------------------------------------------
# Rain daily fair-value anchor (2026-07-28)
# ----------------------------------------------------------------------------

class TestRainFairAnchor(unittest.TestCase):
    """rain_fair_values.json -> load_rain_fair/rain_fair_p -> at-touch GATE
    in the quote loop: quotes always join the touch (rewards need the top of
    book); fair only decides WHETHER to quote (stand aside when the touch
    fights the forecast beyond TOL). Fixture ticker KXRAIN-68DEC31-SEA
    (date parses via %y%b%d like production dailies; %y maps 99->1999)."""

    T = "KXRAIN-68DEC31-SEA"

    def setUp(self):
        _clean_persist()
        imm._rain_fair_state["mtime"] = 0.0
        imm._rain_fair_state["fair"] = {}
        # KXRAIN halves its ladder 16:00-01:59 ET (Jack 2026-08-04), and these
        # assertions are on literal rung sizes against the wall clock — so the
        # whole class failed from 4pm ET onward. Neutralise the hour windows;
        # their own coverage lives in TestPerSeriesHourMultiplier.
        self._saved_hour_mults = imm.SERIES_HOUR_MULTS
        imm.SERIES_HOUR_MULTS = []
        # Same for the daily x1.5 family size (2026-09-27): these assertions
        # are about the fair GATE, so the family size is pinned at 1.0 here;
        # its own coverage lives in TestDailyRainSizeMult.
        self._saved_rain_ov = imm.SERIES_OVERRIDES["KXRAIN"]
        imm.SERIES_OVERRIDES["KXRAIN"] = dataclasses.replace(
            self._saved_rain_ov, size_mult=None)
        try:
            os.remove(imm.RAIN_FAIR_FILE)
        except FileNotFoundError:
            pass

    def tearDown(self):
        imm.SERIES_HOUR_MULTS = self._saved_hour_mults
        imm.SERIES_OVERRIDES["KXRAIN"] = self._saved_rain_ov

    def _write_fair(self, p, age_secs=0.0):
        fetched = datetime.now(timezone.utc) - timedelta(seconds=age_secs)
        with open(imm.RAIN_FAIR_FILE, "w", encoding="utf-8") as f:
            json.dump({"fair": {"2068-12-31": {
                "SEA": {"p": p, "fetched_at": fetched.isoformat()}}}}, f)
        # mtime-gated reload: a rewrite inside the same mtime tick must not
        # be silently skipped
        os.utime(imm.RAIN_FAIR_FILE,
                 (time.time(), time.time() + self._bump))
        self._bump += 1
        self.assertEqual(imm.load_rain_fair(), 1)

    _bump = 1

    def _bot(self):
        client = FakeClient()
        now = datetime.now(timezone.utc)
        far = (now + timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
        client.programs.append(
            {"market_ticker": self.T, "incentive_type": "liquidity",
             "period_reward": 7000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": client.programs[0]["start_date"],
             "end_date": client.programs[0]["end_date"]})
        client.markets[self.T] = {
            "ticker": self.T, "event_ticker": "KXRAIN-68DEC31",
            "status": "active", "close_time": far,
            "yes_bid_dollars": "0.4900", "yes_ask_dollars": "0.5100",
            "volume_fp": "500.00"}
        client.books[self.T] = {"orderbook_fp": {
            "yes_dollars": [["0.48", "500"], ["0.49", "600"]],
            "no_dollars": [["0.49", "1200"]]}}          # 49 x 51
        return IncentiveMarketMaker(client=client, live=False)

    def _rain_quotes(self, bot):
        return sorted((o["book_side"], o["yes_price"], o["remaining_count"])
                      for o in bot.state.sim_orders.values()
                      if o["ticker"] == self.T)

    def test_lookup_parsing_and_ttl(self):
        self._write_fair(0.30)
        now_ts = time.time()
        self.assertAlmostEqual(imm.rain_fair_p(self.T, now_ts), 0.30)
        self.assertIsNone(imm.rain_fair_p("KXRAIN-68DEC31-NYC", now_ts))   # absent city
        self.assertIsNone(imm.rain_fair_p("KXRAINMIAM-99DEC-5", now_ts))   # monthly series
        self.assertIsNone(imm.rain_fair_p("KXGOOD-99DEC31-A", now_ts))     # other series
        self.assertIsNone(imm.rain_fair_p("KXRAIN-BADDATE-SEA", now_ts))   # unparseable
        self.assertIsNone(                                                  # TTL expiry
            imm.rain_fair_p(self.T, now_ts + imm.RAIN_FAIR_TTL_MIN * 60 + 5))

    def test_stale_entry_degrades_to_plain_join(self):
        self._write_fair(0.30, age_secs=imm.RAIN_FAIR_TTL_MIN * 60 + 60)
        bot = self._bot()
        bot.run_cycle()
        self.assertEqual(self._rain_quotes(bot), sorted([
            ("bid", 49, 5.0), ("bid", 48, 10.0), ("bid", 47, 20.0),
            ("ask", 51, 5.0), ("ask", 52, 10.0), ("ask", 53, 20.0)]))

    PLAIN_JOIN = sorted([
        ("bid", 49, 5.0), ("bid", 48, 10.0), ("bid", 47, 20.0),
        ("ask", 51, 5.0), ("ask", 52, 10.0), ("ask", 53, 20.0)])

    def test_agreeing_fair_quotes_at_touch(self):
        self._write_fair(0.45)     # |touch - fair| within tol 10 -> AT TOUCH,
        bot = self._bot()          # never re-priced (rewards need the join)
        bot.run_cycle()
        self.assertEqual(self._rain_quotes(bot), self.PLAIN_JOIN)

    def test_tol_boundary_inclusive(self):
        self._write_fair(0.39)     # bid touch 49 == fair 39 + tol 10: NOT a
        bot = self._bot()          # breach (strict >), still quotes at touch
        bot.run_cycle()
        self.assertEqual(self._rain_quotes(bot), self.PLAIN_JOIN)

    def test_bid_touch_over_fair_stands_aside_then_resumes(self):
        self._write_fair(0.30)     # bid touch 49 > 30+10 -> paying over fair
        bot = self._bot()
        bot.run_cycle()
        self.assertEqual(self._rain_quotes(bot), [])
        self.assertIn(self.T, bot._rain_fair_stood)
        self.assertIn(self.T, bot.state.selected)     # sticky: still selected
        # non-rain market in the same cycle keeps its plain join
        good = sorted((o["book_side"], o["yes_price"]) for o in
                      bot.state.sim_orders.values()
                      if o["ticker"] == "KXGOOD-99DEC31-A")
        self.assertIn(("bid", 49), good)
        self.assertIn(("ask", 51), good)
        self._write_fair(0.50)     # forecast agrees again -> resume AT TOUCH
        bot.run_cycle()
        self.assertNotIn(self.T, bot._rain_fair_stood)
        self.assertEqual(self._rain_quotes(bot), self.PLAIN_JOIN)

    def test_ask_touch_under_fair_stands_aside(self):
        self._write_fair(0.70)     # ask touch 51 < 70-10 -> selling under fair
        bot = self._bot()
        bot.run_cycle()
        self.assertEqual(self._rain_quotes(bot), [])
        self.assertIn(self.T, bot._rain_fair_stood)

    def test_disabled_flag_restores_plain_join(self):
        self._write_fair(0.30)     # would gate if enabled
        old = imm.RAIN_FAIR_ENABLE
        imm.RAIN_FAIR_ENABLE = False
        try:
            bot = self._bot()
            bot.run_cycle()
            self.assertEqual(self._rain_quotes(bot), self.PLAIN_JOIN)
        finally:
            imm.RAIN_FAIR_ENABLE = old


class TestCarbonArcFairGate(unittest.TestCase):
    """carbon_arc_fair.json -> load_ca_fair/ca_fair_p -> the rain gate's
    shape on Carbon Arc-settled markets (Jack 2026-09-26, with Carbon Arc's
    consent: "use Carbon Arc's data when quoting"). Fixture ticker
    KXFAKECC-68DEC07-T100: a Carbon Arc verdict, measurement month 2068-11
    (the month before the ticker date), far from the late-month windows."""

    T = "KXFAKECC-68DEC07-T100"
    _bump = 1

    def setUp(self):
        _clean_persist()
        imm._ca_fair_state.update(mtime=0.0, entries={}, moved_at={})
        self._saved_hour_mults = imm.SERIES_HOUR_MULTS
        imm.SERIES_HOUR_MULTS = []
        imm.FAMILY_VERDICTS["KXFAKECC"] = {
            "carbon_arc": True, "ts": time.time(), "title": ""}
        imm.FAMILY_VERDICTS["KXNOTCACC"] = {
            "carbon_arc": False, "ts": time.time(), "title": ""}
        try:
            os.remove(imm.CA_FAIR_FILE)
        except FileNotFoundError:
            pass

    def tearDown(self):
        imm.SERIES_HOUR_MULTS = self._saved_hour_mults
        imm.FAMILY_VERDICTS.pop("KXFAKECC", None)
        imm.FAMILY_VERDICTS.pop("KXNOTCACC", None)

    def _write_fair(self, entries, age_secs=0.0):
        fetched = (datetime.now(timezone.utc)
                   - timedelta(seconds=age_secs)).isoformat()
        with open(imm.CA_FAIR_FILE, "w", encoding="utf-8") as f:
            json.dump({"entries": {s: dict(e, fetched_at=fetched)
                                   for s, e in entries.items()}}, f)
        os.utime(imm.CA_FAIR_FILE, (time.time(), time.time() + self._bump))
        TestCarbonArcFairGate._bump += 1
        n, _moved = imm.load_ca_fair()
        self.assertEqual(n, len(entries))

    def _entry(self, mu, sigma=2.0, month="2068-11"):
        return {"mu": mu, "sigma": sigma, "month": month}

    def _bot(self, ticker=None):
        t = ticker or self.T
        client = FakeClient()
        now = datetime.now(timezone.utc)
        far = (now + timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
        client.programs.append(
            {"market_ticker": t, "incentive_type": "liquidity",
             "period_reward": 7000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": client.programs[0]["start_date"],
             "end_date": client.programs[0]["end_date"]})
        client.markets[t] = {
            "ticker": t, "event_ticker": t.rsplit("-", 1)[0],
            "status": "active", "close_time": far,
            "yes_bid_dollars": "0.4900", "yes_ask_dollars": "0.5100",
            "volume_fp": "500.00"}
        # 49 x 51, five levels a side: the *CC family safe-joins behind the
        # touch, so the qualifying walk must reach past it or the market is
        # zero_yield and never quoted at all
        lv = [["0.45", "400"], ["0.46", "400"], ["0.47", "400"],
              ["0.48", "400"], ["0.49", "300"]]
        client.books[t] = {"orderbook_fp": {"yes_dollars": lv,
                                            "no_dollars": lv}}
        return IncentiveMarketMaker(client=client, live=False)

    def _quotes(self, bot, ticker=None):
        t = ticker or self.T
        return sorted((o["book_side"], o["yes_price"])
                      for o in bot.state.sim_orders.values()
                      if o["ticker"] == t)

    def test_measurement_month_and_strike_scale(self):
        self.assertEqual(imm.ca_measurement_month("KXAMZNCC-26OCT07-T96"),
                         "2026-09")
        self.assertEqual(imm.ca_measurement_month("KXDRPEPPERPOS-26OCT03-T98"),
                         "2026-09")
        self.assertIsNone(imm.ca_measurement_month("KXAMZNCC-DOG-T1"))
        # a negative strike can only be growth percent (the August point-of-
        # sale ladders: T-3 = index 97); everything else is the index, even
        # far below the read (KXGROKAPP lists 20-46 under a ~122 read, and
        # KXAMUSEMENTADS 117-127 under ~192 -- a nearer-reading rule flipped
        # both on the 9/26 books)
        self.assertEqual(imm.ca_strike_value(-3.0), 97.0)
        self.assertEqual(imm.ca_strike_value(12.0), 12.0)
        self.assertEqual(imm.ca_strike_value(98.0), 98.0)
        self.assertEqual(imm.ca_strike_value(40.0), 40.0)

    def test_lookup_month_ttl_and_strike(self):
        self._write_fair({"KXFAKECC": self._entry(100.0)})
        now_ts = time.time()
        self.assertAlmostEqual(imm.ca_fair_p(self.T, now_ts), 0.5)
        self.assertAlmostEqual(imm.ca_fair_p("KXFAKECC-68DEC07-T102", now_ts),
                               0.158655, places=5)       # one sigma above
        self.assertAlmostEqual(imm.ca_fair_p("KXFAKECC-68DEC07-T98", now_ts),
                               0.841345, places=5)
        # growth-percent strike reads on the index (T-2 = 98)
        self.assertAlmostEqual(imm.ca_fair_p("KXFAKECC-68DEC07-T-2", now_ts),
                               0.841345, places=5)
        # wrong measurement month (next cycle's event), no strike, other
        # series, stale -> None (plain quoting)
        self.assertIsNone(imm.ca_fair_p("KXFAKECC-69JAN07-T100", now_ts))
        self.assertIsNone(imm.ca_fair_p("KXFAKECC-68DEC07", now_ts))
        self.assertIsNone(imm.ca_fair_p("KXOTHERCC-68DEC07-T100", now_ts))
        self.assertIsNone(imm.ca_fair_p(
            self.T, now_ts + imm.CA_FAIR_TTL_MIN * 60 + 5))

    def test_reload_counts_moved_reads_and_skips_bad_entries(self):
        self._write_fair({"KXFAKECC": self._entry(100.0)})
        with open(imm.CA_FAIR_FILE, "w", encoding="utf-8") as f:
            json.dump({"entries": {
                "KXFAKECC": dict(self._entry(100.0),
                                 fetched_at=datetime.now(timezone.utc).isoformat()),
                "KXBADSIG": {"mu": 100.0, "sigma": 0.0, "month": "2068-11",
                             "fetched_at": datetime.now(timezone.utc).isoformat()},
                "KXNOTS": {"mu": 100.0, "sigma": 1.0, "month": "2068-11"}}}, f)
        os.utime(imm.CA_FAIR_FILE, (time.time(), time.time() + 99))
        self.assertEqual(imm.load_ca_fair(), (1, 0))     # same read, 2 dropped
        self.assertEqual(imm.load_ca_fair(), (0, 0))     # unchanged mtime

    def test_breach_is_strict_and_per_side(self):
        self.assertEqual(imm.fair_gate_breach(49, 51, 30.0, 15), (True, False))
        self.assertEqual(imm.fair_gate_breach(49, 51, 34.0, 15), (False, False))
        self.assertEqual(imm.fair_gate_breach(49, 51, 70.0, 15), (False, True))
        self.assertEqual(imm.fair_gate_breach(None, 51, 70.0, 15), (False, True))
        self.assertEqual(imm.fair_gate_breach(49, None, 30.0, 15), (True, False))

    def test_band_and_noise_cap(self):
        # mu 98.95, sigma 2: P(> 100) = 0.30 at sigma, 0.147 at sigma / 2
        self._write_fair({"KXFAKECC": self._entry(98.95)})
        pc, lo, hi = imm.ca_fair_band(self.T, time.time())
        self.assertAlmostEqual(pc, 0.2997, places=3)
        self.assertAlmostEqual(lo, 0.1469, places=3)
        self.assertEqual(hi, pc)
        # a read noisier than 20% of mu cannot overrule the book: no band
        self._write_fair({"KXFAKECC": self._entry(100.0, sigma=25.0)})
        self.assertIsNone(imm.ca_fair_band(self.T, time.time()))
        self.assertIsNotNone(imm.ca_fair_p(self.T, time.time()))
        # a wing strike the book prices confidently (3x6 on T104, read 100 /
        # sigma 2.5: 5.5% at sigma, 0.3% at sigma/2) is NOT a breach: the ask
        # at 6 sits inside [0.3 - 15, ...] -- the Amazon-wing case that
        # fired 75 times on the 9/26 books without the band
        self._write_fair({"KXFAKECC": self._entry(100.0, sigma=2.5)})
        _pc, lo, hi = imm.ca_fair_band("KXFAKECC-68DEC07-T104", time.time())
        self.assertEqual(imm.fair_gate_breach(3, 6, lo * 100, 15, hi * 100),
                         (False, False))

    def test_refresh_hold_after_a_moved_read_not_on_first_load(self):
        self._write_fair({"KXFAKECC": self._entry(100.0)})     # first load
        self.assertFalse(imm.ca_refresh_held(self.T, time.time()))
        self._write_fair({"KXFAKECC": self._entry(100.4)})     # read moved
        now_ts = time.time()
        self.assertTrue(imm.ca_refresh_held(self.T, now_ts))
        # other months' markets are not held by this read
        self.assertFalse(imm.ca_refresh_held("KXFAKECC-69JAN07-T100", now_ts))
        self.assertFalse(imm.ca_refresh_held(
            self.T, now_ts + imm.CA_FAIR_REFRESH_HOLD_MIN * 60 + 1))
        # an unchanged rewrite does not restart the hold
        imm._ca_fair_state["moved_at"]["KXFAKECC"] -= 3600
        self._write_fair({"KXFAKECC": self._entry(100.4)})
        self.assertFalse(imm.ca_refresh_held(self.T, time.time()))
        with mock.patch.object(imm, "CA_FAIR_REFRESH_HOLD_MIN", 0):
            self._write_fair({"KXFAKECC": self._entry(100.9)})
            self.assertFalse(imm.ca_refresh_held(self.T, time.time()))

    def test_caps_are_the_breach_limits(self):
        # bids at most the band top + 15, asks at least the bottom - 15; a
        # floor at or under zero is no floor
        self.assertEqual(imm.ca_fair_caps(14.69, 29.97), (44, 0))
        self.assertEqual(imm.ca_fair_caps(70.03, 85.3), (100, 56))
        self.assertEqual(imm.ca_fair_caps(0.0, 0.4), (15, 0))
        # a touch exactly at a cap is no breach, so it is never moved
        self.assertEqual(imm.fair_gate_breach(44, 51, 14.69, 15, 29.97),
                         (False, False))
        self.assertEqual(imm.fair_gate_breach(45, 51, 14.69, 15, 29.97),
                         (True, False))

    def test_bid_touch_over_fair_rests_only_the_earning_side_then_resumes(self):
        # mu 98.95 / sigma 2 -> P(> 100) = 0.30: bid touch 49 > 30 + 15.
        # Jack 2026-10-04: "the bot should sit on the bid if it's earning
        # money on it, but not if it wouldnt earn". The bid is capped at 44,
        # behind 1,900 contracts at 45-49 against a 1,000 target: the walk
        # never reaches it, so it does not rest. The ask (the side the read
        # favours) still quotes at the (safe-)join.
        self._write_fair({"KXFAKECC": self._entry(98.95)})
        bot = self._bot()
        bot.run_cycle()
        q = self._quotes(bot)
        self.assertFalse(any(s == "bid" for s, _p in q), q)
        self.assertTrue(any(s == "ask" for s, _p in q), q)
        self.assertIn(self.T, bot._ca_fair_capped)
        self.assertNotIn(self.T, bot._ca_fair_stood)
        self.assertEqual(bot._ca_unearning.get(self.T), {"bid"})
        self.assertIn(self.T, bot.state.selected)
        # the read moves back to the book: first the refresh hold parks both
        # sides while the book reprices...
        self._write_fair({"KXFAKECC": self._entry(100.0)})
        bot.run_cycle()
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot._ca_fair_stood)
        # ...then both sides resume at the (safe-)join, uncapped
        imm._ca_fair_state["moved_at"]["KXFAKECC"] -= 3600
        bot.run_cycle()
        self.assertNotIn(self.T, bot._ca_fair_stood)
        self.assertNotIn(self.T, bot._ca_fair_capped)
        self.assertNotIn(self.T, bot._ca_unearning)
        q = self._quotes(bot)
        self.assertTrue(any(s == "bid" for s, _p in q), q)
        self.assertTrue(any(s == "ask" for s, _p in q), q)

    def test_a_capped_bid_that_still_earns_rests_at_its_cap(self):
        # only 200 contracts in front of the 44c cap (48 x 100, 49 x 100;
        # the side still qualifies on 1,000 at 20-21c): the walk reaches the
        # capped bid, so it sits there -- at most fair_hi + 15, never at 49
        self._write_fair({"KXFAKECC": self._entry(98.95)})
        bot = self._bot()
        bot.client.books[self.T] = {"orderbook_fp": {
            "yes_dollars": [["0.20", "800"], ["0.21", "200"],
                            ["0.48", "100"], ["0.49", "100"]],
            "no_dollars": [["0.45", "400"], ["0.46", "400"], ["0.47", "400"],
                           ["0.48", "400"], ["0.49", "300"]]}}
        bot.run_cycle()
        q = self._quotes(bot)
        bids = [p for s, p in q if s == "bid"]
        self.assertTrue(bids, q)
        self.assertLessEqual(max(bids), 44)
        self.assertTrue(any(s == "ask" for s, _p in q), q)
        self.assertEqual(bot._ca_unearning.get(self.T, set()), set())

    def test_ask_touch_under_fair_rests_only_the_bid(self):
        # mu 101.05 -> P(> 100) = 0.70: ask touch 51 < 70 - 15. The ask is
        # floored at 56, behind the whole NO side, and does not rest; the
        # bid quotes at the (safe-)join
        self._write_fair({"KXFAKECC": self._entry(101.05)})
        bot = self._bot()
        bot.run_cycle()
        q = self._quotes(bot)
        self.assertTrue(any(s == "bid" for s, _p in q), q)
        self.assertFalse(any(s == "ask" for s, _p in q), q)
        self.assertEqual(bot._ca_unearning.get(self.T), {"ask"})
        self.assertNotIn(self.T, bot._ca_fair_stood)

    def test_cap_off_parks_both_sides_as_before(self):
        # IMM_CA_FAIR_CAP=0: the pre-2026-10-04 both-sides stand-aside
        self._write_fair({"KXFAKECC": self._entry(98.95)})
        with mock.patch.object(imm, "CA_FAIR_CAP", False):
            bot = self._bot()
            bot.run_cycle()
            self.assertEqual(self._quotes(bot), [])
            self.assertIn(self.T, bot._ca_fair_stood)
            self.assertNotIn(self.T, bot._ca_fair_capped)
            self._write_fair({"KXFAKECC": self._entry(101.05)})
            imm._ca_fair_state["moved_at"].pop("KXFAKECC", None)
            bot.run_cycle()
            self.assertEqual(self._quotes(bot), [])

    def test_stale_or_disabled_or_not_carbon_arc_quotes_plainly(self):
        self._write_fair({"KXFAKECC": self._entry(98.95)},
                         age_secs=imm.CA_FAIR_TTL_MIN * 60 + 60)
        bot = self._bot()
        bot.run_cycle()
        self.assertNotEqual(self._quotes(bot), [])
        self.assertNotIn(self.T, bot._ca_fair_stood)
        self._write_fair({"KXFAKECC": self._entry(98.95)})
        with mock.patch.object(imm, "CA_FAIR_ENABLE", False):
            bot = self._bot()
            bot.run_cycle()
            self.assertNotEqual(self._quotes(bot), [])
        # a series without a Carbon Arc verdict is never gated, even with a
        # (bogus) read under its name
        other = "KXPLAINX-68DEC07-T100"
        self._write_fair({"KXPLAINX": self._entry(98.95)})
        bot = self._bot(other)
        bot.run_cycle()
        self.assertNotIn(other, bot._ca_fair_stood)
        self.assertNotEqual(self._quotes(bot, other), [])


class TestOpenRouterFairGate(unittest.TestCase):
    """openrouter_fair.json -> load_or_fair/or_gate_reason -> the stand-aside
    on KXTOKENUSE / KXTOKENUSEM (Jack 2026-09-27: "yes build the OpenRouter
    token usage gate"). Unlike the Carbon Arc gate it fails CLOSED: these
    series are allowed only because the feed exists. Fixture event
    KXTOKENUSE-68DEC04 (far from any cutoff), strike T100."""

    T = "KXTOKENUSE-68DEC04-T100"
    EV = "KXTOKENUSE-68DEC04"
    _bump = 1

    def setUp(self):
        _clean_persist()
        imm._or_fair_state.update(mtime=0.0, entries={}, moved_at={})
        self._saved_hour_mults = imm.SERIES_HOUR_MULTS
        imm.SERIES_HOUR_MULTS = []
        try:
            os.remove(imm.OR_FAIR_FILE)
        except FileNotFoundError:
            pass

    def tearDown(self):
        imm.SERIES_HOUR_MULTS = self._saved_hour_mults

    def _write(self, mu=100.0, sigma=2.0, known=5, complete=False, age_secs=0.0):
        fetched = (datetime.now(timezone.utc) - timedelta(seconds=age_secs)).isoformat()
        with open(imm.OR_FAIR_FILE, "w", encoding="utf-8") as f:
            json.dump({"entries": {self.EV: {
                "mu": mu, "sigma": sigma, "known": known, "complete": complete,
                "fetched_at": fetched}}}, f)
        os.utime(imm.OR_FAIR_FILE, (time.time(), time.time() + self._bump))
        TestOpenRouterFairGate._bump += 1
        return imm.load_or_fair()

    def _bot(self):
        client = FakeClient()
        now = datetime.now(timezone.utc)
        far = (now + timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
        client.programs.append(
            {"market_ticker": self.T, "incentive_type": "liquidity",
             "period_reward": 7000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": client.programs[0]["start_date"],
             "end_date": client.programs[0]["end_date"]})
        client.markets[self.T] = {
            "ticker": self.T, "event_ticker": self.EV,
            "status": "active", "close_time": far,
            "yes_bid_dollars": "0.4900", "yes_ask_dollars": "0.5100",
            "volume_fp": "500.00"}
        lv = [["0.45", "400"], ["0.46", "400"], ["0.47", "400"],
              ["0.48", "400"], ["0.49", "300"]]
        client.books[self.T] = {"orderbook_fp": {"yes_dollars": lv,
                                                 "no_dollars": lv}}
        return IncentiveMarketMaker(client=client, live=False)

    def _quotes(self, bot):
        return sorted((o["book_side"], o["yes_price"])
                      for o in bot.state.sim_orders.values()
                      if o["ticker"] == self.T)

    def test_allowlisted_uncapped_and_exact(self):
        self.assertIn("KXTOKENUSE", imm.ALLOW_SERIES)
        self.assertIn("KXTOKENUSEM", imm.ALLOW_SERIES)
        # Jack 2026-09-29: "remove the 3-strike cap on OpenRouter" -- every
        # strike the gate clears quotes (0 = no cap), pinned by exact name
        self.assertEqual(imm.event_top_n_for("KXTOKENUSE"), 0)
        self.assertEqual(imm.event_top_n_for("KXTOKENUSEM"), 0)
        self.assertIn(("=KXTOKENUSE", 0), imm.EVENT_TOP_N)
        self.assertIn(("=KXTOKENUSEM", 0), imm.EVENT_TOP_N)
        self.assertEqual(imm.event_top_n_for("KXTOKENUSED"), 0)   # exact names only
        self.assertIn("KXTOKENUSE", imm.OR_FAIR_SERIES)

    def test_reason_fail_closed_complete_hold_and_band(self):
        now_ts = time.time()
        self.assertEqual(imm.or_gate_reason(self.T, now_ts, 49, 51)[1]["reason"], "no_read")
        self.assertEqual(self._write(mu=100.0), (1, 1))          # first load: no hold
        self.assertEqual(imm.or_gate_reason(self.T, time.time(), 49, 51), ("", {}))
        self.assertEqual(imm.or_gate_reason("KXTOKENUSE-68DEC04", time.time(), 49, 51)[1]["reason"],
                         "no_read")                              # no strike segment
        self.assertEqual(imm.or_gate_reason(
            self.T, time.time() + imm.OR_FAIR_TTL_MIN * 60 + 5, 49, 51)[1]["reason"], "stale")
        self._write(mu=100.0, known=6)                            # a new day published
        self.assertEqual(imm.or_gate_reason(self.T, time.time(), 49, 51)[1]["reason"], "hold")
        imm._or_fair_state["moved_at"][self.EV] -= 3600
        self.assertEqual(imm.or_gate_reason(self.T, time.time(), 49, 51), ("", {}))
        self._write(mu=98.95, known=6)                            # same day, lower read
        why, inp = imm.or_gate_reason(self.T, time.time(), 49, 51)
        self.assertEqual((inp["reason"], inp["bid_bad"], inp["ask_bad"]), ("band", True, False))
        self._write(mu=150.0, sigma=0.0, known=7, complete=True)
        self.assertEqual(imm.or_gate_reason(self.T, time.time(), 99, 100)[1]["reason"], "complete")

    def test_quotes_on_an_agreeing_read_and_stands_aside_without_one(self):
        bot = self._bot()
        bot.run_cycle()                                           # no file: closed
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot._or_fair_stood)
        self._write(mu=100.0)                                     # first load: no hold
        bot.run_cycle()
        self.assertNotIn(self.T, bot._or_fair_stood)
        q = self._quotes(bot)
        self.assertIn(("bid", 49), q)
        self.assertIn(("ask", 51), q)
        self._write(mu=98.95)                                     # bid 49 > 30 + 15
        bot.run_cycle()
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot._or_fair_stood)
        self.assertIn(self.T, bot.state.selected)                 # sticky

    def test_complete_window_and_stale_read_stand_aside(self):
        self._write(mu=100.2, sigma=0.0, known=7, complete=True)
        bot = self._bot()
        bot.run_cycle()
        self.assertEqual(self._quotes(bot), [])
        imm._or_fair_state.update(mtime=0.0, entries={}, moved_at={})
        self._write(mu=100.0, age_secs=imm.OR_FAIR_TTL_MIN * 60 + 60)
        bot = self._bot()
        bot.run_cycle()
        self.assertEqual(self._quotes(bot), [])

    def test_gate_off_quotes_plainly(self):
        with mock.patch.object(imm, "OR_FAIR_ENABLE", False):
            bot = self._bot()
            bot.run_cycle()
            self.assertNotEqual(self._quotes(bot), [])


class TestNoLivePathUnderTest(unittest.TestCase):
    """setUpModule must redirect EVERY path incentive_mm bakes from the live
    status dir at import. 2026-10-01: SHARE_FAIR_FILE was missed, and a full
    suite run left TestOpenRouterShareFairGate's fixture in the live
    run-logs/incentive-mm (setUp also DELETES each gate's file, so a missed
    redirect of a live gate's file would blank it under the running bot).
    The class sweep: any upper-case string constant still pointing into the
    live dir fails here, whichever gate adds it next."""

    def test_every_baked_path_is_redirected(self):
        live = os.path.normcase(os.path.abspath(os.environ.get(
            "IMM_STATUS_DIR", r"C:\Users\jackd\Documents\KL\run-logs\incentive-mm")))
        self.assertNotEqual(os.path.normcase(os.path.abspath(imm.STATUS_DIR)), live)
        bad = [f"{owner}.{name}"
               for owner, ns in (("imm", vars(imm)),
                                 ("IncentiveMarketMaker", vars(imm.IncentiveMarketMaker)))
               for name, v in ns.items()
               if name.isupper() and isinstance(v, str) and v
               and os.path.normcase(os.path.abspath(v)).startswith(live)]
        self.assertEqual(bad, [])


class TestRainMonthlyGate(unittest.TestCase):
    """rain_monthly_fair.json -> load_rain_monthly/rain_monthly_gate_reason
    -> the stand-aside on KXRAINCHIM / KXRAINAUSM (Jack 2026-10-01: "quote
    these monthly rain markets, with an algorithm like how you quote the
    dailies"). The daily rain gate's at-touch shape, but fail CLOSED and out
    while it rains at the station. Fixture event KXRAINCHIM-68DEC (far from
    any cutoff), strike 3 inches."""

    T = "KXRAINCHIM-68DEC-3"
    EV = "KXRAINCHIM-68DEC"
    _bump = 1

    def setUp(self):
        _clean_persist()
        imm._rain_monthly_state.update(mtime=0.0, markets={}, events={})
        self._saved_hour_mults = imm.SERIES_HOUR_MULTS
        imm.SERIES_HOUR_MULTS = []
        try:
            os.remove(imm.RAIN_MONTHLY_FILE)
        except FileNotFoundError:
            pass

    def tearDown(self):
        imm.SERIES_HOUR_MULTS = self._saved_hour_mults

    def _write(self, p=0.5, wet=False, last_wet_mins=None, stale_cli=False,
               boundary=False, age_secs=0.0):
        now = datetime.now(timezone.utc)
        fetched = (now - timedelta(seconds=age_secs)).isoformat()
        lw = ((now - timedelta(minutes=last_wet_mins)).isoformat()
              if last_wet_mins is not None else None)
        with open(imm.RAIN_MONTHLY_FILE, "w", encoding="utf-8") as f:
            json.dump({"markets": {self.T: {"event": self.EV, "p": p,
                                            "boundary": boundary,
                                            "fetched_at": fetched}},
                       "event_state": {self.EV: {
                           "wet": wet, "last_wet_at": lw, "stale_cli": stale_cli,
                           "mtd": 2.2, "obs_time": fetched}}}, f)
        os.utime(imm.RAIN_MONTHLY_FILE, (time.time(), time.time() + self._bump))
        TestRainMonthlyGate._bump += 1
        return imm.load_rain_monthly()

    def _bot(self):
        client = FakeClient()
        now = datetime.now(timezone.utc)
        far = (now + timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
        client.programs.append(
            {"market_ticker": self.T, "incentive_type": "liquidity",
             "period_reward": 7000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": client.programs[0]["start_date"],
             "end_date": client.programs[0]["end_date"]})
        client.markets[self.T] = {
            "ticker": self.T, "event_ticker": self.EV,
            "status": "active", "close_time": far,
            "yes_bid_dollars": "0.4900", "yes_ask_dollars": "0.5100",
            "volume_fp": "500.00"}
        lv = [["0.45", "400"], ["0.46", "400"], ["0.47", "400"],
              ["0.48", "400"], ["0.49", "300"]]
        client.books[self.T] = {"orderbook_fp": {"yes_dollars": lv,
                                                 "no_dollars": lv}}
        return IncentiveMarketMaker(client=client, live=False)

    def _quotes(self, bot):
        return sorted((o["book_side"], o["yes_price"])
                      for o in bot.state.sim_orders.values()
                      if o["ticker"] == self.T)

    ALL = ("KXRAINAUSM", "KXRAINCHIM", "KXRAINCLLM", "KXRAINCMHM", "KXRAINDALM",
           "KXRAINDENM", "KXRAINHOUM", "KXRAINLAXM", "KXRAINLEXM", "KXRAINMIAM",
           "KXRAINMKEM", "KXRAINNYCM", "KXRAINPVDM", "KXRAINSEAM", "KXRAINSFOM",
           "KXRAINSTPM")

    def test_every_city_allowlisted_with_the_day_before_cutoff(self):
        # the two Jack named, then "yes add all the cities": the sixteen
        # KXRAIN<CITY>M series in the catalog on 2026-10-01
        self.assertEqual(imm.RAIN_MONTHLY_SERIES, frozenset(self.ALL))
        for s in self.ALL:
            self.assertIn(s, imm.ALLOW_SERIES, s)
            self.assertTrue(imm.rain_monthly_series(s), s)
            ov = imm.SERIES_OVERRIDES[s]
            self.assertEqual(ov.cutoff_from_close_min, 1560, s)
            self.assertEqual((ov.price_min_cents, ov.price_max_cents), (5, 90), s)
            self.assertEqual(imm.event_top_n_for(s), 0, s)
        # the daily KXRAIN is not a monthly (its own NWS gate)
        self.assertFalse(imm.rain_monthly_series("KXRAIN"))
        # close 23:59:59 ET on Oct 31 -> out at 22:00 ET on Oct 30 (the
        # dailies' "10pm the day before the rain day"); EST in November
        U = timezone.utc
        for ev, close, want in (
                ("KXRAINCHIM-26OCT", datetime(2026, 11, 1, 3, 59, 59, tzinfo=U),
                 datetime(2026, 10, 31, 1, 59, 59, tzinfo=U)),
                ("KXRAINAUSM-26NOV", datetime(2026, 12, 1, 4, 59, 59, tzinfo=U),
                 datetime(2026, 11, 30, 2, 59, 59, tzinfo=U))):
            occ = close + timedelta(days=1)
            cut = imm.trade_cutoff_utc(ev, occ, occ)
            self.assertEqual(imm.apply_series_cutoff_adjustments(
                ev.split("-")[0], ev, cut, close), want, ev)
        self.assertIn("RAIN_MONTHLY_ENABLE", imm._CONFIG_CODE_KNOBS)

    def test_reason_fail_closed_wet_drying_stale_cli_boundary_band(self):
        now_ts = time.time()
        self.assertEqual(imm.rain_monthly_gate_reason(self.T, now_ts, 49, 51)[1]["reason"],
                         "no_read")
        self.assertEqual(self._write(), 1)
        self.assertEqual(imm.rain_monthly_gate_reason(self.T, time.time(), 49, 51), ("", {}))
        self.assertEqual(imm.rain_monthly_gate_reason(
            self.T, time.time() + imm.RAIN_MONTHLY_TTL_MIN * 60 + 5, 49, 51)[1]["reason"],
            "stale")
        self._write(wet=None)
        self.assertEqual(imm.rain_monthly_gate_reason(self.T, time.time(), 49, 51)[1]["reason"],
                         "no_obs")
        self._write(wet=True, last_wet_mins=0)
        why, inp = imm.rain_monthly_gate_reason(self.T, time.time(), 49, 51)
        self.assertEqual(inp["reason"], "raining")
        self._write(wet=False, last_wet_mins=20)                 # stopped 20m ago
        self.assertEqual(imm.rain_monthly_gate_reason(self.T, time.time(), 49, 51)[1]["reason"],
                         "drying")
        self._write(wet=False, last_wet_mins=imm.RAIN_MONTHLY_DRY_MIN + 5)
        self.assertEqual(imm.rain_monthly_gate_reason(self.T, time.time(), 49, 51), ("", {}))
        self._write(stale_cli=True)
        self.assertEqual(imm.rain_monthly_gate_reason(self.T, time.time(), 49, 51)[1]["reason"],
                         "stale_cli")
        self._write(boundary=True)
        self.assertEqual(imm.rain_monthly_gate_reason(self.T, time.time(), 49, 51)[1]["reason"],
                         "boundary")
        self._write(p=0.30)                                       # bid 49 > 30 + 10
        why, inp = imm.rain_monthly_gate_reason(self.T, time.time(), 49, 51)
        self.assertEqual((inp["reason"], inp["bid_bad"], inp["ask_bad"]), ("band", True, False))
        self._write(p=0.70)                                       # ask 51 < 70 - 10
        why, inp = imm.rain_monthly_gate_reason(self.T, time.time(), 49, 51)
        self.assertEqual((inp["reason"], inp["bid_bad"], inp["ask_bad"]), ("band", False, True))
        self._write(p=0.59)                                       # inside the tolerance
        self.assertEqual(imm.rain_monthly_gate_reason(self.T, time.time(), 49, 51), ("", {}))

    def test_quotes_dry_and_stands_aside_while_it_rains(self):
        bot = self._bot()
        bot.run_cycle()                                           # no file: closed
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot._rain_monthly_stood)
        self._write()
        bot.run_cycle()
        self.assertNotIn(self.T, bot._rain_monthly_stood)
        q = self._quotes(bot)
        self.assertIn(("bid", 49), q)
        self.assertIn(("ask", 51), q)
        self._write(wet=True, last_wet_mins=0)                    # rain starts
        bot.run_cycle()
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot._rain_monthly_stood)
        self.assertIn(self.T, bot.state.selected)                 # sticky

    def test_launcher_freezes_no_monthly_rain(self):
        # the launcher's IMM_BLOCKLIST froze every monthly city since 7/26;
        # code and launcher must agree, or an allowed city stays frozen (the
        # list is PREFIX-matched, so no KXRAIN entry of any length may stay)
        import re
        with open(os.path.join(os.path.dirname(os.path.abspath(imm.__file__)),
                               "run_incentive_mm.ps1"), encoding="utf-8") as f:
            text = f.read()
        chunks = re.findall(r'\$ProbeEnv\s*=\s*"(set .*?)"', text, re.S)
        env = dict(re.findall(r"set ([A-Za-z_][A-Za-z0-9_]*)=([^&]*)&&", chunks[-1]))
        blocked = [b for b in env["IMM_BLOCKLIST"].split(",") if b]
        self.assertEqual([b for b in blocked if b.startswith("KXRAIN")], [], blocked)
        self.assertEqual(set(blocked), {"KXCRYPTOSTRUCTURE", "KXAAAGASW"})

    def test_gate_off_takes_the_family_out(self):
        import subprocess
        import sys
        code = ("import incentive_mm as imm\n"
                "print(sorted(s for s in imm.ALLOW_SERIES if s.startswith('KXRAIN')))\n"
                "print(imm.RAIN_MONTHLY_ENABLE)\n")
        env = dict(os.environ, IMM_RAIN_MONTHLY_ENABLE="0")
        r = subprocess.run([sys.executable, "-c", code], cwd=os.path.dirname(
            os.path.abspath(imm.__file__)), env=env, capture_output=True, timeout=120)
        self.assertEqual(r.returncode, 0, r.stderr.decode("utf-8", "replace")[-800:])
        out = r.stdout.decode("utf-8").strip().splitlines()
        self.assertNotIn("KXRAINCHIM", out[-2])
        self.assertNotIn("KXRAINAUSM", out[-2])
        self.assertEqual(out[-1], "False")


class TestRainPeriodGate(unittest.TestCase):
    """KXRAINNAPAM and the other KXRAIN period totals (Jack 2026-10-04:
    "quote KXRAINNAPAM and similar families based on rain feed"): the monthly
    gate's file and checks at RAIN_PERIOD_TOL_CENTS, except that a touch that
    fights the fair caps that side, which rests only while it earns, instead
    of parking both. Fixture event KXRAINNAPAM-01NOV68-31MAR69 (far from any
    cutoff), strike 20 inches."""

    T = "KXRAINNAPAM-01NOV68-31MAR69-T20"
    EV = "KXRAINNAPAM-01NOV68-31MAR69"
    _bump = 1

    def setUp(self):
        _clean_persist()
        imm._rain_monthly_state.update(mtime=0.0, markets={}, events={})
        self._saved_hour_mults = imm.SERIES_HOUR_MULTS
        imm.SERIES_HOUR_MULTS = []
        try:
            os.remove(imm.RAIN_MONTHLY_FILE)
        except FileNotFoundError:
            pass

    def tearDown(self):
        imm.SERIES_HOUR_MULTS = self._saved_hour_mults
        imm.RAIN_PERIOD_CAP = True

    def _write(self, p=0.5, wet=False, last_wet_mins=None):
        now = datetime.now(timezone.utc)
        lw = ((now - timedelta(minutes=last_wet_mins)).isoformat()
              if last_wet_mins is not None else None)
        with open(imm.RAIN_MONTHLY_FILE, "w", encoding="utf-8") as f:
            json.dump({"markets": {self.T: {"event": self.EV, "p": p, "boundary": False,
                                            "fetched_at": now.isoformat()}},
                       "event_state": {self.EV: {
                           "wet": wet, "last_wet_at": lw, "stale_cli": False,
                           "mtd": 0.0, "obs_time": now.isoformat()}}}, f)
        os.utime(imm.RAIN_MONTHLY_FILE, (time.time(), time.time() + self._bump))
        TestRainPeriodGate._bump += 1
        return imm.load_rain_monthly()

    def _bot(self, yes_lv=None):
        client = FakeClient()
        far = (datetime.now(timezone.utc) + timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
        client.programs.append(
            {"market_ticker": self.T, "incentive_type": "liquidity",
             "period_reward": 5000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": client.programs[0]["start_date"],
             "end_date": client.programs[0]["end_date"]})
        client.markets[self.T] = {
            "ticker": self.T, "event_ticker": self.EV, "status": "active",
            "close_time": far, "yes_bid_dollars": "0.4900",
            "yes_ask_dollars": "0.5100", "volume_fp": "500.00"}
        lv = [["0.45", "400"], ["0.46", "400"], ["0.47", "400"],
              ["0.48", "400"], ["0.49", "300"]]
        client.books[self.T] = {"orderbook_fp": {"yes_dollars": yes_lv or lv,
                                                 "no_dollars": lv}}
        return IncentiveMarketMaker(client=client, live=False)

    def _quotes(self, bot):
        return sorted((o["book_side"], o["yes_price"])
                      for o in bot.state.sim_orders.values()
                      if o["ticker"] == self.T)

    def test_family_guards_band_and_cutoff(self):
        for s in ("KXRAINNAPAM", "KXRAINNYCW"):
            ov = imm.series_override(s)
            self.assertEqual((ov.price_min_cents, ov.price_max_cents), (5, 90), s)
            self.assertEqual(ov.cutoff_from_close_min, 1560, s)
            self.assertIsNone(ov.cutoff_before_event_min, s)
            # x2 (Jack 2026-10-04 night: "2x snow markets, and rain ones like
            # napa"): rungs, the per-market and per-event caps together
            self.assertEqual(ov.size_mult, 2.0, s)
            self.assertEqual(imm.applied_mention_mult(s), 2.0, s)
            self.assertEqual(imm.series_max_position(s), imm.MAX_POSITION_CONTRACTS * 2, s)
            self.assertEqual(imm.event_cap_contracts(f"{s}-01NOV26-31MAR27"),
                             imm.MAX_EVENT_CONTRACTS * 2, s)
            self.assertEqual([q for _t, q in imm.base_scaled_levels(s)],
                             [max(1, int(q * 2 + 0.5)) for _t, q in imm.series_levels(s)], s)
        self.assertIn("RAIN_PERIOD_SIZE_MULT", imm._CONFIG_CODE_KNOBS)
        # ...at every hour (Jack 2026-10-05, "KXRAINNAPAM-01NOV26-31MAR27
        # isnt at 2x"): the KXRAIN 19-1 ET halving stays the dailies' and
        # the city monthlies', never the period family's (a clone included)
        imm.SERIES_HOUR_MULTS = imm._parse_series_hour_mults("KXRAIN:19-1:0.5")
        imm.SERIES_OVERRIDES.pop("KXRAINSONOMAM", None)
        try:
            imm.ensure_family_override("KXRAINSONOMAM")
            evening = utc(2026, 10, 5, 4, 30)            # 00:30 EDT Monday
            noon = utc(2026, 10, 5, 16, 0)
            for s in ("KXRAINNAPAM", "KXRAINNYCW", "KXRAINSONOMAM"):
                self.assertTrue(imm.rain_period_member(s), s)
                self.assertEqual(imm.hour_size_mult(s, evening), 1.0, s)
                self.assertEqual([q for _t, q in imm.hour_scaled_levels(s, evening)],
                                 [q for _t, q in imm.hour_scaled_levels(s, noon)], s)
            for s in ("KXRAIN", "KXRAINWKND", "KXRAINCHIM"):
                self.assertFalse(imm.rain_period_member(s), s)
                self.assertEqual(imm.hour_size_mult(s, evening), 0.5, s)
                self.assertEqual(imm.hour_size_mult(s, noon), 1.0, s)
        finally:
            imm.SERIES_OVERRIDES.pop("KXRAINSONOMAM", None)
        # a new city clones the archetype at first sight; a rainstorm city
        # still takes the span archetype (out at the start date)
        for s in ("KXRAINSONOMAM", "KXRAINSCHI"):
            imm.SERIES_OVERRIDES.pop(s, None)
        try:
            imm.ensure_family_override("KXRAINSONOMAM")
            imm.ensure_family_override("KXRAINSCHI")
            self.assertEqual(imm.series_override("KXRAINSONOMAM").cutoff_from_close_min,
                             1560)
            self.assertEqual(imm.series_override("KXRAINSCHI").cutoff_before_event_min, 0)
            self.assertIsNone(imm.series_override("KXRAINSCHI").cutoff_from_close_min)
        finally:
            for s in ("KXRAINSONOMAM", "KXRAINSCHI"):
                imm.SERIES_OVERRIDES.pop(s, None)
        # the season closes 23:59 PDT Mar 31 and is out at 21:59 PDT Mar 30;
        # its ticker reads day first (Nov 1, not 2001-11-26), and the close
        # anchor replaces the ticker rule in refresh_universe
        ev = "KXRAINNAPAM-01NOV26-31MAR27"
        self.assertEqual(imm.parse_event_date(ev), utc(2026, 11, 1, 4, 0))
        self.assertEqual(imm.apply_series_cutoff_adjustments(
            "KXRAINNAPAM", ev, None, utc(2027, 4, 1, 6, 59)), utc(2027, 3, 31, 4, 59))
        self.assertTrue(imm.series_override("KXRAINNAPAM").cutoff_from_close_min)
        for k in ("RAIN_PERIOD_ENABLE", "RAIN_PERIOD_TOL_CENTS", "RAIN_PERIOD_CAP"):
            self.assertIn(k, imm._CONFIG_CODE_KNOBS)

    def test_rainstorm_span_reads_its_start_day_first(self):
        # KXRAINSBOS-03OCT26-04OCT26 is Oct 3-4. Read YYMONDD it started
        # 2003-10-26, already past, so the span stood down unquoted; it is
        # out at 00:00 ET Oct 3, "up until the start date"
        ev = "KXRAINSBOS-03OCT26-04OCT26"
        stop = utc(2026, 10, 3, 4, 0)
        self.assertEqual(imm.parse_event_date(ev), stop)
        exp = utc(2026, 10, 5, 5, 0)
        self.assertEqual(imm.apply_series_cutoff_adjustments(
            "KXRAINSBOS", ev, imm.trade_cutoff_utc(ev, exp, exp),
            close_time=utc(2026, 10, 5, 3, 59)), stop)
        # one-date tickers keep YYMONDD
        self.assertEqual(imm.parse_event_date("KXRAINWKND-26OCT10"), utc(2026, 10, 10, 4, 0))
        self.assertEqual(imm.parse_event_date("KXRAIN-26OCT05-NYC"), utc(2026, 10, 5, 4, 0))

    def test_gate_reasons_and_caps(self):
        g = imm.rain_period_gate
        why, inp, caps = g(self.T, time.time(), 49, 51)
        self.assertEqual((inp["reason"], caps), ("no_read", None))
        self.assertTrue(why)
        self._write(p=0.5)
        self.assertEqual(g(self.T, time.time(), 49, 51), ("", {}, None))
        self._write(wet=True, last_wet_mins=0)
        why, inp, caps = g(self.T, time.time(), 49, 51)
        self.assertEqual((inp["reason"], caps), ("raining", None))
        # bid 49 > 30 + 10: bids capped at 40, the ask keeps the touch
        self._write(p=0.30)
        why, inp, caps = g(self.T, time.time(), 49, 51)
        self.assertEqual((why, caps), ("", (40, 20)))
        self.assertEqual((inp["reason"], inp["bid_bad"], inp["ask_bad"]), ("band", True, False))
        # ask 51 < 70 - 10: asks floored at 60
        self._write(p=0.70)
        self.assertEqual(g(self.T, time.time(), 49, 51)[2], (80, 60))
        # the season's T35 on the 10/4 book: fair 0.84c, a 12c bid capped
        # at 10, no ask floor
        self._write(p=0.0084)
        self.assertEqual(g(self.T, time.time(), 12, 59)[2], (10, 0))
        # cap off: a breach parks both sides, as on the monthlies
        imm.RAIN_PERIOD_CAP = False
        self._write(p=0.30)
        why, inp, caps = g(self.T, time.time(), 49, 51)
        self.assertTrue(why)
        self.assertEqual((inp["reason"], caps), ("band", None))

    def test_quotes_through_the_gate_and_caps_the_side_that_fights_it(self):
        bot = self._bot()
        bot.run_cycle()                                       # no file: closed
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot._rain_monthly_stood)
        self.assertEqual(bot._rain_period_series, {"KXRAINNAPAM"})
        self._write(p=0.5)
        bot.run_cycle()
        self.assertNotIn(self.T, bot._rain_monthly_stood)
        q = self._quotes(bot)
        self.assertIn(("bid", 49), q)
        self.assertIn(("ask", 51), q)
        # the fair drops to 30: the 49c bid touch fights it. Capped at 40,
        # behind 1,900 contracts of bids (over the 1,000 target), the bid
        # earns nothing and does not rest; the ask stays at the touch
        self._write(p=0.30)
        bot.run_cycle()
        q = self._quotes(bot)
        self.assertTrue(q)
        self.assertEqual({s for s, _ in q}, {"ask"}, q)
        self.assertIn(("ask", 51), q)
        self.assertIn(self.T, bot._rain_period_capped)
        self.assertEqual(bot._rain_period_unearning[self.T], {"bid"})
        # rain at the station: both sides out
        self._write(p=0.5, wet=True, last_wet_mins=0)
        bot.run_cycle()
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot._rain_monthly_stood)
        self.assertIn(self.T, bot.state.selected)                 # sticky

    def test_a_capped_side_that_still_earns_rests_at_its_cap(self):
        # 300 bid at 49 in front (under the 1,000 target), 900 at 30
        # behind: the scored walk reaches a 40c bid, so it rests there
        bot = self._bot(yes_lv=[["0.30", "900"], ["0.49", "300"]])
        self._write(p=0.30)
        bot.run_cycle()
        q = self._quotes(bot)
        self.assertIn(("bid", 40), q)
        self.assertIn(("ask", 51), q)
        self.assertFalse([p for s, p in q if s == "bid" and p > 40], q)


class TestSnowMonthlyGate(unittest.TestCase):
    """snow_monthly_fair.json -> load_snow_monthly/snow_monthly_gate -> the
    KX<CITY>SNOWM markets (Jack 2026-10-04: "build the snow feed"): the rain
    gate's checks on the snow file, failing closed, out while it snows, and a
    touch that fights the fair caps that side. Fixture event
    KXCHISNOWM-68DEC (far from any cutoff), strike 8 inches."""

    T = "KXCHISNOWM-68DEC-8"
    EV = "KXCHISNOWM-68DEC"
    _bump = 1

    def setUp(self):
        _clean_persist()
        imm._snow_monthly_state.update(mtime=0.0, markets={}, events={})
        self._saved_hour_mults = imm.SERIES_HOUR_MULTS
        imm.SERIES_HOUR_MULTS = []
        try:
            os.remove(imm.SNOW_MONTHLY_FILE)
        except FileNotFoundError:
            pass

    def tearDown(self):
        imm.SERIES_HOUR_MULTS = self._saved_hour_mults
        imm.SNOW_MONTHLY_CAP = True

    def _write(self, p=0.5, wet=False, last_wet_mins=None, stale_cli=False,
               stale_why=None, boundary=False):
        now = datetime.now(timezone.utc)
        lw = ((now - timedelta(minutes=last_wet_mins)).isoformat()
              if last_wet_mins is not None else None)
        with open(imm.SNOW_MONTHLY_FILE, "w", encoding="utf-8") as f:
            json.dump({"markets": {self.T: {"event": self.EV, "p": p, "boundary": boundary,
                                            "fetched_at": now.isoformat()}},
                       "event_state": {self.EV: {
                           "wet": wet, "last_wet_at": lw, "stale_cli": stale_cli,
                           "stale_why": stale_why, "mtd": 1.2,
                           "obs_time": now.isoformat()}}}, f)
        os.utime(imm.SNOW_MONTHLY_FILE, (time.time(), time.time() + self._bump))
        TestSnowMonthlyGate._bump += 1
        return imm.load_snow_monthly()

    def _bot(self):
        client = FakeClient()
        far = (datetime.now(timezone.utc) + timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
        client.programs.append(
            {"market_ticker": self.T, "incentive_type": "liquidity",
             "period_reward": 5000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": client.programs[0]["start_date"],
             "end_date": client.programs[0]["end_date"]})
        client.markets[self.T] = {
            "ticker": self.T, "event_ticker": self.EV, "status": "active",
            "close_time": far, "yes_bid_dollars": "0.4900",
            "yes_ask_dollars": "0.5100", "volume_fp": "500.00"}
        lv = [["0.45", "400"], ["0.46", "400"], ["0.47", "400"],
              ["0.48", "400"], ["0.49", "300"]]
        client.books[self.T] = {"orderbook_fp": {"yes_dollars": lv, "no_dollars": lv}}
        return IncentiveMarketMaker(client=client, live=False)

    def _quotes(self, bot):
        return sorted((o["book_side"], o["yes_price"])
                      for o in bot.state.sim_orders.values()
                      if o["ticker"] == self.T)

    TEN = ("KXBOSSNOWM", "KXCHISNOWM", "KXDCSNOWM", "KXDENSNOWM", "KXDETSNOWM",
           "KXMKESNOWM", "KXMSPSNOWM", "KXNYCSNOWM", "KXPHILSNOWM", "KXPITSNOWM")

    def test_family_allowlist_guards_and_cutoff(self):
        self.assertEqual(imm.SNOW_MONTHLY_SERIES, frozenset(self.TEN))
        old = imm.ALLOWLIST_ONLY
        imm.ALLOWLIST_ONLY = True
        try:
            a = IncentiveMarketMaker._allowed
            for s in self.TEN + ("KXBUFSNOWM",):              # a new city by name
                self.assertTrue(imm.snow_monthly_series(s), s)
                self.assertTrue(a(f"{s}-26DEC-8"), s)
            # other snow contracts: the Denver NWS line, Big Sky's resort
            # report, the old KXSNOW* lines, the crab catch
            for s in ("KXDENSNOWMB", "KXTSNOWFALLBIGSKYM", "KXSNOWNYM", "KXSNOWCRABCATCH"):
                self.assertFalse(imm.snow_monthly_series(s), s)
                self.assertFalse(a(f"{s}-26DEC-8"), s)
        finally:
            imm.ALLOWLIST_ONLY = old
        for s in self.TEN:
            self.assertIn(s, imm.ALLOW_SERIES, s)
            ov = imm.series_override(s)
            self.assertEqual((ov.price_min_cents, ov.price_max_cents), (5, 90), s)
            self.assertEqual(ov.cutoff_from_close_min, 1560, s)
            # x2 (Jack 2026-10-04 night: "2x snow markets")
            self.assertEqual(ov.size_mult, 2.0, s)
            self.assertEqual(imm.applied_mention_mult(s), 2.0, s)
            self.assertEqual(imm.series_max_position(s), imm.MAX_POSITION_CONTRACTS * 2, s)
            # with the rain monthlies: x1 at every hour, no Saturday/yield
            self.assertTrue(imm.is_daily_series(s), s)
            self.assertFalse(imm.yield_size_eligible(s), s)
        imm.SERIES_OVERRIDES.pop("KXBUFSNOWM", None)
        try:
            imm.ensure_family_override("KXBUFSNOWM")
            self.assertEqual(imm.series_override("KXBUFSNOWM").cutoff_from_close_min, 1560)
        finally:
            imm.SERIES_OVERRIDES.pop("KXBUFSNOWM", None)
        # close 23:59 CST Dec 31 -> out 21:59 CST Dec 30
        self.assertEqual(imm.apply_series_cutoff_adjustments(
            "KXCHISNOWM", "KXCHISNOWM-26DEC", None, utc(2027, 1, 1, 5, 59)),
            utc(2026, 12, 31, 3, 59))
        for k in ("SNOW_MONTHLY_ENABLE", "SNOW_MONTHLY_TOL_CENTS", "SNOW_MONTHLY_CAP",
                  "SNOW_MONTHLY_SIZE_MULT"):
            self.assertIn(k, imm._CONFIG_CODE_KNOBS)
        import imm_risk_controls
        self.assertIn("snow_monthly", imm_risk_controls.GATE_GUARDS)

    def test_gate_reasons_and_caps(self):
        g = imm.snow_monthly_gate
        why, inp, caps = g(self.T, time.time(), 49, 51)
        self.assertEqual((why, inp["reason"], caps),
                         ("no monthly snow fair for this market", "no_read", None))
        self._write()
        self.assertEqual(g(self.T, time.time(), 49, 51), ("", {}, None))
        self.assertEqual(g(self.T, time.time() + imm.SNOW_MONTHLY_TTL_MIN * 60 + 5,
                           49, 51)[1]["reason"], "stale")
        self._write(wet=None)
        self.assertEqual(g(self.T, time.time(), 49, 51)[1]["reason"], "no_obs")
        self._write(wet=True, last_wet_mins=0)
        why, inp, caps = g(self.T, time.time(), 49, 51)
        self.assertEqual((why, inp["reason"]), ("snowing at the station", "snowing"))
        self._write(last_wet_mins=20)
        why, inp, caps = g(self.T, time.time(), 49, 51)
        self.assertEqual(inp["reason"], "drying")
        self.assertTrue(why.startswith("snowed 2"), why)
        self._write(stale_cli=True, stale_why="snow since the last climate report")
        self.assertEqual(g(self.T, time.time(), 49, 51)[:2],
                         ("snow since the last climate report", {"reason": "stale_cli"}))
        self._write(boundary=True)
        self.assertEqual(g(self.T, time.time(), 49, 51)[1]["reason"], "boundary")
        # bid 49 > 30 + 10: the bid is capped at 40, the ask keeps the touch
        self._write(p=0.30)
        why, inp, caps = g(self.T, time.time(), 49, 51)
        self.assertEqual((why, caps, inp["bid_bad"]), ("", (40, 20), True))
        imm.SNOW_MONTHLY_CAP = False
        why, inp, caps = g(self.T, time.time(), 49, 51)
        self.assertEqual((inp["reason"], caps), ("band", None))
        self.assertTrue(why)
        # the rain gate's own messages are untouched by the refactor
        self.assertEqual(imm.rain_monthly_gate_reason("KXRAINCHIM-68DEC-3", time.time(),
                                                      49, 51)[0],
                         "no monthly rain fair for this market")

    def test_quotes_through_the_gate_and_stands_aside_while_it_snows(self):
        bot = self._bot()
        bot.run_cycle()                                       # no file: closed
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot._rain_monthly_stood)
        self.assertEqual(bot._snow_series, {"KXCHISNOWM"})
        self._write()
        bot.run_cycle()
        q = self._quotes(bot)
        self.assertIn(("bid", 49), q)
        self.assertIn(("ask", 51), q)
        # the fair drops to 30: the bid behind 1,900 contracts earns nothing
        self._write(p=0.30)
        bot.run_cycle()
        self.assertEqual({s for s, _ in self._quotes(bot)}, {"ask"})
        self.assertEqual(bot._rain_period_unearning[self.T], {"bid"})
        self._write(wet=True, last_wet_mins=0)                # snow starts
        bot.run_cycle()
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot.state.selected)                 # sticky


class TestOpenRouterShareFairGate(unittest.TestCase):
    """openrouter_share_fair.json -> load_share_fair/share_gate_reason -> the
    stand-aside on KX<AUTHOR>SHARE (Jack 2026-09-30: "scrape OpenRouter for
    market share markets", then "i got permission"). Fails CLOSED like the
    token gate, and also stands aside while an OpenRouter feed has stalled.
    Fixture event KXANTHSHARE-68DEC04 (far from any cutoff), strike 2.7 --
    YES from a published 2.8, i.e. a share >= 2.75."""

    T = "KXANTHSHARE-68DEC04-2.7"
    EV = "KXANTHSHARE-68DEC04"
    _bump = 1

    def setUp(self):
        _clean_persist()
        imm._share_fair_state.update(mtime=0.0, entries={}, moved_at={})
        self._saved_hour_mults = imm.SERIES_HOUR_MULTS
        imm.SERIES_HOUR_MULTS = []
        try:
            os.remove(imm.SHARE_FAIR_FILE)
        except FileNotFoundError:
            pass

    def tearDown(self):
        imm.SERIES_HOUR_MULTS = self._saved_hour_mults

    def _write(self, mu=2.75, sigma=0.2, p_ident=1.0, complete=False, lag=False,
               version="v1", age_secs=0.0):
        fetched = (datetime.now(timezone.utc) - timedelta(seconds=age_secs)).isoformat()
        with open(imm.SHARE_FAIR_FILE, "w", encoding="utf-8") as f:
            json.dump({"entries": {self.EV: {
                "mu": mu, "sigma": sigma, "p_ident": p_ident, "complete": complete,
                "lag": lag, "lag_reason": "the chart last moved 12-01 02:15Z, 225m ago" if lag else "",
                "data_version": version, "fetched_at": fetched}}}, f)
        os.utime(imm.SHARE_FAIR_FILE, (time.time(), time.time() + self._bump))
        TestOpenRouterShareFairGate._bump += 1
        return imm.load_share_fair()

    def _bot(self):
        client = FakeClient()
        now = datetime.now(timezone.utc)
        far = (now + timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
        client.programs.append(
            {"market_ticker": self.T, "incentive_type": "liquidity",
             "period_reward": 7000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": client.programs[0]["start_date"],
             "end_date": client.programs[0]["end_date"]})
        client.markets[self.T] = {
            "ticker": self.T, "event_ticker": self.EV,
            "status": "active", "close_time": far,
            "yes_bid_dollars": "0.4900", "yes_ask_dollars": "0.5100",
            "volume_fp": "500.00"}
        lv = [["0.45", "400"], ["0.46", "400"], ["0.47", "400"],
              ["0.48", "400"], ["0.49", "300"]]
        client.books[self.T] = {"orderbook_fp": {"yes_dollars": lv,
                                                 "no_dollars": lv}}
        return IncentiveMarketMaker(client=client, live=False)

    def _quotes(self, bot):
        return sorted((o["book_side"], o["yes_price"])
                      for o in bot.state.sim_orders.values()
                      if o["ticker"] == self.T)

    def test_allowlisted_with_the_week_end_cutoff(self):
        for s in ("KXANTHSHARE", "KXOPENSHARE", "KXGOOGSHARE", "KXDEEPSHARE",
                  "KXBABASHARE", "KXXIAOMISHARE", "KXZAISHARE", "KXMISTRALSHARE",
                  "KXTENCENTSHARE", "KXSTEALTHSHARE"):
            self.assertIn(s, imm.ALLOW_SERIES, s)
            self.assertTrue(imm.share_fair_series(s), s)
            self.assertEqual(imm.SERIES_OVERRIDES[s].cutoff_from_close_min, 840, s)
            # Jack 2026-10-01: "set max 3 markets per event", by exact name
            self.assertEqual(imm.event_top_n_for(s), 3, s)
            self.assertIn((f"={s}", 3), imm.EVENT_TOP_N)
            self.assertTrue(imm.IncentiveMarketMaker._allowed(f"{s}-26OCT05-3.1"), s)
            self.assertFalse(imm.IncentiveMarketMaker._blocked(f"{s}-26OCT05-3.1"), s)
        # the Vercel open-weights series is a different feed and gate, and
        # KXOPENSHARE's cap is not a prefix of it
        self.assertFalse(imm.share_fair_series("KXOPENSOURCESHARE"))
        self.assertEqual(imm.event_top_n_for("KXOPENSOURCESHARE"), 0)
        self.assertIn("SHARE_EVENT_TOP_N", imm._CONFIG_CODE_KNOBS)
        self.assertIn("share_fair", imm.STICKY_DEATH_REASONS)
        self.assertIn("share_no_read", imm.STICKY_DEATH_REASONS)
        # close 14:00Z Monday (10:00 ET) -> cutoff 00:00Z, the week's end
        close = datetime(2026, 10, 5, 14, 0, tzinfo=timezone.utc)
        self.assertEqual(close - timedelta(minutes=imm.SHARE_CUTOFF_FROM_CLOSE_MIN),
                         datetime(2026, 10, 5, 0, 0, tzinfo=timezone.utc))
        self.assertIn("SHARE_FAIR_ENABLE", imm._CONFIG_CODE_KNOBS)

    def test_kill_switch_takes_the_family_out(self):
        import subprocess
        import sys
        code = ("import incentive_mm as imm\n"
                "print(sorted(s for s in imm.ALLOW_SERIES if s.endswith('SHARE')))\n"
                "print(imm.SHARE_FAIR_ENABLE, imm.share_fair_series('KXANTHSHARE'))\n")
        env = dict(os.environ, IMM_SHARE_FAIR_ENABLE="0")
        r = subprocess.run([sys.executable, "-c", code], cwd=os.path.dirname(
            os.path.abspath(imm.__file__)), env=env, capture_output=True, timeout=120)
        self.assertEqual(r.returncode, 0, r.stderr.decode("utf-8", "replace")[-800:])
        out = r.stdout.decode("utf-8").strip().splitlines()
        self.assertEqual(out[-2], "['KXOPENSOURCESHARE']")      # Vercel's, not ours
        self.assertEqual(out[-1], "False False")

    def test_reason_fail_closed_complete_lag_hold_and_band(self):
        now_ts = time.time()
        self.assertEqual(imm.share_gate_reason(self.T, now_ts, 49, 51)[1]["reason"], "no_read")
        self.assertEqual(self._write(), (1, 1))                  # first load: no hold
        self.assertEqual(imm.share_gate_reason(self.T, time.time(), 49, 51), ("", {}))
        self.assertEqual(imm.share_gate_reason(self.EV, time.time(), 49, 51)[1]["reason"],
                         "no_read")                              # no strike segment
        self.assertEqual(imm.share_gate_reason(
            self.T, time.time() + imm.SHARE_FAIR_TTL_MIN * 60 + 5, 49, 51)[1]["reason"], "stale")
        self._write(lag=True)                                     # the chart stalled
        why, inp = imm.share_gate_reason(self.T, time.time(), 49, 51)
        self.assertEqual(inp["reason"], "lag")
        self.assertIn("OpenRouter feed stalled (the chart last moved", why)
        self._write(version="v2")                                 # a new day landed
        self.assertEqual(imm.share_gate_reason(self.T, time.time(), 49, 51)[1]["reason"], "hold")
        imm._share_fair_state["moved_at"][self.EV] -= 3600
        self.assertEqual(imm.share_gate_reason(self.T, time.time(), 49, 51), ("", {}))
        self._write(mu=2.5, version="v2")                         # same day, lower read
        why, inp = imm.share_gate_reason(self.T, time.time(), 49, 51)
        self.assertEqual((inp["reason"], inp["bid_bad"], inp["ask_bad"]), ("band", True, False))
        # P(YES) = p_ident x P(share >= 2.75): a fair 50c read named 30% of
        # the time is a 15c market
        self._write(mu=2.75, p_ident=0.3, version="v2")
        why, inp = imm.share_gate_reason(self.T, time.time(), 49, 51)
        self.assertEqual((inp["reason"], inp["fair"]), ("band", 15.0))
        self.assertAlmostEqual(imm.share_p_yes(2.7, 2.75, 0.2, 1.0), 0.5)
        self._write(mu=3.0, sigma=0.0, complete=True, version="v3")
        self.assertEqual(imm.share_gate_reason(self.T, time.time(), 99, 100)[1]["reason"],
                         "complete")

    def test_no_read_takes_no_slot_and_a_stalled_feed_stands_aside(self):
        bot = self._bot()
        bot.run_cycle()                                           # no file
        self.assertEqual(self._quotes(bot), [])
        self.assertNotIn(self.T, bot.state.selected)              # takes no slot
        self._write()                                             # first load: no hold
        bot.state.universe_at = 0.0                               # force a refresh
        bot.run_cycle()
        self.assertIn(self.T, bot.state.selected)
        self.assertNotIn(self.T, bot._share_fair_stood)
        q = self._quotes(bot)
        self.assertIn(("bid", 49), q)
        self.assertIn(("ask", 51), q)
        self._write(lag=True)                                     # a feed stalled
        bot.run_cycle()
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot._share_fair_stood)
        bot.state.universe_at = 0.0                               # and at a refresh
        bot.run_cycle()
        self.assertIn(self.T, bot.state.selected)                 # transient: keeps the slot
        self.assertEqual(self._quotes(bot), [])

    def test_a_touch_the_gate_rejects_frees_its_slot_at_a_refresh(self):
        # 3 per event (Jack 2026-10-01): a strike the gate would stand aside
        # every cycle must not hold one of the three
        self._write()
        bot = self._bot()
        bot.run_cycle()
        self.assertIn(self.T, bot.state.selected)
        self._write(mu=2.5)                                       # listed 49x51 vs fair ~11
        bot.run_cycle()                                           # the quote loop first
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot._share_fair_stood)
        self.assertIn(self.T, bot.state.selected)                 # sticky between refreshes
        bot.state.universe_at = 0.0                               # still fighting at a refresh
        bot.run_cycle()
        self.assertNotIn(self.T, bot.state.selected)              # the slot is freed
        self.assertEqual(self._quotes(bot), [])

    def test_gate_off_quotes_plainly(self):
        with mock.patch.object(imm, "SHARE_FAIR_ENABLE", False):
            bot = self._bot()
            bot.run_cycle()
            self.assertNotEqual(self._quotes(bot), [])

    def test_x1_at_every_hour_and_a_net_cap_per_event(self):
        # 2026-10-03 (Jack: "make the share market change"): the family takes
        # no quiet-hours / Saturday / evening / yield-mode size, and an event
        # nets at most SHARE_EVENT_CAP (every strike is one author's share)
        sat_3am = imm.ET.localize(datetime(2026, 10, 3, 3, 0)).astimezone(timezone.utc)
        mon_7pm = imm.ET.localize(datetime(2026, 10, 5, 19, 0)).astimezone(timezone.utc)
        shares = ("KXANTHSHARE", "KXOPENSHARE", "KXGOOGSHARE", "KXDEEPSHARE",
                  "KXBABASHARE", "KXXIAOMISHARE", "KXZAISHARE", "KXMISTRALSHARE",
                  "KXTENCENTSHARE", "KXSTEALTHSHARE")
        with mock.patch.object(imm, "HOUR_SIZE_MULTS", imm._parse_hour_mults("0-9:2.0")), \
                mock.patch.object(imm, "HOUR_SIZE_MULTS_NEXT", {}), \
                mock.patch.object(imm, "SAT_SIZE_MULT", 1.5), \
                mock.patch.object(imm, "EVENING_SIZE_MULTS", {h: 1.5 for h in range(18, 22)}):
            self.assertEqual(imm.hour_size_mult("KXGOOD", sat_3am), 3.0)   # the long-dated book
            for s in shares:
                self.assertEqual(imm.hour_size_mult(s, sat_3am), 1.0, s)
                self.assertEqual(imm.hour_size_mult(s, mon_7pm), 1.0, s)
                self.assertEqual(imm.hour_scaled_levels(s, sat_3am), imm.base_scaled_levels(s))
                self.assertFalse(imm.yield_size_eligible(s), s)
                self.assertEqual(imm.event_cap_contracts(f"{s}-26OCT05"), imm.SHARE_EVENT_CAP)
        self.assertEqual(imm.SHARE_EVENT_CAP, 100)
        # Vercel's open-weights series is not this family
        self.assertEqual(imm.event_cap_contracts("KXOPENSOURCESHARE-26OCT05"),
                         imm.MAX_EVENT_CONTRACTS * imm.applied_mention_mult("KXOPENSOURCESHARE"))
        self.assertIn("SHARE_EVENT_CAP", imm._CONFIG_CODE_KNOBS)
        # the cap binds the quote loop: an event net long past it bids no
        # strike and still offers (a small cap here keeps the per-market
        # cap and the skew knees out of it)
        self._write(mu=2.75, sigma=0.2)
        for cap, bids in ((imm.SHARE_EVENT_CAP, True), (20.0, False)):
            with mock.patch.object(imm, "SHARE_EVENT_CAP", cap):
                bot = self._bot()
                bot.client.positions[self.T] = 25.0
                bot.pnl.pos[self.T] = 25.0                     # ours, not manual
                bot.run_cycle()
                sides = {b for b, _ in self._quotes(bot)}
                self.assertEqual("bid" in sides, bids, cap)
                self.assertIn("ask", sides, cap)


class TestGasBuddyFairGate(unittest.TestCase):
    """gasbuddy_fair.json -> load_gb_fair/gb_gate_reason -> the stand-aside on
    the AAA state dailies (Jack 2026-09-27: "i received permission to use
    fuelinsights.gasbuddy.com. use that"). Fails CLOSED like the OpenRouter
    gate: the family is unblocked only because the feed exists. Fixture
    event KXAAAGASDZZ-68DEC04 (a two-letter state shape, far from any
    cutoff), strike 4.0000."""

    T = "KXAAAGASDZZ-68DEC04-4.0000"
    EV = "KXAAAGASDZZ-68DEC04"
    _bump = 1

    def setUp(self):
        _clean_persist()
        # since the 2026-10-01 gas trial the state dailies are BLOCKED by
        # default; this class exercises the gated state quoting that
        # IMM_GB_STATE_QUOTE=1 brings back, so it runs under that config
        # The gas trial (2026-10-01) gave the national daily -- and so, by
        # family cloning, this state fixture -- a 00:00-13:00 ET no-quote
        # window (03:05-04:00, the print blackout, before it). This class
        # tests the GasBuddy gate, not the blackouts (their own tests pin
        # those), so the parent's blackout is lifted here; otherwise two of
        # its tests fail by wall clock 13 hours a day (found 10/01 09:05 ET,
        # identically on main 6e5f58c). patch.dict also drops the clone the
        # cycle adds.
        import dataclasses
        for p in (mock.patch.object(imm, "GB_STATE_QUOTE", True),
                  mock.patch.object(imm, "SERIES_BLOCK_PATTERNS", tuple(
                      imm.re.compile(x) for x in
                      imm._series_block_default(True).split(",") if x)),
                  mock.patch.dict(imm.SERIES_OVERRIDES, {"KXAAAGASD": dataclasses.replace(
                      imm.SERIES_OVERRIDES["KXAAAGASD"], blackout_et=None)})):
            p.start()
            self.addCleanup(p.stop)
        imm._gb_fair_state.update(mtime=0.0, entries={})
        self._saved_hour_mults = imm.SERIES_HOUR_MULTS
        imm.SERIES_HOUR_MULTS = []
        try:
            os.remove(imm.GB_FAIR_FILE)
        except FileNotFoundError:
            pass

    def tearDown(self):
        imm.SERIES_HOUR_MULTS = self._saved_hour_mults
        # the cycle clones the national KXAAAGASD guards onto the fixture
        # series; do not leak that into the family-override tests
        imm.SERIES_OVERRIDES.pop("KXAAAGASDZZ", None)

    def _write(self, mu=4.0, sigma=0.005, age_secs=0.0, ev=None):
        fetched = (datetime.now(timezone.utc) - timedelta(seconds=age_secs)).isoformat()
        with open(imm.GB_FAIR_FILE, "w", encoding="utf-8") as f:
            json.dump({"entries": {ev or self.EV: {
                "mu": mu, "sigma": sigma, "fetched_at": fetched}}}, f)
        os.utime(imm.GB_FAIR_FILE, (time.time(), time.time() + self._bump))
        TestGasBuddyFairGate._bump += 1
        return imm.load_gb_fair()

    def _bot(self):
        client = FakeClient()
        now = datetime.now(timezone.utc)
        far = (now + timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
        client.programs.append(
            # 10x the OpenRouter fixture: the $1-per-period payout floor
            # still applies to the family
            {"market_ticker": self.T, "incentive_type": "liquidity",
             "period_reward": 70000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": client.programs[0]["start_date"],
             "end_date": client.programs[0]["end_date"]})
        client.markets[self.T] = {
            "ticker": self.T, "event_ticker": self.EV,
            "status": "active", "close_time": far,
            "yes_bid_dollars": "0.4900", "yes_ask_dollars": "0.5100",
            "volume_fp": "500.00"}
        lv = [["0.45", "400"], ["0.46", "400"], ["0.47", "400"],
              ["0.48", "400"], ["0.49", "300"]]
        client.books[self.T] = {"orderbook_fp": {"yes_dollars": lv,
                                                 "no_dollars": lv}}
        return IncentiveMarketMaker(client=client, live=False)

    def _quotes(self, bot):
        return sorted((o["book_side"], o["yes_price"])
                      for o in bot.state.sim_orders.values()
                      if o["ticker"] == self.T)

    def test_family_shape_and_kill_switch_patterns(self):
        self.assertTrue(imm.gb_fair_series("KXAAAGASDCA"))
        self.assertFalse(imm.gb_fair_series("KXAAAGASDNYC"))     # not a state shape
        self.assertFalse(imm.gb_fair_series("KXAAAGASW"))
        # the diesel daily (2026-09-27: "ok do that for diesel daily") and the
        # national gas daily (2026-09-27: "yes gate KXAAAGASD national on
        # gasbuddy") join behind their switches -- both default OFF since the
        # 2026-10-01 gas trial (plain quoting, 13:00-24:00 ET); the weeklies,
        # monthlies and Alaska diesel never join
        self.assertFalse(imm.GB_DIESEL_ENABLE)
        self.assertFalse(imm.GB_NATGAS_ENABLE)
        self.assertFalse(imm.gb_fair_series("KXDIESELD"))
        self.assertFalse(imm.gb_fair_series("KXAAAGASD"))
        with mock.patch.object(imm, "GB_DIESEL_ENABLE", True):
            self.assertTrue(imm.gb_fair_series("KXDIESELD"))
            self.assertFalse(imm.gb_fair_series("KXDIESELW"))
            self.assertFalse(imm.gb_fair_series("KXDIESELMONAK"))
            self.assertTrue(imm.gb_fair_series("KXAAAGASDCA"))
        with mock.patch.object(imm, "GB_NATGAS_ENABLE", True):
            self.assertTrue(imm.gb_fair_series("KXAAAGASD"))
            self.assertFalse(imm.gb_fair_series("KXAAAGASM"))
            self.assertTrue(imm.gb_fair_series("KXAAAGASDCA"))
        # the DEFAULT since the gas trial: GasBuddy refresher on, the state
        # dailies blocked by the 9/14 pattern
        self.assertTrue(imm.GB_FAIR_ENABLE)
        default = [imm.re.compile(p) for p in imm._series_block_default(False).split(",")]
        self.assertTrue(any(p.fullmatch("KXAAAGASDCA") for p in default))
        # the gated config this class runs under (IMM_GB_STATE_QUOTE=1):
        # state dailies unblocked, anything longer blocked
        self.assertFalse(imm.series_pattern_blocked("KXAAAGASDCA"))
        self.assertTrue(imm.series_pattern_blocked("KXAAAGASDNYC"))
        self.assertFalse(imm.series_pattern_blocked("KXAAAGASD"))
        self.assertTrue(imm.series_pattern_blocked("KXTEMPMIAH"))  # untouched
        # IMM_GB_FAIR_ENABLE=0 puts the 9/14 pattern back exactly
        off = [imm.re.compile(p) for p in imm._series_block_default(False).split(",")]
        self.assertTrue(any(p.fullmatch("KXAAAGASDCA") for p in off))
        self.assertFalse(any(p.fullmatch("KXAAAGASD") for p in off))
        on = imm._series_block_default(True).split(",")
        self.assertEqual(on[1:], imm._series_block_default(False).split(",")[1:])
        self.assertTrue(all("{" not in p for p in on))            # comma-split safe

    def test_reason_fail_closed_stale_vague_and_band(self):
        now_ts = time.time()
        self.assertEqual(imm.gb_gate_reason(self.T, now_ts, 49, 51)[1]["reason"], "no_read")
        self.assertEqual(self._write(mu=4.0), 1)
        self.assertEqual(imm.gb_gate_reason(self.T, time.time(), 49, 51), ("", {}))
        self.assertEqual(imm.gb_gate_reason(self.EV, time.time(), 49, 51)[1]["reason"],
                         "no_read")                              # no strike segment
        self.assertEqual(imm.gb_gate_reason(
            self.T, time.time() + imm.GB_FAIR_TTL_MIN * 60 + 5, 49, 51)[1]["reason"], "stale")
        self._write(mu=4.0, sigma=0.025)                          # 2.5c > 2c cap
        self.assertEqual(imm.gb_gate_reason(self.T, time.time(), 49, 51)[1]["reason"], "vague")
        # AAA ~3.998: P(> 4.0000) 34% at sigma, 21% at half -> bid 49 fights it
        self._write(mu=3.998, sigma=0.005)
        why, inp = imm.gb_gate_reason(self.T, time.time(), 49, 51)
        self.assertEqual((inp["reason"], inp["bid_bad"], inp["ask_bad"]), ("band", True, False))
        self.assertAlmostEqual(inp["hi"], 34.46, places=1)
        # AAA ~4.002: the mirror -> the ask fights it
        self._write(mu=4.002, sigma=0.005)
        inp = imm.gb_gate_reason(self.T, time.time(), 49, 51)[1]
        self.assertEqual((inp["bid_bad"], inp["ask_bad"]), (False, True))
        # tolerance 0 is strict: a touch exactly on the band still quotes
        self._write(mu=4.0, sigma=0.005)
        self.assertEqual(imm.gb_gate_reason(self.T, time.time(), 50, 50), ("", {}))
        self.assertEqual(imm.gb_gate_reason(self.T, time.time(), 51, 52)[1]["bid_bad"], True)

    def test_state_clone_drops_only_the_rate_floor(self):
        fake = "KXAAAGASDQX"
        self.assertNotIn(fake, imm.SERIES_OVERRIDES)
        try:
            imm.ensure_family_override(fake)
            self.assertEqual(imm.series_min_est_rate(fake), 0.0)
            self.assertEqual(imm.series_min_est_rate("KXAAAGASD"), 2.0)   # national keeps it
            self.assertTrue(imm.series_safe_join(fake))
            self.assertEqual(imm.SERIES_OVERRIDES[fake].blackout_et,
                             imm.SERIES_OVERRIDES["KXAAAGASD"].blackout_et)
            with mock.patch.object(imm, "GB_STATE_MIN_RATE", 2.0):
                imm.SERIES_OVERRIDES.pop(fake, None)
                imm.ensure_family_override(fake)
                self.assertEqual(imm.series_min_est_rate(fake), 2.0)
            with mock.patch.object(imm, "GB_FAIR_ENABLE", False):
                imm.SERIES_OVERRIDES.pop(fake, None)
                imm.ensure_family_override(fake)                   # plain clone
                self.assertEqual(imm.series_min_est_rate(fake), 2.0)
        finally:
            imm.SERIES_OVERRIDES.pop(fake, None)

    def test_national_gas_strike_format_and_guards(self):
        # KXAAAGASD strikes are plain: KXAAAGASD-26SEP28-4.5050
        self._write(mu=4.0, sigma=0.005, ev="KXAAAGASD-68DEC04")
        self.assertEqual(imm.gb_gate_reason("KXAAAGASD-68DEC04-4.0000", time.time(), 49, 51),
                         ("", {}))
        inp = imm.gb_gate_reason("KXAAAGASD-68DEC04-4.0020", time.time(), 49, 51)[1]
        self.assertEqual((inp["reason"], inp["bid_bad"]), ("band", True))
        self.assertEqual(imm.gb_gate_reason("KXAAAGASD-68DEC05-4.0000", time.time(), 49, 51)[1]["reason"],
                         "no_read")
        # the parent keeps its own guard set: no state-style rate-floor swap
        before = imm.SERIES_OVERRIDES["KXAAAGASD"]
        imm.ensure_family_override("KXAAAGASD")
        self.assertIs(imm.SERIES_OVERRIDES["KXAAAGASD"], before)

    def test_diesel_strike_format(self):
        # KXDIESELD strikes carry a T: KXDIESELD-26SEP28-T6.470
        self._write(mu=4.0, sigma=0.005, ev="KXDIESELD-68DEC04")
        self.assertEqual(imm.gb_gate_reason("KXDIESELD-68DEC04-T4.000", time.time(), 49, 51),
                         ("", {}))
        inp = imm.gb_gate_reason("KXDIESELD-68DEC04-T4.002", time.time(), 49, 51)[1]
        self.assertEqual((inp["reason"], inp["bid_bad"]), ("band", True))
        self.assertEqual(imm.gb_gate_reason("KXDIESELD-68DEC05-T4.000", time.time(), 49, 51)[1]["reason"],
                         "no_read")

    def test_loader_drops_bad_rows(self):
        with open(imm.GB_FAIR_FILE, "w", encoding="utf-8") as f:
            json.dump({"entries": {
                "A-68DEC04": {"mu": 4.0, "sigma": 0.0,
                              "fetched_at": datetime.now(timezone.utc).isoformat()},
                "B-68DEC04": {"mu": "x", "sigma": 0.01, "fetched_at": "now"},
                "C-68DEC04": {"mu": 4.0, "sigma": 0.01},
                self.EV: {"mu": 4.0, "sigma": 0.004,
                          "fetched_at": datetime.now(timezone.utc).isoformat()}}}, f)
        os.utime(imm.GB_FAIR_FILE, (time.time(), time.time() + 7777))
        self.assertEqual(imm.load_gb_fair(), 1)
        self.assertEqual(imm.load_gb_fair(), -1)                  # unchanged mtime
        self.assertEqual(sorted(imm._gb_fair_state["entries"]), [self.EV])

    def test_selection_needs_a_read_and_the_gate_stands_aside_on_disagreement(self):
        bot = self._bot()
        bot.run_cycle()                                           # no file
        self.assertEqual(self._quotes(bot), [])
        self.assertNotIn(self.T, bot.state.selected)              # takes no slot
        self._write(mu=4.0)
        bot.state.universe_at = 0.0                              # force a refresh
        bot.run_cycle()
        self.assertIn(self.T, bot.state.selected)
        self.assertNotIn(self.T, bot._gb_fair_stood)
        q = self._quotes(bot)
        self.assertTrue(any(side == "bid" for side, _ in q), q)
        self.assertTrue(any(side == "ask" for side, _ in q), q)
        self._write(mu=3.998)                                     # bid 49 > 34
        bot.run_cycle()                                           # no refresh: the quote loop
        self.assertEqual(self._quotes(bot), [])
        self.assertIn(self.T, bot._gb_fair_stood)
        self.assertIn(self.T, bot.state.selected)                 # sticky between refreshes
        bot.state.universe_at = 0.0                               # still fighting at a refresh
        bot.run_cycle()
        self.assertNotIn(self.T, bot.state.selected)              # the slot is freed
        self.assertEqual(self._quotes(bot), [])

    def test_a_member_without_a_read_frees_its_slot(self):
        self._write(mu=4.0)
        bot = self._bot()
        bot.run_cycle()
        self.assertIn(self.T, bot.state.selected)
        self._write(mu=4.0, ev="KXAAAGASDQQ-68DEC04")             # a Monday / an outage
        bot.state.universe_at = 0.0
        bot.run_cycle()
        self.assertNotIn(self.T, bot.state.selected)
        self.assertEqual(self._quotes(bot), [])

    def test_a_fresh_strike_the_gate_rejects_takes_no_slot(self):
        self._write(mu=3.998)                                     # listed 49x51 vs fair 34
        bot = self._bot()
        bot.run_cycle()
        self.assertNotIn(self.T, bot.state.selected)
        self._write(mu=4.0, sigma=0.03)                           # too early to call
        bot.state.universe_at = 0.0
        bot.run_cycle()
        self.assertNotIn(self.T, bot.state.selected)

    def test_stale_read_stands_aside_and_gate_off_quotes_plainly(self):
        self._write(mu=4.0, age_secs=imm.GB_FAIR_TTL_MIN * 60 + 60)
        bot = self._bot()
        bot.run_cycle()
        self.assertEqual(self._quotes(bot), [])
        with mock.patch.object(imm, "GB_FAIR_ENABLE", False):
            bot = self._bot()
            bot.run_cycle()
            self.assertNotEqual(self._quotes(bot), [])


class TestPayoutFloorAccounting(unittest.TestCase):
    """The exchange pays NOTHING for a market whose program-period payout
    lands under $1.00 (2026-08-04 statement: 2,720 LIQUIDITY credits, minimum
    exactly $1.00, none below). The raw integral therefore books revenue on markets
    that pay zero; the paid-basis counters apply that floor."""

    def _bot(self):
        _clean_persist()
        return IncentiveMarketMaker(client=FakeClient(), live=False)

    def _accrue(self, bot, rates, dt_days):
        """Drive the accrual arithmetic directly (run_cycle's inner block)."""
        paid_delta = 0.0
        for t, rate in rates.items():
            prev = bot.state.accrued_est.get(t, 0.0)
            new = prev + rate * dt_days
            bot.state.accrued_est[t] = new
            if t in bot.state.paid_crossed:
                paid_delta += new - prev
            elif new >= imm.PAYOUT_FLOOR_DOLLARS:
                bot.state.paid_crossed.add(t)
                paid_delta += new
        bot.state.reward_paid_today += paid_delta
        bot.state.reward_paid_lifetime += paid_delta

    def test_market_under_the_floor_never_counts(self):
        bot = self._bot()
        try:
            self._accrue(bot, {"A": 0.90}, 1.0)     # $0.90 -> pays zero
            self.assertAlmostEqual(bot.state.accrued_est["A"], 0.90)
            self.assertEqual(bot.state.reward_paid_today, 0.0)
            self.assertEqual(bot.state.reward_paid_lifetime, 0.0)
        finally:
            _clean_persist()

    def test_whole_backlog_lands_on_the_crossing_cycle(self):
        bot = self._bot()
        try:
            self._accrue(bot, {"A": 0.60}, 1.0)     # 0.60, still nothing
            self.assertEqual(bot.state.reward_paid_today, 0.0)
            self._accrue(bot, {"A": 0.60}, 1.0)     # 1.20 -> crosses
            self.assertAlmostEqual(bot.state.reward_paid_today, 1.20)
            self._accrue(bot, {"A": 0.50}, 1.0)     # already paid: increment
            self.assertAlmostEqual(bot.state.reward_paid_today, 1.70)
            self.assertAlmostEqual(bot.state.reward_paid_lifetime, 1.70)
            self.assertAlmostEqual(bot.state.accrued_est["A"], 1.70)
        finally:
            _clean_persist()

    def test_paid_basis_is_never_above_the_raw_integral(self):
        bot = self._bot()
        try:
            rates = {"A": 3.0, "B": 0.4, "C": 1.0, "D": 0.05}
            self._accrue(bot, rates, 1.0)
            raw = sum(bot.state.accrued_est.values())
            self.assertLessEqual(bot.state.reward_paid_lifetime, raw + 1e-9)
            # only A and C cleared $1
            self.assertAlmostEqual(bot.state.reward_paid_lifetime, 4.0)
        finally:
            _clean_persist()

    def test_crossed_set_persists_so_restarts_do_not_recredit(self):
        """paid_crossed MUST round-trip with accrued_est: without it the first
        cycle after a restart re-credits every carried market's whole
        backlog — one full book of phantom reward per restart, and this bot
        restarts many times a day."""
        _clean_persist()
        try:
            bot = IncentiveMarketMaker(client=FakeClient(), live=False)
            bot.state.known_tickers = {"A"}
            self._accrue(bot, {"A": 2.0}, 1.0)
            self.assertAlmostEqual(bot.state.reward_paid_lifetime, 2.0)
            bot._save_persist()

            bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
            self.assertIn("A", bot2.state.paid_crossed)
            self.assertAlmostEqual(bot2.state.accrued_est["A"], 2.0)
            self.assertAlmostEqual(bot2.state.reward_paid_lifetime, 2.0)
            self._accrue(bot2, {"A": 0.25}, 1.0)     # increment only
            self.assertAlmostEqual(bot2.state.reward_paid_lifetime, 2.25)
        finally:
            _clean_persist()

    def test_crossed_set_pruned_with_accrued_est(self):
        """A ticker dropped from known_tickers leaves BOTH maps, so a re-listed
        ticker cannot resume in the already-paid state."""
        _clean_persist()
        try:
            bot = IncentiveMarketMaker(client=FakeClient(), live=False)
            bot.state.known_tickers = {"A"}
            self._accrue(bot, {"A": 2.0, "GONE": 2.0}, 1.0)
            bot._save_persist()
            bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
            self.assertIn("A", bot2.state.paid_crossed)
            self.assertNotIn("GONE", bot2.state.paid_crossed)
            self.assertNotIn("GONE", bot2.state.accrued_est)
        finally:
            _clean_persist()

    def test_migration_adopts_carried_markets_without_back_crediting(self):
        """First load after this shipped: the old state file has accrued_est
        and no paid_crossed. Those markets accrued over days that the raw
        counters already booked, so crossing them now would dump the whole
        backlog into TODAY."""
        _clean_persist()
        try:
            bot = IncentiveMarketMaker(client=FakeClient(), live=False)
            bot.state.known_tickers = {"BIG", "SMALL"}
            bot.state.accrued_est = {"BIG": 40.0, "SMALL": 0.4}
            bot._save_persist()
            # simulate the pre-change file: drop the new key
            with open(bot.PERSIST_PATH, encoding="utf-8") as f:
                data = json.load(f)
            data.pop("paid_crossed", None)
            with open(bot.PERSIST_PATH, "w", encoding="utf-8") as f:
                json.dump(data, f)

            bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
            self.assertEqual(bot2.state.paid_crossed, {"BIG"})
            self.assertEqual(bot2.state.reward_paid_today, 0.0)
            self.assertEqual(bot2.state.reward_paid_lifetime, 0.0)
            self._accrue(bot2, {"BIG": 2.0}, 1.0)      # forward accrual only
            self.assertAlmostEqual(bot2.state.reward_paid_lifetime, 2.0)
        finally:
            _clean_persist()

    def test_daily_roll_records_both_bases(self):
        _clean_persist()
        try:
            bot = IncentiveMarketMaker(client=FakeClient(), live=False)
            bot.state.reward_est_today = 12.34
            bot.state.reward_paid_today = 9.99
            bot.state.last_markets_line = "x"
            bot.build_daily_summary()
            key = (datetime.now(timezone.utc).astimezone(imm.CT).date()
                   - timedelta(days=1)).isoformat()
            self.assertAlmostEqual(bot.state.reward_history[key], 12.34)
            self.assertAlmostEqual(bot.state.reward_paid_history[key], 9.99)
            self.assertEqual(bot.state.reward_est_today, 0.0)
            self.assertEqual(bot.state.reward_paid_today, 0.0)
        finally:
            _clean_persist()


class TestRateBarScopedToNewEvents(unittest.TestCase):
    """Jack 2026-08-05: "i want sticky quoting when a market is already
    quoted, unless it is hopeless. i do not want to open up new events that
    otherwise weren't being quoted."

    The rate bar is kept, but only gates the FIRST strike of an event the bot
    is not already working. A sibling on an event we already hold is depth on
    an exposure already taken; the first strike of an untouched event is a new
    exposure. Dropping the bar outright did both — measured +122 markets
    across +9 previously-excluded events, which is not what was asked for."""

    AFFECTED = ("KXUST7AM", "KXUST2AM", "KXUST10AM", "KXUST5AM", "KXUST30AM",
                "KXFSLR", "KXHOOD")

    def test_the_bar_is_still_in_force(self):
        for s in self.AFFECTED:
            self.assertEqual(imm.series_min_est_rate(s), 2.0, s)

    def test_safe_join_and_the_payout_floor_are_intact(self):
        for s in self.AFFECTED:
            self.assertTrue(imm.series_safe_join(s), s)
            self.assertGreaterEqual(imm.series_min_est_total(s),
                                    imm.PAYOUT_FLOOR_DOLLARS, s)

    def test_both_rate_bar_defaults_agree(self):
        """The re-entry loop and the rates loop each carry their own default.
        They diverged once (2026-08-05) and the Treasuries silently kept the
        old bar, so assert they cannot drift apart again."""
        self.assertEqual(imm.series_min_est_rate("KXAAAGASD"),
                         imm.series_min_est_rate("KXUST2AD"))

    # --- the gate itself, exercised as the selection loop evaluates it ------
    @staticmethod
    def _blocked(ticker, event, prev_selected, prev_events, est_per_day,
                 projected):
        """Mirror of the rate_floor branch in refresh_universe."""
        return (ticker not in prev_selected
                and event not in prev_events
                and event not in imm.FORCE_EVENTS
                and est_per_day < 2.0
                and projected < imm.RATE_FLOOR_TOTAL_ALT)

    def test_first_strike_of_an_untouched_event_is_blocked(self):
        self.assertTrue(self._blocked(
            "KXFSLR-26OCTX-1", "KXFSLR-26OCTX", set(), set(), 0.83, 3.4))

    def test_sibling_of_an_already_quoted_event_is_admitted(self):
        self.assertFalse(self._blocked(
            "KXFSLR-26OCTX-2", "KXFSLR-26OCTX",
            {"KXFSLR-26OCTX-1"}, {"KXFSLR-26OCTX"}, 0.83, 3.4))

    def test_a_sticky_event_does_not_unlock_a_DIFFERENT_event(self):
        """The leak that made the blanket change wrong."""
        self.assertTrue(self._blocked(
            "KXHOOD-26NOVY-1", "KXHOOD-26NOVY",
            {"KXFSLR-26OCTX-1"}, {"KXFSLR-26OCTX"}, 0.96, 3.9))

    def test_a_market_clearing_the_bar_still_opens_its_event(self):
        self.assertFalse(self._blocked(
            "KXNEW-26OCTZ-1", "KXNEW-26OCTZ", set(), set(), 9.0, 40.0))

    def test_horizon_escape_still_opens_an_event_on_total_value(self):
        self.assertFalse(self._blocked(
            "KXNEW-26OCTZ-1", "KXNEW-26OCTZ", set(), set(), 0.5,
            imm.RATE_FLOOR_TOTAL_ALT))

    def test_with_no_sticky_the_clause_is_inert(self):
        """prev_events empty => the added condition is always True => the gate
        is byte-for-byte the old behaviour on a cold start."""
        for est, proj in ((0.83, 3.4), (0.1, 0.2), (1.99, 4.99)):
            self.assertTrue(self._blocked("KXA-26X-1", "KXA-26X", set(), set(),
                                          est, proj))


class TestRateFloorEscapeHorizonCap(unittest.TestCase):
    """Jack 2026-08-07: cap the horizon escape at RATE_FLOOR_ESCAPE_DAYS.

    The escape admits on projected TOTAL >= $5, but a total dilutes with
    window length: KXCRYPTOSTRUCTURE entered at ~$0.36/day because its
    13.9-day program window stretched pennies to $5.04 — an effective bar
    5.5x looser than the $2/day rate bar. The cap makes the escape
    bar-neutral: <=2.5-day windows keep the full anti-flapping escape,
    longer windows face the bar undiluted."""

    def test_cryptostructure_shape_is_now_blocked(self):
        # the exact 2026-08-07 06:22Z admission: $0.36/day x 13.9d window
        projected = imm.rate_floor_projected(
            accrued=0.0, est_total=0.36 * 13.9, peak=0.0, quotable_days=13.9)
        self.assertAlmostEqual(projected, 0.36 * 2.5, places=6)
        self.assertLess(projected, imm.RATE_FLOOR_TOTAL_ALT)

    def test_short_window_keeps_the_full_escape(self):
        # a 1-day program at $5/day total: the anti-flapping case must
        # still clear (cap only shrinks windows LONGER than the escape days)
        projected = imm.rate_floor_projected(
            accrued=0.0, est_total=5.0, peak=0.0, quotable_days=1.0)
        self.assertAlmostEqual(projected, 5.0, places=6)
        self.assertGreaterEqual(projected, imm.RATE_FLOOR_TOTAL_ALT)

    def test_boundary_window_is_uncapped(self):
        projected = imm.rate_floor_projected(
            accrued=0.0, est_total=4.0, peak=0.0,
            quotable_days=imm.RATE_FLOOR_ESCAPE_DAYS)
        self.assertAlmostEqual(projected, 4.0, places=6)

    def test_banked_accrual_counts_in_full(self):
        # accrued credit is money, not a projection — never scaled
        projected = imm.rate_floor_projected(
            accrued=5.0, est_total=0.0, peak=0.0, quotable_days=14.0)
        self.assertAlmostEqual(projected, 5.0, places=6)

    def test_peak_is_scaled_like_the_total(self):
        # the 1h-peak memory must not smuggle the uncapped horizon back in
        projected = imm.rate_floor_projected(
            accrued=0.0, est_total=0.0, peak=5.04, quotable_days=13.9)
        self.assertAlmostEqual(projected, 5.04 * 2.5 / 13.9, places=6)
        self.assertLess(projected, imm.RATE_FLOOR_TOTAL_ALT)

    def test_huge_escape_days_restores_old_behaviour(self):
        # IMM_RATE_FLOOR_ESCAPE_DAYS=big = the pre-cap gate, byte for byte
        old = imm.RATE_FLOOR_ESCAPE_DAYS
        imm.RATE_FLOOR_ESCAPE_DAYS = 1e9
        try:
            projected = imm.rate_floor_projected(
                accrued=0.3, est_total=5.04, peak=6.0, quotable_days=13.9)
            self.assertAlmostEqual(projected, 0.3 + 6.0, places=6)
        finally:
            imm.RATE_FLOOR_ESCAPE_DAYS = old

    def test_tiny_window_denominator_is_safe(self):
        # sub-hour windows must not divide by zero or explode the cap
        projected = imm.rate_floor_projected(
            accrued=0.0, est_total=1.0, peak=0.0, quotable_days=0.0)
        self.assertAlmostEqual(projected, 1.0, places=6)

    def test_selection_branch_calls_the_real_function(self):
        """Wiring: the refresh_universe rate-floor branch must consult
        rate_floor_projected — a mirror that drifts is worthless."""
        bot_cls = TestStickySelection
        helper = bot_cls.__dict__.get("_quoting_bot")
        self.assertIsNotNone(helper, "fixture moved; rewire this test")
        bot = helper(bot_cls())
        t = bot_cls.T
        old_ov = imm.SERIES_OVERRIDES.get("KXGOOD")
        imm.SERIES_OVERRIDES["KXGOOD"] = imm.SeriesOverride(min_est_per_day=1e9)
        try:
            for forced_value, expect_in in ((-1.0, False), (1e9, True)):
                with mock.patch.object(imm, "rate_floor_projected",
                                       return_value=forced_value) as spy:
                    bot.state.selected.pop(t, None)
                    bot.state.sticky_prev.discard(t)
                    bot._est_peak.clear()
                    bot.state.universe_at = 0.0
                    bot.run_cycle()
                    self.assertTrue(spy.called,
                                    "branch no longer calls rate_floor_projected")
                self.assertEqual(t in bot.state.selected, expect_in,
                                 f"forced projected={forced_value}")
        finally:
            if old_ov is None:
                imm.SERIES_OVERRIDES.pop("KXGOOD", None)
            else:
                imm.SERIES_OVERRIDES["KXGOOD"] = old_ov
            _clean_persist()


class TestTwoSidedDepthGate(unittest.TestCase):
    """Jack 2026-08-05: "dont quote, and remove existing quotes, if either
    side has <1000 contracts. only pad on hourly TEMP markets."

    A snapshot is EXCLUDED unless both sides reach the program target, so a
    book that cannot get there pays nothing however well it is quoted. Hourly
    temp is exempt because its pads ARE the mechanism for reaching target."""

    T = "KXGOOD-99DEC31-A"

    def setUp(self):
        # Padding went back to GLOBAL on 2026-08-05 ("turn pads back on for
        # everything"), which makes this gate inert almost everywhere — a thin
        # side gets padded to target instead of standing the market down. The
        # gate is still live code and re-arms the moment padding is narrowed,
        # so exercise it with padding off.
        self._pad_default = imm.PAD_TO_TARGET_GLOBAL
        imm.PAD_TO_TARGET_GLOBAL = False
        self.addCleanup(setattr, imm, "PAD_TO_TARGET_GLOBAL", self._pad_default)

    def _bot(self, yes, no):
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        bot.client.books[self.T] = {"orderbook_fp": {
            "yes_dollars": [["0.49", str(yes)]],
            "no_dollars": [["0.49", str(no)]]}}
        return bot

    def test_padding_is_global_again(self):
        """2026-08-05: temp-only -> global. The temp-only spell cost the
        near-miss tail (DUOL/MELI strikes at 584-981 vs a 1000 target stood
        down where a 20-420 contract pad would have qualified them)."""
        self.assertTrue(self._pad_default, "global padding expected by default")
        imm.PAD_TO_TARGET_GLOBAL = self._pad_default
        for s in ("KXTEMPAUSH", "KXGOOD", "KXUST7AM", "KXFSLR", "KXRAIN",
                  "KXDIESELD", "KXLOVEISLMENTION", "KXEARNINGSMENTIONUBER"):
            self.assertTrue(imm.series_pad_to_target(s), s)

    def test_gate_is_inert_while_padding_is_global(self):
        """The safety property of the revert: with pads on, a thin side is
        padded rather than stood down, so nothing is dropped by the gate."""
        imm.PAD_TO_TARGET_GLOBAL = True
        bot = self._bot(300, 1200)
        try:
            bot.run_cycle()
            self.assertIn(self.T, bot.state.selected)
        finally:
            _clean_persist()

    def test_both_sides_deep_quotes_normally(self):
        bot = self._bot(1200, 1200)
        try:
            bot.run_cycle()
            self.assertIn(self.T, bot.state.selected)
            self.assertTrue(bot.state.sim_orders)
        finally:
            _clean_persist()

    def test_one_thin_side_stands_the_market_down(self):
        for yes, no in ((300, 1200), (1200, 300)):
            bot = self._bot(yes, no)
            try:
                bot.run_cycle()
                self.assertNotIn(self.T, bot.state.selected,
                                 f"yes {yes} / no {no}")
                self.assertFalse([o for o in bot.state.sim_orders.values()
                                  if o["ticker"] == self.T])
            finally:
                _clean_persist()

    def test_exactly_at_target_still_quotes(self):
        bot = self._bot(1000, 1000)
        try:
            bot.run_cycle()
            self.assertIn(self.T, bot.state.selected)
        finally:
            _clean_persist()

    def test_existing_quotes_are_REMOVED_when_a_side_goes_thin(self):
        """'remove existing quotes' — a market already quoting must be
        cancelled, not merely left alone."""
        bot = self._bot(1200, 1200)
        try:
            bot.run_cycle()
            self.assertTrue([o for o in bot.state.sim_orders.values()
                             if o["ticker"] == self.T])
            bot.client.books[self.T] = {"orderbook_fp": {
                "yes_dollars": [["0.49", "200"]],
                "no_dollars": [["0.49", "1200"]]}}
            bot.state.universe_at = time.time()      # keep it a member
            bot.run_cycle()
            self.assertFalse([o for o in bot.state.sim_orders.values()
                              if o["ticker"] == self.T],
                             "thin side must cancel the resting quotes")
        finally:
            _clean_persist()

    def test_temp_is_exempt_and_pads_instead(self):
        """A thin hourly-temp book keeps quoting — the pad lifts it to
        target rather than standing it down."""
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        t = self.T
        try:
            bot.client.books[t] = {"orderbook_fp": {
                "yes_dollars": [["0.49", "200"]],
                "no_dollars": [["0.49", "200"]]}}
            _pad = imm.PAD_TO_TARGET_GLOBAL
            imm.PAD_TO_TARGET_GLOBAL = True          # stand in for a temp series
            try:
                bot.run_cycle()
                self.assertIn(t, bot.state.selected)
                pads = [o for o in bot.state.sim_orders.values()
                        if o["ticker"] == t and o["yes_price"] in
                        (imm.PAD_BID_CENTS, imm.PAD_ASK_CENTS)]
                self.assertTrue(pads, "expected pad orders on the thin sides")
            finally:
                imm.PAD_TO_TARGET_GLOBAL = _pad
        finally:
            _clean_persist()

    def test_estimator_agrees_with_the_quote_loop(self):
        """The gate lives in BOTH places on purpose: if selection still ranked
        a market the loop refuses to quote, it would hold budget and an event
        slot while resting nothing."""
        bot = self._bot(300, 1200)
        try:
            bot.run_cycle()
            self.assertNotIn(self.T, bot.state.selected)
        finally:
            _clean_persist()


class TestLiveEventDepthGate(unittest.TestCase):
    """Jack 2026-08-31: "Remove padding on TRUMPMENTION and MAMDANIMENTION
    markets. If <1k on either side of a market, stop quoting the whole
    event." These events' start times are not reliably known, so a thin
    EXTERNAL book on any quotable strike is read as the event going LIVE —
    and the WHOLE event stands down, not just the thin market (adverse
    selection protection, not reward math)."""

    EV = "KXGOOD-99DEC31"
    A = "KXGOOD-99DEC31-A"
    B = "KXGOOD-99DEC31-B"

    def setUp(self):
        self._prefixes = imm.EVENT_DEPTH_GATE_PREFIXES
        imm.EVENT_DEPTH_GATE_PREFIXES = ("KXGOOD",)
        self.addCleanup(setattr, imm, "EVENT_DEPTH_GATE_PREFIXES",
                        self._prefixes)
        # Date arm (Jack 2026-09-04, commit 37f16a7): known-FUTURE ticker
        # dates suppress every live trigger — which is exactly this class's
        # 99DEC31 fixtures, so the gate-logic tests here all went red when
        # the arm shipped. Arm unconditionally so they keep testing the
        # gate itself; the arming rule has its own test below.
        self._prearm = imm.EVENT_LIVE_GATE_PREARM_SECS
        imm.EVENT_LIVE_GATE_PREARM_SECS = float("inf")
        self.addCleanup(setattr, imm, "EVENT_LIVE_GATE_PREARM_SECS",
                        self._prearm)
        self.addCleanup(_clean_persist)

    def test_date_arm_suppresses_triggers_before_ticker_day(self):
        # Jack 2026-09-04: triggers fire "only when 1/ the date of the
        # event is not known or 2/ the date of the event is known and is
        # the current date" — a Sep 8 speech cannot be live on Sep 4, so
        # with the REAL pre-arm the far-future fixture must NOT halt on a
        # thin book...
        imm.EVENT_LIVE_GATE_PREARM_SECS = self._prearm
        try:
            bot = self._bot(no_b=200)          # thin: halts when armed
            bot.run_cycle()
            self.assertNotIn(self.EV, bot.state.event_depth_halt)
            self.assertTrue(self._event_orders(bot))
            # ...and the arming primitive: unknown date / past date ->
            # armed, known-future -> suppressed.
            now_ts = time.time()
            self.assertTrue(
                imm.event_live_gate_armed("KXGOOD-NODATE", now_ts))
            self.assertTrue(
                imm.event_live_gate_armed("KXGOOD-20AUG01", now_ts))
            self.assertFalse(
                imm.event_live_gate_armed("KXGOOD-99DEC31", now_ts))
        finally:
            imm.EVENT_LIVE_GATE_PREARM_SECS = float("inf")

    def _bot(self, yes_a=1200, no_a=1200, yes_b=1200, no_b=1200):
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        now = datetime.now(timezone.utc)
        start = (now - timedelta(days=1)).strftime("%Y-%m-%dT%H:%M:%SZ")
        end = (now + timedelta(days=6)).strftime("%Y-%m-%dT%H:%M:%SZ")
        far = (now + timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
        # second market in the SAME event as A
        bot.client.programs.append(
            {"market_ticker": self.B, "incentive_type": "liquidity",
             "period_reward": 7000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": start, "end_date": end})
        bot.client.markets[self.B] = {
            "ticker": self.B, "event_ticker": self.EV,
            "status": "active", "close_time": far,
            "yes_bid_dollars": "0.4900", "yes_ask_dollars": "0.5100",
            "volume_fp": "500.00"}
        self._books(bot, yes_a, no_a, yes_b, no_b)
        return bot

    def _books(self, bot, yes_a, no_a, yes_b, no_b):
        bot.client.books[self.A] = {"orderbook_fp": {
            "yes_dollars": [["0.49", str(yes_a)]],
            "no_dollars": [["0.49", str(no_a)]]}}
        bot.client.books[self.B] = {"orderbook_fp": {
            "yes_dollars": [["0.49", str(yes_b)]],
            "no_dollars": [["0.49", str(no_b)]]}}

    def _event_orders(self, bot):
        return [o for o in bot.state.sim_orders.values()
                if o["ticker"] in (self.A, self.B)]

    def test_gated_series_never_pad(self):
        """Padding is manufactured depth — it would blind the gate AND
        re-qualify exactly the book we no longer want to rest in. Prefix
        match: KXTRUMPMENTIONB rides the KXTRUMPMENTION entry."""
        imm.EVENT_DEPTH_GATE_PREFIXES = self._prefixes   # the REAL defaults
        self.assertTrue(imm.PAD_TO_TARGET_GLOBAL)
        for s in ("KXTRUMPMENTION", "KXTRUMPMENTIONB"):
            self.assertTrue(imm.series_event_depth_gated(s), s)
            self.assertFalse(imm.series_pad_to_target(s), s)
        # KXMAMDANIMENTION left the gate 2026-09-05 (fdc3a17, Jack: quote
        # through liveness) — it pads like any ungated series again
        for s in ("KXGOOD", "KXTEMPAUSH", "KXLOVEISLMENTION", "KXMAMDANIMENTION"):
            self.assertFalse(imm.series_event_depth_gated(s), s)
            self.assertTrue(imm.series_pad_to_target(s), s)

    def test_external_depths_net_out_our_own_orders(self):
        """The gate measures the EXTERNAL book: our own ladder (or a legacy
        1k pad still resting through the config change) must not hold the
        reading over the bar while everyone else pulls out."""
        yes = [[49, 1200.0]]
        no = [[49, 800.0]]
        own = [("bid", 49, 300.0), ("ask", 51, 200.0)]
        self.assertEqual(imm.external_depths(yes, no, own), (900.0, 600.0))
        self.assertEqual(imm.external_depths(yes, no, []), (1200.0, 800.0))

    def test_both_markets_deep_quotes_normally(self):
        bot = self._bot()
        bot.run_cycle()
        self.assertIn(self.A, bot.state.selected)
        self.assertIn(self.B, bot.state.selected)
        self.assertTrue(self._event_orders(bot))
        self.assertNotIn(self.EV, bot.state.event_depth_halt)

    def test_thin_sibling_stops_the_whole_event(self):
        """The event-level point: B is thin so A — itself perfectly deep —
        must not quote either. B never even gets selected (est=0), so this
        is the estimator hook doing the marking."""
        bot = self._bot(yes_b=300)
        bot.run_cycle()
        self.assertFalse(self._event_orders(bot))
        self.assertIn(self.EV, bot.state.event_depth_halt)
        self.assertTrue(any(c == "event_depth" for c, _m in bot.alerter.today))

    def test_going_thin_cancels_the_whole_quoting_event(self):
        """'stop quoting the whole event' on a LIVE transition: both markets
        already resting, then one side of B empties out."""
        bot = self._bot()
        bot.run_cycle()
        self.assertTrue(self._event_orders(bot))
        self._books(bot, 1200, 1200, 1200, 200)
        bot.state.universe_at = time.time()          # no refresh: quote loop only
        bot.run_cycle()
        self.assertFalse(self._event_orders(bot),
                         "thin side on B must cancel A's quotes too")
        self.assertIn(self.EV, bot.state.event_depth_halt)

    def test_lost_touch_mid_band_halts_the_event(self):
        """A book that WAS two-sided in band and lost a touch entirely is
        the withdrawal signal at full volume (the one-sided breaker alone
        would stand down only that market for 30min)."""
        bot = self._bot()
        bot.run_cycle()
        self.assertTrue(self._event_orders(bot))
        bot.client.books[self.B] = {"orderbook_fp": {
            "yes_dollars": [["0.49", "1200"]], "no_dollars": []}}
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertFalse(self._event_orders(bot))
        self.assertIn(self.EV, bot.state.event_depth_halt)

    def test_extreme_pinned_strike_is_not_a_signal(self):
        """A 96c pin is thin by nature and proves nothing — the event keeps
        quoting (the strike itself is screened out individually)."""
        bot = self._bot()
        bot.client.books[self.B] = {"orderbook_fp": {
            "yes_dollars": [["0.95", "30"]], "no_dollars": [["0.03", "40"]]}}
        bot.run_cycle()
        self.assertNotIn(self.EV, bot.state.event_depth_halt)
        self.assertTrue([o for o in bot.state.sim_orders.values()
                         if o["ticker"] == self.A],
                        "deep sibling must keep quoting")

    def test_resume_needs_quiet_time_and_all_markets_healthy(self):
        bot = self._bot(yes_b=300)
        bot.run_cycle()
        self.assertIn(self.EV, bot.state.event_depth_halt)
        # book recovers, but the thin reading is FRESH -> still down
        self._books(bot, 1200, 1200, 1200, 1200)
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertIn(self.EV, bot.state.event_depth_halt)
        self.assertFalse(self._event_orders(bot))
        # quiet for EVENT_DEPTH_RESUME_SECS -> resume pass clears it...
        bot.state.event_depth_halt[self.EV] = \
            time.time() - imm.EVENT_DEPTH_RESUME_SECS - 5
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertNotIn(self.EV, bot.state.event_depth_halt)
        # ...and the NEXT cycle quotes again (sticky selection kept A)
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertTrue(self._event_orders(bot))

    def test_halt_survives_a_restart(self):
        """~20 restarts/day: a restart mid-speech must come back already
        standing down, not spend a cycle rediscovering the thin strike."""
        bot = self._bot(yes_b=300)
        bot.run_cycle()
        self.assertIn(self.EV, bot.state.event_depth_halt)
        bot._save_persist()
        bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
        self.assertIn(self.EV, bot2.state.event_depth_halt)

    def test_settled_jump_out_of_band_kills_the_event_forever(self):
        """Jack 2026-08-31 #2: a deep in-band strike that jumps to 99c (the
        word got said) is the event CONFIRMED live — permanent halt, and no
        amount of book recovery or quiet time brings the event back."""
        bot = self._bot()
        bot.run_cycle()
        self.assertTrue(self._event_orders(bot))          # prev_mid seeded ~50
        bot.client.books[self.B] = {"orderbook_fp": {
            "yes_dollars": [["0.98", "150"]],
            "no_dollars": [["0.01", "300"]]}}             # 98x99, mid 98.5
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertFalse(self._event_orders(bot))
        self.assertIn(self.EV, bot.state.event_live_halt)
        self.assertTrue(any(c == "event_live" for c, _m in bot.alerter.today))
        # books fully recover AND every timestamp goes stale -> STILL down
        self._books(bot, 1200, 1200, 1200, 1200)
        bot.state.event_depth_halt[self.EV] = \
            time.time() - imm.EVENT_DEPTH_RESUME_SECS - 5
        bot.state.event_live_halt[self.EV] = \
            time.time() - imm.EVENT_DEPTH_RESUME_SECS - 5
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertFalse(self._event_orders(bot))
        self.assertIn(self.EV, bot.state.event_live_halt)
        self.assertIn(self.EV, bot.state.event_depth_halt)

    def test_gapped_book_in_band_mid_is_not_a_live_confirm(self):
        """2026-10-05 SANC: 28c -> a 7x64 gapped book (mid 35.5c). The touch
        fails the pad gate but the mid never left the band -- no settled
        strike, so no PERMANENT halt."""
        bot = self._bot()
        bot.run_cycle()
        self.assertTrue(self._event_orders(bot))          # prev_mid seeded ~50
        bot.client.books[self.B] = {"orderbook_fp": {
            "yes_dollars": [["0.07", "1500"]],
            "no_dollars": [["0.36", "1500"]]}}             # 7x64, mid 35.5
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertNotIn(self.EV, bot.state.event_live_halt)
        self.assertFalse(any(c == "event_live" for c, _m in bot.alerter.today))

    def test_low_touch_strike_does_not_block_resume(self):
        """2026-10-05 14:09Z: a resumable halt on an event with a 6x7 strike
        (mid in the 5-90 band, touch under the 10c pad gate) must still
        resume once the event is quiet."""
        bot = self._bot()
        bot.run_cycle()
        self._books(bot, 1200, 1200, 300, 1200)           # B thin -> halt
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertIn(self.EV, bot.state.event_depth_halt)
        bot.client.books[self.B] = {"orderbook_fp": {
            "yes_dollars": [["0.06", "1500"]],
            "no_dollars": [["0.93", "1500"]]}}             # 6x7, mid 6.5
        bot.state.event_depth_halt[self.EV] = \
            time.time() - imm.EVENT_DEPTH_RESUME_SECS - 5
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertNotIn(self.EV, bot.state.event_depth_halt)
        self.assertNotIn(self.EV, bot.state.event_live_halt)

    def test_known_start_arms_noisy_triggers_late_jump_keeps_the_day(self):
        """Point 7 (Jack 2026-10-05, 26OCT05 rally at 7pm ET): with a known
        start, thin / one-sided / fill triggers wait for start - pre-arm;
        the settled-strike jump keeps the ticker-day arm."""
        now_ts = time.time()
        far = datetime.fromtimestamp(now_ts + 365 * 86400, timezone.utc)
        near = datetime.fromtimestamp(now_ts + 20 * 60, timezone.utc)
        with mock.patch.dict(imm.EVENT_START_OVERRIDES, {self.EV: far}):
            self.assertFalse(imm.event_live_gate_armed(self.EV, now_ts))
            self.assertTrue(imm.event_live_gate_armed(self.EV, now_ts,
                                                      jump=True))
            bot = self._bot()
            bot.run_cycle()
            self.assertTrue(self._event_orders(bot))      # prev_mid seeded ~50
            # the words get said anyway: the jump still confirms LIVE
            bot.client.books[self.B] = {"orderbook_fp": {
                "yes_dollars": [["0.98", "150"]],
                "no_dollars": [["0.01", "300"]]}}         # 98x99
            bot.state.universe_at = time.time()
            bot.run_cycle()
            self.assertIn(self.EV, bot.state.event_live_halt)
        with mock.patch.dict(imm.EVENT_START_OVERRIDES, {self.EV: near}):
            self.assertTrue(imm.event_live_gate_armed(self.EV, now_ts))
        # no override: the ticker-day rule, as before
        self.assertTrue(imm.event_live_gate_armed(self.EV, now_ts))

    def test_known_start_far_out_thin_book_does_not_halt(self):
        _clean_persist()
        far = datetime.fromtimestamp(time.time() + 365 * 86400, timezone.utc)
        with mock.patch.dict(imm.EVENT_START_OVERRIDES, {self.EV: far}):
            bot = self._bot()
            bot.run_cycle()
            self._books(bot, 1200, 1200, 1200, 200)       # B goes thin
            bot.state.universe_at = time.time()
            bot.run_cycle()
            self.assertNotIn(self.EV, bot.state.event_depth_halt)
            self.assertTrue(self._event_orders(bot))

    def test_event_live_clear_file_releases_a_confirm(self):
        bot = self._bot()
        bot.state.event_live_halt[self.EV] = time.time()
        bot.state.event_depth_halt[self.EV] = time.time()
        bot.state.event_fill_strikes[self.EV] = 1
        with open(imm.EVENT_LIVE_CLEAR_FILE, "w", encoding="utf-8") as f:
            f.write(f"# false confirm\n{self.EV}\n")
        try:
            bot.run_cycle()
            self.assertNotIn(self.EV, bot.state.event_live_halt)
            self.assertNotIn(self.EV, bot.state.event_fill_strikes)
            self.assertFalse(os.path.exists(imm.EVENT_LIVE_CLEAR_FILE))
            self.assertTrue(os.path.exists(imm.EVENT_LIVE_CLEAR_FILE + ".done"))
        finally:
            for p in (imm.EVENT_LIVE_CLEAR_FILE, imm.EVENT_LIVE_CLEAR_FILE + ".done"):
                if os.path.exists(p):
                    os.remove(p)

    def test_live_confirm_survives_restart_and_refuses_reselection(self):
        bot = self._bot()
        bot.run_cycle()
        bot.client.books[self.B] = {"orderbook_fp": {
            "yes_dollars": [["0.98", "150"]],
            "no_dollars": [["0.01", "300"]]}}
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertIn(self.EV, bot.state.event_live_halt)
        bot._save_persist()
        bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
        self.assertIn(self.EV, bot2.state.event_live_halt)
        bot2.run_cycle()          # fresh process, healthy default A book
        self.assertFalse([o for o in bot2.state.sim_orders.values()
                          if o["ticker"] in (self.A, self.B)],
                         "live-confirmed event must never quote again")

    def test_pinned_strike_blocks_thin_halt_resume(self):
        """Jack 2026-08-31 #2: 'settled strike SHOULD hold an event down
        forever.' Even without jump history (restart amnesia), a strike
        sitting out of band counts as NOTHING for the resume pass — the
        halted event stays down until that strike is back in band or gone."""
        bot = self._bot()
        bot.run_cycle()
        self._books(bot, 1200, 1200, 300, 1200)           # B thin in-band
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertIn(self.EV, bot.state.event_depth_halt)
        bot.state.prev_mid.pop(self.B, None)              # amnesia: no jump
        bot.client.books[self.B] = {"orderbook_fp": {
            "yes_dollars": [["0.95", "30"]],
            "no_dollars": [["0.03", "40"]]}}              # pinned 95x97
        bot.state.event_depth_halt[self.EV] = \
            time.time() - imm.EVENT_DEPTH_RESUME_SECS - 5
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertIn(self.EV, bot.state.event_depth_halt,
                      "out-of-band pin must block resume")
        self.assertNotIn(self.EV, bot.state.event_live_halt)
        self.assertFalse(self._event_orders(bot))
        # only a fully healthy in-band event releases the thin-only halt
        self._books(bot, 1200, 1200, 1200, 1200)
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertNotIn(self.EV, bot.state.event_depth_halt)
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertTrue(self._event_orders(bot))

    def test_thin_then_pin_with_history_escalates_to_live_confirm(self):
        """With mid history intact the same pin IS the jump signature: the
        halt branch keeps prev_mid fresh precisely so a later settle-jump
        still confirms."""
        bot = self._bot()
        bot.run_cycle()
        self._books(bot, 1200, 1200, 300, 1200)           # thin first
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertIn(self.EV, bot.state.event_depth_halt)
        bot.client.books[self.B] = {"orderbook_fp": {
            "yes_dollars": [["0.95", "30"]],
            "no_dollars": [["0.03", "40"]]}}              # then settles ~96
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertIn(self.EV, bot.state.event_live_halt)

    def test_fill_burst_halts_the_whole_event(self):
        """Jack 2026-09-01 postmortem: fills ARE the adverse selection —
        one burst on a gated market stands the whole event down even with
        IMM_BREAKERS off (the box's default) and even though every book
        still reads deep."""
        self.assertFalse(imm.BREAKERS_ENABLED)
        bot = self._bot()
        bot.run_cycle()
        self.assertTrue(self._event_orders(bot))
        # fills move the bot's own book AND the account position together
        # (a divergence would be the manual-standoff signature instead)
        bot.pnl.pos[self.B] = imm.EVENT_FILL_HALT_CONTRACTS + 5.0
        bot.client.positions[self.B] = imm.EVENT_FILL_HALT_CONTRACTS + 5.0
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertFalse(self._event_orders(bot),
                         "A's quotes must die with B's fill burst")
        self.assertIn(self.EV, bot.state.event_depth_halt)
        self.assertNotIn(self.EV, bot.state.event_live_halt)  # strike 1/2
        self.assertTrue(any(c == "event_fill" for c, _m in bot.alerter.today))

    def test_second_fill_burst_confirms_live_permanently(self):
        bot = self._bot()
        bot.run_cycle()
        bot.pnl.pos[self.B] = 20.0                        # burst 1
        bot.client.positions[self.B] = 20.0
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertEqual(bot.state.event_fill_strikes.get(self.EV), 1)
        # halt clears (books fine), event re-enters...
        bot.state.event_depth_halt.pop(self.EV, None)
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertTrue(self._event_orders(bot))
        bot.pnl.pos[self.B] = 45.0                        # burst 2 -> LIVE
        bot.client.positions[self.B] = 45.0
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertIn(self.EV, bot.state.event_live_halt)
        self.assertFalse(self._event_orders(bot))
        # strikes survive a restart, so the escalation cannot be reset
        bot._save_persist()
        bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
        self.assertEqual(bot2.state.event_fill_strikes.get(self.EV), 2)
        self.assertIn(self.EV, bot2.state.event_live_halt)


class TestSidesCanQualify(unittest.TestCase):
    """Jack 2026-08-05: the gate must ask whether a pad WILL BE PLACED, not
    whether the series is the padding kind. A padding series still gets no pad
    when the mid is outside the band, when the pad price is not far enough
    behind the touch, or when the gap exceeds PAD_MAX_CONTRACTS — and the old
    test waved all three through to quote into a book that cannot qualify."""

    S = "KXGOOD"          # padding series (padding is global again)
    TGT = 1000.0

    def setUp(self):
        self.assertTrue(imm.series_pad_to_target(self.S))

    def q(self, dy, dn, eb=40, ea=44):
        return imm.sides_can_qualify(self.S, self.TGT, dy, dn, eb, ea)

    def test_deep_book_qualifies_without_any_pad(self):
        self.assertEqual(self.q(1200, 1200), (True, True))

    def test_thin_side_qualifies_when_a_pad_will_be_placed(self):
        self.assertEqual(self.q(300, 1200), (True, True))
        self.assertEqual(self.q(1200, 300), (True, True))

    def test_mid_outside_the_band_gets_NO_pad_so_cannot_qualify(self):
        # mid 96.5 -> pad_band_ok False. The old check called this a padding
        # series and let it quote anyway.
        self.assertFalse(imm.pad_band_ok(self.S, 96, 97))
        self.assertEqual(imm.sides_can_qualify(self.S, self.TGT, 300, 1200,
                                               96, 97), (False, True))

    def test_pad_too_close_to_the_touch_cannot_qualify(self):
        # a 2c touch leaves the 1c pad only 1 tick behind (< PAD_MIN_TICKS_BEHIND)
        self.assertLess(2 - imm.PAD_BID_CENTS, imm.PAD_MIN_TICKS_BEHIND)
        bid_ok, _ = imm.sides_can_qualify(self.S, self.TGT, 300, 1200, 2, 40)
        self.assertFalse(bid_ok)

    def test_gap_wider_than_the_pad_cap_cannot_qualify(self):
        big = imm.PAD_MAX_CONTRACTS + 500.0
        bid_ok, _ = imm.sides_can_qualify(self.S, big, 0, big, 40, 44)
        self.assertFalse(bid_ok)
        # ...but a gap the cap CAN close still qualifies
        ok, _ = imm.sides_can_qualify(self.S, float(imm.PAD_MAX_CONTRACTS),
                                      0, float(imm.PAD_MAX_CONTRACTS), 40, 44)
        self.assertTrue(ok)

    def test_non_padding_series_needs_real_depth(self):
        old = imm.PAD_TO_TARGET_GLOBAL
        imm.PAD_TO_TARGET_GLOBAL = False
        try:
            self.assertEqual(imm.sides_can_qualify("KXNOPAD", self.TGT,
                                                   300, 1200, 40, 44),
                             (False, True))
            self.assertEqual(imm.sides_can_qualify("KXNOPAD", self.TGT,
                                                   1200, 1200, 40, 44),
                             (True, True))
        finally:
            imm.PAD_TO_TARGET_GLOBAL = old

    def test_no_cutoff_mention_class_joins_the_depth_gate(self):
        # Jack 2026-09-08 (KXWORLDNEWSMENTION-26SEP08, "What will the
        # reporters say during ABC World News Tonight?"): a mention event
        # with no derivable start quoted all 16 markets through the 6:30pm
        # show and padded 400-700 lots into the crash. "Mention markets
        # without a clear cutoff time ... should follow TRUMPMENTION
        # padding/quoting behavior and stand down / not pad."
        from datetime import datetime, timedelta, timezone
        exp = datetime(2026, 9, 23, 14, 0, tzinfo=timezone.utc)
        clear = imm.mention_cutoff_is_clear
        # WORLDNEWS's real inputs: resolver None, no pre-settlement
        # occurrence, a two-week expiration placeholder -> NOT clear
        self.assertFalse(clear("KXWORLDNEWSMENTION", None, None, exp))
        # an override / fixed hour / feed hit (resolver != None) -> clear
        self.assertTrue(clear("KXWORLDNEWSMENTION", exp - timedelta(days=15),
                              None, exp))
        # an occurrence meaningfully before expiration is a real start
        self.assertTrue(clear("KXEARNINGSMENTIONCHWY", None,
                              exp - timedelta(days=2), exp))
        # ...but an occurrence AT expiration is a settlement stamp
        # (KXTRUMPMENTION-26SEP09 reads occ == expected expiration)
        self.assertFalse(clear("KXTRUMPMENTION", None, exp, exp))
        self.assertFalse(clear("KXTRUMPMENTION", None,
                               exp - timedelta(minutes=30), exp))
        # no expiration to compare against: an occurrence alone counts
        self.assertTrue(clear("KXFEDMENTION", None, exp, None))
        # the rule is scoped to the MENTION family; everything else is
        # "clear" by construction and never marked
        self.assertTrue(clear("KXAAAGASDNY", None, None, exp))
        self.assertTrue(clear("KXTRUEV", None, None, None))

        # marking a series puts it on the SAME gate TRUMPMENTION uses:
        # series_event_depth_gated flips and pads are forced off, for the
        # TTL, refreshed by re-marking, and expiring on its own.
        s = "KXWORLDNEWSMENTION"
        saved = dict(imm._DYNAMIC_DEPTH_GATE)
        old_ttl, old_knob = imm.MENTION_NO_CUTOFF_TTL_SECS, imm.MENTION_NO_CUTOFF_GATE
        try:
            imm._DYNAMIC_DEPTH_GATE.clear()
            imm.MENTION_NO_CUTOFF_GATE = True
            self.assertFalse(imm.series_event_depth_gated(s))
            self.assertTrue(imm.series_pad_to_target(s))
            now = time.time()
            self.assertTrue(imm.mark_no_cutoff_mention(s, now))     # new mark
            self.assertFalse(imm.mark_no_cutoff_mention(s, now + 1))  # refresh
            self.assertTrue(imm.series_event_depth_gated(s))
            self.assertFalse(imm.series_pad_to_target(s))
            self.assertIn(s, imm.dynamic_depth_gated_series())
            # expiry: two refreshes after the last unresolved sighting
            imm._DYNAMIC_DEPTH_GATE[s] = now - imm.MENTION_NO_CUTOFF_TTL_SECS - 1
            self.assertFalse(imm.series_event_depth_gated(s))
            self.assertNotIn(s, imm.dynamic_depth_gated_series())
            self.assertTrue(imm.series_pad_to_target(s))
            # an expired mark re-marks as NEW (so the transition logs again)
            self.assertTrue(imm.mark_no_cutoff_mention(s, now))
            # a statically-gated series is never re-marked (the log line
            # would misattribute its protection to the class rule)
            self.assertFalse(imm.mark_no_cutoff_mention("KXTRUMPMENTION", now))
            self.assertNotIn("KXTRUMPMENTION", imm.dynamic_depth_gated_series())
            # the static prefix list is untouched by the knob...
            self.assertTrue(imm.series_event_depth_gated("KXTRUMPMENTION"))
            self.assertTrue(imm.series_event_depth_gated("KXTRUMPMENTIONB"))
            # ...and the class rule is switchable on its own
            imm.MENTION_NO_CUTOFF_GATE = False
            self.assertFalse(imm.series_event_depth_gated(s))
            self.assertFalse(imm.mark_no_cutoff_mention("KXOTHERMENTION", now))
            self.assertTrue(imm.series_event_depth_gated("KXTRUMPMENTION"))
        finally:
            imm._DYNAMIC_DEPTH_GATE.clear()
            imm._DYNAMIC_DEPTH_GATE.update(saved)
            imm.MENTION_NO_CUTOFF_TTL_SECS, imm.MENTION_NO_CUTOFF_GATE = old_ttl, old_knob

    def test_no_target_is_never_gated(self):
        self.assertEqual(imm.sides_can_qualify(self.S, 0.0, 0, 0, 40, 44),
                         (True, True))

    def test_one_sided_book_cannot_qualify(self):
        # pad_band_ok treats a missing touch as outside the band
        self.assertEqual(imm.sides_can_qualify(self.S, self.TGT, 300, 1200,
                                               None, 44)[0], False)


class TestMemberMidBand(unittest.TestCase):
    """Jack 2026-08-05. member_price_band() widens a quoting market's
    PLACEMENT to 5-93, but _screen kept testing the MID against 5-90 for
    everyone — so a member whose mid drifted past 90 was dropped from
    selection before the widened band could ever apply, and the widening was
    partly dead. Members are now screened against the same band they may
    quote in; FRESH entry is unchanged."""

    def _bot(self):
        _clean_persist()
        return IncentiveMarketMaker(client=FakeClient(), live=False)

    def _meta(self, mid):
        return imm.MarketMeta(
            ticker="KXHOOD-26NOVX-1", event_ticker="KXHOOD-26NOVX",
            series="KXHOOD", dollars_per_day=25.0, program_end=None,
            target_size=1000.0, discount_factor=0.5, cutoff=None,
            close_time=datetime.now(timezone.utc) + timedelta(days=30),
            mid_cents=mid, spread_cents=1, volume=100.0,
            open_time=datetime.now(timezone.utc) - timedelta(days=1))

    def test_the_two_bands_agree_by_construction(self):
        """Defaults track STICKY_PRICE_MAX rather than restating 93 — two
        copies of one number diverging is what stranded the Treasuries."""
        self.assertEqual(imm.MID_BAND_MEMBER_HI, imm.STICKY_PRICE_MAX)
        self.assertEqual(imm.member_price_band("KXHOOD", True),
                         (imm.MID_BAND_MEMBER_LO, imm.MID_BAND_MEMBER_HI))

    def test_member_survives_a_mid_between_90_and_93(self):
        bot = self._bot()
        try:
            for mid in (90.5, 92.0, 93.0):
                self.assertIsNone(bot._screen(self._meta(mid),
                                              datetime.now(timezone.utc),
                                              member=True), f"mid {mid}")
        finally:
            _clean_persist()

    def test_fresh_entry_is_unchanged_in_that_range(self):
        bot = self._bot()
        try:
            for mid in (90.5, 92.0, 93.0):
                self.assertEqual(bot._screen(self._meta(mid),
                                             datetime.now(timezone.utc),
                                             member=False), "extreme_mid",
                                 f"mid {mid}")
        finally:
            _clean_persist()

    def test_beyond_the_member_band_still_screens_out(self):
        bot = self._bot()
        try:
            for mid in (93.5, 96.0, 4.0):
                self.assertEqual(bot._screen(self._meta(mid),
                                             datetime.now(timezone.utc),
                                             member=True), "extreme_mid",
                                 f"mid {mid}")
        finally:
            _clean_persist()

    def test_normal_mids_unaffected_either_way(self):
        bot = self._bot()
        try:
            for mid in (5.0, 50.0, 90.0):
                for mem in (True, False):
                    self.assertIsNone(bot._screen(self._meta(mid),
                                                  datetime.now(timezone.utc),
                                                  member=mem), f"{mid} {mem}")
        finally:
            _clean_persist()


class TestSafeJoinCappedAtReference(unittest.TestCase):
    """Jack 2026-08-05. Under the amended rules only orders at or above the
    REFERENCE score, so on a book whose touch level alone exceeds the target
    the qualifying walk ends at the touch and standing two ticks behind it
    earns exactly zero — safe-join and getting paid become mutually exclusive.
    Capping safe-join at the reference keeps its full effect wherever the
    reference sits behind the touch (the thin-touch case it was written for)
    and stops exactly where it would only cost reward.

    Measured live: KXFSLR-26OCTMWSOLD-4200 frac 0.00000 -> 0.01392,
    KXHOOD-26NOVECVOL-12000000000 0.00000 -> 0.01861."""

    SERIES = "KXFSLR"          # safe-join is on for the re-entry set

    def setUp(self):
        self.assertTrue(imm.series_safe_join(self.SERIES),
                        "test assumes a safe-join series")
        self._mode = imm.LADDER_MODE
        imm.LADDER_MODE = "atref"

    def tearDown(self):
        imm.LADDER_MODE = self._mode

    def _px(self, side, anchor, opposite, ref):
        q = imm.build_side_ladder(f"{self.SERIES}-26OCTX-1", side, anchor,
                                  opposite, room=100, levels=[(0, 20)],
                                  ref_px=ref)
        return q[0].price_cents if q else None

    def test_reference_at_the_touch_is_not_pushed_behind(self):
        # tight book (spread 4 < SAFE_JOIN_MIN_SPREAD) whose touch already
        # exceeds target -> reference IS the touch
        self.assertEqual(self._px("bid", 48, 52, 48), 48)
        self.assertEqual(self._px("ask", 52, 48, 52), 52)

    def test_safe_join_still_applies_when_the_reference_is_deeper(self):
        # thin touch: reference sits 5 ticks back, safe-join's 2-tick cap is
        # not the binding constraint and placement lands on the reference
        self.assertEqual(self._px("bid", 48, 52, 43), 43)
        self.assertEqual(self._px("ask", 52, 48, 57), 57)

    def test_reference_one_tick_back_beats_the_two_tick_offset(self):
        # would previously have rested at 46 (anchor-2), scoring nothing
        # below the 47 reference
        self.assertEqual(self._px("bid", 48, 52, 47), 47)
        self.assertEqual(self._px("ask", 52, 48, 53), 53)

    def test_wide_book_never_engaged_safe_join_at_all(self):
        # spread 10 >= SAFE_JOIN_MIN_SPREAD -> no cap either way
        self.assertEqual(self._px("bid", 45, 55, 45), 45)

    def test_non_safe_join_series_unaffected(self):
        self.assertFalse(imm.series_safe_join("KXTEMPDCH"))
        q = imm.build_side_ladder("KXTEMPDCH-26AUG0512-T80.99", "bid", 48, 52,
                                  room=100, levels=[(0, 20)], ref_px=48)
        self.assertEqual(q[0].price_cents, 48)

    def test_cap_never_makes_us_cross_the_opposite_touch(self):
        """Post-only safety: the reference cap must not push a bid to or past
        the ask (build_side_ladder pulls the anchor inside first)."""
        px = self._px("bid", 51, 52, 60)      # absurd ref beyond the ask
        self.assertLess(px, 52)


class TestHopelessExitDipGuard(unittest.TestCase):
    """Jack 2026-08-05: "dont evict on dips under $1".

    The peak-TTL guard claimed to already do this and did not: `pts` only
    refreshes on a new HIGH, so a DECLINING estimate lets the peak expire and
    then one low reading evicts. Measured live: KXUST7AM-26AUG31 went 15
    strikes -> 7 overnight, KXFSLR-26OCTMWSOLD and KXHOOD-26NOVECVOL 7 -> 5.
    Eviction is near-permanent (re-entry must clear the fresh-candidate rate
    bar these cannot meet), so the exit has to be sure, not fast."""

    def _bot(self):
        _clean_persist()
        return IncentiveMarketMaker(client=FakeClient(), live=False)

    def _step(self, bot, ticker, reaches_min, now_ts):
        """The universe-refresh bookkeeping, in isolation."""
        if reaches_min:
            bot.state.hopeless_since.pop(ticker, None)
        else:
            bot.state.hopeless_since.setdefault(ticker, now_ts)
        sub = now_ts - bot.state.hopeless_since.get(ticker, now_ts)
        return (imm.HOPELESS_EXIT and not reaches_min
                and sub >= imm.HOPELESS_SUSTAIN_SECS)

    def test_a_single_dip_does_not_evict(self):
        bot = self._bot()
        try:
            t0 = 1_000_000.0
            self.assertFalse(self._step(bot, "A", True, t0))
            self.assertFalse(self._step(bot, "A", False, t0 + 60))   # the dip
            self.assertFalse(self._step(bot, "A", True, t0 + 120))   # recovers
            self.assertNotIn("A", bot.state.hopeless_since)
        finally:
            _clean_persist()

    def test_a_brief_run_of_dips_does_not_evict(self):
        bot = self._bot()
        try:
            t0 = 1_000_000.0
            for i in range(1, 30):        # ~29 minutes under the bar
                self.assertFalse(self._step(bot, "A", False, t0 + 60 * i),
                                 f"evicted after {i} min")
        finally:
            _clean_persist()

    def test_sustained_sub_bar_still_evicts(self):
        bot = self._bot()
        try:
            t0 = 1_000_000.0
            self._step(bot, "A", False, t0)
            self.assertFalse(self._step(bot, "A", False,
                                        t0 + imm.HOPELESS_SUSTAIN_SECS - 1))
            self.assertTrue(self._step(bot, "A", False,
                                       t0 + imm.HOPELESS_SUSTAIN_SECS))
        finally:
            _clean_persist()

    def test_one_recovery_resets_the_whole_clock(self):
        """A market that recovers even briefly starts over — the point is that
        only CONTINUOUS hopelessness counts."""
        bot = self._bot()
        try:
            t0 = 1_000_000.0
            self._step(bot, "A", False, t0)
            self._step(bot, "A", True, t0 + imm.HOPELESS_SUSTAIN_SECS - 10)
            self.assertFalse(self._step(bot, "A", False,
                                        t0 + imm.HOPELESS_SUSTAIN_SECS + 10))
        finally:
            _clean_persist()

    def test_clock_survives_a_restart(self):
        """~20 deploys/day would otherwise keep resetting it and the exit
        could never fire at all."""
        _clean_persist()
        try:
            bot = IncentiveMarketMaker(client=FakeClient(), live=False)
            bot.state.known_tickers = {"A"}
            bot.state.hopeless_since["A"] = 1_000_000.0
            bot._save_persist()
            bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
            self.assertAlmostEqual(bot2.state.hopeless_since.get("A"), 1_000_000.0)
        finally:
            _clean_persist()

    def test_sustain_window_is_30_minutes_by_default(self):
        # Jack 2026-09-26: "30min checks instead of hourly" (was 3600)
        self.assertEqual(imm.HOPELESS_SUSTAIN_SECS, 1800)
        self.assertFalse(imm.MEMBER_PEAK_GUARD)

    def test_member_exit_runs_on_the_live_projection_not_the_peak(self):
        """MURRAY1 (2026-09-26): a member admitted on a thin-book reading
        was carried by that reading's 1h peak, then by a re-seed that landed
        on a second blip -- ~3h15m before the clock even started. Now the
        live projection starts the clock whatever the peak says, and the
        member leaves after HOPELESS_SUSTAIN_SECS."""
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        T = "KXGOOD-99DEC31-A"
        bot.run_cycle()
        self.assertIn(T, bot.state.selected)
        old_floor = imm.MIN_EST_TOTAL_DOLLARS
        imm.MIN_EST_TOTAL_DOLLARS = imm.PAYOUT_FLOOR_DOLLARS = 1e9
        try:
            bot._est_peak[T] = (2e9, time.time())      # a fresh, huge peak
            bot.state.universe_at = 0.0
            bot.run_cycle()
            self.assertIn(T, bot.state.selected)       # clock started, not run
            self.assertIn(T, bot.state.hopeless_since)
            bot.state.hopeless_since[T] = (
                time.time() - imm.HOPELESS_SUSTAIN_SECS - 1)
            bot.state.universe_at = 0.0
            bot.run_cycle()
            self.assertNotIn(T, bot.state.selected)    # 30 min under -> out
        finally:
            imm.MIN_EST_TOTAL_DOLLARS, imm.PAYOUT_FLOOR_DOLLARS = old_floor, 1.0
            _clean_persist()


class TestDailyRainSizeMult(unittest.TestCase):
    """Jack 2026-09-27: "1.5x multiplier on KXUST and daily RAIN since it's
    consistently performed well". The daily city binaries (series KXRAIN)
    only: the monthlies, the weekend contract and the rainstorm spans keep
    the global size."""

    def test_daily_rain_x1_5(self):
        self.assertEqual(imm.RAIN_DAILY_SIZE_MULT, 1.5)
        S = "KXRAIN"
        ov = imm.SERIES_OVERRIDES[S]
        self.assertEqual(ov.size_mult, 1.5)
        self.assertEqual(imm.applied_mention_mult(S), 1.5)
        self.assertEqual(imm.series_max_position(S),
                         1.5 * imm.MAX_POSITION_CONTRACTS)
        self.assertEqual(imm.event_cap_contracts("KXRAIN-26SEP29"),
                         1.5 * imm.MAX_EVENT_CONTRACTS)
        base = imm.series_levels(S)
        self.assertEqual(imm.base_scaled_levels(S),
                         [(t, max(1, int(z * 1.5 + 0.5))) for t, z in base])
        # the rain band and the 10pm-the-day-before cutoff are untouched
        self.assertEqual((ov.price_min_cents, ov.price_max_cents), (5, 90))
        self.assertEqual(ov.cutoff_before_event_min, 120)

    def test_the_evening_halving_composes(self):
        # the code-default 19-01 ET halving sits on top: x1.5 x 0.5 = x0.75
        S = "KXRAIN"
        base = imm.series_levels(S)
        with mock.patch.object(imm, "SERIES_HOUR_MULTS",
                               imm._parse_series_hour_mults("KXRAIN:19-1:0.5")):
            day = datetime(2026, 9, 29, 16, 0, tzinfo=timezone.utc)   # Tue noon EDT
            eve = datetime(2026, 9, 29, 23, 30, tzinfo=timezone.utc)  # Tue 7:30pm EDT
            self.assertEqual(imm.hour_size_mult(S, day), 1.0)
            self.assertEqual(imm.hour_size_mult(S, eve), 0.5)
            self.assertEqual(imm.hour_scaled_levels(S, day),
                             [(t, max(1, int(z * 1.5 + 0.5))) for t, z in base])
            self.assertEqual(imm.hour_scaled_levels(S, eve),
                             [(t, max(1, int(z * 0.75 + 0.5))) for t, z in base])

    def test_other_rain_shapes_keep_the_global_size(self):
        for s in ("KXRAINNYCM", "KXRAINAUSM", "KXRAINWKND",
                  imm.RAINSTORM_ARCHETYPE):
            self.assertIn(s, imm.SERIES_OVERRIDES, s)
            self.assertIsNone(imm.SERIES_OVERRIDES[s].size_mult, s)
            self.assertEqual(imm.applied_mention_mult(s), 1.0, s)
            self.assertEqual(imm.series_max_position(s),
                             imm.MAX_POSITION_CONTRACTS, s)


class TestTreasuryYieldSeriesEnrolled(unittest.TestCase):
    """Jack 2026-08-04: allowlist the five daily Treasury-yield tenors."""

    DAILIES = ("KXUST2AD", "KXUST5AD", "KXUST7AD", "KXUST10AD", "KXUST30AD")
    MONTHLIES = ("KXUST2AM", "KXUST5AM", "KXUST7AM", "KXUST10AM", "KXUST30AM")
    TENORS = DAILIES + MONTHLIES

    def setUp(self):
        # Other suites toggle these and don't always restore them; pin them so
        # this asserts enrolment rather than whatever ran before it.
        self._saved = (imm.ALLOWLIST_ONLY, set(imm.EXTRA_ALLOW_SERIES))
        imm.ALLOWLIST_ONLY = True
        imm.EXTRA_ALLOW_SERIES.clear()

    def tearDown(self):
        imm.ALLOWLIST_ONLY = self._saved[0]
        imm.EXTRA_ALLOW_SERIES.clear()
        imm.EXTRA_ALLOW_SERIES.update(self._saved[1])

    def test_all_five_tenors_are_allowed(self):
        for s in self.TENORS:
            self.assertIn(s, imm.ALLOW_SERIES, s)
            self.assertTrue(
                imm.IncentiveMarketMaker._allowed(f"{s}-26AUG05-T4.25"), s)

    def test_they_carry_the_guarded_re_entry_treatment(self):
        """A rate print sits tight and two-sided until the number lands, so
        joining the touch is the expensive way to be there."""
        for s in self.TENORS:
            self.assertTrue(imm.series_safe_join(s), s)
            self.assertEqual(imm.series_min_est_rate(s), 2.0, s)
            self.assertGreaterEqual(imm.series_min_est_total(s),
                                    imm.PAYOUT_FLOOR_DOLLARS, s)

    def test_every_treasury_family_is_allowlisted(self):
        """Jack 2026-09-30: 'KXUST10YRRATE27 / KXUST30YRRATE27 and all
        treasury families should be on the treasury allowlist'. Same guards
        as the ten, minus the horizon-blind $2/day rate bar; the 15-minute
        tenors and the test series stay out."""
        extra = imm._DEFAULT_RATES_EXTRA_SERIES.split(",")
        for s in ("KXUST10YRRATE27", "KXUST30YRRATE27", "KXUST10AW", "KXNOTE10W",
                  "KXTNOTED", "KX10YRDIRHM", "KX10Y2Y", "KXYINVERT", "KX3MTBILL"):
            self.assertIn(s, extra, s)
            self.assertIn(s, imm.ALLOW_SERIES, s)
            self.assertTrue(imm.series_safe_join(s), s)
            self.assertEqual(imm.series_min_est_rate(s), 0.0, s)
            self.assertEqual(imm.SERIES_OVERRIDES[s].size_mult, imm.RATES_SIZE_MULT, s)
            self.assertGreaterEqual(imm.series_min_est_total(s),
                                    imm.PAYOUT_FLOOR_DOLLARS, s)
        self.assertTrue(imm.IncentiveMarketMaker._allowed("KXUST10YRRATE27-27DEC31-T4.24"))
        self.assertTrue(imm.IncentiveMarketMaker._allowed("KXUST30YRRATE27-27DEC31-T4.24"))
        self.assertEqual(imm.scan_universe_reason("KXUST10YRRATE27-27DEC31-T4.24"), "allowed")
        for s in ("KX10YRRATE15M", "KX2YRRATE15M", "KX5YRRATE15M", "KX30YRRATE15M",
                  "KX2YTEST", "KXSECTREASURY", "KXUSTHOLDERS"):
            self.assertNotIn(s, extra, s)
            self.assertNotIn(s, imm.ALLOW_SERIES, s)
        self.assertTrue(set(extra).isdisjoint(self.TENORS))
        for s in self.TENORS:                                    # the ten unchanged
            self.assertEqual(imm.series_min_est_rate(s), 2.0, s)

    def test_year_end_cutoff_is_the_print_day_morning(self):
        self.assertEqual(
            self._cutoff("KXUST10YRRATE27", "KXUST10YRRATE27-27DEC31",
                         close=imm.ET.localize(datetime(2027, 12, 31, 15, 30))),
            "2027-12-31 07:30")

    def test_monthlies_enrolled_too(self):
        """Jack 2026-08-04, second pass: 'also allowlist the treasury
        monthlies like KXUST2AM'. Same contract, ~4 weeks out."""
        for s in self.MONTHLIES:
            self.assertIn(s, imm.ALLOW_SERIES, s)
            self.assertTrue(
                imm.IncentiveMarketMaker._allowed(f"{s}-26AUG31-T4.25"), s)

    def test_monthlies_carry_the_same_cutoff_and_guards(self):
        """The monthly settles on the same 3:30pm ET snapshot, so the 7:30am
        event-day rule reads across — it just does not bite until month end."""
        for s in self.MONTHLIES:
            self.assertTrue(imm.series_safe_join(s), s)
            self.assertEqual(
                self._cutoff(s, f"{s}-26AUG31",
                             close=self._et(31, 15, 30)),
                "2026-08-31 07:30", s)

    def test_x1_5_family_size(self):
        """Jack 2026-09-27: "1.5x multiplier on KXUST and daily RAIN since
        it's consistently performed well" -- all ten tenors on the size_mult
        wire, so the rung, both caps and the floor projection's day ladder
        scale together, and the guards stay as they were."""
        self.assertEqual(imm.RATES_SIZE_MULT, 1.5)
        for s in self.TENORS:
            ov = imm.SERIES_OVERRIDES[s]
            self.assertEqual(ov.size_mult, 1.5, s)
            self.assertEqual(imm.applied_mention_mult(s), 1.5, s)
            self.assertEqual(imm.series_max_position(s),
                             1.5 * imm.MAX_POSITION_CONTRACTS, s)
            self.assertEqual(imm.event_cap_contracts(f"{s}-26SEP30"),
                             1.5 * imm.MAX_EVENT_CONTRACTS, s)
            base = imm.series_levels(s)
            self.assertEqual(imm.base_scaled_levels(s),
                             [(t, max(1, int(z * 1.5 + 0.5))) for t, z in base], s)
            self.assertTrue(imm.series_safe_join(s), s)
            self.assertEqual(ov.event_day_cutoff_et, (7, 30), s)
        # nothing outside the enrolled Treasury families rides the prefix
        # (the weeklies joined 2026-09-30 by name; the 15-minute tenors and
        # the test series stay out)
        for s in ("KXUSTFOO", "KX10YRRATE15M", "KX2YTEST"):
            self.assertEqual(imm.applied_mention_mult(s), 1.0, s)
        self.assertEqual(imm.applied_mention_mult("KXUST2AW"), 1.5)

    def test_no_prefix_bleed_onto_unenrolled_ust_shapes(self):
        # exact-series matching: an unenrolled shape must not ride in on the
        # KXUST prefix just because other Treasury families are enrolled (the
        # real weeklies were enrolled BY NAME on 2026-09-30)
        for s in ("KXUST3AD", "KXUSTFOO", "KX10YRRATE15M", "KX2YTEST"):
            self.assertNotIn(s, imm.ALLOW_SERIES, s)
            self.assertFalse(
                imm.IncentiveMarketMaker._allowed(f"{s}-26AUG31-T4.25"), s)

    @staticmethod
    def _et(day, hh, mm):
        return imm.ET.localize(datetime(2026, 8, day, hh, mm)).astimezone(timezone.utc)

    def _cutoff(self, series, event, occurrence=None, close=None):
        close = close if close is not None else self._et(5, 15, 30)
        c = imm.trade_cutoff_utc(event, occurrence, close)
        c = imm.apply_series_cutoff_adjustments(series, event, c, close)
        return c.astimezone(imm.ET).strftime("%Y-%m-%d %H:%M") if c else None

    def test_quotes_until_730am_et_on_the_event_day(self):
        """Jack 2026-08-04: 'quote treasuries until 7:30am EST'. Midnight is
        the right default for a scheduled RELEASE; a Treasury yield settles on
        a 3:30pm ET snapshot of a continuously-traded rate, so the overnight
        hours are no more informed than the evening before. 7:30 puts the bot
        out ahead of the 08:30 data."""
        for s in self.TENORS:
            self.assertEqual(self._cutoff(s, f"{s}-26AUG05"),
                             "2026-08-05 07:30", s)

    def test_other_day_dated_series_keep_the_midnight_rule(self):
        for s in ("KXAAAGASD", "KXDIESELD", "KXUSGASCPI", "KXBKFT"):
            self.assertEqual(self._cutoff(s, f"{s}-26AUG05"),
                             "2026-08-05 00:00", s)

    def test_a_real_event_start_still_beats_the_extension(self):
        """The extender shifts the ticker-date CANDIDATE, so min() still lets
        an occurrence_datetime win. An earlier draft applied it to the
        finished cutoff and quoted straight through a 4am event start."""
        self.assertEqual(
            self._cutoff("KXUST10AD", "KXUST10AD-26AUG05",
                         occurrence=self._et(5, 4, 0)),
            "2026-08-05 04:00")

    def test_a_later_event_start_does_not_extend_us_further(self):
        self.assertEqual(
            self._cutoff("KXUST10AD", "KXUST10AD-26AUG05",
                         occurrence=self._et(5, 9, 0)),
            "2026-08-05 07:30")

    def test_extension_is_clamped_to_the_close(self):
        self.assertEqual(
            self._cutoff("KXUST10AD", "KXUST10AD-26AUG05",
                         close=self._et(5, 3, 0)),
            "2026-08-05 03:00")


class TestPerSeriesHourMultiplier(unittest.TestCase):
    """Jack 2026-08-04: halve the ladder on KXDIESELD / KXAAAGASD / KXRAIN
    from 4pm ET. Window runs to 01:59 ET because the gas/diesel dailies trade
    until then — stopping at midnight would restore full size for their last
    two hours. KXTRUEV (Jack 2026-08-24, with its allowlisting) halves an
    hour later, from 5pm ET."""

    def setUp(self):
        # Pin the config under test instead of reading whatever
        # IMM_SERIES_HOUR_MULT happens to be, so this asserts the RULE and
        # stays green under an env override.
        self._saved = imm.SERIES_HOUR_MULTS
        imm.SERIES_HOUR_MULTS = imm._parse_series_hour_mults(
            "KXDIESELD:16-1:0.5,KXAAAGASD:16-1:0.5,KXRAIN:16-1:0.5,"
            "KXTRUEV:17-1:0.5")

    def tearDown(self):
        imm.SERIES_HOUR_MULTS = self._saved

    def _at(self, et_hour):
        return imm.ET.localize(
            datetime(2026, 8, 4, et_hour, 30)).astimezone(timezone.utc)

    def test_halved_from_4pm_et(self):
        for s in ("KXDIESELD-26AUG05-T5.315", "KXAAAGASD-26AUG05-3.10",
                  "KXRAIN-26AUG05-DEN"):
            for h in (16, 20, 23):
                self.assertEqual(
                    imm.hour_size_mult(s.split("-")[0], self._at(h)), 0.5,
                    f"{s} at ET {h}")

    def test_window_runs_past_midnight_to_the_daily_close(self):
        # gas/diesel dailies close 01:59 ET
        for h in (0, 1):
            self.assertEqual(
                imm.hour_size_mult("KXDIESELD", self._at(h)), 0.5, f"ET {h}")
        self.assertEqual(imm.hour_size_mult("KXDIESELD", self._at(2)), 1.0)

    def test_truev_halved_from_5pm_et(self):
        # Jack 2026-08-24: KXTRUEV halves an hour later than gas/diesel —
        # full size through the 4pm hour, half from 5pm through the
        # overnight tail (later-dated siblings keep quoting past midnight).
        self.assertEqual(imm.hour_size_mult("KXTRUEV", self._at(16)), 1.0)
        for h in (17, 20, 23, 0, 1):
            self.assertEqual(
                imm.hour_size_mult("KXTRUEV", self._at(h)), 0.5, f"ET {h}")
        self.assertEqual(imm.hour_size_mult("KXTRUEV", self._at(2)), 1.0)

    def test_full_size_before_4pm(self):
        for h in (9, 12, 15):
            self.assertEqual(
                imm.hour_size_mult("KXRAIN", self._at(h)), 1.0, f"ET {h}")

    def test_weeklies_and_monthlies_keep_full_size(self):
        # the prefixes are the DAILY tickers on purpose
        for s in ("KXAAAGASW", "KXAAAGASM", "KXDIESELW"):
            self.assertEqual(imm.hour_size_mult(s, self._at(20)), 1.0, s)

    def test_ladder_actually_halves_on_the_production_shape(self):
        """The launcher runs IMM_LEVELS=0:20 (one rung of 20), so pin that
        rather than the 3-rung in-code default, whose per-rung half-up
        rounding makes 35 -> 18 rather than 17.5."""
        old = imm.LEVELS
        try:
            imm.LEVELS = [(0, 20)]
            self.assertEqual(imm.hour_scaled_levels("KXDIESELD", self._at(12)),
                             [(0, 20)])
            self.assertEqual(imm.hour_scaled_levels("KXDIESELD", self._at(20)),
                             [(0, 10)])
        finally:
            imm.LEVELS = old

    def test_ladder_never_rounds_a_rung_away(self):
        """Halving must not silently delete a rung — floor is 1 contract."""
        old = imm.LEVELS
        try:
            imm.LEVELS = [(0, 1)]
            self.assertEqual(imm.hour_scaled_levels("KXRAIN", self._at(20)),
                             [(0, 1)])
        finally:
            imm.LEVELS = old

    def test_per_series_rule_beats_the_global_window_and_exclude(self):
        old_g, old_x = imm.HOUR_SIZE_MULTS, imm.HOUR_MULT_EXCLUDE
        try:
            imm.HOUR_SIZE_MULTS = {20: 2.0}          # global says double
            imm.HOUR_MULT_EXCLUDE = ("KXRAIN",)      # and excludes rain
            # the explicit per-series rule still wins in both directions
            self.assertEqual(imm.hour_size_mult("KXRAIN", self._at(20)), 0.5)
            self.assertEqual(imm.hour_size_mult("KXOTHER", self._at(20)), 2.0)
        finally:
            imm.HOUR_SIZE_MULTS, imm.HOUR_MULT_EXCLUDE = old_g, old_x

    def test_global_window_survives_outside_the_per_series_hours(self):
        """A per-series rule owns only its own hours: outside them a
        long-dated series keeps the global window (KXTRUEV's 5pm halving
        must not cancel its quiet hours). Daily families (2026-09-12 pm)
        take no global window at all, but their own halving still applies."""
        old_g = imm.HOUR_SIZE_MULTS
        try:
            imm.HOUR_SIZE_MULTS = {3: 2.0, 4: 2.0, 5: 2.0, 6: 2.0, 7: 2.0}
            self.assertFalse(imm.is_daily_series("KXTRUEV"))
            self.assertEqual(imm.hour_size_mult("KXTRUEV", self._at(5)), 2.0)
            self.assertEqual(imm.hour_size_mult("KXTRUEV", self._at(20)), 0.5)
            self.assertEqual(imm.hour_size_mult("KXTRUEV", self._at(12)), 1.0)
            for s in ("KXDIESELD", "KXAAAGASD", "KXRAIN"):
                self.assertTrue(imm.is_daily_series(s), s)
                self.assertEqual(imm.hour_size_mult(s, self._at(5)), 1.0, s)
                self.assertEqual(imm.hour_size_mult(s, self._at(20)), 0.5, s)
                self.assertEqual(imm.hour_size_mult(s, self._at(12)), 1.0, s)
        finally:
            imm.HOUR_SIZE_MULTS = old_g

    def test_longest_prefix_wins(self):
        spec = imm._parse_series_hour_mults("KXA:0-23:2.0,KXAAAGASD:0-23:0.5")
        prefixes = [p for p, _h in spec]
        self.assertEqual(prefixes[0], "KXAAAGASD")   # most specific first

    def test_bad_spec_raises(self):
        for bad in ("KXA", "KXA:", ":1-2:0.5", "KXA:99-1:0.5", "KXA:1-2:x"):
            with self.assertRaises(ValueError, msg=bad):
                imm._parse_series_hour_mults(bad)


class TestShippedHourMultDefaults(unittest.TestCase):
    """TestPerSeriesHourMultiplier pins its own spec to assert the RULE, so
    a rule silently dropped from the shipped IMM_SERIES_HOUR_MULT default
    would still pass it. Assert the import-time default directly (skipped
    under an env override, like the allowlist-default tests effectively are)."""

    def setUp(self):
        if os.environ.get("IMM_SERIES_HOUR_MULT"):
            self.skipTest("IMM_SERIES_HOUR_MULT env override active")
        self.rules = dict(imm.SERIES_HOUR_MULTS)

    def test_truev_default_halves_at_5pm_not_4(self):
        # Jack 2026-08-24: "halve normal quote amounts starting at 5pm EST"
        self.assertIn("KXTRUEV", self.rules)
        self.assertNotIn(16, self.rules["KXTRUEV"])
        for h in (17, 23, 0, 1):
            self.assertEqual(self.rules["KXTRUEV"].get(h), 0.5, f"ET {h}")

    def test_gas_diesel_rain_defaults_still_present(self):
        self.assertEqual(self.rules["KXDIESELD"].get(16), 0.5)
        self.assertEqual(self.rules["KXAAAGASD"].get(16), 0.5)
        self.assertEqual(self.rules["KXRAIN"].get(19), 0.5)


class TestCodeChangeSelfRestart(unittest.TestCase):
    """Jack 2026-08-24: deploys sat inert because nothing restarted the bot
    after sync pulled new code (KXTRUEV shipped allowlisted and still quoted
    $0 against live programs). The bot now exits for the launcher at the
    next safe moment when its own source file changes on disk."""

    CHANGED = imm._SOURCE_MTIME + 1000.0
    AGED = CHANGED + 3600.0          # now_ts making the new mtime >=60s old
    TEMP = {"KXTEMPMIAH-26AUG2415-T80.99": None}

    def _at(self, minute):
        return imm.ET.localize(
            datetime(2026, 8, 24, 12, minute)).astimezone(timezone.utc)

    def test_no_change_no_exit(self):
        self.assertFalse(imm.code_change_exit_due(
            self.TEMP, self._at(55), current_mtime=imm._SOURCE_MTIME,
            now_ts=self.AGED))

    def test_changed_and_no_hourly_temp_exits_any_minute(self):
        for m in (7, 30, 44):
            self.assertTrue(imm.code_change_exit_due(
                {}, self._at(m), current_mtime=self.CHANGED,
                now_ts=self.AGED), m)
        # weekly average-temp is NOT hourly temp — no window hold
        self.assertTrue(imm.code_change_exit_due(
            {"KXAVGTKDFW-26AUG24-B85.5": None}, self._at(30),
            current_mtime=self.CHANGED, now_ts=self.AGED))

    def test_changed_with_hourly_temp_waits_for_the_window(self):
        for m in (7, 30, 49):
            self.assertFalse(imm.code_change_exit_due(
                self.TEMP, self._at(m), current_mtime=self.CHANGED,
                now_ts=self.AGED), m)
        for m in (50, 55, 0, 5):
            self.assertTrue(imm.code_change_exit_due(
                self.TEMP, self._at(m), current_mtime=self.CHANGED,
                now_ts=self.AGED), m)

    def test_fresh_mtime_settles_first(self):
        # a file the sync is still writing must never be half-imported
        self.assertFalse(imm.code_change_exit_due(
            {}, self._at(55), current_mtime=self.CHANGED,
            now_ts=self.CHANGED + 10))

    def test_kill_switch(self):
        old = imm.EXIT_ON_CODE_CHANGE
        try:
            imm.EXIT_ON_CODE_CHANGE = False
            self.assertFalse(imm.code_change_exit_due(
                {}, self._at(55), current_mtime=self.CHANGED,
                now_ts=self.AGED))
        finally:
            imm.EXIT_ON_CODE_CHANGE = old


class TestSideMaxClampedToPositionCap(unittest.TestCase):
    """A single side may not rest more than the market's whole net position
    cap. Live breach 2026-08-04 (KXTEMPAUSH-26AUG0409-T79.99, cap 50): long
    +25 -> sell room 50+25=75 trimmed to a 60-contract ladder -> 35 filled ->
    a full 60 re-placed 28s later off the stale +25 -> position -70."""

    def test_temp_ladder_cannot_exceed_its_own_position_cap(self):
        # 20/side x the 3.0 deep-reference multiplier = 60, cap is 50
        b, a = imm.clamp_side_max_to_position_cap(60, 60, 50.0)
        self.assertEqual((b, a), (50, 50))

    def test_sides_are_clamped_independently(self):
        b, a = imm.clamp_side_max_to_position_cap(60, 20, 50.0)
        self.assertEqual((b, a), (50, 20))

    def test_no_effect_when_the_ladder_already_fits(self):
        # non-temp: 20/side x 3.0 = 60 against a 150 cap — untouched
        self.assertEqual(imm.clamp_side_max_to_position_cap(60, 60, 150.0),
                         (60, 60))

    def test_zero_or_absent_cap_is_a_no_op(self):
        self.assertEqual(imm.clamp_side_max_to_position_cap(60, 60, 0.0),
                         (60, 60))
        self.assertEqual(imm.clamp_side_max_to_position_cap(60, 60, -1.0),
                         (60, 60))

    def test_live_regression_temp_ladder_of_twenty_per_side(self):
        """The PRODUCTION shape, pinned: the launcher runs IMM_TEMP_LEVELS=0:20
        (not the in-code default), which is what made 20 x 3.0 = 60 exceed the
        50 cap. Set it explicitly so this asserts the live config rather than
        whatever env the suite happens to run under."""
        import dataclasses
        ov = imm.SERIES_OVERRIDES["KXTEMPAUSH"]
        try:
            imm.SERIES_OVERRIDES["KXTEMPAUSH"] = dataclasses.replace(
                ov, levels=[(0, 20)])
            lv = imm.hour_scaled_levels(
                "KXTEMPAUSH", datetime(2026, 8, 4, 12, tzinfo=timezone.utc))
            base = sum(s for _t, s in lv)
            side_max = int(round(base * imm.REF_DEPTH_MAX_MULT))
            maxpos = imm.series_max_position("KXTEMPAUSH")
            self.assertEqual(side_max, 60)        # the live 2026-08-04 number
            self.assertGreater(side_max, maxpos)  # the hole, unclamped
            b, a = imm.clamp_side_max_to_position_cap(side_max, side_max, maxpos)
            self.assertEqual((b, a), (50, 50))
        finally:
            imm.SERIES_OVERRIDES["KXTEMPAUSH"] = ov


class TestCoverageIsNotAnEstimateFactor(unittest.TestCase):
    """The exclusion rule is already inside estimate_reward_share (an excluded
    snapshot returns frac 0.0), so multiplying the rate by the coverage EMA
    applied it twice. Measured on the clean post-amendment window: raw 0.982x
    credited, coverage-multiplied 1.057x."""

    def test_excluded_snapshot_contributes_nothing(self):
        thin = [[50, 10.0]]                      # far below target
        deep = [[50, 5000.0]]
        frac, sides = imm.estimate_reward_share(
            deep, thin, [("bid", 50, 100.0)], 1000.0, 0.5, own_in_book=True)
        self.assertEqual(frac, 0.0)
        self.assertLess(sides, 2)

    def test_estimate_rate_has_no_coverage_term(self):
        """est_dollars_per_day must equal frac x pool exactly — a market whose
        book has been one-sided in the past must not be discounted twice."""
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        bot._coverage_ema["KXGOOD-99DEC31-A"] = 0.25   # ugly history
        meta = imm.MarketMeta(
            ticker="KXGOOD-99DEC31-A", event_ticker="KXGOOD-99DEC31",
            series="KXGOOD", dollars_per_day=100.0, program_end=None,
            target_size=1000.0, discount_factor=0.5, cutoff=None,
            close_time=datetime.now(timezone.utc) + timedelta(hours=2),
            mid_cents=50.0, spread_cents=2, volume=100.0)
        self.assertTrue(bot._estimate_candidate_yield(meta, []))
        self.assertAlmostEqual(meta.est_dollars_per_day,
                               meta.est_frac * meta.dollars_per_day, places=9)


# ---- zero-share strike: is a zero share about the BOOK or about US? --------

class TestZeroShareStrikeCounts(unittest.TestCase):
    """The 2026-08-06 Kalshi maintenance outage, in predicate form.

    Kalshi went down 07:16-09:00Z (19,949 x 503 in 07Z, 18,737 in 08Z). The
    failsafe cancelled every order at 07:18:44Z; post-only 409s and our own
    429 throttle then kept us off the book for two hours (36,321 rejections,
    ZERO successful placements — and the 08Z half had no 503s at all). The old
    guard scored `frac` from our RESTING orders but tested our DESIRED quotes,
    so every selected market struck every cycle against books that never
    stopped qualifying. 307 markets benched 07:45:59-08:13:29Z: 293 of 471
    candidates, selected 390 -> 31, est reward ~$404/day -> ~$159/day.

    A zero share is only a verdict on the MARKET when our real non-pad size is
    actually resting on both sides."""

    FULL = [("bid", 47, 100.0), ("ask", 53, 100.0)]

    def test_a_full_non_pad_ladder_earning_nothing_IS_a_verdict(self):
        self.assertTrue(imm.zero_share_strike_counts(0.0, self.FULL))

    def test_nothing_resting_is_a_verdict_on_US_not_the_book(self):
        # the measured outage state: failsafe cancel-all, own == []
        self.assertFalse(imm.zero_share_strike_counts(0.0, []))

    def test_pads_only_cannot_score_so_cannot_convict(self):
        # a 1c/99c pad is thousands of ticks below the qualifying walk, so
        # frac is 0.0 BY CONSTRUCTION — and `mq` is non-empty, which is
        # exactly what the old `and mq` test waved through.
        pads = [("bid", imm.PAD_BID_CENTS, 900.0),
                ("ask", imm.PAD_ASK_CENTS, 900.0)]
        self.assertFalse(imm.zero_share_strike_counts(0.0, pads))

    def test_a_real_rung_beside_a_pad_still_needs_BOTH_sides(self):
        self.assertFalse(imm.zero_share_strike_counts(
            0.0, [("bid", 49, 100.0), ("ask", imm.PAD_ASK_CENTS, 900.0)]))

    def test_one_side_only_is_our_own_cap_or_skew_not_the_book(self):
        self.assertFalse(imm.zero_share_strike_counts(0.0, [("bid", 49, 100.0)]))
        self.assertFalse(imm.zero_share_strike_counts(0.0, [("ask", 51, 100.0)]))

    def test_zero_remaining_ghosts_are_not_resting_size(self):
        # if the count field is ever renamed, order_remaining falls through to
        # 0.0 and own_by_ticker fills with all-zero entries — the class of the
        # _fp rename that silently killed position reads for two weeks.
        self.assertFalse(imm.zero_share_strike_counts(
            0.0, [("bid", 47, 0.0), ("ask", 53, 0.0)]))

    def test_any_positive_share_is_never_a_strike(self):
        self.assertFalse(imm.zero_share_strike_counts(1e-9, self.FULL))
        self.assertFalse(imm.zero_share_strike_counts(0.5, []))

    def test_pads_alongside_real_rungs_still_convict(self):
        self.assertTrue(imm.zero_share_strike_counts(0.0, [
            ("bid", imm.PAD_BID_CENTS, 900.0), ("bid", 47, 100.0),
            ("ask", imm.PAD_ASK_CENTS, 900.0), ("ask", 53, 100.0)]))

    def test_the_estimator_agrees_with_the_predicate_on_the_outage_state(self):
        """Pin the algebra the predicate rests on: with our orders absent the
        REAL estimator returns exactly 0.0 while BOTH sides still qualify. So
        `sides` is 2 during an outage — a fix keyed on `sides` would be wrong,
        and the coverage alert (sides < 2) never overlaps with the bench."""
        yes = [[49, 1200.0]]
        no = [[49, 1200.0]]
        frac, sides = imm.estimate_reward_share(yes, no, [], 1000.0, 0.5,
                                                own_in_book=True)
        self.assertEqual(frac, 0.0)
        self.assertEqual(sides, 2)
        self.assertFalse(imm.zero_share_strike_counts(frac, []))
        # ...and our real size at the touch does earn something
        own = [("bid", 49, 100.0), ("ask", 51, 100.0)]
        frac2, sides2 = imm.estimate_reward_share(yes, no, own, 1000.0, 0.5,
                                                  own_in_book=True)
        self.assertGreater(frac2, 0.0)
        self.assertEqual(sides2, 2)


def _resting(oid, ticker, book_side, yes_px, n=100):
    """A resting order of OURS, in the shape fetch_resting_orders accepts."""
    return {"order_id": oid, "ticker": ticker, "status": "resting",
            "client_order_id": f"{imm.CLIENT_ORDER_PREFIX}-test-{oid}",
            "book_side": book_side, "yes_price": yes_px,
            "remaining_count": n}


class TestOutageDoesNotBench(unittest.TestCase):
    """Full-cycle regression for the 2026-08-06 bench storm.

    live=True is MANDATORY here: in dry mode incentive_mm.py sets est_own to
    the DESIRED ladder, so frac > 0 by construction, the streak never
    increments, and a live=False version of every test below would pass
    identically before and after the fix and prove nothing."""

    T = "KXGOOD-99DEC31-A"

    def _bot(self):
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=True)
        # a book that never stopped qualifying — 1200 a side vs a 1000 target,
        # which is what the cycle log showed throughout the outage (both sides
        # at or above target on 97-98% of rows in every 10-minute bucket)
        bot.client.books[self.T] = {"orderbook_fp": {
            "yes_dollars": [["0.49", "1200"]],
            "no_dollars": [["0.49", "1200"]]}}
        return bot

    def _second_cycle(self, bot, orders):
        """Arm cycle 2 with exactly `orders` of ours resting."""
        # _merge_ledger unions the exchange view with our local ledger and
        # counts young unconfirmed entries as resting, so stubbing get_orders
        # alone does NOT empty `own` — cycle 1's placements survive.
        bot.state.ledger.clear()
        bot.client.get_orders = lambda **kw: {"orders": list(orders),
                                              "cursor": None}
        bot.state.universe_at = time.time()   # no refresh between cycles

    def test_an_outage_cannot_bench_a_1200x1200_book(self):
        bot = self._bot()
        try:
            bot.run_cycle()
            self._second_cycle(bot, [])
            # name the real cause: placements rejected, nothing ever rests
            def _boom(**kw):
                raise HttpError("Service Unavailable", 503)
            bot.client.create_order = _boom
            bot.state.zero_share_streak[self.T] = imm.QUALIFY_PATIENCE_CYCLES - 1
            bot.run_cycle()
            self.assertNotIn(self.T, bot.state.bench_until)
            self.assertIn(self.T, bot.state.selected)
            self.assertFalse(any(c == "benched" for c, _m in bot.alerter.today))
        finally:
            _clean_persist()

    def test_the_streak_is_RESET_not_paused_so_a_flapping_outage_cannot_bank(self):
        bot = self._bot()
        try:
            bot.run_cycle()
            self._second_cycle(bot, [])
            # deliberately NOT one short of the bench: at 29 the old code also
            # ends at {} — by benching. Mid-streak is the discriminating probe.
            # An untrusted cycle must ZERO the count, not merely skip it, or a
            # flapping outage banks strikes across the good cycles between
            # blackouts and benches anyway.
            partial = imm.QUALIFY_PATIENCE_CYCLES // 2
            bot.state.zero_share_streak[self.T] = partial
            bot.run_cycle()
            self.assertEqual(bot.state.zero_share_streak, {})
            self.assertNotIn(self.T, bot.state.bench_until)
        finally:
            _clean_persist()

    def test_a_healthy_first_cycle_scores_NO_strike(self):
        # measured pre-fix: {'KXGOOD-99DEC31-A': 1} after cycle 1, because the
        # counter at the top of the quote loop judges a placement that has not
        # happened yet. The counter was off-by-one from its stated meaning
        # even on the happy path.
        bot = self._bot()
        try:
            bot.run_cycle()
            self.assertEqual(bot.state.zero_share_streak, {})
        finally:
            _clean_persist()

    def test_pads_only_is_not_a_verdict_on_the_book(self):
        bot = self._bot()
        try:
            bot.run_cycle()
            self._second_cycle(bot, [
                _resting("p1", self.T, "bid", imm.PAD_BID_CENTS, 900),
                _resting("p2", self.T, "ask", imm.PAD_ASK_CENTS, 900)])
            bot.state.zero_share_streak[self.T] = imm.QUALIFY_PATIENCE_CYCLES - 1
            bot.run_cycle()
            self.assertNotIn(self.T, bot.state.bench_until)
            self.assertIn(self.T, bot.state.selected)
        finally:
            _clean_persist()

    def test_a_full_ladder_earning_nothing_STILL_benches(self):
        """The anti-deletion test. Without this the fix is indistinguishable
        from deleting the bench. Our real non-pad size rests on BOTH sides,
        far below the qualifying walk (which stops at 49c once 1200 >= the
        1000 target), so we carry fill risk for exactly zero rent."""
        bot = self._bot()
        try:
            bot.run_cycle()
            self._second_cycle(bot, [
                _resting("r1", self.T, "bid", 40, 100),
                _resting("r2", self.T, "ask", 60, 100)])
            bot.state.zero_share_streak[self.T] = imm.QUALIFY_PATIENCE_CYCLES - 1
            bot.run_cycle()
            self.assertIn(self.T, bot.state.bench_until)
            self.assertNotIn(self.T, bot.state.selected)
            self.assertTrue(any(c == "benched" for c, _m in bot.alerter.today))
        finally:
            _clean_persist()

    def test_wake_grace_never_strikes(self):
        """Post-sleep reads "can SUCCEED with garbage (partial positions/
        orders)" — the gate standoffs and universe selection already had and
        this counter never did. Same fixture as the legitimate bench above."""
        bot = self._bot()
        try:
            bot.run_cycle()
            self._second_cycle(bot, [
                _resting("r1", self.T, "bid", 40, 100),
                _resting("r2", self.T, "ask", 60, 100)])
            bot.wake_grace_until = time.time() + 300
            bot.state.zero_share_streak[self.T] = imm.QUALIFY_PATIENCE_CYCLES - 1
            bot.run_cycle()
            self.assertNotIn(self.T, bot.state.bench_until)
            self.assertEqual(bot.state.zero_share_streak, {})
        finally:
            _clean_persist()


class TestCallWindowFreeze(unittest.TestCase):
    """Jack 2026-08-06: "sit out completely during call windows".

    Once a scheduled earnings call has STARTED, the market gets no orders at
    all — not even reduce-only wind-down. Positions ride to settlement.

    The bug this closes: restore_orphan_metas built its cutoff from
    trade_cutoff_utc() alone, which knows nothing about EVENT_START_OVERRIDES
    (only the selection path consults resolver.resolve()). So
    KXEARNINGSMENTIONDKNG-26AUG07, whose call ran 16:00 ET on Aug 6, resolved
    to midnight-ET-of-Aug-7 — still in the future — and kept 7 reduce-only
    orders resting 1.2h into the live call. MEASURED, not hypothetical.
    """

    T = "KXGOOD-99DEC31-A"
    EV = "KXGOOD-99DEC31"

    def setUp(self):
        _clean_persist()
        self.addCleanup(_clean_persist)
        self._saved = dict(imm.EVENT_START_OVERRIDES)
        self.addCleanup(lambda: (imm.EVENT_START_OVERRIDES.clear(),
                                 imm.EVENT_START_OVERRIDES.update(self._saved)))

    def _bot(self):
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        bot.state.known_tickers.add(self.T)
        bot.pnl.pos[self.T] = -40.0
        return bot

    def _meta_for(self):
        return MarketMeta(
            ticker=self.T, event_ticker=self.EV, series="KXGOOD",
            dollars_per_day=0.0, program_end=None, target_size=0.0,
            discount_factor=0.5, cutoff=None, close_time=None)

    def _set_call(self, minutes_from_now):
        imm.EVENT_START_OVERRIDES[self.EV] = (
            datetime.now(timezone.utc) + timedelta(minutes=minutes_from_now))

    def test_started_call_blocks_orphan_restore(self):
        self._set_call(-60)                      # call began an hour ago
        bot = self._bot()
        bot.restore_orphan_metas({self.T: -40.0})
        self.assertNotIn(self.T, bot.state.managed_extra,
                         "orphan restored into a live call window")

    def test_started_call_flushes_an_existing_entry_and_rests_nothing(self):
        self._set_call(-60)
        bot = self._bot()
        # the position must be visible to run_cycle, or managed_extra is
        # dropped for being flat and the test passes without exercising the
        # call-window branch at all
        bot.client.positions[self.T] = -40.0
        bot.state.managed_extra[self.T] = self._meta_for()
        bot.run_cycle()
        self.assertNotIn(self.T, bot.state.managed_extra)
        self.assertNotIn(self.T, bot.state.selected)
        self.assertFalse([o for o in bot.state.sim_orders.values()
                          if o.get("ticker") == self.T],
                         "orders rested during a live call window")

    def test_buffer_counts_as_started(self):
        """Orders must be gone OVERRIDE_BUFFER_MIN BEFORE the call, so the
        freeze has to bite inside the buffer too, not exactly at the start."""
        self._set_call(imm.OVERRIDE_BUFFER_MIN - 1)
        bot = self._bot()
        bot.restore_orphan_metas({self.T: -40.0})
        self.assertNotIn(self.T, bot.state.managed_extra)

    def test_future_call_still_winds_down_normally(self):
        """The freeze must not become a blanket ban on reduce-only exits —
        before the call, working out inventory is exactly what we want."""
        self._set_call(24 * 60)                  # call is tomorrow
        self.enterContext(mock.patch.object(imm, "WINDDOWN_DROPPED", True))
        bot = self._bot()
        bot.restore_orphan_metas({self.T: -40.0})
        self.assertIn(self.T, bot.state.managed_extra,
                      "wind-down wrongly frozen well before the call")

    def test_no_override_is_unaffected(self):
        """Series with no scheduled call (rates, gas, rain) keep their
        existing wind-down behaviour — this change is scoped to call windows,
        and freezing them would strand inventory at settlement instead."""
        imm.EVENT_START_OVERRIDES.pop(self.EV, None)
        self.enterContext(mock.patch.object(imm, "WINDDOWN_DROPPED", True))
        bot = self._bot()
        bot.restore_orphan_metas({self.T: -40.0})
        self.assertIn(self.T, bot.state.managed_extra)


class TestOpportunisticEmail(unittest.TestCase):
    """The 'Opportunistic IMM' daily email (Jack 2026-09-05). Light checks:
    the module imports (catches syntax/import regressions) and its event
    labels resolve without a client for mapped families and the ADS suffix
    (the client path is only the fallback for un-mapped events)."""

    def test_import_and_labels(self):
        import send_opportunistic_imm as opp
        # mapped families and the Carbon Arc ad-spend suffix need no client
        self.assertEqual(opp.event_label(None, "KXSPRLVL-26SEP09"),
                         "US Strategic Petroleum Reserve level")
        self.assertEqual(opp.event_label(None, "KXAMZNCC-26OCT07"),
                         "Amazon credit-card spend")
        self.assertEqual(opp.event_label(None, "KXFOOTWEARADS-26OCT06"),
                         "Ad spend (Carbon Arc)")
        # every base finecon family has a friendly label (no ticker-scheme
        # leaking into the email) — ADS members are covered by the suffix
        for s in imm._DEFAULT_FINECON_SERIES.split(","):
            lbl = opp.event_label(None, f"{s}-26OCT01")
            self.assertTrue(lbl and not lbl.startswith("KX"), s)

    def test_opportunistic_tables_render_per_tier(self):
        # Jack 2026-09-06: "a similarly formatted table for non-finecon
        # opportunistic bot" — both tiers render through the SAME table
        # functions, each with its own TOTAL row; no TIER column.
        import send_opportunistic_imm as opp
        rows = [{"event": "KXSPRLVL-26SEP09", "label": "US SPR level",
                 "tier": "finecon", "mkts": 3, "earn": 1.50, "pnl": -0.25,
                 "net": 1.25, "pos": 12},
                {"event": "KXNOVEL-26OCT13", "label": "Novel print",
                 "tier": "scan", "mkts": 2, "earn": 0.40, "pnl": 0.10,
                 "net": 0.50, "pos": -4}]
        t = opp.tier_totals(rows)
        self.assertEqual(t["mkts"], 5)
        self.assertAlmostEqual(t["earn"], 1.90)
        self.assertAlmostEqual(t["pnl"], -0.15)
        self.assertAlmostEqual(t["net"], 1.75)
        L = opp.text_table(rows)
        self.assertEqual(len(L), 4)                      # header, 2 rows, TOTAL
        self.assertTrue(L[0].startswith("EVENT"))
        self.assertNotIn("TIER", L[0])
        self.assertIn("US SPR level", L[1])
        self.assertTrue(L[-1].startswith("TOTAL"))
        self.assertIn("1.90", L[-1])
        self.assertIn("-0.15", L[-1])
        self.assertIn("+1.75", L[-1])
        # the same rows through the HTML twin
        html = opp.html_table(rows)
        self.assertIn("Novel print", html)
        self.assertIn("TOTAL", html)
        self.assertNotIn("TIER", html)
        self.assertEqual(html.count("<tr"), 4)
        # an empty tier still renders a well-formed TOTAL row
        self.assertTrue(opp.text_table([])[-1].startswith("TOTAL"))
        self.assertEqual(opp.tier_totals([])["net"], 0.0)

    def test_carbon_arc_is_left_out_of_the_email(self):
        # Jack 2026-10-04: "email should only have finecon and open scan,
        # remove carbon arc". The *CC family (this email's third tier from
        # 2026-09-11) and every other Carbon Arc-settled market map to NO
        # tier, so no table, headline, subject or credited footer can carry
        # them. REPORTING only: test_cc_family_suffix_allows_into_normal_book
        # still holds -- the normal book quotes them as before.
        import send_opportunistic_imm as opp
        fin = {"KXSPRLVL", "KXJOLTSOPEN"}
        scan = {"KXNOVEL-26OCT13-T5"}
        for t in ("KXAMZNCC-26OCT07-T108", "KXSBUXCC-26OCT07-T98",
                  "KXURBNCC-26OCT07-T94", "KXNEVERSEENCC-26OCT07-T1"):
            self.assertIsNone(opp.tier_of(t, fin, scan), t)
            self.assertTrue(opp.is_family(t), t)
            self.assertTrue(opp.excluded_carbon_arc(t), t)
        # the EVENT ticker too -- the cumulative table works on events
        self.assertIsNone(opp.tier_of("KXSBUXCC-26OCT07", fin, scan))
        # the two reported tiers are unchanged
        self.assertEqual(opp.tier_of("KXSPRLVL-26SEP16-T1", fin, scan),
                         "finecon")
        self.assertEqual(opp.tier_of("KXNOVEL-26OCT13-T5", fin, scan), "scan")
        # and the rest of the normal book is still not opportunistic
        for t in ("KXTRUMPMENTION-26SEP12-WALL", "KXBTCD-26SEP11-T100"):
            self.assertIsNone(opp.tier_of(t, fin, scan), t)
        # a series that merely CONTAINS the suffix is not the family (the
        # same rule incentive_mm._parse_event_top_n's "*CC" match uses)
        self.assertFalse(opp.is_family("KXCCOUNTY-26OCT07-T1"))

    def test_tier_precedence_matches_the_bot(self):
        # Carbon Arc first (Jack 2026-10-04): out even where finecon or the
        # scan admitted it, which is how the 12 September point-of-sale
        # events the scan quoted before the 9/22 family rule leave the
        # scan's history. Then finecon before scan: a series in BOTH sets is
        # walked and capped as finecon by incentive_mm._allowed.
        import send_opportunistic_imm as opp
        t = "KXWEIRDCC-26OCT07-T1"            # no verdict: the suffix decides
        self.assertIsNone(opp.tier_of(t, {"KXWEIRDCC"}, set()))
        self.assertIsNone(opp.tier_of(t, set(), {t}))
        self.assertIsNone(opp.tier_of(t, set(), set()))
        p = "KXPLAIN-26OCT07-T1"
        self.assertEqual(opp.tier_of(p, {"KXPLAIN"}, {p}), "finecon")
        self.assertEqual(opp.tier_of(p, set(), {p}), "scan")
        # the settlement source decides, not the name: a verdict that a
        # CC-named series is NOT Carbon Arc keeps it reportable
        saved = dict(opp.CARBON_ARC_SERIES)
        try:
            opp.CARBON_ARC_SERIES["KXWEIRDCC"] = False
            self.assertEqual(opp.tier_of(t, {"KXWEIRDCC"}, set()), "finecon")
            self.assertEqual(opp.tier_of(t, set(), {t}), "scan")
            opp.CARBON_ARC_SERIES["KXWEIRDCC"] = True
            self.assertIsNone(opp.tier_of(t, {"KXWEIRDCC"}, {t}))
        finally:
            opp.CARBON_ARC_SERIES.clear()
            opp.CARBON_ARC_SERIES.update(saved)

    def test_no_family_series_the_bot_allows_reaches_the_email(self):
        # The invariant since 2026-10-04 (it was the opposite one, "every
        # family market has a tier", after the 2026-09-10 regression): a
        # market the bot quotes through a Carbon Arc family suffix maps to
        # NO tier of this email. Driven off the bot's own constant, so a
        # suffix added to ALLOW_FAMILY_SUFFIXES can never slip into it.
        import send_opportunistic_imm as opp
        self.assertTrue(imm.ALLOW_FAMILY_SUFFIXES)
        saved_only = imm.ALLOWLIST_ONLY
        saved_verdicts = dict(imm.FAMILY_VERDICTS)
        imm.ALLOWLIST_ONLY = True
        try:
            for suf in imm.ALLOW_FAMILY_SUFFIXES:
                t = "KXPROBE{}-26OCT07-T1".format(suf)
                # the bot's membership needs its Carbon Arc source verdict
                # (2026-09-22)
                imm.FAMILY_VERDICTS["KXPROBE" + suf] = {
                    "carbon_arc": True, "ts": time.time(), "title": ""}
                self.assertTrue(IncentiveMarketMaker._allowed(t), t)
                self.assertIsNone(opp.tier_of(t, set(), set()), t)
                # not even under a stale scan membership
                self.assertIsNone(opp.tier_of(t, set(), {t}), t)
        finally:
            imm.ALLOWLIST_ONLY = saved_only
            imm.FAMILY_VERDICTS.clear()
            imm.FAMILY_VERDICTS.update(saved_verdicts)

    def test_cc_labels_never_leak_the_ticker_scheme(self):
        # 28 of the 30 *CC series have no _LABEL entry and resolve from the
        # live event title; with no client the family fallback must still
        # read as English rather than "KXURBNCC".
        import send_opportunistic_imm as opp
        self.assertEqual(opp.event_label(None, "KXSBUXCC-26OCT07"),
                         "Starbucks credit-card spend")
        self.assertEqual(opp.family_label("KXURBNCC"),
                         "Credit-card spend (Carbon Arc)")
        self.assertEqual(opp.family_label("KXFOOTWEARADS"),
                         "Ad spend (Carbon Arc)")
        self.assertEqual(opp.family_label("KXSPRLVL"), "")
        lbl = opp.event_label(None, "KXNEVERSEENCC-26OCT07")
        self.assertTrue(lbl and not lbl.startswith("KX"), lbl)

    def test_carbon_arc_exclusion_is_by_settlement_source(self):
        # Jack 2026-09-23: "why doesnt carbon arc group include all carbon
        # arc events including foottraffic markets like KXBROSFT-26OCT08
        # and KXCAVAFT-26OCT08. and app download markets like
        # KXDKNGAPP-26OCT08 and KXNFLXAPP-26OCT08?" -- all four are Carbon
        # Arc-settled but admitted by the exact company allowlist, so a
        # suffix-only rule never saw them. Membership is the settlement
        # source: the bot's verdict, else this script's cached lookup. Since
        # 2026-10-04 that membership decides what the email LEAVES OUT.
        import send_opportunistic_imm as opp
        saved = dict(opp.CARBON_ARC_SERIES)
        saved_ts = dict(opp._carbon_arc_ts)
        saved_v = dict(imm.FAMILY_VERDICTS)
        saved_path = opp.CARBON_ARC_CACHE_PATH
        opp.CARBON_ARC_CACHE_PATH = os.path.join(imm.STATUS_DIR,
                                                 "test_carbon_arc.json")
        opp.CARBON_ARC_SERIES.clear()
        opp._carbon_arc_ts.clear()
        try:
            fin, scan = {"KXSPRLVL"}, set()
            # unknown source: an *FT / *APP name proves nothing, so nothing
            # is excluded yet -- a finecon member would still report
            for t in ("KXBROSFT-26OCT08-T5", "KXDKNGAPP-26OCT08-T1.2M"):
                self.assertFalse(opp.excluded_carbon_arc(t), t)
                self.assertIsNone(opp.tier_of(t, fin, scan), t)
            self.assertEqual(opp.tier_of("KXBROSFT-26OCT08-T5", {"KXBROSFT"},
                                         set()), "finecon")
            # the bot's own verdict (a suffix family) counts, no read spent
            imm.FAMILY_VERDICTS["KXURBNCC"] = {"carbon_arc": True, "ts": 1.0,
                                               "title": ""}
            self.assertTrue(opp.is_carbon_arc("KXURBNCC-26OCT07-T94"))

            class _C:
                reads = 0

                def get(self, path, params=None):
                    _C.reads += 1
                    s = path.rsplit("/", 1)[1]
                    src = ("Carbon Arc" if s.endswith(("FT", "APP"))
                           and s != "KXNFLDRAFT" else "the Governing League")
                    return {"series": {"title": s,
                                       "settlement_sources": [{"name": src}]}}
            n = opp.resolve_carbon_arc(
                _C(), ["KXBROSFT", "KXCAVAFT", "KXDKNGAPP", "KXNFLXAPP",
                       "KXNFLDRAFT", "KXURBNCC"], 1000.0)
            self.assertEqual(n, 5)          # KXURBNCC: the bot's verdict
            for t in ("KXBROSFT-26OCT08-T5", "KXCAVAFT-26OCT08-T5",
                      "KXDKNGAPP-26OCT08-T1.2M", "KXNFLXAPP-26OCT08-T30M"):
                self.assertTrue(opp.excluded_carbon_arc(t), t)
                # out of every tier, finecon and scan included
                self.assertIsNone(opp.tier_of(t, {t.split("-")[0]}, {t}), t)
                # the EVENT ticker resolves the same way (cumulative table)
                ev = t.rsplit("-", 1)[0]
                self.assertIsNone(opp.tier_of(ev, set(), {ev}), t)
            # a *FT that is NOT Carbon Arc stays reportable
            self.assertFalse(opp.excluded_carbon_arc("KXNFLDRAFT-27-QB"))
            self.assertEqual(opp.tier_of("KXNFLDRAFT-27-QB", {"KXNFLDRAFT"},
                                         scan), "finecon")
            # a second resolve inside the TTL reads nothing
            _C.reads = 0
            self.assertEqual(opp.resolve_carbon_arc(
                _C(), ["KXBROSFT", "KXNFLDRAFT"], 2000.0), 0)
            self.assertEqual(_C.reads, 0)
            # the cache round-trips
            self.assertTrue(os.path.exists(opp.CARBON_ARC_CACHE_PATH))
            opp.CARBON_ARC_SERIES.clear()
            opp._carbon_arc_ts.clear()
            self.assertEqual(opp.load_carbon_arc_cache(), 6)
            self.assertTrue(opp.is_carbon_arc("KXCAVAFT-26OCT08"))
            self.assertFalse(opp.is_carbon_arc("KXNFLDRAFT-27"))
            # the cached verdict still excludes after a reload
            self.assertIsNone(opp.tier_of("KXBROSFT-26OCT08-T5", {"KXBROSFT"},
                                          {"KXBROSFT-26OCT08-T5"}))
            # labels for the two families that have no per-series entry
            self.assertEqual(opp.family_label("KXBROSFT"),
                             "Foot traffic (Carbon Arc)")
            self.assertEqual(opp.family_label("KXDKNGAPP"),
                             "App downloads (Carbon Arc)")
            self.assertEqual(opp.family_label("KXNFLDRAFT"), "")
            # a failed read leaves the series unknown, never raises

            class _Bad:
                def get(self, path, params=None):
                    raise RuntimeError("429")
            self.assertEqual(opp.resolve_carbon_arc(_Bad(), ["KXNEWFT"],
                                                    3000.0), 1)
            self.assertFalse(opp.excluded_carbon_arc("KXNEWFT-26OCT08-T1"))
            self.assertIsNone(opp.tier_of("KXNEWFT-26OCT08-T1", fin, scan))
        finally:
            opp.CARBON_ARC_SERIES.clear()
            opp.CARBON_ARC_SERIES.update(saved)
            opp._carbon_arc_ts.clear()
            opp._carbon_arc_ts.update(saved_ts)
            imm.FAMILY_VERDICTS.clear()
            imm.FAMILY_VERDICTS.update(saved_v)
            try:
                os.remove(opp.CARBON_ARC_CACHE_PATH)
            except OSError:
                pass
            opp.CARBON_ARC_CACHE_PATH = saved_path

    def test_credited_column_and_cumulative_tables(self):
        # Jack 2026-09-11 "make sure it shows not just active, but also
        # cumulative": CREDITED rides alongside the estimate per row, and
        # the cumulative table carries the tier totals. CREDITED is a SUBSET
        # of EARN EST (accrued_est is never reset at a period end), so no
        # renderer may add the two into one figure.
        import send_opportunistic_imm as opp
        rows = [{"event": "KXSBUXCC-26OCT07", "label": "Starbucks cc spend",
                 "tier": "family", "mkts": 3, "earn": 8.55, "cred": 5.21,
                 "pnl": -48.33, "net": -39.78, "pos": -202},
                # a row with NO cred key at all -- the pre-2026-09-11 shape
                {"event": "KXSPRLVL-26SEP16", "label": "US SPR level",
                 "tier": "finecon", "mkts": 3, "earn": 2.29, "pnl": 0.0,
                 "net": 2.29, "pos": 0}]
        t = opp.tier_totals(rows)
        self.assertAlmostEqual(t["cred"], 5.21)
        self.assertAlmostEqual(t["earn"], 10.84)
        # NET never absorbs CREDITED -- it would double-count the accrual
        self.assertAlmostEqual(t["net"], t["earn"] + t["pnl"])
        L = opp.text_table(rows)
        self.assertIn("CRED$", L[0])
        self.assertIn("5.21", L[1])
        # the CRED field of a never-credited row is BLANK, not 0.00 (the
        # 9 chars straight after that row's EARN EST value)
        self.assertEqual(L[2].split("2.29")[1][:9], " " * 9)
        self.assertIn("5.21", L[-1])
        html = opp.html_table(rows)
        self.assertIn("CREDITED$", html)
        self.assertIn("5.21", html)
        self.assertEqual(html.count("<tr"), 4)
        cum = [{"tier": "FINECON", "events": 12, "cred": 21.83, "est": 64.65,
                "realized": -26.20, "mtm": -22.55, "net": 15.90},
               {"tier": "TOTAL", "events": 12, "cred": 21.83, "est": 64.65,
                "realized": -26.20, "mtm": -22.55, "net": 15.90}]
        CL = opp.cum_text_table(cum)
        self.assertEqual(len(CL), 3)                     # header + 2 rows
        self.assertIn("CREDITED$", CL[0])
        self.assertIn("REALIZED$", CL[0])
        self.assertTrue(CL[-1].startswith("TOTAL"))
        chtml = opp.cum_html_table(cum)
        self.assertEqual(chtml.count("<tr"), 3)
        self.assertIn("21.83", chtml)

    def test_est_and_credited_are_not_nested(self):
        # Jack 2026-09-11 pm: "how can credited$ be more than earn est$ for
        # certain markets?" Because accrued_est is pruned with
        # known_tickers (`known_tickers &= managed | positions`), so a
        # market that stops being quoted while flat has its accrual DELETED
        # and restarts from zero next period; and because credits are per
        # EVENT forever while a row's EST sums only tickers still in its
        # book. Live on 2026-09-11: KXCBDECISIONNZ-26OCT27 est 6.33 vs
        # credited 10.92, KXMONSTERPOS-26OCT03 est 1.63 vs credited 3.41.
        # Neither quantity contains the other; the renderers must never sum
        # them, and a CREDITED above EARN EST must render without complaint.
        import send_opportunistic_imm as opp
        rows = [{"event": "KXCBDECISIONNZ-26OCT27", "label": "RBNZ",
                 "tier": "finecon", "mkts": 0, "held": 1, "earn": 6.33,
                 "cred": 10.92, "pnl": 3.60, "net": 9.93, "pos": -40}]
        t = opp.tier_totals(rows)
        self.assertGreater(t["cred"], t["earn"])          # the whole point
        self.assertAlmostEqual(t["net"], t["earn"] + t["pnl"])
        L = opp.text_table(rows)
        self.assertIn("10.92", L[1])
        self.assertIn("6.33", L[1])
        self.assertIn("10.92", L[-1])
        html = opp.html_table(rows)
        self.assertIn("10.92", html)
        # and the same inversion in the cumulative table
        cum = [{"tier": "FINECON", "events": 1, "cred": 10.92, "est": 6.33,
                "realized": 0.0, "mtm": 3.60, "net": 9.93}]
        self.assertIn("10.92", opp.cum_text_table(cum)[1])
        self.assertIn("10.92", opp.cum_html_table(cum))

    def test_period_column_unmeasurable_is_not_zero(self):
        # Jack 2026-09-11: "earn est of 23.70 seems wrong ... i see earnings
        # of ~$4". accrued_est runs from first quote and is not reset at a
        # program boundary, while the exchange's rewards view shows the
        # CURRENT period -- two different quantities. The email now carries
        # both, and a market whose roll the bot has not SEEN yet must print
        # "-", never 0.00: no baseline exists, so the period is unmeasurable.
        import send_opportunistic_imm as opp
        rows = [{"event": "KXA-26SEP30", "label": "measured", "tier": "finecon",
                 "mkts": 3, "earn": 24.64, "period": 4.10, "cred": 0.0,
                 "pnl": -3.90, "net": 20.74, "pos": -20},
                {"event": "KXB-26SEP30", "label": "not seen roll yet",
                 "tier": "finecon", "mkts": 1, "earn": 5.00, "period": None,
                 "cred": 0.0, "pnl": 0.0, "net": 5.00, "pos": 0}]
        t = opp.tier_totals(rows)
        self.assertAlmostEqual(t["period"], 4.10)      # only the measured one
        self.assertAlmostEqual(t["earn"], 29.64)       # all-time sums both
        L = opp.text_table(rows)
        self.assertIn("PERIOD$", L[0])
        self.assertIn("ALL-TIME$", L[0])
        self.assertIn("4.10", L[1])
        # the unmeasurable row renders "-" in PERIOD and still shows all-time
        self.assertIn("5.00", L[2])
        self.assertEqual(L[2].split("5.00")[0].strip()[-1], "-")
        html = opp.html_table(rows)
        self.assertIn("THIS PERIOD$", html)
        self.assertIn("ALL-TIME EST$", html)
        self.assertIn("&mdash;", html)
        # a tier where NOTHING is measurable yet shows "-", not a false 0.00
        none_rows = [dict(rows[1])]
        self.assertIsNone(opp.tier_totals(none_rows)["period"])
        self.assertIn("-", opp.text_table(none_rows)[-1])
        # and the pre-period row shape still renders (no "period" key at all)
        legacy = [{"event": "KXC-26SEP30", "label": "old", "tier": "scan",
                   "mkts": 1, "earn": 1.0, "pnl": 0.0, "net": 1.0, "pos": 0}]
        self.assertIsNone(opp.tier_totals(legacy)["period"])
        self.assertTrue(opp.text_table(legacy)[-1].startswith("TOTAL"))

    def test_reward_period_roll_rebaselines_accrual(self):
        # The bot records accrued_est as each market's program period opens,
        # so `accrued - base` is that period's earning. Measured 2026-09-11:
        # KXAAAGASMINM-26SEP30 ran 09-02 -> 09-09 and again 09-09 -> 09-16,
        # with accrual running straight through the boundary.
        _clean_persist()
        bot = IncentiveMarketMaker(client=None, live=False)
        T1 = "KXAAAGASMINM-26SEP30-3.75"
        p1 = datetime(2026, 9, 2, tzinfo=timezone.utc)
        p2 = datetime(2026, 9, 9, tzinfo=timezone.utc)

        # FIRST SIGHT: the period may already be half over, so there is no
        # honest baseline -- record the period, leave the baseline absent.
        bot.state.accrued_est[T1] = 12.00
        bot._roll_reward_periods({T1: {"start": p1, "end": p2}})
        self.assertEqual(bot.state.period_start[T1], p1.isoformat())
        self.assertNotIn(T1, bot.state.period_base)

        # same period again: no re-baseline, and no baseline invented
        bot.state.accrued_est[T1] = 20.00
        bot._roll_reward_periods({T1: {"start": p1, "end": p2}})
        self.assertNotIn(T1, bot.state.period_base)

        # THE ROLL: baseline captures accrual through the end of the period
        # that just closed, so the new period starts measuring from zero
        bot._roll_reward_periods({T1: {"start": p2, "end": p2}})
        self.assertEqual(bot.state.period_start[T1], p2.isoformat())
        self.assertAlmostEqual(bot.state.period_base[T1], 20.00)
        bot.state.accrued_est[T1] = 24.10
        self.assertAlmostEqual(
            bot.state.accrued_est[T1] - bot.state.period_base[T1], 4.10)

        # a program with no start is skipped rather than treated as a roll
        bot._roll_reward_periods({T1: {"end": p2}})
        self.assertEqual(bot.state.period_start[T1], p2.isoformat())

        # both dicts survive a save/restore and prune with known_tickers
        bot.state.known_tickers.add(T1)
        bot._save_persist()
        bot2 = IncentiveMarketMaker(client=None, live=False)   # loads on init
        self.assertAlmostEqual(bot2.state.period_base[T1], 20.00)
        self.assertEqual(bot2.state.period_start[T1], p2.isoformat())
        bot.state.known_tickers.discard(T1)
        bot._save_persist()
        bot3 = IncentiveMarketMaker(client=None, live=False)
        self.assertNotIn(T1, bot3.state.period_base)
        self.assertNotIn(T1, bot3.state.period_start)

    def test_paid_basis_crosses_the_floor_per_period(self):
        # The digest's paid-basis counter had the same lifetime defect as
        # the floor projection (2026-09-22): a market that crossed $1 in a
        # PAID period counted every cent of a fresh sub-floor period as paid.
        _clean_persist()
        bot = IncentiveMarketMaker(client=None, live=False)
        T = "KXRT-STRA-50"
        p1 = datetime(2026, 9, 10, 2, 7, tzinfo=timezone.utc)
        p2 = datetime(2026, 9, 22, 16, 49, tzinfo=timezone.utc)
        bot.state.accrued_est[T] = 0.0
        bot._roll_reward_periods({T: {"start": p1, "end": p2}})
        # first period: crosses at $1 with the backlog, then cent by cent
        self.assertAlmostEqual(bot._paid_basis_delta(T, 0.0, 0.6), 0.0)
        self.assertNotIn(T, bot.state.paid_crossed)
        self.assertAlmostEqual(bot._paid_basis_delta(T, 0.6, 1.2), 1.2)
        self.assertIn(T, bot.state.paid_crossed)
        self.assertAlmostEqual(bot._paid_basis_delta(T, 1.2, 4.9), 3.7)
        bot.state.accrued_est[T] = 4.9123
        # THE ROLL (the KXRT-STRA-50 numbers): the new period starts
        # uncrossed and measures from the baseline, so sub-floor accrual is
        # NOT paid...
        bot._roll_reward_periods({T: {"start": p2, "end": p2}})
        self.assertNotIn(T, bot.state.paid_crossed)
        self.assertAlmostEqual(bot._paid_basis_delta(T, 4.9123, 5.0058), 0.0)
        self.assertNotIn(T, bot.state.paid_crossed)
        self.assertAlmostEqual(bot.period_accrued(T) if False else
                               5.0058 - 4.9123, 0.0935)
        # ...until this period clears $1 on its own, and then only this
        # period's backlog lands
        self.assertAlmostEqual(bot._paid_basis_delta(T, 5.0058, 5.95),
                               5.95 - 4.9123)
        self.assertIn(T, bot.state.paid_crossed)
        self.assertAlmostEqual(bot._paid_basis_delta(T, 5.95, 6.0), 0.05)
        # a stale flag from an earlier period is healed on the next refresh
        # when the current period is under the floor (the inherited state)
        bot.state.accrued_est[T] = 5.0
        bot.state.paid_crossed.add(T)
        bot._roll_reward_periods({T: {"start": p2, "end": p2}})
        self.assertNotIn(T, bot.state.paid_crossed)
        self.assertAlmostEqual(bot.period_accrued(T), 5.0 - 4.9123)
        # kill switch: the lifetime crossing, the old accounting
        with mock.patch.object(imm, "FLOOR_ACCRUAL_PER_PERIOD", False):
            bot.state.paid_crossed.discard(T)
            self.assertAlmostEqual(bot.period_accrued(T), 5.0)
            self.assertAlmostEqual(bot._paid_basis_delta(T, 5.0, 5.1), 5.1)

    def test_realized_is_lifetime_and_bot_attributed(self):
        # Jack 2026-09-11, on the AAA gas monthlies: "P&L of $1.30 is wrong.
        # I see P&L of -$5". The row P&L was open-book MTM plus only the
        # past 24h of fill-attributed realized, so a book that holds
        # multi-week inventory showed almost none of its trading.
        # KXAAAGASMINM-26SEP30 printed +1.30 (pure MTM) while Kalshi's own
        # realized on the same two markets was -5.20 -- -4.00 of it on a
        # strike the bot had already closed, which contributed nothing.
        import send_opportunistic_imm as opp
        # -3.75 still open and ours; -3.85 closed out (flat, still in the
        # account with its realized); both in the account, positions agree
        acct_real = {"KXAAAGASMINM-26SEP30-3.75": -1.20,
                     "KXAAAGASMINM-26SEP30-3.85": -4.00}
        acct_pos = {"KXAAAGASMINM-26SEP30-3.75": -20.0,
                    "KXAAAGASMINM-26SEP30-3.85": 0.0}
        bot_pos = {"KXAAAGASMINM-26SEP30-3.75": -20.0}
        sink = {}
        tick = sorted(acct_real)
        got, disputed = opp.realized_for(tick, acct_real, acct_pos, bot_pos, sink)
        self.assertAlmostEqual(got, -5.20)
        self.assertEqual(disputed, 0)

        # a market that has SETTLED has aged out of the positions endpoint;
        # only the bot's sink still carries it
        tick2 = tick + ["KXAAAGASMAXM-26SEP30-4.20"]
        sink2 = dict(sink, **{"KXAAAGASMAXM-26SEP30-4.20": -9.40})
        got2, _ = opp.realized_for(tick2, acct_real, acct_pos, bot_pos, sink2)
        self.assertAlmostEqual(got2, -14.60)

        # SHARED MARKET: the account figure is account-level, so where the
        # bot's position does NOT match the account's, another bot or a
        # manual trade is in the market and OUR attribution must win.
        acct_real3 = {"KXSHARED-26OCT07-T1": -50.0}
        acct_pos3 = {"KXSHARED-26OCT07-T1": -90.0}    # account holds 90
        bot_pos3 = {"KXSHARED-26OCT07-T1": -20.0}     # the bot only 20
        sink3 = {"KXSHARED-26OCT07-T1": -3.00}
        got3, disputed3 = opp.realized_for(["KXSHARED-26OCT07-T1"], acct_real3,
                                           acct_pos3, bot_pos3, sink3)
        self.assertAlmostEqual(got3, -3.00)           # the sink, not -50.00
        self.assertEqual(disputed3, 1)

        # a market in neither source contributes nothing (a floor, not a lie)
        self.assertEqual(opp.realized_for(["KXGONE-26OCT07-T1"], {}, {}, {}, {}),
                         (0.0, 0))

    def test_durable_history_folds_sinks_without_double_counting(self):
        # The cumulative table's one real hazard: the `realized` sink writes
        # DELTAS, so re-reading a day would inflate it. Only COMPLETE UTC
        # days may be cached; today's partial file is summed live every run.
        # The scan roster is a SET and folds idempotently either way.
        import send_opportunistic_imm as opp
        d = tempfile.mkdtemp(prefix="imm_opp_hist_")
        old_dir, old_roster = imm.STATUS_DIR, opp.ROSTER_PATH
        imm.STATUS_DIR = d
        opp.ROSTER_PATH = os.path.join(d, "opportunistic_roster.json")

        def sink(name, day, recs):
            with open(os.path.join(d, "{}_{}.jsonl".format(name, day)), "a",
                      encoding="utf-8") as f:
                for r in recs:
                    f.write(json.dumps(r) + "\n")
        try:
            # keyed by TICKER since 2026-09-11: the row P&L unions this
            # per market with Kalshi's own realized_pnl_dollars
            sink("realized", "2026-09-09",
                 [{"ticker": "KXA-26OCT07-T1", "event_ticker": "KXA-26OCT07",
                   "realized_delta_dollars": -2.0},
                  {"ticker": "KXA-26OCT07-T1", "event_ticker": "KXA-26OCT07",
                   "realized_delta_dollars": -1.0},
                  {"ticker": "KXB-26OCT07-T1", "event_ticker": "KXB-26OCT07",
                   "realized_delta_dollars": 5.0}])
            sink("realized", "2026-09-10",
                 [{"ticker": "KXA-26OCT07-T1", "event_ticker": "KXA-26OCT07",
                   "realized_delta_dollars": 0.5}])
            # is_scan ALONE is not membership: the sink logs every decision
            # CHANGE and is_scan rides on the candidate meta, so a market the
            # scan merely looked at and REJECTED carries it too. Only
            # decision == "selected" means the tier quoted it -- that is how
            # the bot itself forms scan_members. Shipping the loose test
            # attributed $118.40 of credits to the scan tier that it never
            # earned, $84.74 of it on `manual` stand-asides (Jack's own
            # orders) -- a 4.8x overstatement of the lifetime footer.
            sink("selection_events", "2026-09-09",
                 [{"event_ticker": "KXS-26OCT07", "is_scan": True,
                   "decision": "selected"},
                  {"event_ticker": "KXREJECT-26OCT07", "is_scan": True,
                   "decision": "scan_top_n"},
                  {"event_ticker": "KXMANUAL-26OCT07", "is_scan": True,
                   "decision": "manual"},
                  {"event_ticker": "KXFLOOR-26OCT07", "is_scan": True,
                   "decision": "payout_floor"},
                  {"event_ticker": "KXNOT-26OCT07", "is_scan": False,
                   "decision": "selected"}])
            today = "2026-09-10"              # so 09-10 is the partial day
            first = opp.durable_history(today)
            self.assertAlmostEqual(first["realized"]["KXA-26OCT07-T1"], -2.5)
            self.assertAlmostEqual(first["realized"]["KXB-26OCT07-T1"], 5.0)
            # ONLY the selected scan candidate; not the three rejects, and
            # not the selected NON-scan market (that is the normal book)
            self.assertEqual(first["scan_events"], {"KXS-26OCT07"})
            self.assertEqual(first["first_day"], "2026-09-09")
            # re-run: identical, because the partial day is never cached
            for _ in range(3):
                again = opp.durable_history(today)
                self.assertAlmostEqual(again["realized"]["KXA-26OCT07-T1"], -2.5)
                self.assertAlmostEqual(again["realized"]["KXB-26OCT07-T1"], 5.0)
            with open(opp.ROSTER_PATH, encoding="utf-8") as f:
                cached = json.load(f)
            self.assertEqual(cached["folded_realized"], ["2026-09-09"])
            self.assertNotIn(today, cached["folded_realized"])
            # the partial day's remainder lands once the day completes
            sink("realized", "2026-09-10",
                 [{"ticker": "KXA-26OCT07-T1", "event_ticker": "KXA-26OCT07",
                   "realized_delta_dollars": 0.25}])
            done = opp.durable_history("2026-09-11")
            self.assertAlmostEqual(done["realized"]["KXA-26OCT07-T1"], -2.25)
            self.assertAlmostEqual(
                opp.durable_history("2026-09-11")["realized"]["KXA-26OCT07-T1"],
                -2.25)
        finally:
            imm.STATUS_DIR, opp.ROSTER_PATH = old_dir, old_roster

    def test_quote_gaps_open_scan_labels(self):
        # imm_quote_gaps labels a scan-universe market from the live bot's
        # PERSISTED screen caches — never a fetch (the script is read-only).
        import imm_quote_gaps as qg
        _clean_persist()
        bot = IncentiveMarketMaker(client=None, live=False)
        now = datetime.now(timezone.utc)
        t = "KXNOVEL-99DEC31-T5"
        self.assertEqual(qg.scan_gap_label(bot, t, now), "screens pending")
        self.assertEqual(qg.scan_gap_label(bot, "KXNOVEL-99DEC31-HOLD", now),
                         "shape")
        # a month-named numeric ticker on an unread series is no longer a
        # flat 'undated' (2026-09-06 Fiscal.ai class): the bot hydrates it
        # and reads the series, so the label is pending; month-less stays
        self.assertEqual(qg.scan_gap_label(bot, "KXNOVEL-26OCTDELIV-T5", now),
                         "screens pending")
        self.assertEqual(qg.scan_gap_label(bot, "KXNOVEL-DELIV-T5", now),
                         "undated")
        # a cached category ban is only repeated while the knob still names
        # the category (2026-09-06 ban lift): by default it is stale and the
        # bot re-reads the series, so the label says pending
        bot.state.scan_series_meta["KXNOVEL"] = {
            "ts": time.time(), "ok": False, "why": "category:Sports",
            "category": "Sports"}
        self.assertEqual(qg.scan_gap_label(bot, t, now), "screens pending")
        with mock.patch.object(imm, "SCAN_EXCLUDE_CATEGORIES",
                               frozenset({"Sports"})):
            self.assertEqual(qg.scan_gap_label(bot, t, now), "category:Sports")
            # and an ok verdict on a newly banned category reads as the ban
            bot.state.scan_series_meta["KXNOVEL"] = {
                "ts": time.time(), "ok": True, "why": "", "category": "Sports"}
            self.assertEqual(qg.scan_gap_label(bot, t, now), "category:Sports")
        # other cached rejects are trusted as written
        bot.state.scan_series_meta["KXNOVEL"] = {
            "ts": time.time(), "ok": False, "why": "live_source",
            "category": "Sports"}
        self.assertEqual(qg.scan_gap_label(bot, t, now), "live_source")
        # Fiscal.ai month-named KPI events (2026-09-06): pending until the
        # series is read, 'undated' on a judged non-fiscal series, admissible
        # (through to the history screen) on a fiscal one, 'cutoff_passed'
        # once the report month has begun; a month binary is 'shape'
        nxt = (now.astimezone(imm.ET) + timedelta(days=40)).strftime("%y%b").upper()
        cur = now.astimezone(imm.ET).strftime("%y%b").upper()
        ft = f"KXFISC-{nxt}ALBD-25800000.0"
        self.assertEqual(qg.scan_gap_label(bot, ft, now), "screens pending")
        self.assertEqual(qg.scan_gap_label(bot, f"KXFISC-{nxt}ALBD-YES", now),
                         "shape")
        bot.state.scan_series_meta["KXFISC"] = {
            "ts": time.time(), "ok": True, "why": "", "category": "Economics",
            "fiscal": False, "sources": ["fiscal.ai https://fiscal.ai"]}
        self.assertEqual(qg.scan_gap_label(bot, ft, now), "undated")
        bot.state.scan_series_meta["KXFISC"] = {
            "ts": time.time(), "ok": True, "why": "", "category": "Financials",
            "fiscal": True, "sources": ["fiscal.ai https://fiscal.ai"]}
        self.assertEqual(qg.scan_gap_label(bot, ft, now), "screens pending")
        bot.state.scan_history_cache[ft] = {"ts": time.time(), "ok": True, "bars": 40, "range": 2.0, "jump": 1.0, "vol": 10.0}
        self.assertEqual(qg.scan_gap_label(bot, ft, now),
                         "eligible (slots/ROI/live screens)")
        # a pre-2026-09-24 ok entry (no persisted sources) is STALE -- the
        # bot re-reads the series before trusting it, so the label is
        # pending rather than eligible; a source that a keyword now names
        # reads as the live-source reject with no re-read
        bot.state.scan_series_meta["KXFISC"] = {
            "ts": time.time(), "ok": True, "why": "", "category": "Financials",
            "fiscal": True}
        self.assertEqual(qg.scan_gap_label(bot, ft, now), "screens pending")
        bot.state.scan_series_meta["KXFISC"] = {
            "ts": time.time(), "ok": True, "why": "", "category": "Financials",
            "fiscal": True, "sources": ["openrouter https://openrouter.ai/x"]}
        self.assertEqual(qg.scan_gap_label(bot, ft, now), "live_source")
        bot.state.scan_series_meta["KXFISC"] = {
            "ts": time.time(), "ok": True, "why": "", "category": "Financials",
            "fiscal": True, "sources": ["fiscal.ai https://fiscal.ai"]}
        # A market inside its report month is NOT labelled from the month
        # alone (2026-09-06 pm narrowing): whether the month cutoff applies
        # depends on the published report date and the program end, which
        # this cache-only function cannot see — build_meta + the cutoff
        # screen own that verdict.
        cm = f"KXFISC-{cur}ALBD-1"
        bot.state.scan_history_cache[cm] = {"ts": time.time(), "ok": True, "bars": 40, "range": 2.0, "jump": 1.0, "vol": 10.0}
        self.assertEqual(qg.scan_gap_label(bot, cm, now),
                         "eligible (slots/ROI/live screens)")
        bot.state.scan_series_meta["KXNOVEL"] = {
            "ts": time.time(), "ok": True, "why": "", "category": "Economics",
            "sources": ["eia https://www.eia.gov"]}
        # a cached reject is RE-SCORED against the current caps, so the
        # label follows today's thresholds, not the ones in the entry
        bot.state.scan_history_cache[t] = {
            "ts": time.time(), "ok": False, "why": "history_range",
            "bars": 40, "range": 30.0, "jump": 30.0, "vol": 10.0}
        self.assertEqual(qg.scan_gap_label(bot, t, now), "history_jump")
        with mock.patch.object(imm, "SCAN_MAX_RANGE_CENTS", 10):
            self.assertEqual(qg.scan_gap_label(bot, t, now), "history_range")
        # ... and a stale reject whose numbers now pass is NOT reported
        bot.state.scan_history_cache[t] = {
            "ts": time.time(), "ok": False, "why": "history_range",
            "bars": 40, "range": 12.0, "jump": 1.0, "vol": 10.0}
        self.assertEqual(qg.scan_gap_label(bot, t, now),
                         "eligible (slots/ROI/live screens)")
        # an entry with no stats cannot be re-scored -> re-read, so pending
        bot.state.scan_history_cache[t] = {"ts": time.time(), "ok": True}
        self.assertEqual(qg.scan_gap_label(bot, t, now), "screens pending")
        bot.state.scan_history_cache[t] = {"ts": time.time(), "ok": True, "bars": 40, "range": 2.0, "jump": 1.0, "vol": 10.0}
        self.assertEqual(qg.scan_gap_label(bot, t, now),
                         "eligible (slots/ROI/live screens)")
        bot.state.scan_series_strikes["KXNOVEL"] = [time.time(), time.time()]
        self.assertEqual(qg.scan_gap_label(bot, t, now), "series_struck")
        bot.state.scan_halt_day = imm._halt_day_key(now)
        self.assertEqual(qg.scan_gap_label(bot, t, now), "tier halted today")
        bot.state.scan_evicted_events["KXNOVEL-99DEC31"] = time.time()
        self.assertEqual(qg.scan_gap_label(bot, t, now), "evicted")


class TestFineconFamilyRule(unittest.TestCase):
    """Jack 2026-09-09: "add a family rule for central banks, they are
    eligible for finecon but quoting must stop at event datetime so no
    adverse selection."

    Before this, 17 central banks were flagged `review: (unclassified)` by
    the daily task (England and Japan 25 times each since 2026-07-29) and 2
    were enrolled by hand. classify_series has no recognizer for them, review
    is log-only, and the feed audit needs one SERIES over $300/day while the
    family is a uniform $188/day x 5, so nothing ever escalated."""

    def setUp(self):
        self._fam = set(imm.FINECON_FAMILY)
        self._fin = set(imm.FINECON_SERIES)
        self._ovr = dict(imm.SERIES_OVERRIDES)
        self.addCleanup(self._restore)

    def _restore(self):
        imm.FINECON_FAMILY.clear(); imm.FINECON_FAMILY.update(self._fam)
        imm.FINECON_SERIES.clear(); imm.FINECON_SERIES.update(self._fin)
        imm.SERIES_OVERRIDES.clear(); imm.SERIES_OVERRIDES.update(self._ovr)

    def test_prefix_admits_new_banks_from_the_live_feed(self):
        self.assertEqual(imm.FINECON_SERIES_PREFIXES, ("KXCBD",))
        for s in ("KXCBDNORWAY", "KXCBDPOLAND", "KXCBDSWEDEN"):
            imm.FINECON_SERIES.discard(s); imm.FINECON_FAMILY.discard(s)
            imm.SERIES_OVERRIDES.pop(s, None)
        n = imm.finecon_expand_family([
            "KXCBDNORWAY-26SEP24-HOLD", "KXCBDPOLAND-26OCT07-C25",
            "KXCBDSWEDEN-26SEP24-H25", "KXSPRLVL-26SEP09-T286"])
        self.assertEqual(n, 3, "only the KXCBD* prefix is admitted")
        for s in ("KXCBDNORWAY", "KXCBDPOLAND", "KXCBDSWEDEN"):
            self.assertIn(s, imm.FINECON_SERIES)
            self.assertTrue(imm.IncentiveMarketMaker._allowed(f"{s}-26SEP24-HOLD"))
        self.assertNotIn("KXSPRLVL", imm.FINECON_FAMILY)
        # idempotent: a second pass adds nothing
        self.assertEqual(imm.finecon_expand_family(["KXCBDNORWAY-26SEP24-HOLD"]), 0)

    def test_family_members_stop_quoting_before_the_decision(self):
        """The whole point of the rule. Kalshi puts close_time exactly one
        minute before the announcement, so the guard is close-anchored — the
        ticker-date midnight-ET rule is 4h early for Norway but 21h early for
        the RBNZ, whose ticker day and announcement day differ."""
        imm.FINECON_SERIES.discard("KXCBDNORWAY")
        imm.FINECON_FAMILY.discard("KXCBDNORWAY")
        imm.SERIES_OVERRIDES.pop("KXCBDNORWAY", None)
        imm.finecon_expand_family(["KXCBDNORWAY-26SEP24-HOLD"])
        ov = imm.SERIES_OVERRIDES["KXCBDNORWAY"]
        self.assertEqual(ov.cutoff_from_close_min,
                         imm.FINECON_FAMILY_CUTOFF_FROM_CLOSE_MIN)
        self.assertTrue(ov.safe_join)
        self.assertEqual(ov.min_est_per_day, 0.0)      # finecon: no rate bar
        # the derived cutoff really does land before the announcement
        decision = datetime(2026, 9, 24, 8, 0, tzinfo=timezone.utc)
        close = decision - timedelta(minutes=1)        # Kalshi's shape
        cut = close - timedelta(minutes=ov.cutoff_from_close_min)
        self.assertLess(cut, decision)
        self.assertGreaterEqual((decision - cut).total_seconds() / 60.0, 60)
        # ... and for an Asia-Pacific bank whose ticker DAY differs from the
        # announcement day, where the ticker-date rule would be a full day out
        rbnz_decision = datetime(2026, 10, 28, 1, 0, tzinfo=timezone.utc)
        rbnz_cut = (rbnz_decision - timedelta(minutes=1)
                    - timedelta(minutes=ov.cutoff_from_close_min))
        self.assertLess(rbnz_cut, rbnz_decision)
        ticker_rule = imm.parse_event_date("KXCBDECISIONNZ-26OCT27")
        self.assertLess(ticker_rule, rbnz_cut,
                        "close-anchored must be LATER than the crude ticker "
                        "rule here, i.e. it recovers forfeited accrual")

    def test_missing_close_time_fails_closed(self):
        """A close-anchored series with no close_time must stand down, not
        fall back to quoting."""
        imm.finecon_expand_family(["KXCBDNORWAY-26SEP24-HOLD"])
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        meta = imm.MarketMeta(
            ticker="KXCBDNORWAY-26SEP24-HOLD",
            event_ticker="KXCBDNORWAY-26SEP24", series="KXCBDNORWAY",
            dollars_per_day=37.66, program_end=None, target_size=1000,
            discount_factor=0.5, cutoff=None, close_time=None,
            mid_cents=50.0, spread_cents=2)
        self.assertEqual(bot._screen(meta, datetime.now(timezone.utc)),
                         "no_event_window")

    def test_blocklisted_series_is_refused(self):
        with mock.patch.object(imm, "SERIES_BLOCKLIST_PREFIXES",
                               tuple(imm.SERIES_BLOCKLIST_PREFIXES) + ("KXCBDBAD",)):
            imm.finecon_expand_family(["KXCBDBAD-26SEP24-HOLD"])
        self.assertNotIn("KXCBDBAD", imm.FINECON_SERIES)

    def test_extra_file_reload_does_not_wipe_family_members(self):
        """load_finecon_extra_series rebuilds FINECON_SERIES from
        _FINECON_BASE, so feed-discovered members must be folded in or they
        would vanish on the next hot reload."""
        imm.finecon_expand_family(["KXCBDNORWAY-26SEP24-HOLD"])
        self.assertIn("KXCBDNORWAY", imm.FINECON_SERIES)
        import json as _json, os as _os
        _os.makedirs(imm.STATUS_DIR, exist_ok=True)
        with open(imm.FINECON_EXTRA_FILE, "w") as f:
            _json.dump({"series": ["KXSOMETHINGNEW", "KXSOMETHINGADS",
                                   "KXSOMETHINGPOS"]}, f)
        try:
            imm._finecon_extra_state["mtime"] = 0.0
            imm.load_finecon_extra_series()
            self.assertIn("KXCBDNORWAY", imm.FINECON_SERIES,
                          "family member wiped by the extra-file rebuild")
            self.assertIn("KXSOMETHINGNEW", imm.FINECON_SERIES)
            # a name-pattern family member in the file is the NORMAL book's
            # (2026-09-22): skipped by the loader, never walked as finecon
            self.assertNotIn("KXSOMETHINGADS", imm.FINECON_SERIES)
            self.assertNotIn("KXSOMETHINGPOS", imm.FINECON_SERIES)
        finally:
            try: _os.remove(imm.FINECON_EXTRA_FILE)
            except OSError: pass
            imm._finecon_extra_state["mtime"] = 0.0


class TestLifetimeSlotRelease(unittest.TestCase):
    """Jack 2026-09-09: "release a lifetime slot if <=5 contracts were filled
    on it and it becomes unquotable (both sides out of band). only count
    lifetime slots if had 6+ filled contracts".

    Measured cause: KXDIESELELECT-26NOV03 held all three lifetime slots on
    T4.40/T4.60/T4.80, which had drifted to 95-98c against a 5-90c band, so
    all three stood down while six healthy siblings were cut as event_top_n.
    KXDIESELMINY-26DEC31 was the mirror image at 1-4c. ~$386/day of pool
    parked on strikes that could not quote."""

    EV = "KXDIESEL-26NOV03"

    def setUp(self):
        _clean_persist()
        self.bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        self.addCleanup(_clean_persist)

    def _slots(self, *tickers):
        return {"markets": [f"{self.EV}-{t}" for t in tickers], "ts": time.time()}

    def test_filled_is_seeded_from_inventory_on_load(self):
        """Jack 2026-09-09 "Seed own_filled from |own_pos| on load". `filled`
        started at zero for every market that traded before 3e91438, so the
        earned-slot rule released KXDIESELW-26SEP14's T5.84/T5.86/T5.92 as
        "filled 0 < 6" while the bot held -65/-72/-40 in them, and the event
        ended the day with inventory in eight strikes. A position is a lower
        bound on gross fills: seed it, never reduce a real counter."""
        worked, real, flat = (f"{self.EV}-T5.84", f"{self.EV}-T4.80",
                              f"{self.EV}-T4.40")
        self.bot.pnl.pos[worked] = -65.0          # traded before the counter existed
        self.bot.pnl.filled.pop(worked, None)
        self.bot.pnl.pos[real] = 10.0             # counter already knows more
        self.bot.pnl.filled[real] = 90.0
        self.bot.pnl.pos[flat] = 0.0              # never traded: stays 0
        self.bot.pnl.filled[flat] = 0.0
        self.bot._save_persist()
        bot2 = IncentiveMarketMaker(client=FakeClient(), live=False)
        self.assertEqual(bot2.pnl.filled.get(worked), 65.0)
        self.assertEqual(bot2.pnl.filled.get(real), 90.0)      # not reduced
        self.assertEqual(bot2.pnl.filled.get(flat, 0.0), 0.0)
        # and the consequence: the worked, now-unquotable holder keeps its
        # slot instead of being released as never-traded
        entry = self._slots("T5.84", "T4.40")
        kept = bot2._live_event_slots(self.EV, entry, {worked, flat})
        self.assertEqual(kept, [worked])

    def test_barely_traded_and_unquotable_releases_its_slot(self):
        self.assertEqual(imm.EVENT_SLOT_EARNED_FILLS, 6)
        entry = self._slots("T4.40", "T4.60", "T4.80")
        # T4.40 filled 5 (under the bar) and is now out of band -> released
        self.bot.pnl.filled[f"{self.EV}-T4.40"] = 5.0
        self.bot.pnl.filled[f"{self.EV}-T4.60"] = 0.0
        self.bot.pnl.filled[f"{self.EV}-T4.80"] = 40.0     # earned it
        unquotable = {f"{self.EV}-T4.40", f"{self.EV}-T4.60", f"{self.EV}-T4.80"}
        kept = self.bot._live_event_slots(self.EV, entry, unquotable)
        self.assertEqual(kept, [f"{self.EV}-T4.80"],
                         "only the market that actually traded keeps its slot")
        # the ledger itself is pruned, so the room is real on the next cut
        self.assertEqual(entry["markets"], [f"{self.EV}-T4.80"])

    def test_six_fills_earns_the_slot_forever(self):
        entry = self._slots("T4.40")
        self.bot.pnl.filled[f"{self.EV}-T4.40"] = 6.0      # exactly the bar
        kept = self.bot._live_event_slots(self.EV, entry, {f"{self.EV}-T4.40"})
        self.assertEqual(kept, [f"{self.EV}-T4.40"])
        self.bot.pnl.filled[f"{self.EV}-T4.40"] = 5.99
        self.assertEqual(
            self.bot._live_event_slots(self.EV, dict(entry), {f"{self.EV}-T4.40"}), [])

    def test_a_quotable_market_keeps_its_slot_however_little_it_traded(self):
        """The concurrency meaning of the cap must survive: a live low-fill
        market still holds its slot, so an event never quotes more than N."""
        entry = self._slots("T4.40", "T4.60")
        self.bot.pnl.filled.clear()
        kept = self.bot._live_event_slots(self.EV, entry, set())   # none unquotable
        self.assertEqual(len(kept), 2)

    def test_a_slot_holder_absent_from_this_refresh_is_never_released(self):
        """unquotable_now only holds markets bulk-read this refresh, so a
        slot-holder missing from the feed must not be released on no data."""
        entry = self._slots("T4.40")
        self.bot.pnl.filled.clear()
        kept = self.bot._live_event_slots(self.EV, entry, {"KXOTHER-26NOV03-T1"})
        self.assertEqual(kept, [f"{self.EV}-T4.40"])

    def test_released_slot_lets_a_healthy_sibling_in(self):
        """End to end through the real cut: with the ledger full of dead
        strikes the sibling is rejected; once released it is admitted."""
        def m(t):
            return imm.MarketMeta(
                ticker=f"{self.EV}-{t}", event_ticker=self.EV, series="KXDIESEL",
                dollars_per_day=14.29, program_end=None, target_size=1000,
                discount_factor=0.5, cutoff=None, close_time=None,
                est_dollars_per_day=1.0, est_exposure_dollars=10.0,
                est_collateral_dollars=0.0, quotable_sides=2)
        healthy = [m("T5.20"), m("T5.60"), m("T5.80")]
        full = self._slots("T4.40", "T4.60", "T4.80")
        cut = imm.event_top_n_cut(healthy, incumbent=set(),
                                  slots_used={self.EV: list(full["markets"])})
        self.assertEqual(len(cut), 3, "ledger full -> every sibling cut")
        # now release them: barely traded and out of band
        self.bot.pnl.filled.clear()
        unq = {t for t in full["markets"]}
        live = self.bot._live_event_slots(self.EV, full, unq)
        self.assertEqual(live, [])
        cut2 = imm.event_top_n_cut(healthy, incumbent=set(),
                                   slots_used={self.EV: live})
        self.assertEqual(cut2, set(), "released slots admit the healthy strikes")

    def test_knob_off_restores_the_strict_lifetime_ledger(self):
        entry = self._slots("T4.40")
        self.bot.pnl.filled.clear()
        with mock.patch.object(imm, "EVENT_SLOT_EARNED_FILLS", 0):
            kept = self.bot._live_event_slots(self.EV, entry, {f"{self.EV}-T4.40"})
        self.assertEqual(kept, [f"{self.EV}-T4.40"])

    def test_gross_fills_are_tracked_and_survive_a_restart(self):
        """`pos` cannot answer 'did we trade here' — a market worked flat
        reads 0 — so the rule needs the gross figure."""
        t = f"{self.EV}-T4.40"
        self.bot.pnl.on_fill(t, "yes", "buy", 20, 50)
        self.bot.pnl.on_fill(t, "yes", "sell", 20, 51)
        self.assertEqual(self.bot.pnl.pos.get(t, 0.0), 0.0)   # flat
        self.assertEqual(self.bot.pnl.filled[t], 40.0)        # but 40 traded
        self.bot._save_persist()
        bot2 = IncentiveMarketMaker(client=self.bot.client, live=False)
        self.assertEqual(bot2.pnl.filled.get(t), 40.0)


class TestOpenScanTier(unittest.TestCase):
    """Jack 2026-09-05: "extend the opportunistic IMM with 15 slots and 5 to
    scan all markets. be very careful for adverse selection". The tier's
    universe is the COMPLEMENT of the allowed book, so these tests run with
    the real allowlist policy (ALLOWLIST_ONLY on) and a novel series that no
    allowlist knows. Every screen fails closed; every tripwire evicts the
    whole event for good; the tier has its own daily loss budget."""

    S = "KXNOVEL"
    EV = "KXNOVEL-99DEC31"
    A = "KXNOVEL-99DEC31-T5"
    B = "KXNOVEL-99DEC31-T6"

    def setUp(self):
        self._allow = imm.ALLOWLIST_ONLY
        imm.ALLOWLIST_ONLY = True
        self.addCleanup(setattr, imm, "ALLOWLIST_ONLY", self._allow)
        # PRODUCTION ladder mode (the launcher runs IMM_LADDER_MODE=atref):
        # in the suite's default offsets mode a safe-joined rung two ticks
        # behind a deep touch sits OUTSIDE the qualifying walk and scores
        # zero, which is the 2026-08-05 reference-cap lesson, not a scan
        # property — atref caps safe-join at the reference.
        self._mode = imm.LADDER_MODE
        imm.LADDER_MODE = "atref"
        self.addCleanup(setattr, imm, "LADDER_MODE", self._mode)
        self.addCleanup(_clean_persist)
        self.addCleanup(self._release)
        _clean_persist()

    def _release(self):
        for s in list(imm.SCAN_GUARDED_SERIES):
            imm.release_scan_override(s)
        for s in (self.S, "KXPRIOR"):
            imm.SERIES_OVERRIDES.pop(s, None)

    @staticmethod
    def _candles(n=20, bid=40, ask=44, vol=1):
        return [{"yes_bid": {"close": bid}, "yes_ask": {"close": ask},
                 "volume": vol} for _ in range(n)]

    def _market(self, t, bid="0.4900", ask="0.5100", vol24="5", age_h=48):
        now = datetime.now(timezone.utc)
        fmt = "%Y-%m-%dT%H:%M:%SZ"
        return {"ticker": t, "event_ticker": self.EV, "status": "active",
                "close_time": (now + timedelta(days=30)).strftime(fmt),
                "open_time": (now - timedelta(hours=age_h)).strftime(fmt),
                "yes_bid_dollars": bid, "yes_ask_dollars": ask,
                "volume_fp": "20.00", "volume_24h_fp": vol24,
                "strike_type": "greater"}

    def _bot(self, tickers=None, category="Economics", sources=None,
             candles=None):
        client = FakeClient()
        now = datetime.now(timezone.utc)
        fmt = "%Y-%m-%dT%H:%M:%SZ"
        start = (now - timedelta(days=1)).strftime(fmt)
        end = (now + timedelta(days=6)).strftime(fmt)
        for t in (tickers or [self.A]):
            client.programs.append(
                {"market_ticker": t, "incentive_type": "liquidity",
                 "period_reward": 7000000, "target_size_fp": "1000.00",
                 "discount_factor_bps": 5000, "paid_out": False,
                 "start_date": start, "end_date": end})
            client.markets[t] = self._market(t)
            client.books[t] = {"orderbook_fp": {
                "yes_dollars": [["0.48", "500"], ["0.49", "600"]],
                "no_dollars": [["0.49", "1200"]]}}
            client.candles[t] = list(candles) if candles is not None \
                else self._candles()
        client.series_meta[self.S] = {
            "category": category,
            "settlement_sources": sources or [
                {"name": "EIA", "url": "https://www.eia.gov"}]}
        return IncentiveMarketMaker(client=client, live=False)

    def _meta(self, t=None, **kw):
        now = datetime.now(timezone.utc)
        base = dict(ticker=t or self.A, event_ticker=self.EV, series=self.S,
                    dollars_per_day=100.0, program_end=None,
                    target_size=1000.0, discount_factor=0.5, cutoff=None,
                    close_time=None, mid_cents=50.0, spread_cents=2,
                    open_time=now - timedelta(hours=48), scan=True,
                    volume_24h=5.0)
        base.update(kw)
        return MarketMeta(**base)

    def _orders(self, bot, t):
        out = []
        for o in bot.state.sim_orders.values():
            if o.get("ticker") != t:
                continue
            parsed = order_yes_book_cents(o)
            if parsed is None:
                continue
            out.append((parsed[0], parsed[1], order_remaining(o)))
        return out

    # ---- universe / structure ------------------------------------------------

    def test_universe_is_the_complement_of_the_allowed_book(self):
        r = imm.scan_universe_reason
        self.assertIsNone(r("KXNOVEL-26OCT13-T5"))
        # everything the normal book quotes is NOT scan universe
        self.assertEqual(r("KXSPRLVL-26OCT13-T286"), "allowed")   # finecon
        self.assertEqual(r("KXBKFT-26NOV08-T100"), "allowed")     # company (Carbon Arc FT)
        self.assertEqual(r("KXBA-26JULDELIV-130"), "blocked")     # company KPI, cut 2026-10-03
        self.assertEqual(r("KXSUEZWEEKLY-26OCT11-T30"), "allowed")  # open-scan graduate
        self.assertEqual(r("KXWCMENTION-26JUL11ARGSUI-VAR"), "allowed")
        # state gas dailies: pattern-blocked 2026-09-14, so they are NOT
        # scan universe either (the de-allowlist-only route would have made
        # this None = scan candidate). Since 2026-09-27 they are normal-book
        # members behind the GasBuddy gate -- still never scan universe.
        # (2026-10-01, the gas trial: blocked again unless IMM_GB_STATE_QUOTE=1)
        self.assertEqual(r("KXAAAGASDTX-26SEP08-4.14"),
                         "allowed" if imm.GB_STATE_QUOTE else "blocked")
        self.assertEqual(r("KXAAAGASDNYC-26SEP08-4.14"), "blocked")
        self.assertEqual(r("KXAAAGASD-26SEP08-4.14"), "allowed")   # national kept
        # blocklist wins over everything (other bots' books)
        self.assertEqual(r("KXHIGHNY-26JUL10-B90"), "blocked")
        self.assertEqual(r("KXXRPMAXMON-XRP-26JUL31-140"), "blocked")
        self.assertEqual(r("KXMLBMENTION-26JUL14ALNL-GRAN"), "blocked")
        # structural exclusions: other repo bots (ownership), live feeds,
        # the 9/2 traps
        for t in ("KXLOWTSATX-26SEP08-T70", "KXRAINNYC-26SEP03-X",
                  "KXEURUSD-26SEP08-T1.1", "KXINXU-26SEP08-T6000",
                  "KXBTCD-26AUG0521-T54099.99", "KXETHMAXW-26SEP12-T5000",
                  "KXUE-RUS26SEP-T5", "KXISMPMI-26OCT01-T50",
                  "KXSNOWCRABCATCH-26OCT09-T1", "KXTRUFAIDP-26AUG26-T50",
                  "KXTXERCOTPEAK-26SEP08-T70000"):
            self.assertEqual(r(t), "excluded_family", t)
        # NO category families by prefix (Jack 2026-09-06 "dont
        # systematically drop Sports, Crypto, Elections, Politics, Climate
        # and Weather, Culture, Entertainment"): sports, weather outside the
        # other bots' families, politics and non-price crypto are scan
        # universe — the per-series/per-market screens judge them
        for t in ("KXNFLGAME-26SEP08-T1", "KXPGATOUR-26SEP13-T270",
                  "KXDENSNOWMB-26DEC31-T10", "KXNYTTRUMPAPPROVAL-26SEP30-T45",
                  "KXHARDFORKBTC-26DEC31-T1", "KXBOXOFFICE-26SEP13-T50"):
            self.assertIsNone(r(t), t)
        # the snow monthlies left the scan universe for the normal book on
        # 2026-10-04 (the snow gate, snow_monthly_series)
        self.assertEqual(r("KXNYCSNOWM-26DEC31-T10"), "allowed")
        # knobs: tier off / allowlist off -> no scan universe at all
        old = imm.SCAN_TOP_N
        imm.SCAN_TOP_N = 0
        try:
            self.assertEqual(r("KXNOVEL-26OCT13-T5"), "off")
        finally:
            imm.SCAN_TOP_N = old
        imm.ALLOWLIST_ONLY = False
        self.assertEqual(r("KXNOVEL-26OCT13-T5"), "allowlist_off")
        imm.ALLOWLIST_ONLY = True
        # _allowed itself is untouched: the scan path is the ONLY way in
        self.assertFalse(IncentiveMarketMaker._allowed("KXNOVEL-26OCT13-T5"))

    def test_structure_screen_dated_numeric(self):
        sr = imm.scan_shape_reason
        for t in ("KXNOVEL-26OCT13-T286", "KXNOVEL-26OCT13-B90",
                  "KXNOVEL-26OCT13-4.1400", "KXNOVEL-26OCT13-T1.2M",
                  "KXNOVEL-26OCT13-T54099.99"):
            self.assertIsNone(sr(t), t)
        # categorical / binary outcomes are the resolution-jump class
        self.assertEqual(sr("KXNOVEL-26OCT27-HOLD"), "shape")
        self.assertEqual(sr("KXNOVEL-26OCT27-YES"), "shape")
        # Kalshi's own strike_type rescues an odd ticker segment
        self.assertIsNone(sr("KXNOVEL-26OCT27-HOLD", "greater"))
        self.assertEqual(sr("KXNOVEL-26OCT27-HOLD", "custom"), "shape")
        # no day in the ticker = no midnight-ET release guard (KXUE/ISMPMI)
        self.assertEqual(sr("KXBA-26JULDELIV-130"), "undated")
        self.assertEqual(sr("KXRT-DOG-45"), "undated")
        self.assertEqual(sr("KXUE-RUS26SEP-T5"), "undated")

    def test_fiscal_month_named_events(self):
        # Jack 2026-09-06 "include markets settled by Fiscal.ai as part of
        # the opportunistic scan": the KPI class names events by REPORT
        # MONTH with no day (KXCCL-26SEPALBD). The month parses to 00:00 ET
        # on the first of that month, which becomes the cutoff — the
        # month-level twin of the day-dated midnight rule — and 'undated'
        # is waived for a Fiscal.ai-settled series only.
        pm = imm.parse_event_month
        self.assertEqual(pm("KXCCL-26SEPALBD"),
                         imm.ET.localize(datetime(2026, 9, 1)).astimezone(timezone.utc))
        self.assertEqual(pm("KXF-26OCTUSSALES-480000"),
                         imm.ET.localize(datetime(2026, 10, 1)).astimezone(timezone.utc))
        self.assertEqual(pm("KXBAA-28JANDELIV"),
                         imm.ET.localize(datetime(2028, 1, 1)).astimezone(timezone.utc))
        # day-dated, month-less, prefixed-month and bad-month segments: None
        for t in ("KXNFLGAME-26SEP08-T1", "KXBTCD-26SEP0609-T1", "KXRT-DOG",
                  "KXUE-RUS26SEP-T5", "KXFOO-26NL", "KXFOO-26ABCX", "KXFOO"):
            self.assertIsNone(pm(t), t)
        sr = imm.scan_shape_reason
        self.assertEqual(sr("KXCCL-26SEPALBD-25800000.0", "greater"), "undated")
        self.assertIsNone(sr("KXCCL-26SEPALBD-25800000.0", "greater", fiscal=True))
        self.assertIsNone(sr("KXYUM-26NOVTBSSS-N3.0", "greater", fiscal=True))
        # the waiver needs a month: a month-less undated ticker stays out
        self.assertEqual(sr("KXRT-DOG-45", "greater", fiscal=True), "undated")
        # ... and a month-named BINARY is still the resolution-jump class
        self.assertEqual(sr("KXCAHSR-26DECOPEN-YES", "custom", fiscal=True), "shape")
        # cutoff: first of the report month, tightened by anything earlier,
        # day-dated tickers untouched
        rc = imm.scan_report_month_cutoff
        sep1 = imm.ET.localize(datetime(2026, 9, 1)).astimezone(timezone.utc)
        self.assertEqual(rc("KXCCL-26SEPALBD", None), sep1)
        self.assertEqual(rc("KXCCL-26SEPALBD", sep1 + timedelta(days=20)), sep1)
        earlier = sep1 - timedelta(days=3)
        self.assertEqual(rc("KXCCL-26SEPALBD", earlier), earlier)
        dated = datetime(2026, 9, 21, 4, tzinfo=timezone.utc)
        self.assertEqual(rc("KXNFLGAME-26SEP21NYGLAR", dated), dated)
        self.assertIsNone(rc("KXRT-DOG", None))

    def test_report_month_narrowed_by_the_paying_window(self):
        # Jack 2026-09-06 pm ("narrow the month rule"), on KXDOL-26SEPCOMP:
        # the month is a stand-in for "the report might land while we quote".
        # When Kalshi PUBLISHES a report date that falls after the paying
        # program window, that stand-in is provably wrong — the number
        # cannot print while the bot earns — so no month cutoff.
        rc = imm.scan_report_month_cutoff
        sep1 = imm.ET.localize(datetime(2026, 9, 1)).astimezone(timezone.utc)
        prog_end = datetime(2026, 9, 11, 3, 59, tzinfo=timezone.utc)
        occ_cut = datetime(2026, 9, 12, 4, tzinfo=timezone.utc)   # DOL reports 9/12
        # report AFTER the window: the occurrence-derived cutoff stands
        self.assertEqual(rc("KXDOL-26SEPCOMP", occ_cut, report=occ_cut,
                            program_end=prog_end), occ_cut)
        # report INSIDE the window: the month still bites, early
        inside = datetime(2026, 9, 8, 4, tzinfo=timezone.utc)
        self.assertEqual(rc("KXDOL-26SEPCOMP", inside, report=inside,
                            program_end=prog_end), sep1)
        # report exactly at the window end counts as inside (>, not >=)
        self.assertEqual(rc("KXDOL-26SEPCOMP", prog_end, report=prog_end,
                            program_end=prog_end), sep1)
        # NO published report date (CHWY/KR/TTAN): month stands — an unknown
        # date must fail toward quoting less (the 8/6 CELH asymmetry)
        self.assertEqual(rc("KXCHWY-26SEPACTIVECUST", None, report=None,
                            program_end=prog_end), sep1)
        # no program end known: month stands
        self.assertEqual(rc("KXDOL-26SEPCOMP", occ_cut, report=occ_cut,
                            program_end=None), sep1)
        # day-dated events never consult any of this
        dated = datetime(2026, 9, 21, 4, tzinfo=timezone.utc)
        self.assertEqual(rc("KXNFLGAME-26SEP21NYGLAR", dated, report=dated,
                            program_end=prog_end), dated)
        # the report-date reader: occurrence == expiration is Kalshi
        # restating the expiry, not a published date (CHWY/KR/TTAN read so)
        rd = imm.scan_report_date
        exp = datetime(2027, 1, 8, 4, tzinfo=timezone.utc)
        self.assertEqual(rd(occ_cut, exp), occ_cut)
        self.assertIsNone(rd(exp, exp))
        self.assertIsNone(rd(exp - timedelta(minutes=30), exp))
        self.assertIsNone(rd(None, exp))
        self.assertEqual(rd(occ_cut, None), occ_cut)
        # the fiscal flag comes from the series' settlement sources
        fiscal = {"category": "Financials", "settlement_sources": [
            {"name": "Fiscal.ai", "url": "https://fiscal.ai"}]}
        self.assertTrue(imm.scan_series_is_fiscal(fiscal))
        self.assertFalse(imm.scan_series_is_fiscal(
            {"settlement_sources": [{"name": "EIA", "url": "https://eia.gov"}]}))
        self.assertFalse(imm.scan_series_is_fiscal({}))
        self.assertFalse(imm.scan_series_is_fiscal(None))
        # ... and a Fiscal.ai series is otherwise an ordinary admissible
        # family (Financials, no live feed)
        self.assertEqual(imm.scan_series_meta_verdict(fiscal),
                         (True, "", "Financials"))
        # string-level pre-screen: month-named tickers hydrate when the
        # series is fiscal or not yet judged (incl. a pre-flag verdict);
        # a judged non-fiscal series screens out without a read
        ok = imm.scan_month_prescreen_ok
        self.assertTrue(ok("KXCCL-26SEPALBD-1", None))
        self.assertTrue(ok("KXCCL-26SEPALBD-1", {"ok": True, "category": "Economics"}))
        self.assertTrue(ok("KXCCL-26SEPALBD-1", {"ok": True, "fiscal": True}))
        self.assertFalse(ok("KXCCL-26SEPALBD-1", {"ok": True, "fiscal": False}))
        self.assertFalse(ok("KXRT-DOG-45", None))

    def test_history_verdict(self):
        # SHIPPED DEFAULTS since 2026-09-07 (Jack): bar-count and range OFF,
        # jump 10c, volume 1000/72h.
        self.assertEqual(imm.SCAN_MIN_HISTORY_BARS, 0)
        self.assertEqual(imm.SCAN_MAX_RANGE_CENTS, 0)
        self.assertEqual(imm.SCAN_MAX_JUMP_CENTS, 10)
        self.assertEqual(imm.SCAN_MAX_HISTORY_VOLUME, 1000)
        v = imm.scan_history_verdict(self._candles())
        self.assertTrue(v["ok"])
        self.assertEqual(v["bars"], 20)
        # thin / wide books now PASS, and the stats are still measured
        v = imm.scan_history_verdict(self._candles(n=5))
        self.assertTrue(v["ok"])
        self.assertEqual(v["bars"], 5)
        # a 19c DRIFT in 1c steps: big range, no step -> passes now
        drift = [c for i in range(20)
                 for c in self._candles(n=1, bid=40 + i, ask=44 + i)]
        v = imm.scan_history_verdict(drift)
        self.assertTrue(v["ok"])
        self.assertEqual((v["range"], v["jump"]), (19.0, 1.0))
        # a one-hour STEP is still the reject that matters, at the 10c bar
        stepped = self._candles(n=12) + self._candles(n=8, bid=52, ask=56)
        self.assertEqual(imm.scan_history_verdict(stepped)["why"],
                         "history_jump")
        # ... and a 9c step now passes where the old 6c bar rejected it
        small = self._candles(n=12) + self._candles(n=8, bid=49, ask=53)
        self.assertTrue(imm.scan_history_verdict(small)["ok"])
        busy = self._candles(vol=20)          # 400 traded in 72h
        self.assertTrue(imm.scan_history_verdict(busy)["ok"])
        busier = self._candles(vol=60)        # 1200 traded in 72h
        self.assertEqual(imm.scan_history_verdict(busier)["why"],
                         "history_volume")
        # dollars-string encoding parses
        dollars = [{"yes_bid": {"close_dollars": "0.40"},
                    "yes_ask": {"close_dollars": "0.44"}, "volume_fp": "1"}
                   for _ in range(15)]
        self.assertTrue(imm.scan_history_verdict(dollars)["ok"])
        # NO two-sided bars at all: reachable only with the bar check off,
        # and it must not raise. Passing here is deliberate — _screen's
        # one_sided / mid-band checks still demand a real book right now.
        junk = [{"garbage": 1}, {"yes_bid": {"close": 40}}] * 10
        v = imm.scan_history_verdict(junk)
        self.assertTrue(v["ok"])
        self.assertEqual((v["bars"], v["range"], v["jump"]), (0, 0.0, 0.0))
        v = imm.scan_history_verdict(None)
        self.assertTrue(v["ok"])
        self.assertEqual(v["bars"], 0)
        # a SINGLE bar has a range but no pairwise jump; must not raise
        v = imm.scan_history_verdict(self._candles(n=1))
        self.assertTrue(v["ok"])
        self.assertEqual((v["bars"], v["jump"]), (1, 0.0))

    def test_book_entirely_outside_the_band_never_takes_a_slot(self):
        """Jack 2026-09-07: "add a screen for books entirely outside the
        quotable band, dont allow them as one of the 30". The quote loop
        already stands such a market down per side, so admitting it burns a
        slot to rest nothing — measured on KXDIESELELECT/KXDIESELYE, which
        took 3 of the tier's new slots on a 4c/98c book."""
        bot = self._bot()
        now = datetime.now(timezone.utc)
        lo, hi = imm.member_price_band(self.S, False)
        budget = {"series": 9, "history": 9}
        # both touches outside the band -> rejected, no slot, no reads spent
        dead = dict(self._market(self.A), yes_bid_dollars="0.0400",
                    yes_ask_dollars="0.9800")
        reads = getattr(bot.client, "series_reads", 0)
        self.assertEqual(bot._scan_admission(self._meta(), dead, {}, now,
                                             budget), "band")
        self.assertEqual(getattr(bot.client, "series_reads", 0), reads)
        # ONE side in band is enough: the healthy side still earns
        for bid, ask in (("0.0400", "0.5000"), ("0.5000", "0.9800")):
            one = dict(self._market(self.A), yes_bid_dollars=bid,
                       yes_ask_dollars=ask)
            self.assertIsNone(bot._scan_admission(self._meta(), one, {}, now,
                                                  budget))
        # and an ordinary two-sided book is unaffected
        self.assertIsNone(bot._scan_admission(self._meta(),
                                              self._market(self.A), {}, now,
                                              budget))
        # the band edges themselves are IN (<=, not <)
        edge = dict(self._market(self.A),
                    yes_bid_dollars=f"{lo/100:.4f}", yes_ask_dollars="0.9800")
        self.assertIsNone(bot._scan_admission(self._meta(), edge, {}, now,
                                              budget))
        edge2 = dict(self._market(self.A), yes_bid_dollars="0.0400",
                     yes_ask_dollars=f"{hi/100:.4f}")
        self.assertIsNone(bot._scan_admission(self._meta(), edge2, {}, now,
                                              budget))
        # a book with no prices at all is also out
        blank = dict(self._market(self.A))
        blank.pop("yes_bid_dollars", None); blank.pop("yes_ask_dollars", None)
        self.assertEqual(bot._scan_admission(self._meta(), blank, {}, now,
                                             budget), "band")

    def test_cached_history_verdicts_rescore_against_current_caps(self):
        """Jack 2026-09-07: "rescore cached verdicts against current caps".
        Verdicts cache 6h, so without this a knob change took until the TTL
        expired to show — the 9/7 loosening went live and the next refresh
        still reported 27 history_range rejects written under the old caps.
        The stats are persisted, so the caps are simply re-applied."""
        rs = imm.scan_history_rescore
        # a reject written under the OLD range cap: its numbers pass today
        stale = {"ts": time.time(), "ok": False, "why": "history_range",
                 "bars": 40, "range": 12.0, "jump": 1.0, "vol": 10.0}
        self.assertEqual(rs(stale), (True, ""))
        with mock.patch.object(imm, "SCAN_MAX_RANGE_CENTS", 10):
            self.assertEqual(rs(stale), (False, "history_range"))
        # a pass written under the OLD volume cap that today's cap rejects
        was_ok = {"ts": time.time(), "ok": True, "why": "",
                  "bars": 40, "range": 1.0, "jump": 1.0, "vol": 900.0}
        self.assertEqual(rs(was_ok), (True, ""))
        with mock.patch.object(imm, "SCAN_MAX_HISTORY_VOLUME", 250):
            self.assertEqual(rs(was_ok), (False, "history_volume"))
        # FAIL CLOSED: a pre-2026-09-07 thin short-circuit never measured
        # range/jump, so its zeros are absence of data -> re-read, never a
        # free pass
        self.assertIsNone(rs({"ts": time.time(), "ok": False,
                              "why": "history_thin", "bars": 3,
                              "range": 0.0, "jump": 0.0, "vol": 0.0}))
        # ... as are entries with no stats at all, or an unusable shape
        self.assertIsNone(rs({"ts": time.time(), "ok": True}))
        self.assertIsNone(rs({"bars": "x", "range": 1, "jump": 1, "vol": 1}))
        self.assertIsNone(rs(None))
        # a fresh read and a re-scored entry can never disagree: both go
        # through score_history()
        v = imm.scan_history_verdict(self._candles(n=20, bid=40, ask=44))
        self.assertEqual(rs(dict(v, ts=time.time())), (v["ok"], v["why"]))

        # bot level: the cached entry is re-scored with NO extra candle read
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        now_ts = time.time()
        bot.state.scan_history_cache[self.A] = dict(stale)
        reads = getattr(bot.client, "candle_reads", 0)
        meta = self._meta()
        self.assertEqual(bot._scan_history_ok(meta, now_ts,
                                              {"history": 5}), (True, ""))
        self.assertEqual(getattr(bot.client, "candle_reads", 0), reads)
        with mock.patch.object(imm, "SCAN_MAX_RANGE_CENTS", 10):
            self.assertEqual(bot._scan_history_ok(meta, now_ts,
                                                  {"history": 5}),
                             (False, "history_range"))
        # an un-rescorable entry falls through to a real read
        bot.state.scan_history_cache[self.A] = {"ts": now_ts, "ok": True}
        bot.client.candles[self.A] = self._candles()
        self.assertEqual(bot._scan_history_ok(meta, now_ts,
                                              {"history": 5}), (True, ""))
        self.assertEqual(getattr(bot.client, "candle_reads", 0), reads + 1)

